INSERT INTO `crs_tabledata1530` VALUES ('1', '{83691ED2-D10B-4FBF-9792-41E730367904}', '61', 'INHE-0578', '2018-01-12 08:42:32', '0000-00-00 00:00:00', '2018-01-12 08:42:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2018011201/立项申请/MX', '', 'MeterX Proprietary Limited', 'Meter X', '南非', 'Lawrence Letuka', '+27 83 303 1717', 'lawrence.letuka@meterx.co.za', 'Meter X 主要业务为电表及抄表系统业务，为Solar Xgen （太阳能EPC工程公司）下属公司；主要配合Xgen公司业务进行电表业务。Xgen 及Meter X公司具有BBBEE资质，主要负责人为黑人，团队其他人员白人居多；均具有一定的电力行业从业经历。根据联系了解，Meter X公司具有较完备的生意模式，付款方式、结算条件较优；且在南非太阳能行业具有一定的口碑和能力，可以为后期其他业务（配电等）开拓储备一定的客户资源。', '', '', '', '', '', '', '', '', '', 'MeterX Proprietary Limited', 'Meter X', '南非', 'Lawrence Letuka', '+27 83 303 1717', 'lawrence.letuka@meterx.co.za', null);
INSERT INTO `crs_tabledata1530` VALUES ('2', '{4823EF1D-80A6-4E53-913C-530B14C9F0A0}', '60', 'INHE-0680', '2018-01-16 11:17:16', '0000-00-00 00:00:00', '2018-01-18 10:51:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018011602/立项申请/MAV', '', 'MAV Trade Plus', 'MAV', '吉尔吉斯斯坦', 'Kanybek Kenzhebaev', '996 772853322', 'levkg@mail.ru', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', null);
INSERT INTO `crs_tabledata1530` VALUES ('3', '{079A415B-5141-4099-B5D8-48CA10B50450}', '61', 'INHE-0440', '2018-01-22 14:14:13', '0000-00-00 00:00:00', '2018-01-24 08:39:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012202/TTN', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。', '{079A415B51414099B5D848CA10B5045011015FBC745F4B1982FBEF12F4BBACD1}_Fida Hussein Rashid.docx', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），预算金额约为2000万美元（DDP）价格条款。', '{079A415B51414099B5D848CA10B50450FFC3E6BB8328443AA9AAC603FC047FE8}_REPORT  OF THE CONROLLER AND AUDITOR  GENERAL  ON THE CONSOLIDATED  FINANCIAL  STATEMENTS 2014-15.pdf', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('4', '{733B3315-DF77-4B15-A83E-EF9FD7A55274}', '60', 'INHE-0680', '2018-01-23 10:55:09', '0000-00-00 00:00:00', '2018-01-24 14:22:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012303/DOSH', '', 'MAV Trade Plus', 'MAV', '吉尔吉斯斯坦', 'Kanybek Kenzhebaev', '996 772853322', 'levkg@mail.ru', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', null);
INSERT INTO `crs_tabledata1530` VALUES ('5', '{ABD0FBCA-0F6F-43C3-A467-4F1450A6D464}', '61', 'INHE-0500', '2018-01-29 10:20:19', '0000-00-00 00:00:00', '2018-02-01 09:03:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012902/ERED', '', 'Pre-Paid Mobile Vending Solutions cc', 'PPM', '纳米比亚', 'Richard N Gaoseb', '+264812754478', 'rgaoseb@yahoo.com', '1.成立于2009年，纳米比亚本地中小型私营公司，主营业务为：纳米比亚第三方通讯服务和售电服务提供商，有ICT技术背景，之前和南非一家ICT公司Expertron合作过Airtime第三方通讯服务业务；2.BEE等级：公司所有权100%纳米比亚黑人，管理层100%纳米比亚黑人，等级较高（纳米比亚本地招标对BEE资质是强制性要求）；', '', 'Erongo Regional Electricity Distributor Company (Pty) Ltd', 'ERONGO', '纳米比亚', 'Mrs. A Welgemoed', '+26464214600', 'N/A', '1.Namibia市场 6个主要售电公司之一，属于半国营企业，公司主要股东为NamPower（纳米比亚唯一国有发电和输电公司）和地区区域政府，售电管理区域主要为Walvis Bay,Swakopmund,Henties Bay,Arandis,Karibib,Usakos和Omaruru,总电力用户数量为45400个，其中商业用表数量为3500个，LPU用表数量为400个；2.Erongo当前电表一半比例为兰吉尔和Itron的Cashpower分体式代码表，另外一半仍是机械式电表和插座式代码表，售电系统为南非公司Syntell提供，功能陈旧；3.Erongo本地招标对BEE资质有强制性要求，投标者必须要满足纳米比亚BEE资质（本地黑人一定所有权和管理权等，等级越高评分越高）。', '', 'Pre-Paid Mobile Vending Solutions cc', 'PPM', '纳米比亚', 'Richard N Gaoseb', '+264812754478', 'rgaoseb@yahoo.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('6', '{6019F102-4306-4C94-B645-FE5DD6EBEE9B}', '61', 'INHE-0593', '2018-01-29 13:23:40', '0000-00-00 00:00:00', '2018-02-01 16:07:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012903/EGP', '', 'ZENS Distribution Limited', 'zens', '中国', 'Arthur Lam', '852 9276 6128', 'arthur.lam@zens.com.hk', 'ZENS Distribution Limited成立于2014年，香港企业，致力于提升客户网络安全等级/数据库安全等级/app安全等级方面的服务，同时也为客户提供其他网络管理方案', '', 'ZENS Distribution Limited', 'zens', '中国', 'Arthur Lam', '852 9276 6128', 'arthur.lam@zens.com.hk', 'ZENS Distribution Limited成立于2014年，香港企业，致力于提升客户网络安全等级/数据库安全等级/app安全等级方面的服务，同时也为客户提供其他网络管理方案。', '', 'ZENS Distribution Limited', 'zens', '中国', 'Arthur Lam', '852 9276 6128', 'arthur.lam@zens.com.hk', null);
INSERT INTO `crs_tabledata1530` VALUES ('7', '{3964B83D-45CC-480F-88B3-822E631797F1}', '60', 'INHE-0560', '2018-01-29 11:06:34', '0000-00-00 00:00:00', '2020-07-03 15:10:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2018012901/SUM', '', 'OOO \"Shinavanda-Savdo\"', 'OOO \"Shinavanda-Savdo\"', '乌兹别克斯坦', 'Бобур Умаров', '+99871 291 12 21', 'bobur-aka@mail.ru', 'OOO \"Shinavanda-Savdo\"公司是一家主要从事电力设备供应及销售的企业#FE54`经营产品包括电能表，水表，气表，电缆，电流互感器等。在乌兹别克斯坦拥有强大的分销渠道及经营门店，用户种类多涉及终端用户，工业用户，商业用户及电力公司，且需求稳定。该公司现在其国内大力推广宣传其产品，发展其实力。Бобур Умаров为该公司总经理及创始人，其毕业于乌兹别克斯坦国际关系学院，2001-2007年在塔斯社担任记者，2007年开始在俄罗斯创业，于2010年创办OOO \"Shinavanda-Savdo\"公司，并被评为“乌兹别克斯坦杰出企业家100强”，该公司现在乌兹别克斯坦境内电力设备销售市场上拥有广泛且稳定的客户群体，占有较大的市场份额。其总经理为实干型企业家，具有敏锐的商业头脑及开拓精神。', '', '', '', '', '', '', '', '', '', 'OOO \"Shinavanda-Savdo\"', 'OOO \"Shinavanda-Savdo\"', '乌兹别克斯坦', 'Бобур Умаров', '+99871 291 12 21', 'bobur-aka@mail.ru', null);
INSERT INTO `crs_tabledata1530` VALUES ('8', '{89A6A78B-9323-4441-A5E8-8BA139D6FEA9}', '61', 'INHE-0578', '2018-02-01 09:37:45', '0000-00-00 00:00:00', '2018-02-06 08:52:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020101/TSE', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '{89A6A78B93234441A5E88BA139D6FEA9FFC3E6BB8328443AA9AAC603FC047FE8}_1. Copy of 17.01.2018 电表--兰吉尔+CONLOG.xlsx', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', null);
