INSERT INTO `crs_tabledata1530` VALUES ('10', '{E4011D23-7EF1-4901-9939-F423B146AE8E}', '61', 'INHE-0374', '2018-02-05 03:23:27', '0000-00-00 00:00:00', '2018-02-07 11:30:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020501/MTD', '', 'GLOBAL ENGINEERING ENERGY and CONSTRUCTION', 'GEEC', '突尼斯', 'Adnen', '0021626705333', 'adnen.benhacine@gmail.com', '突尼斯智能能源智能家居公司，主要代理欧洲意大利比利时智能用电管理系统（针对公司等大客户），智能家居（针对家庭），总部在突尼斯，在北非阿尔及利亚、利比亚、摩洛哥、西非科特迪瓦有分公司。在电力公司以及能源部有不错关系基础，有建厂合作意愿。', '', 'GLOBAL ENGINEERING ENERGY and CONSTRUCTION', 'GEEC', '突尼斯', 'Adnen', '0021626705333', 'adnen.benhacine@gmail.com', '突尼斯智能能源智能家居公司，主要代理欧洲意大利比利时智能用电管理系统（针对公司等大客户），智能家居（针对家庭），总部在突尼斯，在北非阿尔及利亚、利比亚、摩洛哥、西非科特迪瓦有分公司。在电力公司以及能源部有不错关系基础，有建厂合作意愿。', '', 'GLOBAL ENGINEERING ENERGY and CONSTRUCTION', 'GEEC', '突尼斯', 'Adnen', '0021626705333', 'adnen.benhacine@gmail.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('11', '{73E7FEC3-6449-4476-9C12-FED13B37E7B5}', '61', 'INHE-0432', '2018-02-06 10:57:10', '0000-00-00 00:00:00', '2018-02-07 11:44:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020601/KE03', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', 'KPLC在过去5年采购量过大，导致财政吃紧，付款延迟。但KPLC已意识到这个问题，自2018年起将控制采购俩，缓解财政压力。随着2018年政局稳定，经济发展加速，预计工业用电的用户和电量将增加，将能较好改善KPLC现金状况。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', null);
INSERT INTO `crs_tabledata1530` VALUES ('12', '{32DEE2E7-84F9-4D7B-8D0E-77AE529BB740}', '60', 'INHE-0399', '2018-02-07 15:21:10', '0000-00-00 00:00:00', '2018-02-08 11:45:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018020702/WZT', '', 'Ideal Enterprise', '', '孟加拉', 'A.K.Sarker', '00880 2 9551938/9569467', 'sarkerak@gmail.com', '', '{32DEE2E784F94D7B8D0E77AE529BB74011015FBC745F4B1982FBEF12F4BBACD1}_Trade Licence (Business licence)  English Verson.pdf', 'West Zone Power Distributin Company Limited', 'WZPDCL', '孟加拉国', 'Md.Rakibul Islam', '008801721197674', 'rakibislam04@gmail.com', '孟加拉西部电力公司，用户数100万，负责孟加拉西部地区的供电。', '', 'West Zone Power Distributin Company Limited', 'WZPDCL', '孟加拉国', 'Md.Rakibul Islam', '008801721197674', 'rakibislam04@gmail.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('13', '{F5B385E0-A315-42E5-917E-70E57B21BB32}', '66', 'JXINHE-2559', '2018-02-24 10:02:48', '0000-00-00 00:00:00', '2018-02-25 08:58:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022402/MVB', '', 'VBC Limitada', 'VBC', '莫桑比克', 'Adelino Daúde', '+258 494232', 'adaude@vbc.co.m', 'VBC是一家100%的莫桑比克本土公司，产品涉及电信通讯，移动设备，生物和能源技术。获得IGSQ奖项及2011全非奥运会官方供应商。', '', 'Eletricidadede Mo ambique', 'EDM', '莫桑比克', 'Benjamim Manuel', '+25821430916', 'benjamim.fernandes@edm.co.mz', '1995年莫桑比克国家电力公司（EDM）成立，管理全国用户数量（2011年数据）101万户，员工人数3402人，营业收入2.8亿美元。国家面临着电力基础设施投资落后于经济发展速度的现状,与其他非洲国家相比,莫桑比克具有相对稳定的政治环境,经济持续恢复性增长,投资法律环境较为健全,电力行业急需外部资金和技术进入,以加快电力基础设施项目建设,满足其经济发展的需要。', '', 'Eletricidadede Mo ambique', 'EDM', '莫桑比克', 'Benjamim Manuel', '+25821430916', 'benjamim.fernandes@edm.co.mz', null);
INSERT INTO `crs_tabledata1530` VALUES ('14', '{D6FFB9CB-B870-4E5E-B9E2-3C96B75DE536}', '60', 'INHE-0680', '2018-02-24 11:02:36', '0000-00-00 00:00:00', '2018-02-27 10:47:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022403/MAV', '', 'MAV Trade Plus', 'MAV', '吉尔吉斯斯坦', 'Kanybek Kenzhebaev', '996 772853322', 'levkg@mail.ru', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', 'MAV Trade Plus', 'MAV', '吉尔吉斯斯坦', 'Kanybek Kenzhebaev', '996 772853322', 'levkg@mail.ru', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。');
INSERT INTO `crs_tabledata1530` VALUES ('15', '{BDADBBA9-9592-4705-8AEF-5FAD16723867}', '60', 'INHE-0680', '2018-02-24 15:29:04', '0000-00-00 00:00:00', '2018-02-25 17:35:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022404/MAVN', '', 'MAV Trade Plus', 'MAV', '吉尔吉斯斯坦', 'Kanybek Kenzhebaev', '996 772853322', 'levkg@mail.ru', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。', '', '北方电力severelectro', 'severelectro', '吉尔吉斯斯坦', 'Таалайбек Койбагаров', '996 555008267', 'ms_severelectro@mail.ru', '吉尔吉斯斯坦的首都北方电力公司（ОАО \"Северэлектро\" www.severelectro.kg）约60万用户，的招投标项目，招标产品主要为三相表直通表和三相CT表。产品在测试的过程中出现了一些不符点，比如对继电器的设置、停电显示并且将最后的显示数据上传至系统等需要修改电表的程序，而且需要的时间相对比较长。后续该电力公司的产品招标项目会继续按照这个技术规格来完成，需要根据相应的技术规格来修改电表的程序，以满足电力公司的需求。', '', '北方电力severelectro', 'severelectro', '吉尔吉斯斯坦', 'Таалайбек Койбагаров', '996 555008267', 'ms_severelectro@mail.ru', null);
INSERT INTO `crs_tabledata1530` VALUES ('16', '{BFDF561E-FE93-486F-9ACF-47D6612E6355}', '61', 'INHE-0593', '2018-02-25 09:11:44', '0000-00-00 00:00:00', '2018-02-26 18:40:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018022501/BFN10', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', null);
