INSERT INTO `crs_tabledata1530` VALUES ('18', '{F5119609-35B0-40A9-9268-1E2381DA3CE9}', '61', 'INHE-0662', '2018-03-05 14:59:37', '0000-00-00 00:00:00', '2018-03-05 16:42:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030501/DAN', '立项目的何在？需要做什么？如何做？不能弄个询盘就立项。', 'Danke Electricals Ltd', 'Danke', '印度', 'Amit Patel', '919879113901', 'amit.patel@dankepower.com', '印度古吉拉特邦的一家变压器公司，拥有自己的变压器工厂，跟印度电力能源部有一定关系，看重印度市场潜力巨大的电表市场，想跟银河合作在该邦建厂。', '', '', '', '', '', '', '', '', '{F511960935B040A992681E2381DA3CE9FFC3E6BB8328443AA9AAC603FC047FE8}_DANKE GROUP - BROUCHER.pdf', 'Danke Electricals Ltd', 'Danke', '印度', 'Amit Patel', '919879113901', 'amit.patel@dankepower.com', '印度古吉拉特邦的一家变压器公司，拥有自己的变压器工厂，跟印度电力能源部有一定关系，看重印度市场潜力巨大的电表市场，想跟银河合作在该邦建厂。');
INSERT INTO `crs_tabledata1530` VALUES ('19', '{53B6CC69-CB66-4F81-AF87-B6F37428B45D}', '66', 'INHE-0579', '2018-03-05 17:20:36', '0000-00-00 00:00:00', '2018-03-07 10:33:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030503/LOP', '', 'SHARP MINDS SAL', 'E24', '黎巴嫩', 'Elias Haddad', '+961-1-492705', 'elias.haddad@e24solutions.com', 'SHARP MINDS SAL是E24在中东&非洲的子公司。E24是一家提供能源解决方案公司，主要致力于太阳能可再生能源和储存能源项目设计和执行。业务涉及智能家居，智能电网（为工厂，村庄，建筑楼，通讯公司等提供电力储备方案）等。在北美，欧亚，欧洲，中东，非洲均有分公司。我们的客户是中东&非洲区的子公司。', '', '', '', '', '', '', '', '', '', 'SHARP MINDS SAL', 'E24', '黎巴嫩', 'Elias Haddad', '+961-1-492705', 'elias.haddad@e24solutions.com', 'SHARP MINDS SAL是E24在中东&非洲的子公司。E24是一家提供能源解决方案公司，主要致力于太阳能可再生能源和储存能源项目设计和执行。业务涉及智能家居，智能电网（为工厂，村庄，建筑楼，通讯公司等提供电力储备方案）等。在北美，欧亚，欧洲，中东，非洲均有分公司。我们的客户是中东&非洲区的子公司。');
INSERT INTO `crs_tabledata1530` VALUES ('20', '{06283B7B-9CCA-40CB-B33C-EE8E0196AE28}', '60', 'INHE-0601', '2018-03-09 17:15:43', '0000-00-00 00:00:00', '2018-03-12 13:08:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2018030902/PIK', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。', '', '', '', '', '', '', '', '', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。');
INSERT INTO `crs_tabledata1530` VALUES ('21', '{94089D0B-0E04-40F7-A41D-4B9AC8AF2950}', '61', 'INHE-0642', '2018-03-14 00:00:27', '0000-00-00 00:00:00', '2018-03-22 09:19:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031401/JJN', '', 'Process * Plant Automation Limited', 'PPA', '加纳', 'Adika', '+233269104398', 'kadika@automationghana.com', '以前在加纳有过合作项目，属于老客户范畴。现在PPA打算和我司在加纳MCA项目中合作。该公司在2003年设立，公司员工超过120人以上，主要业务包括电力建设，电力设备供应等，其在加纳市场电力公司有一定的关系网络。目前的主要联系人为该公司销售经理。', '', 'Millennium Development Authority', 'MiDA', '加纳', 'Head OfficeMillennium Development Authority', '+(233) 302 666619,', 'info@mida.gov.gh,procurement@mida.gov.gh', 'MiDA以The Government of Ghana Millennium Challenge Account 名义实施项目， Millennium Challenge Account 实属美国千禧年公司旗下，用以资金援建非洲地区的机构。该机构由Millennium Development Authority (MiDA)监督、管理和实施项目。2014年，MCC和加纳政府达成援助协议，援助金额为US$ 498,200,000，用以帮助加纳经济增长以及消除贫困。', '', 'Millennium Development Authority', 'MiDA', '加纳', 'Head OfficeMillennium Development Authority', '+(233) 302 666619,', 'info@mida.gov.gh,procurement@mida.gov.gh', 'MiDA以The Government of Ghana Millennium Challenge Account 名义实施项目， Millennium Challenge Account 实属美国千禧年公司旗下，用以资金援建非洲地区的机构。该机构由Millennium Development Authority (MiDA)监督、管理和实施项目。2014年，MCC和加纳政府达成援助协议，援助金额为US$ 498,200,000，用以帮助加纳经济增长以及消除贫困。');
INSERT INTO `crs_tabledata1530` VALUES ('22', '{2C2F85D1-8EA5-4B39-B189-73664E5C51D9}', '61', 'INHE-0434', '2018-03-14 17:01:43', '0000-00-00 00:00:00', '2018-03-15 17:05:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031402/AJA', '', 'Denex Trading (PTY) LTD', 'DENEX', '南非', 'JOSE TATI', '0027212761200', 'JoseTati@jedig.biz', '董事长JOSE与施耐德合作起家，从事电表业务多年，公司Denex在南非，在安哥拉有一公司JTDL Holding。JOSE与莫三比克EDM及安哥拉ENDE高层有一定关系', '', '', '', '', '', '', '', '', '', 'Denex Trading (PTY) LTD', 'DENEX', '南非', 'JOSE TATI', '0027212761200', 'JoseTati@jedig.biz', '董事长JOSE与施耐德合作起家，从事电表业务多年，公司Denex在南非，在安哥拉有一公司JTDL Holding。JOSE与莫三比克EDM及安哥拉ENDE高层有一定关系');
INSERT INTO `crs_tabledata1530` VALUES ('23', '{089A5E46-0B1D-49A7-A480-4934F098EEC4}', '60', 'INHE-0535', '2018-03-14 16:18:44', '0000-00-00 00:00:00', '2018-04-24 14:16:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031403/JPM', 'JPM', 'JAY AUTOCOMPONENTS LIMITED', 'JAC', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '', 'Energy Efficiency Services Limited', 'EESL', '印度', 'Ajay Kumar Sharma', '0120-4908000', 'asharma1@eesl.co.in', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；2.	执行中央或邦政府或其代理机构的计划，项目和政策；3.	与私有ESCOs和其他公司合作促进能源效率；4.	在能源效率，CDM项目和其他有关领域提供咨询服务；5.	传授培训，培养股东能力。', '', 'JAY AUTOCOMPONENTS LIMITED', 'JAC', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。');
INSERT INTO `crs_tabledata1530` VALUES ('24', '{F56E8DF5-BAD9-4AB3-BCCD-318E4D2157E6}', '66', 'JXINHE-2559', '2018-03-16 17:11:08', '0000-00-00 00:00:00', '2018-04-11 15:49:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031601/MSG', '', 'Season Malaysia Manufacturing Sdn Bhd', 'SEASON', '马来西亚', 'TAN ENG SAI', '6043997888ext127', 'es.tan@seasongroup.com', 'SEASON GROUP集团下属的生产企业，主要从事于定制化生产和机械服务，在美国，加拿大，墨西哥，英国，中国和马来西亚有分厂，员工人数1800人，占地约80万平方英尺。', '', '', '', '', '', '', '', '', '', 'Season Malaysia Manufacturing Sdn Bhd', 'SEASON', '马来西亚', 'TAN ENG SAI', '6043997888ext127', 'es.tan@seasongroup.com', 'SEASON GROUP集团下属的生产企业，主要从事于定制化生产和机械服务，在美国，加拿大，墨西哥，英国，中国和马来西亚有分厂，员工人数1800人，占地约80万平方英尺。');
INSERT INTO `crs_tabledata1530` VALUES ('25', '{CA476E26-04C7-4233-973D-43476846E5F2}', '60', 'INHE-0514', '2018-03-16 15:38:02', '0000-00-00 00:00:00', '2018-03-22 09:08:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031603/OMA', '', 'Bahwan Projects & Telecoms  LLC', 'BPT', '阿曼', 'Ravinder Raina', '0096824650475', 'ravinder.r@suhaibahwangroup.com', 'Bahwan Projects & Telecoms  LLC为阿曼四大家族企业SBGH集团下属的一家子公司，主要从事通信与工程项目承包，在中东区域都设有子公司，实力较好；', '{CA476E2604C74233973D43476846E5F211015FBC745F4B1982FBEF12F4BBACD1}_Bahwan Group&BPT.zip', 'Majan Electricity Conpany', '', '阿曼', 'Said', '0096899855685', '', 'Majan电力公司是阿曼三大配电公司之一（MEDC, Majan，Mazoon），负责阿曼北部地区的供电，包括Albatinah区域，Al-Dhahirah区域以及Buraimi省，成立于2005年。', '{CA476E2604C74233973D43476846E5F2FFC3E6BB8328443AA9AAC603FC047FE8}_Majan Information.zip', 'Bahwan Projects & Telecoms  LLC', 'BPT', '阿曼', 'Ravinder Raina', '0096824650475', 'ravinder.r@suhaibahwangroup.com', 'Bahwan Projects & Telecoms  LLC为阿曼四大家族企业SBGH集团下属的一家子公司，主要从事通信与工程项目承包，在中东区域都设有子公司，实力较好；');
INSERT INTO `crs_tabledata1530` VALUES ('26', '{FD1775D4-B70B-4952-B3CC-C49529844674}', '66', 'INHE-0634', '2018-03-19 14:08:24', '0000-00-00 00:00:00', '2019-02-28 16:13:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018031901/TOD', '', 'Alpha Power Engineering CO., ltd', 'ALPHA', '缅甸', 'MYINT TUN NAING', '09254899953', 'myinttunnaing@alphapowerengineering.com', '阿尔法电力工程有限公司是缅甸仰光一家EPC公司，成立于2010年，有多次参与电力公司投标经验，当地关系网络相对成熟。是LS（智能能源）, CEWE（电力监测仪器和传感器和电力管理系统）, Secure,（电力监控） Commax（智能家居）等品牌分销商。产品：供应245kV的分站设备（气体断路器，断路开关，电流互感器，电压互感器，避雷器和电力变压器）；245kV ACSR，AAC，HDBC，和相关配件等。供应控制面板，电池组和充电器、电力线载波（PLCC设备）、电源线和电缆附件（400V至66kV）XLPE，SWA，AWA，Cu，PVC端接套件和接头，保护继电器和电表。官网：http://alphapowerengineering.com/', '{FD1775D4B70B4952B3CCC4952984467411015FBC745F4B1982FBEF12F4BBACD1}_Alpha Company Presentation.pdf', 'Electricity Supply Enterprise', 'ESE', '缅甸', '', '', '', '缅甸内比都电力局。内比都是缅甸首都，人口约115.8万。', '', 'Alpha Power Engineering CO., ltd', 'ALPHA', '缅甸', 'MYINT TUN NAING', '09254899953', 'myinttunnaing@alphapowerengineering.com', '阿尔法电力工程有限公司是缅甸仰光一家EPC公司，成立于2010年，有多次参与电力公司投标经验，当地关系网络相对成熟。是LS（智能能源）, CEWE（电力监测仪器和传感器和电力管理系统）, Secure,（电力监控） Commax（智能家居）等品牌分销商。产品：供应245kV的分站设备（气体断路器，断路开关，电流互感器，电压互感器，避雷器和电力变压器）；245kV ACSR，AAC，HDBC，和相关配件等。供应控制面板，电池组和充电器、电力线载波（PLCC设备）、电源线和电缆附件（400V至66kV）XLPE，SWA，AWA，Cu，PVC端接套件和接头，保护继电器和电表。官网：http://alphapowerengineering.com/');
INSERT INTO `crs_tabledata1530` VALUES ('27', '{E1EA356B-A568-46CD-9E66-27B51066513E}', '61', 'INHE-0695', '2018-03-20 10:57:18', '0000-00-00 00:00:00', '2018-03-22 09:20:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032001/SLV', '', 'TRANSTECH, A.S.', 'Transtech SK', '斯洛伐克', 'Stanislav Hutnan', '', 'hutnan@transtech-sk.eu', '斯洛伐克经销商，为摩尔多瓦电表厂ADD GRUP在斯洛伐克的代理，曾在2015年帮助其拿下电力公司VSD Slovakia的招标（14000台智能电表）。2015年公司收入为220万欧元，雇员为7人。参与过两个欧盟资助的调研项目，也被斯洛伐克本地媒体有所报道过。', '', '', '', '', '', '', '', '', '', 'TRANSTECH, A.S.', 'Transtech SK', '斯洛伐克', 'Stanislav Hutnan', '', 'hutnan@transtech-sk.eu', '斯洛伐克经销商，为摩尔多瓦电表厂ADD GRUP在斯洛伐克的代理，曾在2015年帮助其拿下电力公司VSD Slovakia的招标（14000台智能电表）。2015年公司收入为220万欧元，雇员为7人。参与过两个欧盟资助的调研项目，也被斯洛伐克本地媒体有所报道过。');
INSERT INTO `crs_tabledata1530` VALUES ('28', '{F0D9CA6F-33ED-486A-9A12-638ADA09518A}', '88', 'INHE-0091', '2018-03-21 10:23:49', '0000-00-00 00:00:00', '2018-03-26 08:36:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032101/DAK\r\n', '', '', '', '', '', '', '', '', '', 'Rural Electrification Authority', 'REA', '肯尼亚', 'JOEL OMUSEBE （Ag. HEAD OF PROCUREMENT）', '00 254-20-2710955/2713921', 'info@rea.co.ke#FE54` procurement@rea.co.ke', 'REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金●制定和更新农村电气化总体规划REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金●制定和更新农村电气化总体规划●考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。●实施农村电气化项目和寻找额外资金●管理农村电气化牌照和许可，招标和合同授予						考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。实施农村电气化项目和寻找额外资金管理农村电气化牌照和许可，招标和合同授予', '{F0D9CA6F33ED486A9A12638ADA09518AFFC3E6BB8328443AA9AAC603FC047FE8}_DAK项目招标文件.pdf', 'Rural Electrification Authority', 'REA', '肯尼亚', 'JOEL OMUSEBE （Ag. HEAD OF PROCUREMENT）', '00 254-20-2710955/2713921', 'info@rea.co.ke#FE54` procurement@rea.co.ke', 'REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金●制定和更新农村电气化总体规划REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金REA负责肯尼亚农村地区的电力建设：●管理农村/电气化计划基金●制定和更新农村电气化总体规划●考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。●实施农村电气化项目和寻找额外资金●管理农村电气化牌照和许可，招标和合同授予						考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。实施农村电气化项目和寻找额外资金管理农村电气化牌照和许可，招标和合同授予');
INSERT INTO `crs_tabledata1530` VALUES ('29', '{CF07B0A1-7F8B-43F4-8F31-CBE700BED320}', '61', 'INHE-0432', '2018-03-22 21:46:54', '0000-00-00 00:00:00', '2018-03-27 17:31:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032202/SKI', '', 'Safaricom Public Limited Company', 'Safaricom', '肯尼亚', 'Murrey Manases', '+254 721 145 457', 'MMurrey@Safaricom.co.ke', '1.肯尼亚最大的通讯运营商                                                                                                       2.目前移动用户数量约为2800万，占肯尼亚总人口数（约4000万）的70%。                                                              3.股东结构：英国沃达丰集团占股40%、肯尼亚政府占股35%、社会投资占股25%。                                                        4.2007年推出电子钱包支付M-PESA（类似于中国的支付宝、微信），目前注册用户约2700万，全国有13万多个代售点。2017年M-PESA交易额达到约690亿美元。                                                                                                     ', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '1.肯尼亚电力公司还剩400万机械表用户，待换成预付费电表或者直接升级为智能电表。                           2.Safaricom作为本土最大的通讯运营商，在PZ03项目时与银河谈过合作，也看到了智能电表里通讯项目的机会，如SIM卡、流量、用户大数据等。                                                                              3.Safaricom最近和KPLC洽谈，KPLC要Safaricom找到合适的电表厂商，开发低成本、通讯性能稳定、适合集抄的电表产品，然后就可以合作，将400万机械表升级为智能电表。此次Safaricom希望同银河合作，希望银河开发出满足KPLC要求的电表产品。鉴于GPRS模块价格较昂贵，其推荐NB-IOT通讯方案，认为其模块成本较低，通讯性能较稳定。希望银河能尽快提供样机，供Safaricom在其实验室测试。测试通过后将再与KPLC谈合作：银河卖电表，safaricom卖SIM卡及流量、获取用户大数据等                         ');
INSERT INTO `crs_tabledata1530` VALUES ('30', '{D4C649C9-17FA-409C-960A-18A544F6567B}', '60', 'INHE-0560', '2018-03-27 18:37:28', '0000-00-00 00:00:00', '2018-04-24 14:16:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032701/SVA', '', 'Iskraemeco d.d.', 'Iskra', '斯洛文尼亚', 'Ihab Mohkes', '+2010 688 144 16', 'Ihab.Mokhles@iskraemeco.com', 'Iskraemeco 成立于1945年，主要从事先进表计计量产品的设计与生产并拥有强大的研发实力，现已经在全球范围内安装了7500万台电表，其产品种类齐全，包括表计产品，软件系统等，通信方案，其在欧洲表计市场上占有一定的市场份额，综合实力较强。2007年，Iskraemeco与Elsewedy Electric联手，进一步增强了其在欧洲表计市场上的实力。', '', '', '', '', '', '', '', '', '', 'Iskraemeco d.d.', 'Iskra', '斯洛文尼亚', 'Ihab Mohkes', '+2010 688 144 16', 'Ihab.Mokhles@iskraemeco.com', '斯洛文尼亚ISKRAEMECO公司成立于1945年，是欧洲第三大表计生产厂家和世界第五位电能表供应商，其表计和采集器产品具有很高的市场占有率，产品遍布5大洲100多个国家和地区（包括中国和香港地区）。ISKRAEMECO公司现有2100多名员工，在国外拥有10个分厂、3个特许生产企业和5个贸易公司，2002年销售额达到1.076亿欧元。');
INSERT INTO `crs_tabledata1530` VALUES ('31', '{64F10960-953E-49D5-85B9-28B4044FA1BE}', '61', 'INHE-0374', '2018-03-28 17:37:21', '0000-00-00 00:00:00', '2018-03-29 16:48:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032801/SNN', '', 'Inter Global Technology Services', 'IGTS', '塞内加尔', 'Ndiaye Thieyacine', '221776242463', 'thieyacinen@yahoo.fr', '电信代理公司，与SN电力公司总经理以及能源部长有良好的关系。', '', 'Inter Global Technology Services', 'IGTS', '塞内加尔', 'Ndiaye Thieyacine', '221776242463', 'thieyacinen@yahoo.fr', '电信代理公司，姐弟二人，五十多岁，与SN电力公司总经理关系不错。此前曾经在科特迪瓦经营可可豆工厂十余年，财力较强，现在回塞内加尔创业，在塞国有很多人脉，此前没有过电表类业务经验。计划采购生产设备建厂供应电力公司电表产品直采。', '', 'Inter Global Technology Services', 'IGTS', '塞内加尔', 'Ndiaye Thieyacine', '221776242463', 'thieyacinen@yahoo.fr', '电信代理公司，与SN电力公司总经理关系不错。');
INSERT INTO `crs_tabledata1530` VALUES ('32', '{EFC395FF-355F-48AF-8D0E-FCAA61822451}', '61', 'INHE-0381', '2018-03-29 01:45:08', '0000-00-00 00:00:00', '2018-04-02 09:27:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032901/AOR', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司。由法国公司VEOLIA控股。', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('33', '{5042C5C2-7CCD-4B4D-8684-444FE09BAF76}', '61', 'INHE-0434', '2018-03-29 14:16:15', '0000-00-00 00:00:00', '2018-03-29 16:54:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032903/APN', '', 'Crown Resources Development Company', 'CREDCO', '尼日利亚', 'Steve Ogirima', '08030626464', 'steve@a4networks.com.ng', '1. 公司于1998年成立，主营电气工程项目。涉及产品供货，产品本地安装(输变线，变压器，电表等)，试运行，后期维护。2. 该公司和浙江登立(DENGLI)有合作。', '', '', '', '', '', '', '', '', '', 'Crown Resources Development Company', 'CREDCO', '尼日利亚', 'Steve Ogirima', '08030626464', 'steve@a4networks.com.ng', '1. 公司于1998年成立，主营电气工程项目。涉及产品供货，产品本地安装(输变线，变压器，电表等)，试运行，后期维护。2. 该公司和浙江登立(DENGLI)有合作。');
INSERT INTO `crs_tabledata1530` VALUES ('34', '{8F8580FD-C931-465D-8624-E78FA6158D03}', '61', 'INHE-0654', '2018-03-29 13:34:45', '0000-00-00 00:00:00', '2018-03-30 09:03:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2018032904/CHE', '', 'EDALTEC - EMPRESAS DE ALTA TECNOLOGíA', '', '智利', 'Juan José Navarro', '+56 9 4477 1393', '', 'EDALTEC是一家电力软件和通讯服务的供应商。', '', '', '', '', '', '', '', '', '', 'EDALTEC - EMPRESAS DE ALTA TECNOLOGíA', '', '智利', 'Juan José Navarro', '+56 9 4477 1393', '', 'EDALTEC是一家电力软件和通讯服务的供应商。');
INSERT INTO `crs_tabledata1530` VALUES ('35', '{5925D6FA-0D13-456F-A870-F87ECB8E2AC3}', '61', 'INHE-0695', '2018-03-30 09:04:41', '0000-00-00 00:00:00', '2018-04-02 09:12:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2018033001/EGC', '', 'Elgama sistemos, UAB.', 'Elgsis', '立陶宛', 'Pavel Latvis', '+370 5 232 8000', 'pavel.latvis@elgsis.com', '立陶宛当地的一个能源管理系统方案提供商，主要做AMI/AMR软件方面。成立于1994年，在2002年的时候联同当地伙伴公司推出了立陶宛第一个电表抄读系统，有超过3000个计量点接入，通信方式主要为GSM/GPRS，辅助为PSTN及以太网主要业务地区为波罗的海三国，部分欧洲国家（白俄罗斯,波兰，希腊，西班牙）以及南美国家（哥伦比亚，玻利维亚，巴拉圭）公司只无生产电表的 能力，因此也在寻找合适的电表厂商一起合作。对合作表现出了较强烈的愿望，对我们具有DLMS以及MID认证比较看重。公司整体体量及规模不算太大，但可作为银河在欧洲市场的一个切入点。', '{5925D6FA0D13456FA870F87ECB8E2AC311015FBC745F4B1982FBEF12F4BBACD1}_NAVITUS presentation 2018-01-23.pdf', '', '', '', '', '', '', '', '', 'Elgama sistemos, UAB.', 'Elgsis', '立陶宛', 'Pavel Latvis', '+370 5 232 8000', 'pavel.latvis@elgsis.com', '立陶宛当地的一个能源管理系统方案提供商，主要做AMI/AMR软件方面。成立于1994年，在2002年的时候联同当地伙伴公司推出了立陶宛第一个电表抄读系统，有超过3000个计量点接入，通信方式主要为GSM/GPRS，辅助为PSTN及以太网主要业务地区为波罗的海三国，部分欧洲国家（白俄罗斯,波兰，希腊，西班牙）以及南美国家（哥伦比亚，玻利维亚，巴拉圭）公司只无生产电表的 能力，因此也在寻找合适的电表厂商一起合作。对合作表现出了较强烈的愿望，对我们具有DLMS以及MID认证比较看重。公司整体体量及规模不算太大，但可作为银河在欧洲市场的一个切入点。');
INSERT INTO `crs_tabledata1530` VALUES ('36', '{3D8A39F7-70E5-4515-B3F8-9C1224B13CF0}', '60', 'INHE-0549', '2018-04-02 09:29:48', '0000-00-00 00:00:00', '2018-04-02 15:57:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040201/JVE', '', '乐清市俊威电气有限公司', '俊威电气', '中国', '李林', '15067740790', 'peterli@jvele.com', '我司差动断路器供应商之一，与我司在KM项目有合作。', '', '', '', '', '', '', '', '', '', '乐清市俊威电气有限公司', '俊威电气', '中国', '李林', '15067740790', 'peterli@jvele.com', '我司差动断路器供应商之一，与我司在KM项目有合作。');
