INSERT INTO `crs_tabledata1530` VALUES ('39', '{DD495390-9866-4A9E-94AE-A3AE74B26F9D}', '61', 'INHE-0578', '2018-04-08 16:42:15', '0000-00-00 00:00:00', '2018-04-09 10:48:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2018040804/EXJ', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', 'matsotso.vuso@nyamezela.co.za', '实际签合同公司为Nyamezela Metering Pty Ltd,银河在南非市场最大合作伙伴（目前南非唯一合作伙伴）。NYC与银河已有逾7年合作历史，历史执行ZEC2项目，目前正在执行N4工厂、ESA项目。合作以来能够与银河保持一致的市场追求，为获取订单投资（建厂、客户关系、宣传等），对银河付款较为及时，未有拖欠货款等现象。', '', '', '', '', '', '', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', 'matsotso.vuso@nyamezela.co.za', '实际签合同公司为Nyamezela Metering Pty Ltd,银河在南非市场最大合作伙伴（目前南非唯一合作伙伴）。NYC与银河已有逾7年合作历史，历史执行ZEC2项目，目前正在执行N4工厂、ESA项目。合作以来能够与银河保持一致的市场追求，为获取订单投资（建厂、客户关系、宣传等），对银河付款较为及时，未有拖欠货款等现象。');
INSERT INTO `crs_tabledata1530` VALUES ('40', '{6B6BBF6F-DCD3-4E5F-BD4D-19F3914788B4}', '61', 'INHE-0654', '2018-04-10 16:57:29', '0000-00-00 00:00:00', '2018-04-12 08:43:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041101/ADD', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', 'Edenor S.A.', '', '阿根廷', 'Juliana Estefania MATA', '4346-5400', '', '阿根廷最大的电力公司，总部在首都布宜诺斯艾利斯', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。');
