INSERT INTO `crs_tabledata1530` VALUES ('43', '{3C3FCD36-C1DE-4171-9F7D-5EEF7EBB0474}', '0', 'INHE-0717', '2018-04-13 17:17:05', '0000-00-00 00:00:00', '2018-07-03 08:28:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041301/NSI', '', 'SAFE INFORMATION AND COMMUNICATION TECHNOLOGIES LTD', 'SICTL', '尼日利亚', 'Ekpoh Michael Ikoro', '+234 80388 64148', 'Michael.ekpoh@sictl.com.ng', 'SICTL成立于2008年，主要业务分布在ICT,表计及能源领域。其创始团队具有近20年能源领域及工程领域经验，有较广泛的能源及电力领域联络。根据其发送的材料显示，2017年营业额约为120万美金，且在所在领域具有较强的增长态势。', '{3C3FCD36C1DE41719F7D5EEF7EBB047411015FBC745F4B1982FBEF12F4BBACD1}_SICTL 资料.zip', '', '', '', '', '', '', '', '', 'SAFE INFORMATION AND COMMUNICATION TECHNOLOGIES LTD', 'SICTL', '尼日利亚', 'Ekpoh Michael Ikoro', '+234 80388 64148', 'Michael.ekpoh@sictl.com.ng', 'SICTL成立于2008年，主要业务分布在ICT,表计及能源领域。其创始团队具有近20年能源领域及工程领域经验，有较广泛的能源及电力领域联络。根据其发送的材料显示，2017年营业额约为120万美金，且在所在领域具有较强的增长态势。');
