INSERT INTO `crs_tabledata1530` VALUES ('46', '{2CE65A50-5AFD-46E5-A307-B8507D959C85}', '61', 'INHE-0725', '2018-04-18 09:47:44', '0000-00-00 00:00:00', '2018-04-19 16:03:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041801/BTS', '', 'BTS Power Limited', 'BTS', '尼日利亚', 'Owumi Ikomi', '+2348105333555', 'owumi.ikomi@gmail.com', 'BTS电力有限公司是一家专业从事电网、离网和嵌入式发电厂的开发、运营和维护的机构，主要市场为西非地区。其目标和核心业务主要是:为电力基础设施的部署、运营和维护提供一站式解决方案，同时降低客户的运营成本，为西非服务不足的社区和用户提供可靠电力。该公司和尼日利亚的EKEDC公司和IKEJA公司都有良好的关系，对当地的市场也比较熟悉。', '', '', '', '', '', '', '', '', '', 'BTS Power Limited', 'BTS', '尼日利亚', 'Owumi Ikomi', '+2348105333555', 'owumi.ikomi@gmail.com', 'BTS电力有限公司是一家专业从事电网、离网和嵌入式发电厂的开发、运营和维护的机构，主要市场为西非地区。其目标和核心业务主要是:为电力基础设施的部署、运营和维护提供一站式解决方案，同时降低客户的运营成本，为西非服务不足的社区和用户提供可靠电力。该公司和尼日利亚的EKEDC公司和IKEJA公司都有良好的关系，对当地的市场也比较熟悉。');
