INSERT INTO `crs_tabledata1530` VALUES ('48', '{EE60860E-3C0B-4034-A143-C5FB8AE856FE}', '66', 'INHE-0634', '2018-04-18 15:33:15', '0000-00-00 00:00:00', '2018-04-19 09:07:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041803/DYZ', '', 'Danayarzar Co., Ltd.', 'DYZ', '缅甸', 'Aung Soe Win', '(95)95199966', 'aungsoewin75@gmail.com', 'Danayarzar Co., Ltd.是缅甸一家大型配电公司，拥有全国10%、仰光25%的配电项目。有18万用户数量，电力容量约 250-300MW。主要业务包括变压器、11KV和400V的SAC线、变电站等。在APE-ESE投标中与许继合作投标未中，在其官网发现该公司与正泰有过合作。', '', '', '', '', '', '', '', '', '', 'Danayarzar Co., Ltd.', 'DYZ', '缅甸', 'Aung Soe Win', '(95)95199966', 'aungsoewin75@gmail.com', 'Danayarzar Co., Ltd.是缅甸一家大型配电公司，拥有全国10%、仰光25%的配电项目。有18万用户数量，电力容量约 250-300MW。主要业务包括变压器、11KV和400V的SAC线、变电站等。在APE-ESE投标中与许继合作投标未中，在其官网发现该公司与正泰有过合作。');
INSERT INTO `crs_tabledata1530` VALUES ('49', '{7CC4D1A6-992A-446B-B9A1-6827ED2943EF}', '66', 'INHE-0634', '2018-04-18 16:03:54', '0000-00-00 00:00:00', '2018-04-19 14:02:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041804/PAR', '', 'Parami Energy Service Co.,Ltd', 'PES', '缅甸', 'Zayar Tun', '959253066471', 'zayartun@parami.biz', 'Parami Energy Service Co.,Ltd成立于2004年，是缅甸一家中型规模企业，业务范围涉及石油、天然气、建筑以及电力IPP和EPC工程，拥有200名员工，与Honeywell有合作关系。', '', '', '', '', '', '', '', '', '', 'Parami Energy Service Co.,Ltd', 'PES', '缅甸', 'Zayar Tun', '959253066471', 'zayartun@parami.biz', 'Parami Energy Service Co.,Ltd成立于2004年，是缅甸一家中型规模企业，业务范围涉及石油、天然气、建筑以及电力IPP和EPC工程，拥有200名员工，与Honeywell有合作关系。');
INSERT INTO `crs_tabledata1530` VALUES ('50', '{87F89B1F-CEF4-4562-8E56-A972E92F3BCB}', '61', 'INHE-0434', '2018-04-19 09:14:21', '0000-00-00 00:00:00', '2018-04-19 16:04:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018041901/MAP', '', 'Integrated Resources Limited', 'IRL', '尼日利亚', 'Mr.Duro', '+2348028490450', '', '尼日利亚能源公司，在电力能源行业有10年的经验，其主要的服务项目包括设计和建设输电/配电网络，供应和安装电力设备，项目风险评估和管理', '{87F89B1FCEF445628E56A972E92F3BCB11015FBC745F4B1982FBEF12F4BBACD1}_IRL PROFILE  COMPLETE.pdf', '', '', '', '', '', '', '', '', 'Integrated Resources Limited', 'IRL', '尼日利亚', 'Mr.Duro', '+2348028490450', '', '尼日利亚能源公司，在电力能源行业有10年的经验，其主要的服务项目包括设计和建设输电/配电网络，供应和安装电力设备，项目风险评估和管理');
INSERT INTO `crs_tabledata1530` VALUES ('51', '{FD182154-3D0D-43EF-B7C4-965958FB78A6}', '61', 'INHE-0500', '2018-04-21 02:39:40', '0000-00-00 00:00:00', '2018-04-24 14:17:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2018042101/NWH', '', 'Pre-Paid Mobile Vending Solutions cc', 'PPM', '纳米比亚', 'Richard N Gaoseb', '+264812754478', 'rgaoseb@yahoo.com', '1.成立于2009年，纳米比亚本地中小型私营公司，主营业务为：纳米比亚第三方通讯服务和售电服务提供商，有ICT技术背景，之前和南非一家ICT公司Expertron合作过Airtime第三方通讯服务业务；2.BEE等级：公司所有权100%纳米比亚黑人，管理层100%纳米比亚黑人，等级较高（纳米比亚本地招标对BEE资质是强制性要求）；', '', 'City of Windhoek', 'COW', '纳米比亚', 'Technical enquiries: Mr. Jan BlaauwPMU Enquiries:Ms. Aune Kapelwa / Shekupe Mutilifa', 'Tel: (+264) 61 290 2270/2614', 'ans@windhoekcc.org.namsu@windhoekcc.org.na', '1.Namibia市场 6个主要售电主体单位中最大的，属于市政公司性质，和其他5个售电主体公司主要股东为NamPower（纳米比亚唯一国有发电和输电公司）和地区区域政府、并且只从事配电和售电业务不一样，COW属于首都市政府全权管理，配电业务只是其中的一个部门业务，配电和售电管理区域主要为Townhouse, Katutura Customer Care Centre, Khomasdal, Wanaheda, and Soweto。总电力用户数量为5万个，其中商业用表数量为5000个，LPU用表数量为1000个，其余为普通居民用户；                                                      2.COW当前电表绝大部分比例为兰吉尔和Itron的Cashpower分体式代码表，另外一小半仍是机械式电表和插座式代码表，售电系统为南非公司提供，功能陈旧；                                                                                                  ', '{FD1821543D0D43EFB7C4965958FB78A6FFC3E6BB8328443AA9AAC603FC047FE8}_纳米比亚市场调查报告.doc', 'Pre-Paid Mobile Vending Solutions cc', 'PPM', '纳米比亚', 'Richard N Gaoseb', '+264812754478', 'rgaoseb@yahoo.com', '1.成立于2009年，纳米比亚本地中小型私营公司，主营业务为：纳米比亚第三方通讯服务和售电服务提供商，有ICT技术背景，之前和南非一家ICT公司Expertron合作过Airtime第三方通讯服务业务；2.BEE等级：公司所有权100%纳米比亚黑人，管理层100%纳米比亚黑人，等级较高（纳米比亚本地招标对BEE资质是强制性要求）；');
