INSERT INTO `crs_tabledata1530` VALUES ('57', '{5C4B75B2-B2AE-465D-A0C4-9A48FF0EE055}', '61', 'INHE-0434', '2018-05-02 13:33:04', '0000-00-00 00:00:00', '2018-05-28 08:51:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050202/PAG', '请钟云林和客户协商，减少试点种类，争取扩大数量（单品超过100台）；费用客户承担。', 'Process * Plant Automation Ltd', '', '加纳', 'Mr.Adika Kwadzo', '+233-050-1256607', 'kadika@automationghana.com', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表', '', '', '', '', '', '', '', '', '', 'Process * Plant Automation Ltd', '', '加纳', 'Mr.Adika Kwadzo', '+233-050-1256607', 'kadika@automationghana.com', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表');
