INSERT INTO `crs_tabledata1530` VALUES ('59', '{1C8F11E3-6411-4881-8E80-4D1177FBD114}', '61', 'INHE-0434', '2018-05-03 14:40:54', '0000-00-00 00:00:00', '2018-05-08 11:39:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050304/SIC', '', 'Safe Information and Communication Technologies Limited', 'SICTL', '尼日利亚', 'Michael Ikoro Ekpoh', '00234 8038864148', 'michael.ekpo@sictl.com.ng', '1. 客户公司成立于2008年，当前公司职员15人，为VFD集团的子公司2. 客户刚开始做软硬件和网络方案提供商；接着转型做咨询，提供自动化系统和系统服务，培训等；2018年开始做能源行业；3. 客户当前对表计计量业务感兴趣，且对我司LPU和DA方案和技术感兴趣。客户希望从我司采购电表样机做本地测试，进而再扩大和银河的合作范围', '{1C8F11E3641148818E804D1177FBD11411015FBC745F4B1982FBEF12F4BBACD1}_sictl company profile.pdf', '', '', '', '', '', '', '', '', 'Safe Information and Communication Technologies Limited', 'SICTL', '尼日利亚', 'Michael Ikoro Ekpoh', '00234 8038864148', 'michael.ekpo@sictl.com.ng', '1. 客户公司成立于2008年，当前公司职员15人，为VFD集团的子公司2. 客户刚开始做软硬件和网络方案提供商；接着转型做咨询，提供自动化系统和系统服务，培训等；2018年开始做能源行业；3. 客户当前对表计计量业务感兴趣，且对我司LPU和DA方案和技术感兴趣。客户希望从我司采购电表样机做本地测试，进而再扩大和银河的合作范围');
INSERT INTO `crs_tabledata1530` VALUES ('60', '{B1373E00-FE34-41B7-A5A0-F41E69877C3D}', '66', 'JXINHE-2559', '2018-05-04 13:50:31', '0000-00-00 00:00:00', '2018-05-08 16:20:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050401/MLG', '', 'VBC Limitada', 'VBC', '莫桑比克', 'Adelino Daúde', '+258 494232', 'adaude@vbc.co.m', 'VBC是一家100%的莫桑比克本土公司，产品涉及电信通讯，移动设备，生物和能源技术。获得IGSQ奖项及2011全非奥运会官方供应商。', '', 'Eletricidadede Mo ambique', 'EDM', '莫桑比克', 'Benjamim Manuel', '+25821430916', 'benjamim.fernandes@edm.co.mz', '1995年莫桑比克国家电力公司（EDM）成立，管理全国用户数量（2011年数据）101万户，员工人数3402人，营业收入2.8亿美元。国家面临着电力基础设施投资落后于经济发展速度的现状,与其他非洲国家相比,莫桑比克具有相对稳定的政治环境,经济持续恢复性增长,投资法律环境较为健全,电力行业急需外部资金和技术进入,以加快电力基础设施项目建设,满足其经济发展的需要。', '', 'VBC Limitada', 'VBC', '莫桑比克', 'Adelino Daúde', '+258 494232', 'adaude@vbc.co.m', 'VBC是一家100%的莫桑比克本土公司，产品涉及电信通讯，移动设备，生物和能源技术。获得IGSQ奖项及2011全非奥运会官方供应商。');
INSERT INTO `crs_tabledata1530` VALUES ('61', '{890FA47E-7783-4D94-8F29-0F07D8713B0E}', '61', 'INHE-0662', '2018-05-08 09:06:56', '0000-00-00 00:00:00', '2018-05-14 09:03:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050802/HEN', '项目组长汤伟', 'Metrima AB', 'metrima', '瑞典', 'Emil Iggland', '+46(0)70 - 964 27 87', 'emil.iggland@metrima.com', 'Metrima是瑞典的一家AMR供应商，拥有丰富的经验和专业知识，提供测量数据通信和采集解决方案。去年营业额为800万美金。2006年至2010年间，Metrima在瑞典和欧洲为电力公司供应了50多套AMR系统，后将系统扩展到了水，气，热表。表计方面，瑞典在进行全国范围内第一次智能电表部署时，Metrima与Landis+Gyr一起参与了瑞典电力公司，EON Sweden，Kraftringen以及Oresundskraft的电表项目，兰吉尔提供基表，Metrima提供通讯模块。公司有三大股东，Emil Iggland是股东之一，年轻有为，为人比较和善，做事认真。', '', 'Ellevio AB', 'Ellevio', '瑞典', 'Olli ImmonenJohan Svensson', '+358 50 4532269', 'olli.immonen@partners.ellevio.sejohan.h.svensson@ellevio.se', '瑞典第二大电力公司，用户数有93.9万，用户主要分布在瑞典中部， 西海岸以及斯德哥尔摩地区。2017年的总资产为80亿欧元，净销售额为6.89亿欧元，净利润2880万欧元，流动资产1.75亿欧元左右。Ellevio与EON和Vattenfall一起在瑞典电网市场占据主导地位。该电力公司的董事会由9名成员构成，包括一名董事会主席，Soren Mellstig,以及两位员工代表，CEO为Johan Lindehag。', '', 'Ellevio AB', 'Ellevio', '瑞典', 'Olli ImmonenJohan Svensson', '+358 50 4532269', 'olli.immonen@partners.ellevio.sejohan.h.svensson@ellevio.se', '瑞典第二大电力公司，用户数有93.9万，用户主要分布在瑞典中部， 西海岸以及斯德哥尔摩地区。2017年的总资产为80亿欧元，净销售额为6.89亿欧元，净利润2880万欧元，流动资产1.75亿欧元左右。Ellevio与EON和Vattenfall一起在瑞典电网市场占据主导地位。该电力公司的董事会由9名成员构成，包括一名董事会主席，Soren Mellstig,以及两位员工代表，CEO为Johan Lindehag。');
INSERT INTO `crs_tabledata1530` VALUES ('62', '{879B67FD-D191-4BFD-A6CB-D5DE6CEE75BB}', '61', 'INHE-0381', '2018-05-08 11:11:19', '0000-00-00 00:00:00', '2018-05-10 13:35:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050803/MSQ', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司', '', '', '', '', '', '', '', '', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Kouakou Dominique', '', '', '科特迪瓦电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('63', '{005C7995-6233-4F0E-AD5D-B1EA6956DA56}', '61', 'INHE-0695', '2018-05-08 19:16:24', '0000-00-00 00:00:00', '2018-05-15 09:54:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050804/FLP', '', 'Elgama sistemos, UAB.', 'Elgsis', '立陶宛', 'Pavel Latvis', '+370 5 232 8000', 'pavel.latvis@elgsis.com', '立陶宛当地的一个能源管理系统方案提供商，主要做AMI/AMR软件方面。成立于1994年，在2002年的时候联同当地伙伴公司推出了立陶宛第一个电表抄读系统，有超过3000个计量点接入，通信方式主要为GSM/GPRS，辅助为PSTN及以太网主要业务地区为波罗的海三国，部分欧洲国家（白俄罗斯,波兰，希腊，西班牙）以及南美国家（哥伦比亚，玻利维亚，巴拉圭）公司只无生产电表的 能力，因此也在寻找合适的电表厂商一起合作。对合作表现出了较强烈的愿望，对我们具有DLMS以及MID认证比较看重。公司整体体量及规模不算太大，但可作为银河在欧洲市场的一个切入点。', '', '', '', '', '', '', '', '', '', 'Elgama sistemos, UAB.', 'Elgsis', '立陶宛', 'Pavel Latvis', '+370 5 232 8000', 'pavel.latvis@elgsis.com', '立陶宛当地的一个能源管理系统方案提供商，主要做AMI/AMR软件方面。成立于1994年，在2002年的时候联同当地伙伴公司推出了立陶宛第一个电表抄读系统，有超过3000个计量点接入，通信方式主要为GSM/GPRS，辅助为PSTN及以太网主要业务地区为波罗的海三国，部分欧洲国家（白俄罗斯,波兰，希腊，西班牙）以及南美国家（哥伦比亚，玻利维亚，巴拉圭）公司只无生产电表的 能力，因此也在寻找合适的电表厂商一起合作。对合作表现出了较强烈的愿望，对我们具有DLMS以及MID认证比较看重。公司整体体量及规模不算太大，但可作为银河在欧洲市场的一个切入点。');
INSERT INTO `crs_tabledata1530` VALUES ('64', '{DD120BB4-2F67-485C-A4CF-6B26FEC40659}', '61', 'INHE-0440', '2018-05-09 02:17:59', '0000-00-00 00:00:00', '2018-05-10 13:35:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050901/TTA', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），此次国内招标预算金额约2千万美元。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。');
INSERT INTO `crs_tabledata1530` VALUES ('65', '{24A708FA-821D-4285-BEB8-816D5E6BC502}', '61', 'INHE-0500', '2018-05-09 15:15:06', '0000-00-00 00:00:00', '2018-05-10 13:36:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050902/COE', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('66', '{5D07D812-7F7F-4768-A407-E34E64A3B813}', '61', 'INHE-0654', '2018-05-09 15:25:01', '0000-00-00 00:00:00', '2018-05-15 10:30:14', 'unchecked', 'n', 'n', '', '1', 'lxdj2018050903/COL', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', '', '', '', '', '', '', '', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('67', '{B7DACA1A-2249-4374-A894-531925D7C141}', '60', 'INHE-0514', '2018-05-10 18:45:48', '0000-00-00 00:00:00', '2018-05-15 10:30:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051001/IDC', '', 'Al-Tareq For Engineering Technology Co.', '', '约旦', 'Munzer Maraqa', '+962 (0) 6   556 25 02', 'munzer@tateco-eng.com', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '', 'Irbid District Electricity Company', '', '约旦', 'Mohamed', '+ 96227104650', 'ideco@ideco.com.jo', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '', 'Irbid District Electricity Company', '', '约旦', 'Mohamed', '+ 96227104650', 'ideco@ideco.com.jo', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。');
INSERT INTO `crs_tabledata1530` VALUES ('68', '{0C958C39-091A-4795-8AFA-BDBD27C08F36}', '61', 'INHE-0695', '2018-05-11 13:28:07', '0000-00-00 00:00:00', '2018-05-16 18:13:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051101/YKA', '', 'L*G Metering Ltd.', 'LG METERING', '乌克兰', 'Лапинин Игорь', '+38 050 310 52 77', 'Igor.Lapinin@lgmetering.kiev.ua', '该公司成立于1996年，当时作为兰吉尔在乌克兰当地的分支机构而成立。1998年，兰吉尔被西门子收购，该公司CEO拒绝关闭该公司加入西门子，L*G Metering的成员买下该公司并继续作为兰吉尔在当地的代理工作，同时也代理MTE/EMH的电表测试产品。2011年，兰吉尔收回了该公司的电表代理权，转让给了另外一家机构。从此该公司停止电表业务而只代理兰吉尔的暖表业务。该公司同乌克兰本地的能源公司有一定的业务往来（2013年前有电表，2013年后暖表+电表测试产品）。同时也在乌克兰提供AMR系统安装服务。该代理现为乌克兰本地的AMR系统商，也在代理兰吉尔的热表以及其他厂商的数据集中器以及其他电器设备及检验设备（EVM,Гран-Система-С,GOSSEN METRAWATT）。', '', '', '', '', '', '', '', '', '', 'L*G Metering Ltd.', 'LG METERING', '乌克兰', 'Лапинин Игорь', '+38 050 310 52 77', 'Igor.Lapinin@lgmetering.kiev.ua', '该公司成立于1996年，当时作为兰吉尔在乌克兰当地的分支机构而成立。1998年，兰吉尔被西门子收购，该公司CEO拒绝关闭该公司加入西门子，L*G Metering的成员买下该公司并继续作为兰吉尔在当地的代理工作，同时也代理MTE/EMH的电表测试产品。2011年，兰吉尔收回了该公司的电表代理权，转让给了另外一家机构。从此该公司停止电表业务而只代理兰吉尔的暖表业务。该公司同乌克兰本地的能源公司有一定的业务往来（2013年前有电表，2013年后暖表+电表测试产品）。同时也在乌克兰提供AMR系统安装服务。该代理现为乌克兰本地的AMR系统商，也在代理兰吉尔的热表以及其他厂商的数据集中器以及其他电器设备及检验设备（EVM,Гран-Система-С,GOSSEN METRAWATT）。');
INSERT INTO `crs_tabledata1530` VALUES ('69', '{E1A16367-423D-4A8A-B7E9-0522A1E32E10}', '61', 'INHE-0593', '2018-05-13 00:21:08', '0000-00-00 00:00:00', '2018-05-15 09:47:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051301/MLC', '', 'ENTREPRISE MALIENNE DE TRAVAUX ET D’INGENIERIE', 'EMTI', '马里', 'Moussa Daba DIARRA', '(00.223) 66.74.24.16', 'emti@afribone.net.ml', '公司已有客户，2012年曾出货马里电力公司。', '', 'Energie du Mali –SA', 'EDM-SA', '马里', '', '223 20 23 30 60', '', '马里能源公司是一家工商业性质股份有限公司。于1960年10月14日由马里政府创办。创立初期马里能源公司涉及两个业务领域，第一是生产和配送可饮用水，第二部分是在马里共和国全境内发电生产、输电、供电。2011年1月1日生产和配送可应用水功能分离，从此马里能源公司仅负责电力部门的管理。马里政府持有马里能源公司66%股份，剩下的34%由IPS WA持有，马里能源公司服务402 000个客户，其中2000个高压用户，另外400 000个低压客户分布于全国各地。', '', 'Energie du Mali –SA', '', '', '', '', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('70', '{AD7E4C2F-2C49-40F8-8A69-992F244958AD}', '60', 'INHE-0549', '2018-05-14 10:00:15', '0000-00-00 00:00:00', '2018-05-21 09:37:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051401/NFA', '', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'ONEE-Branche Electricité', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212522793680', 'globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥公民的生活和国家的经济竞争力起着很重要的作用。', '', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'ONEE-Branche Electricité', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212522793680', 'globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥公民的生活和国家的经济竞争力起着很重要的作用。', '', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'ONEE-Branche Electricité', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212522793680', 'globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥公民的生活和国家的经济竞争力起着很重要的作用。');
INSERT INTO `crs_tabledata1530` VALUES ('71', '{CED6B991-EF33-4D56-AF03-145FEC253236}', '61', 'INHE-0654', '2018-05-18 16:22:34', '0000-00-00 00:00:00', '2018-05-22 16:53:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018051801/CEO', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('72', '{C250E299-A074-46A4-8B0A-C9B7F73A79B8}', '66', 'JXINHE-2559', '2018-05-22 14:27:46', '0000-00-00 00:00:00', '2018-05-24 16:26:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052201/SIE', '', 'Inova Engineering  Pvt  Ltd.', 'INOVA', '斯里兰卡', 'Nevil', '+94 112869700', 'nevil@inovaeng.lk', '贸易公司，主要从事于通讯，发电站，计量，减灾救灾，信息和通信技术等业务，代理国际公司的产品参加政府性招标。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'Inova Engineering  Pvt  Ltd.', 'INOVA', '斯里兰卡', 'Nevil', '+94 112869700', 'nevil@inovaeng.lk', '贸易公司，主要从事于通讯，发电站，计量，减灾救灾，信息和通信技术等业务，代理国际公司的产品参加政府性招标。');
INSERT INTO `crs_tabledata1530` VALUES ('73', '{63A265AD-3A3E-4F38-A229-D7F30E5638F8}', '61', 'INHE-0440', '2018-05-24 02:50:28', '0000-00-00 00:00:00', '2018-05-24 16:41:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052401/TTR', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\"', '', 'Rural Energy Agency', 'REA', '坦桑尼亚', 'Eng. Bengiel H. Msofe', '+255 22 24 12 001-3/2/', 'dts@rea.go.tz', '为了实现坦桑尼亚全国的发展目标，促进农村经济发展和加快农村电力化进程，2007年，坦桑尼亚政府在能源部下成立了自治机构Rural Energy Agency (REA) 。REA响应坦桑尼亚政府在农村发展和执行现代能源的新政策，目标是满足坦桑尼亚农村地区85%以上的人口对现代能源的需求。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。');
INSERT INTO `crs_tabledata1530` VALUES ('74', '{F46CA41B-FC7D-4248-8CA0-5CB1F9A30399}', '61', 'INHE-0431', '2018-05-24 13:33:50', '0000-00-00 00:00:00', '2018-06-19 08:52:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018052402/WEG', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Winch Energy Group', 'WEG', '英国', 'Vito Caliò', 'mobile: +39 328 4819015', 'vito.calio@winchenergy.com', '客户本部在英国，在意大利及法国均有办事处，自有测试中心在意大利。主要发展可更新能源及提倡能源效率，重点在太阳能发电。据说在欧洲取得较大成功；从2011年起开始将业务范围扩展到非洲，拉丁美洲和亚洲。目前在非洲有离网项目（off-grid),需要电表。');
INSERT INTO `crs_tabledata1530` VALUES ('75', '{D6329B5A-8DA1-4C4F-94C7-DFD9AA103E94}', '66', 'INHE-0634', '2018-05-28 18:11:48', '0000-00-00 00:00:00', '2018-05-30 10:07:05', 'unchecked', 'n', 'n', '', '1', 'EPG', '', 'Parami Energy Service Co.,Ltd', 'PES', '缅甸', 'Zayar Tun', '959253066471', 'zayartun@parami.biz', 'Parami Energy Service Co.,Ltd成立于2004年，是缅甸一家中型规模企业，业务范围涉及石油、天然气、建筑以及电力IPP和EPC工程，拥有200名员工，与Honeywell有合作关系。', '', 'The Electric Power Generation Enterprise (EPGE)', 'EPGE', '缅甸', '', '', '', '缅甸内比都发电部门。', '', 'Parami Energy Service Co.,Ltd', 'PES', '缅甸', 'Zayar Tun', '959253066471', 'zayartun@parami.biz', 'Parami Energy Service Co.,Ltd成立于2004年，是缅甸一家中型规模企业，业务范围涉及石油、天然气、建筑以及电力IPP和EPC工程，拥有200名员工，与Honeywell有合作关系。');
