INSERT INTO `crs_tabledata1530` VALUES ('78', '{76919421-ED06-4D2D-B3AE-97A357C2A402}', '60', 'INHE-0066', '2018-05-31 18:34:04', '0000-00-00 00:00:00', '2018-06-04 09:41:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018053103/ECL', '', 'ECOLIGHT LLC', '', '俄罗斯', 'Ognev Evgeniy', 'Ognev.ea@gmail.com', 'Ognev.ea@gmail.com', '俄罗斯当地电力设备经销商，主要为断路器、照明、电源等。有较完善的渠道销售网络，和电力公司有很好的关系', '', '', '', '', '', '', '', '', '', 'ECOLIGHT LLC', '', '俄罗斯', 'Ognev Evgeniy', 'Ognev.ea@gmail.com', 'Ognev.ea@gmail.com', '俄罗斯当地电力设备经销商，主要为断路器、照明、电源等。有较完善的渠道销售网络，和电力公司有很好的关系	。');
INSERT INTO `crs_tabledata1530` VALUES ('79', '{81DE0AA7-2999-4C41-8D1B-89BF424BAA38}', '61', 'INHE-0381', '2018-06-04 08:02:44', '0000-00-00 00:00:00', '2018-06-15 08:36:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060401/AGS', '', 'TOGO ASSISTANCE SERVICES', '', '', '', '', '', '', '', 'Entreprise d?Electricité et Eau de Guinée-Bissau', '', '', '', '', '', '几内亚比绍水务电力公司', '', 'TOGO ASSISTANCE SERVICES', '', '', '', '', '', '老客户');
INSERT INTO `crs_tabledata1530` VALUES ('80', '{DF872E49-3E62-4A49-A033-8955B313BB38}', '61', 'INHE-0440', '2018-06-06 06:58:12', '0000-00-00 00:00:00', '2018-06-08 10:27:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060601/TTZ', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。', '', 'ZANZIBAR ELECTRICITY CORPORATION', 'ZECO', '坦桑尼亚', 'Eng. Hassan Ali Mbarouk', '+255 2452255', 'info@zeco.co.tz', '桑给巴尔电力公司ZANZIBAR ELECTRICITY CORPORATION (ZECO)，100%属于桑岛政府，归属能源部管辖。ZECO主要从TANESCO购电，然后供岛上居民使用，每年新增约3-5万新用户,是坦桑除国电（TANESCO)、农村电力公司（REA）后的第三个电力公司。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\" INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\"');
INSERT INTO `crs_tabledata1530` VALUES ('81', '{C0112808-CA4B-427E-A364-39739D74187F}', '61', 'INHE-0431', '2018-06-07 13:28:24', '0000-00-00 00:00:00', '2018-06-13 11:01:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018060701/TMC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Meter*Control d.o.o.', 'M*C', '塞尔维亚', 'Jovan Vujasinovi?, MScEECo-founder, President&CEO', 'T +381 11 371 36 21', 'office@meterandcontrol.com', '塞尔维亚表，公司成立于2008，公司创始人有PLC研发的经验。公司有一定规模并取得以下证书：ISO 9001 Quality management/ ISO 14001 Environmental management/ OHSAS 18001 Occupational health and safety/ ISO/IEC 27001 Information security。公司有一定的技术和研发实力，据称自己的产品和方案符合： ISO/IEC 17020 Inspection body type C/ MID-D certificate on production quality system/ EC-type examination certificate and Certificate of Conformity/ DLMS/COSEM/ IDIS/ IEC 62052-11/ IEC 62053-21/ EN 50470-1/ EN 50470-3/ IEC 62055-31');
INSERT INTO `crs_tabledata1530` VALUES ('82', '{7884401D-75C7-4885-941F-E97B02912AD7}', '93', 'INHE-0726', '2018-06-13 11:04:27', '0000-00-00 00:00:00', '2018-06-19 08:52:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061302/PIC', '', 'BURNED STONE CO., LIMITED', 'BURNED STONE', '中国', '谭剑锋', '13606163711', 'tanjianfeng@lakescloud.com', 'BURNED STONE CO.,LIMITED, 中文名为博德世通有限公司，私人股份有限公司，成立于2013年，在香港注册，谭剑锋为法人兼总经理，谭剑锋在江苏还有一家公司，江苏湖岸星光信息技术有限公司，成立于2017年，业务涉及国际 电信设备、服务和国际专线，是贸易商。', '', '', '', '', '', '', '', '', '', 'BURNED STONE CO., LIMITED', 'BURNED STONE', '中国', '谭剑锋', '13606163711', 'tanjianfeng@lakescloud.com', 'BURNED STONE CO.,LIMITED, 中文名为博德世通有限公司，私人股份有限公司，成立于2013年，在香港注册，谭剑锋为法人兼总经理，谭剑锋在江苏还有一家公司，江苏湖岸星光信息技术有限公司，成立于2017年，业务涉及国际 电信设备、服务和国际专线，是贸易商。');
INSERT INTO `crs_tabledata1530` VALUES ('83', '{126D2306-CAA3-47BA-BA1E-36ADDD19F269}', '61', 'INHE-0722', '2018-06-14 18:55:02', '0000-00-00 00:00:00', '2018-06-19 08:51:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061401/MAC', '', 'SIREMCO S.A.DE C.V', 'SMEI', '墨西哥', 'Miguel E García Fonseca', '52 33 3640 4143', '<miguel.garcia@smei.mx>', 'SIREMCO S.A.DE.C.V，简称SMEI，是由墨西哥CENMEX投资控股的一家致力于精准计量电力的公司。拥有完整的电表硬件、程序、通讯和系统设计能力以及安装和集抄实施经验，目前已经向CFE供应和管理着17万只电表，主要是DIN箱式方案表。SMEI的方案可以实现预付费和集抄。SMEI清楚墨西哥当地电力行业规则，懂电表业务，有业务基础，技术、服务能力和经济实力。其公司的管理层清楚墨西哥电表业务的机遇和挑战，有切实可行的竞争策略。', '', '', '', '', '', '', '', '', '', 'SIREMCO S.A.DE C.V', 'SMEI', '墨西哥', 'Miguel E García Fonseca', '52 33 3640 4143', '<miguel.garcia@smei.mx>', 'SIREMCO S.A.DE.C.V，简称SMEI，是由墨西哥CENMEX投资控股的一家致力于精准计量电力的公司。拥有完整的电表硬件、程序、通讯和系统设计能力以及安装和集抄实施经验，目前已经向CFE供应和管理着17万只电表，主要是DIN箱式方案表。SMEI的方案可以实现预付费和集抄。SMEI清楚墨西哥当地电力行业规则，懂电表业务，有业务基础，技术、服务能力和经济实力。其公司的管理层清楚墨西哥电表业务的机遇和挑战，有切实可行的竞争策略。');
INSERT INTO `crs_tabledata1530` VALUES ('84', '{35CCB278-5B02-45CC-A8D5-AF686EEFECD5}', '61', 'INHE-0432', '2018-06-15 16:53:36', '0000-00-00 00:00:00', '2018-06-20 14:33:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061501/PRK', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'PowerGen Renewable Energy', 'Powergen Renew', '肯尼亚', 'Joel Mugyenyi', '+254700940164', 'jmugyenyi@powergen-re.com', '1.公司主营业务：太阳能微网总包项目，现为东非最大的太阳能微网服务供应商，已在肯尼亚、坦桑尼亚、赞比亚等国家建立了数百个太阳能微网发电站。2.公司历史：于2011年在肯尼亚内罗毕成立总部。创始人及董事长等均为美国人且毕业于美国哈佛商学院。公司曾受到TED等媒体专门报道，也收到来自于美国国际发展组织（USAID）的资金赞助。目前总部团成员约50人。');
INSERT INTO `crs_tabledata1530` VALUES ('85', '{4B06BDFC-04C3-498B-8781-26450D23118A}', '61', 'INHE-0642', '2018-06-19 00:04:19', '0000-00-00 00:00:00', '2018-06-21 15:46:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018061901/EGJ', '', 'Electricity Generation Company(Malawi) Ltd', 'Egenco', '马拉维', 'Egenco', '+265 1 836000', 'wmpisa@egenco.mw', '马拉维发电公司，2016年9月9号从ESCOM（Electricity Supply Corporation of Malawi Limited）独立出去，主要负责发电工作，目前掌管350.8MW的水力发电站以及22.57MW的柴油发电站。', '', 'Electricity Generation Company(Malawi) Ltd', 'Egenco', '马拉维', 'Egenco', '+265 1 836000', 'wmpisa@egenco.mw', '马拉维发电公司，2016年9月9号从ESCOM（Electricity Supply Corporation of Malawi Limited）独立出去，主要负责发电工作，目前掌管350.8MW的水力发电站以及22.57MW的柴油发电站。', '', 'Electricity Generation Company(Malawi) Ltd', 'Egenco', '马拉维', 'Egenco', '+265 1 836000', 'wmpisa@egenco.mw', '马拉维发电公司，2016年9月9号从ESCOM（Electricity Supply Corporation of Malawi Limited）独立出去，主要负责发电工作，目前掌管350.8MW的水力发电站以及22.57MW的柴油发电站。');
INSERT INTO `crs_tabledata1530` VALUES ('86', '{54F1C8F1-3782-43F1-8783-80635D37E017}', '60', 'INHE-0727', '2018-06-20 17:36:42', '0000-00-00 00:00:00', '2018-06-21 15:25:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062001/MTA', '', 'Electric Vine Industries', 'EVI', '印尼', 'Matt Basinger', '62 811 933 7892', '62 811 933 7892', '该客户是一家微电力公司，主营微电网，利用太阳能为印度尼西亚没有通电的地区（如偏远地区，农村等）提供电能。当地有工程安装队，负责项目的整体图纸设计，独立采购硬件（太阳能电板、逆变器、蓄电池等）。', '{54F1C8F1378243F1878380635D37E01711015FBC745F4B1982FBEF12F4BBACD1}_2018年6月13日EVI客户来访会议纪要(1).docx', '', '', '', '', '', '', '', '', 'Electric Vine Industries', 'EVI', '印尼', 'Matt Basinger', '62 811 933 7892', '62 811 933 7892', '该客户是一家微电力公司，主营微电网，利用太阳能为印度尼西亚没有通电的地区（如偏远地区，农村等）提供电能。当地有工程安装队，负责项目的整体图纸设计，独立采购硬件（太阳能电板、逆变器、蓄电池等）。');
