INSERT INTO `crs_tabledata1530` VALUES ('90', '{CB57E538-BC23-4D97-A498-BC31A3C6FA34}', '60', 'INHE-0727', '2018-06-22 16:22:38', '0000-00-00 00:00:00', '2018-06-25 17:43:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062206/WON', '', '珠海奥力联合贸易有限公司', '', '中国', '王先生', '13229761002', 'wang@oliunion.com', '客户从事商业建筑行业（公寓、办公楼、商场）的电能管理。国内想找个OEM配套厂家，已来访公司，合作可能性大', '{CB57E538BC234D97A498BC31A3C6FA3411015FBC745F4B1982FBEF12F4BBACD1}_180531印尼客户来访会议纪要.doc', '', '', '', '', '', '', '', '', '珠海奥力联合贸易有限公司', '', '中国', '王先生', '13229761002', 'wang@oliunion.com', '客户从事商业建筑行业（公寓、办公楼、商场）的电能管理。国内想找个OEM配套厂家，已来访公司，合作可能性大');
INSERT INTO `crs_tabledata1530` VALUES ('91', '{0564D069-25D3-4618-924F-7AB17275DFB5}', '60', 'INHE-0535', '2018-06-25 14:59:44', '0000-00-00 00:00:00', '2018-06-28 10:52:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062501/LTE', 'LTE', 'Larsen & Toubro Limited', 'L&T', '印度', 'SANDEEP PURI', '+91-11-26169170', 'alpassoindustries@gmail.com', 'Larsen & Toubro是一个从事技术、工程、建筑、制造业和金融服务等全球业务的大集团。帮助解决全球范围内30多个国家的客户对关键领域的关键需求——碳氢化合物、基础设施、电力、加工工业和国防。L&T涉及经济的核心、高影响力部门，综合能力跨越了“设计交付”的整个范围。70多年的发展强大，以客户为中心的方法和不断追求世界级的质量，拥有丰富的专业技术，工程，建筑，基础设施项目和制造业经验，并在主要业务领域保持前列。', '', 'Energy Efficiency Services Limited', 'EESL', '印度', 'Ajay Kumar Sharma', '0120-4908000', 'asharma1@eesl.co.in', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；2.	执行中央或邦政府或其代理机构的计划，项目和政策；3.	与私有ESCOs和其他公司合作促进能源效率；4.	在能源效率，CDM项目和其他有关领域提供咨询服务；5.	传授培训，培养股东能力。', '', 'Energy Efficiency Services Limited', 'EESL', '印度', 'Ajay Kumar Sharma', '0120-4908000', 'asharma1@eesl.co.in', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；2.	执行中央或邦政府或其代理机构的计划，项目和政策；3.	与私有ESCOs和其他公司合作促进能源效率；4.	在能源效率，CDM项目和其他有关领域提供咨询服务；5.	传授培训，培养股东能力。');
INSERT INTO `crs_tabledata1530` VALUES ('92', '{20BF3672-40C7-4D77-A2DE-698AD3495CA9}', '60', 'INHE-0514', '2018-06-26 12:48:06', '0000-00-00 00:00:00', '2018-06-28 10:33:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062602/ICE', '', 'Energy Care Holding', 'ECC', '沙特阿拉伯', 'Hassan', '+966 12 6436050', 'Farhangi@energycareholding.com', 'ECC是沙特本地电力配电自动化，电表产品以及解决方案的供应商，公司总部位于沙特吉达。ECC是林洋在沙特的长期合作伙伴（林洋为ECC提供OEM/ODM服务），到目前为止，林洋已经通过ECC向SEC供应了超过50万只普通三相电能表。18年初在SEC AMI项目招投标的背景下（MANS项目），ECC向SEC建议将过去提供的50万只电能表，通过外接模块+系统的方式实现AMI功能，如此一来，已经供货的50万只电表则不需要重新替换，SEC认可了ECC的建议，因此，ECC与林洋经与SEC商议，计划18年4月份向SEC演示该方案，但是由于林洋系统方面本身研发实力比较薄弱，且目前阶段公司资源很多都投放在欧洲市场，所以导致18年4月份林洋未能拿出较好的系统方案，因此演示被搁置至7月中旬，该行为引起了ECC的极为不满，导致的结果是林洋要求与ECC签署独家合作协议的要求被ECC拒绝。另外，林洋与ECC合作的引荐人是ECC 的CTO哈桑先生，哈桑与林洋之间存在私下的利益关系；一方面因为林洋的系统问题导致演示推迟且面临较大风险，另一方面由于哈桑与林洋间的利益关系也出现问题，加上哈桑先生得到消息林洋的人计划从ECC', '', 'Saudi Electricity Company', '', '沙特阿拉伯', 'Melvin F. Saemago', '00966118078575', 'HAMnasif@se.com.sa', 'SEC-沙特电力公司是沙特超大型国有企业，负责沙特全境发电，输配电，智能电网建设。SEC目前董事会供9名成员，董事会主席为H.E.Dr. Khaled bin Saleh Al Sultan，执行管理层人员12名，，其中总裁CEO为Ziyad Bin Mohammed Al-Shiha，负责配电和服务的负责人为Khaled Bin Hamad Al-Gnoon（SEC副总裁），', '', 'Energy Care Holding', 'ECC', '沙特阿拉伯', 'Hassan', '+966 12 6436050', 'Farhangi@energycareholding.com', 'ECC是沙特本地电力配电自动化，电表产品以及解决方案的供应商，公司总部位于沙特吉达，与林洋有合作关系。');
INSERT INTO `crs_tabledata1530` VALUES ('93', '{72DF5000-1656-4C7E-A378-AD14DF27161C}', '61', 'INHE-0713', '2018-06-26 17:15:12', '0000-00-00 00:00:00', '2018-06-28 10:33:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062605/DCN', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', 'guillaume.azon@sgeinter.com', '老代理', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('94', '{87F63664-7DF3-4838-8BE8-9DF6579B9BDD}', '61', 'INHE-0725', '2018-06-27 20:08:38', '0000-00-00 00:00:00', '2018-07-03 09:58:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018062701/JJO', '', 'Process * Plant Automation Ltd', 'PPA', '加纳', 'Mr.Adika Kwadzo', '+233-050-1256607', 'kadika@automationghana.com', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表', '', 'Millennium Development Authority', 'MiDA', '加纳', 'Head OfficeMillennium Development Authority', '+(233) 302 666619,', 'info@mida.gov.gh,procurement@mida.gov.gh', 'MiDA以The Government of Ghana Millennium Challenge Account 名义实施项目， Millennium Challenge Account 实属美国千禧年公司旗下，用以资金援建非洲地区的机构。该机构由Millennium Development Authority (MiDA)监督、管理和实施项目。2014年，MCC和加纳政府达成援助协议，援助金额为US$ 498,200,000，用以帮助加纳经济增长以及消除贫困。', '', 'Millennium Development Authority', 'MiDA', '加纳', 'Head OfficeMillennium Development Authority', '+(233) 302 666619,', 'info@mida.gov.gh,procurement@mida.gov.gh', 'MiDA以The Government of Ghana Millennium Challenge Account 名义实施项目， Millennium Challenge Account 实属美国千禧年公司旗下，用以资金援建非洲地区的机构。该机构由Millennium Development Authority (MiDA)监督、管理和实施项目。2014年，MCC和加纳政府达成援助协议，援助金额为US$ 498,200,000，用以帮助加纳经济增长以及消除贫困。');
