INSERT INTO `crs_tabledata1530` VALUES ('97', '{51BD24FC-EA75-4723-BC79-2BCC2D3FCFFA}', '66', 'JXINHE-2559', '2018-07-03 14:52:28', '0000-00-00 00:00:00', '2018-07-05 13:38:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070301/PIN', '', 'INNEXIV (Private) Limited', 'INNEXIV', '巴基斯坦', 'Wajid Arshad', '+923445666680', 'wajid.arshad@innexiv.com', '巴基斯坦软件公司，员工人数150人左右，主要从事于电力系统管理，相关硬件的开发和设计，在阿富汗，巴基斯坦，伊朗，蒙古等地执行过电力智能系统项目，曾经和国内的电表厂商合作，在巴基斯坦执行过小型的AMI项目。', '', '', '', '', '', '', '', '', '', 'INNEXIV (Private) Limited', 'INNEXIV', '巴基斯坦', 'Wajid Arshad', '+923445666680', 'wajid.arshad@innexiv.com', '巴基斯坦软件公司，员工人数150人左右，主要从事于电力系统管理，相关硬件的开发和设计，在阿富汗，巴基斯坦，伊朗，蒙古等地执行过电力智能系统项目，曾经和国内的电表厂商合作，在巴基斯坦执行过小型的AMI项目。');
INSERT INTO `crs_tabledata1530` VALUES ('98', '{38B07B46-5ECA-4590-B5BE-029900B2303C}', '61', 'INHE-0695', '2018-07-04 11:22:43', '0000-00-00 00:00:00', '2018-07-09 16:12:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070402/SLO', '', 'D.A.L.I. - M.N., s.r.o.', 'DALI MN', '斯洛伐克', 'Munir Pasagic', '+421 904 271 240(主要联系电话)', 'tab-mezica@tab-mezica.sk', 'ISKRAMECO在斯洛伐克及捷克的代理。\r\n公司主要代理产品包括：电池，电表，变压器，高压开关，以及电力监测系统。\r\n代理较为靠谱，在斯洛伐克本地，该代理同电力公司关系较好，同该市场三家电力公司均有业务往来，对当地的电表市场较为熟悉。\r\n同时，该公司在邻国捷克有有相应的代理业务。待关系建立成熟后，可同期将业务扩展至捷克。', '{38B07B465ECA4590B5BE029900B2303C11015FBC745F4B1982FBEF12F4BBACD1}_代理公司政府注册信息.pdf', 'Západoslovenská distribucná, a.s.', 'ZSD Slovakia', '斯洛伐克', 'Bálint Jozef', '+421 908718403', 'jozef.balint@zsdis.sk', 'ZSD 是 斯洛伐克三大能源公司之一的ZSE下属的配电事业子公司。其母公司ZSE为斯洛伐克最大的能源商（主要业务在斯洛伐克西部）。ZSE的51%股份属于国有，49%的股份属于德国能源公司 E. ON。', '{38B07B465ECA4590B5BE029900B2303CFFC3E6BB8328443AA9AAC603FC047FE8}_ZSE Energia, 2017年财报.pdf', 'Západoslovenská distribucná, a.s.', 'ZSD Slovakia', '斯洛伐克', 'Bálint Jozef', '+421 908718403', 'jozef.balint@zsdis.sk', 'ZSD 是 斯洛伐克三大能源公司之一的ZSE下属的配电事业子公司。其母公司ZSE为斯洛伐克最大的能源商（主要业务在斯洛伐克西部）。ZSE的51%股份属于国有，49%的股份属于德国能源公司 E. ON。');
INSERT INTO `crs_tabledata1530` VALUES ('99', '{6EAF1C02-C884-4398-8E16-EC2542CE8199}', '60', 'INHE-0714', '2018-07-04 14:17:22', '0000-00-00 00:00:00', '2018-07-04 15:37:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2018070403/MRC', '', '厦门弘基永业投资有限公司', 'MRC', '菲律宾', '林海英', '13306032052', '153858747@qq.com', '厦门弘基永业投资有限公司，公司总部在菲律宾，大股东在菲律宾印刷业和垃圾处理业在业界很有名气。公司没有建网站，主要开展菲律宾业务，因为客户在菲律宾关系网比较强大。公司主要有三大板块，移动支付/建设工程/配电设备的代理。现菲律宾SM微信支付已上线，这是客户与当地的BDO银行合作的业务。所以今后中国游客去菲律宾SM消费都可以用微信支付，现在业务还在拓展更大商铺。马尼拉电力公司是菲律宾最大的电力公司，项目遍及菲律宾36个城市和75个自治区，拥有630多万用户，包括工业，商业和居民用户。								\r\n', '{6EAF1C02C88443988E16EC2542CE819911015FBC745F4B1982FBEF12F4BBACD1}_马电采购电表数量需求.jpg', '', '', '', '', '', '', '', '', '厦门弘基永业投资有限公司', 'MRC', '菲律宾', '林海英', '13306032052', '153858747@qq.com', '厦门弘基永业投资有限公司，公司总部在菲律宾，大股东在菲律宾印刷业和垃圾处理业在业界很有名气。公司没有建网站，主要开展菲律宾业务，因为客户在菲律宾关系网比较强大。公司主要有三大板块，移动支付/建设工程/配电设备的代理。现菲律宾SM微信支付已上线，这是客户与当地的BDO银行合作的业务。所以今后中国游客去菲律宾SM消费都可以用微信支付，现在业务还在拓展更大商铺。');
INSERT INTO `crs_tabledata1530` VALUES ('100', '{F6E03E6B-80DB-4297-B2FE-80C3C86B37C4}', '61', 'INHE-0713', '2018-07-11 09:44:21', '0000-00-00 00:00:00', '2018-07-18 08:49:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071102/ALG', '', '', '', '', '', '', '', '', '', 'ENTREPRISE NATIONALE DES APPAREILS DE MESURE ET DE CONTROLES.P.A. FILIALE DU GROUPE SONELGAZ', 'EN.AMC.S.P.A', '阿尔及利亚', 'NEMMOUR', '00 213 36 47 96 70-74', 'departementachats@yahoo.fr', '阿尔及利亚电力公司', '', 'ENTREPRISE NATIONALE DES APPAREILS DE MESURE ET DE CONTROLES.P.A. FILIALE DU GROUPE SONELGAZ', 'EN.AMC.S.P.A', '阿尔及利亚', 'NEMMOUR', '00 213 36 47 96 70-74', 'departementachats@yahoo.fr', '阿尔及利亚电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('101', '{D097E07D-4E2A-4035-9621-68D9EAEB2EEF}', '61', 'INHE-0654', '2018-07-12 09:04:04', '0000-00-00 00:00:00', '2018-07-18 08:47:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071201/ADE', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', '', '', '', '', '', '', '', '', 'Edenor S.A.', '', '阿根廷', 'Juliana Estefania MATA', '4346-5400', '', '阿根廷最大的电力公司，总部在首都布宜诺斯艾利斯');
INSERT INTO `crs_tabledata1530` VALUES ('102', '{B362CBF3-155C-4780-82EC-32E7D5725CCC}', '66', 'JXINHE-2559', '2018-07-12 11:32:41', '0000-00-00 00:00:00', '2018-07-19 08:39:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071202/NPR', '', 'Promentute Incorporation (P) Ltd', 'PMIC', '尼泊尔', 'Kunjn KC', '+977-9802011007', 'kkc@promentute.com', '电力项目的执行服务公司，业务包括项目的安装，测试和运行。', '', 'Alternative Energy Promotion Center', 'RERL', '尼泊尔', '', '', 'rerl@aepc.gov.np', '尼泊尔国家替代能源推广中心的农网改造部，负责国家农村地区的电网和电力设备的改造，包括电力材料的采购和项目的执行。', '', 'Promentute Incorporation (P) Ltd', 'PMIC', '尼泊尔', 'Kunjn KC', '+977-9802011007', 'kkc@promentute.com', '电力项目的执行服务公司，业务包括项目的安装，测试和运行。');
