INSERT INTO `crs_tabledata1530` VALUES ('104', '{203BAAE1-C4B8-4C21-952C-3BE68D6A859C}', '61', 'INHE-0662', '2018-07-16 10:31:22', '0000-00-00 00:00:00', '2018-07-18 08:45:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071601/DEK', '', 'Dobos Elektronikai Kft', 'Dobos', '匈牙利', 'Viktor Csaki', '36709400726', 'csaki.v@dobosltd.hu', '该公司是一家研发和销售测量配件，提供系统服务的公司，产品包括手持数据采集终端，光学头，抄读工具，GPS等。是ADD Grup的合作伙伴。该公司是一家中小型公司，为当地电力公司ELMU（原为RWE子公司，现被EON收购），EON提供电表的软件服务以及电表配件。老板和MD都是工程师出身，做事较有冲劲，有前瞻性，懂运作，与匈牙利当地的电力公司有长久和稳定的业务联系。', '', '', '', '', '', '', '', '', '', 'Dobos Elektronikai Kft', 'Dobos', '匈牙利', 'Viktor Csaki', '36709400726', 'csaki.v@dobosltd.hu', '该公司是一家研发和销售测量配件，提供系统服务的公司，产品包括手持数据采集终端，光学头，抄读工具，GPS等。是ADD Grup的合作伙伴。该公司是一家中小型公司，为当地电力公司ELMU（原为RWE子公司，现被EON收购），EON提供电表的软件服务以及电表配件。老板和MD都是工程师出身，做事较有冲劲，有前瞻性，懂运作，与匈牙利当地的电力公司有长久和稳定的业务联系。');
INSERT INTO `crs_tabledata1530` VALUES ('105', '{4F708B4C-93DF-4723-A71B-871A1C330C58}', '93', 'INHE-0091', '2018-07-17 16:55:25', '0000-00-00 00:00:00', '2018-07-19 08:39:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2018071701/DAL', '', 'Al-Tareq For Engineering Technology Co.', '', '约旦', 'Munzer Maraqa', '+962 (0) 6   556 25 02', 'munzer@tateco-eng.com', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。该公司在约旦的几家电力公司有一定的人脉关系，倾向于做供应商的佣金代理。', '', 'Irbid District Electricity Co.Ltd.', 'Ideco', '约旦', '', '+962 2 7201500', 'ideco@IDECO.com.jo', '负责约旦北部的发电、输电和配电业务，涵盖整个约旦国家区域的25.6%', '', 'Irbid District Electricity Co.Ltd.', 'Ideco', '约旦', '', '+962 2 7201500', 'ideco@IDECO.com.jo', '负责约旦北部的发电、输电和配电业务，涵盖整个约旦国家区域的25.6%');
