INSERT INTO `crs_tabledata1530` VALUES ('110', '{34ADA7CE-EBD9-47FE-9D85-FA24B405FA6D}', '61', 'INHE-0500', '2018-07-25 03:02:54', '0000-00-00 00:00:00', '2018-07-26 08:58:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072501/BAD', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。', '{34ADA7CEEBD947FE9D85FA24B405FA6DFFC3E6BB8328443AA9AAC603FC047FE8}_2016-2017财年BPC财年汇报.pdf', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。');
INSERT INTO `crs_tabledata1530` VALUES ('111', '{D445555C-DEA1-47E8-8337-EC3629387859}', '60', 'INHE-0712', '2018-07-25 17:13:41', '0000-00-00 00:00:00', '2018-08-03 11:40:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018072503/IDA', '个人意见增加了补充说明', 'JAGUAR OVERSEAS LIMITED', 'JAGUAR', '印度', 'Anil Tiwari', '+91 11 4900 3939', 'anil.tiwari@jaguaroverseas.com', '捷豹海外有限公司是一家全球项目工程公司，从事交钥匙工程，采购和施工（EPC）项目以及供应项目，拥有电力，农业，工业厂房，基础设施，可再生能源等领域的专业知识。是一家ISO认证公司，业务遍及非洲和亚洲。', '', '', '', '', '', '', '', '', '', 'JAGUAR OVERSEAS LIMITED', 'JAGUAR', '印度', 'Anil Tiwari', '+91 11 4900 3939', 'anil.tiwari@jaguaroverseas.com', '捷豹海外有限公司是一家全球项目工程公司，从事交钥匙工程，采购和施工（EPC）项目以及供应项目，拥有电力，农业，工业厂房，基础设施，可再生能源等领域的专业知识。是一家ISO认证公司，业务遍及非洲和亚洲。');
