INSERT INTO `crs_tabledata1530` VALUES ('118', '{7BAE99E4-138D-031F-8062-14D987424BC9}', '60', 'INHE-0729', '2018-07-31 11:38:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', '', '', 'Confidence Group', null, '孟加拉', 'Md. Akhterujjaman', ' +88 01971 76 16 97', 'confidenceakt@gmail.com', '与孟加拉军方企业以及电力公司有关系，以往业务均为向上述企业直接供货。公司合伙人之一是一个华人，在孟加拉生活30多年，熟知当地的业务。有意向向我司直接采购预付费表零配件，在孟加拉组装，通过国有企业GEMCO向REB等电力公司供货。直接采购（简称直采）在孟加拉规定只有政府性质的公司之间才可以开展直接采购。REB还有约2400万只表的需求，其中一部分需求将直采。', null, null, null, null, null, null, null, null, null, 'Confidence Group', null, '孟加拉国', 'Md. Akhterujjaman', ' +88 01971 76 16 97', 'confidenceakt@gmail.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('119', '{8074822B-45D3-FFC5-7C7F-23AC1E53FB2C}', '60', 'INHE-0729', '2018-07-31 11:39:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', '', '', 'Confidence Group', null, '孟加拉', 'Md. Akhterujjaman', ' +88 01971 76 16 97', 'confidenceakt@gmail.com', '与孟加拉军方企业以及电力公司有关系，以往业务均为向上述企业直接供货。公司合伙人之一是一个华人，在孟加拉生活30多年，熟知当地的业务。有意向向我司直接采购预付费表零配件，在孟加拉组装，通过国有企业GEMCO向REB等电力公司供货。直接采购（简称直采）在孟加拉规定只有政府性质的公司之间才可以开展直接采购。REB还有约2400万只表的需求，其中一部分需求将直采。', null, null, null, null, null, null, null, null, null, 'Confidence Group', null, '孟加拉国', 'Md. Akhterujjaman', ' +88 01971 76 16 97', 'confidenceakt@gmail.com', null);
INSERT INTO `crs_tabledata1530` VALUES ('120', '{5F4E23F0-17F0-4CAD-B646-0458287E0DA0}', '66', 'INHE-0579', '2018-07-31 16:19:21', '0000-00-00 00:00:00', '2018-08-02 13:32:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073104/TUS（旧）', '', 'Best AFRICA international', 'Best AFRICA', '突尼斯', 'ben rhouma chiheb', '+216 22 411 316', 'chihebbenrhouma@yahoo.fr', 'Best AFRICA international经营变压器，电表，电缆，表箱等贸易。代理ben rhouma chiheb之前在一家顾问公司工作十年，从事电表相关顾问工作，目前在 Best AFRICA international担任技术总监。他与电力公司AMI部分负责人私交甚好，提前拿到了将在9月底发布的全部标书，还介绍电力公司技术负责人与我认识。', '', 'Tunisian Company of Electricity and Gas', 'STEG', '突尼斯', 'Mohamed Dhia Eddine Fekih', '', 'Fekih.mohameddhia@hotmail.fr', 'STEG控制着突尼斯电网，垄断了电力运输和配电业务。', '{5F4E23F017F04CADB6460458287E0DA0FFC3E6BB8328443AA9AAC603FC047FE8}_突尼斯市场调查.doc', 'Tunisian Company of Electricity and Gas', 'STEG', '突尼斯', 'Mohamed Dhia Eddine Fekih', '', 'Fekih.mohameddhia@hotmail.fr', 'STEG控制着突尼斯电网，垄断了电力运输和配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('121', '{44B59DB2-9101-4DCB-8FCC-C854643EE443}', '61', 'INHE-0713', '2018-07-31 16:43:43', '0000-00-00 00:00:00', '2018-08-03 14:01:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018073105/BNA', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'SOCIETE BENINOISE D’ENERGIE ELECTRONIQUE', 'SBEE', '贝宁', 'Chantal C. DOSSOU', '00229 21 37 73 84/85', 'daem_pase@yahoo.com', '贝宁国家电力公司', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('123', '{9057CE50-7E4C-4884-95C1-D554A5C96007}', '60', 'INHE-0514', '2018-08-07 11:17:29', '0000-00-00 00:00:00', '2018-08-09 09:03:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080702/PET', '', 'Pars Tableau', '', '伊朗', 'Behrouz', '00971506406560', 'behrouz.hajian@gmail.com', 'Pars Tableau是伊朗的EPC承包商，主要从事变电站，配电，转换开关等工程的施工建设，业务范围包括伊朗，中亚，中东，欧洲等区域，且在该区域已经积累了大量的工程建设经验以及市场资源。', '', 'Public Establishment for Transmission of Electricity', 'PETE', '叙利亚', 'Mohamed', '+963 11 2133972', 't.a.g.d@pete.gov.sy', 'PETE是于2011年由叙利亚总统巴沙尔亲自颁发号令成立，借此于电力系统发电和配电单独开来。PETE主要负责叙利亚输电网络的运营，维护以及开发，同时还负责接入该网络的用户的售电。', '', 'Pars Tableau', '', '伊朗', 'Behrouz', '00971506406560', 'behrouz.hajian@gmail.com', 'Pars Tableau是伊朗的EPC承包商，主要从事变电站，配电，转换开关等工程的施工建设，业务范围包括伊朗，中亚，中东，欧洲等区域，且在该区域已经积累了大量的工程建设经验以及市场资源。');
INSERT INTO `crs_tabledata1530` VALUES ('125', '{C391F686-DBAB-4C22-9D8C-8E9A1BF172D8}', '61', 'INHE-0713', '2018-08-08 10:58:50', '0000-00-00 00:00:00', '2018-08-13 08:49:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080802/GNC', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '00228222211355', '', '老代理', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224)623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '00228222211355', '', '老代理');
INSERT INTO `crs_tabledata1530` VALUES ('126', '{FAB0E448-D0F4-4BAB-85BD-B44F26DE15DF}', '61', 'INHE-0719', '2018-08-08 13:41:59', '0000-00-00 00:00:00', '2018-08-13 08:48:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080803/PLL', '建议不要使用PEA做代码', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。', '', '', '', '', '', '', '', '', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('127', '{978C465F-6566-40D5-A967-4C4F7CFAF6BA}', '61', 'INHE-0722', '2018-08-08 16:50:44', '0000-00-00 00:00:00', '2018-10-22 11:44:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080804/MAE', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Proveedora e Importadora Valan S.A. de C.V.', 'Valan', '墨西哥', 'Ruben Martin Torres Montijo', '(662)1 41 72 71', '<ruben.torres@medithor.com>', 'Proveedora e Importadora Valan S.A.de C.V.建立于2002年，主营业务为输电、配电等工程类项目、进口和生产电气设备和电子材料以及提供能源解决方案。拥有自己的品牌Medithor，目前在电表行业管理着超过4000台电表。');
INSERT INTO `crs_tabledata1530` VALUES ('128', '{8F137484-3570-477A-BB57-4D5942E4F008}', '60', 'INHE-0066', '2018-08-09 15:57:17', '0000-00-00 00:00:00', '2018-08-13 08:42:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018080902/RTK', '', 'JSC NPK ROTEK', 'ROTEK', '俄罗斯', 'Sergei Ledin', '+7495 545 4985', 's.ledin@rotek.ru', '该客户为当地领先的电信、广播设备研发、制造商及系统集成商，成立于1991年，主要业务方向为：通信/广播设备研发生产；网络集成。主要客户群体为：国家组织，政府部门机构，电信运行商，银行、金融公司，大型企业和中小企业，业务模式为定制和实施项目。客户自己生产热量表和用于连接水表的LoRa调制解调器。在智能电表的本地组装和计量验证方面有经验。\r随着市场需求的发展，需寻找长久的智能电表和系统的供应商合作伙伴。', '', '', '', '', '', '', '', '', '', 'JSC NPK ROTEK', 'ROTEC', '俄罗斯', 'Sergei Ledin', '+7495 545 4985', 's.ledin@rotek.ru', '该客户为当地领先的电信、广播设备研发、制造商及系统集成商，成立于1991年，主要业务方向为：通信/广播设备研发生产；网络集成。主要客户群体为：国家组织，政府部门机构，电信运行商，银行、金融公司，大型企业和中小企业，业务模式为定制和实施项目。该客户为当地领先的电信、广播设备研发、制造商及系统集成商，成立于1991年，主要业务方向为：通信/广播设备研发生产；网络集成。主要客户群体为：国家组织，政府部门机构，电信运行商，银行、金融公司，大型企业和中小企业，业务模式为定制和实施项目。客户自己生产热量表和用于连接水表的LoRa调制解调器。在智能电表的本地组装和计量验证方面有经验。\r\r\n随着市场需求的发展，需寻找长久的智能电表和系统的供应商合作伙伴。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('129', '{6C647D3B-EC42-42E8-A00D-F824C8993A19}', '66', 'INHE-0634', '2018-08-10 16:10:41', '0000-00-00 00:00:00', '2018-08-15 08:38:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081001/NBL', '', 'Alpha Power Engineering CO., ltd', 'ALPHA', '缅甸', 'MYINT TUN NAING', '09254899953', 'myinttunnaing@alphapowerengineering.com', '阿尔法电力工程有限公司是缅甸仰光一家EPC公司，成立于2010年，有多次参与电力公司投标经验，当地关系网络相对成熟。是LS（智能能源）, CEWE（电力监测仪器和传感器和电力管理系统）, Secure,（电力监控） Commax（智能家居）等品牌分销商。产品：供应245kV的分站设备（气体断路器，断路开关，电流互感器，电压互感器，避雷器和电力变压器）；245kV ACSR，AAC，HDBC，和相关配件等。供应控制面板，电池组和充电器、电力线载波（PLCC设备）、电源线和电缆附件（400V至66kV）XLPE，SWA，AWA，Cu，PVC端接套件和接头，保护继电器和电表。官网：http://alphapowerengineering.com/', '', 'Electricity Supply Enterprise', 'ESE', '缅甸', '', '', '', '缅甸内比都电力局。内比都是缅甸首都，人口约115.8万。', '', 'Alpha Power Engineering CO., ltd', 'ALPHA', '缅甸', 'MYINT TUN NAING', '09254899953', 'myinttunnaing@alphapowerengineering.com', '阿尔法电力工程有限公司是缅甸仰光一家EPC公司，成立于2010年，有多次参与电力公司投标经验，当地关系网络相对成熟。是LS（智能能源）, CEWE（电力监测仪器和传感器和电力管理系统）, Secure,（电力监控） Commax（智能家居）等品牌分销商。产品：供应245kV的分站设备（气体断路器，断路开关，电流互感器，电压互感器，避雷器和电力变压器）；245kV ACSR，AAC，HDBC，和相关配件等。供应控制面板，电池组和充电器、电力线载波（PLCC设备）、电源线和电缆附件（400V至66kV）XLPE，SWA，AWA，Cu，PVC端接套件和接头，保护继电器和电表。官网：http://alphapowerengineering.com/');
INSERT INTO `crs_tabledata1530` VALUES ('130', '{8B9B5BF2-8D70-407E-B13E-3A2D0D00F610}', '60', 'INHE-0712', '2018-08-14 15:17:08', '0000-00-00 00:00:00', '2018-08-16 09:41:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081402/IDB', '', 'JAGUAR OVERSEAS LIMITED', 'JAGUAR', '印度', 'Anil Tiwari', '+91 11 4900 3939', 'anil.tiwari@jaguaroverseas.com', '捷豹海外有限公司是一家全球项目工程公司，从事交钥匙工程，采购和施工（EPC）项目以及供应项目，拥有电力，农业，工业厂房，基础设施，可再生能源等领域的专业知识。是一家ISO认证公司，业务遍及非洲和亚洲。', '', '', '', '', '', '', '', '', '', 'JAGUAR OVERSEAS LIMITED', 'JAGUAR', '印度', 'Anil Tiwari', '+91 11 4900 3939', 'anil.tiwari@jaguaroverseas.com', '捷豹海外有限公司是一家全球项目工程公司，从事交钥匙工程，采购和施工（EPC）项目以及供应项目，拥有电力，农业，工业厂房，基础设施，可再生能源等领域的专业知识。是一家ISO认证公司，业务遍及非洲和亚洲。');
INSERT INTO `crs_tabledata1530` VALUES ('131', '{9B96922F-D72D-4AFA-9B46-198DFADB8B07}', '60', 'INHE-0729', '2018-08-15 16:18:07', '0000-00-00 00:00:00', '2018-08-20 16:21:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081501/CFD', '', 'Confidence Group', 'Confidence', '孟加拉国', 'Md. Akhterujjaman', '+88 01971 76 16 97', 'confidenceakt@gmail.com', '与孟加拉军方企业以及电力公司有关系，以往业务均为向上述企业直接供货。公司合伙人之一是一个华人，在孟加拉生活30多年，熟知当地的业务。有意向向我司直接采购预付费表零配件，在孟加拉组装，通过国有企业GEMCO向REB等电力公司供货。直接采购（简称直采）在孟加拉规定只有政府性质的公司之间才可以开展直接采购。REB还有约2400万只表的需求，其中一部分需求将直采。', '', '', '', '', '', '', '', '', '', 'Confidence Group', 'Confidence', '孟加拉国', 'Md. Akhterujjaman', '+88 01971 76 16 97', 'confidenceakt@gmail.com', '与孟加拉军方企业以及电力公司有关系，以往业务均为向上述企业直接供货。公司合伙人之一是一个华人，在孟加拉生活30多年，熟知当地的业务。有意向向我司直接采购预付费表零配件，在孟加拉组装，通过国有企业GEMCO向REB等电力公司供货。直接采购（简称直采）在孟加拉规定只有政府性质的公司之间才可以开展直接采购。REB还有约2400万只表的需求，其中一部分需求将直采。');
INSERT INTO `crs_tabledata1530` VALUES ('132', '{6B8153B2-CB3D-4BBB-B237-69648AFD4AA4}', '60', 'INHE-0088', '2018-08-16 17:11:14', '0000-00-00 00:00:00', '2018-08-22 13:45:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081602/STE', '', '', '', '', '', '', '', '', '', 'State Electric Company Limited', 'STE', '马尔代夫', 'Abdul Maliku Thaufeeq', '009603338122', 'AbdulMaliku.Thaufeeq@stelco.com.mv', 'STELCO电力公司从1949年开始发展，装机容量仅为14千瓦，并为马累的住宅提供电力。过去五十年来，公司以“电力部”和“马尔代夫电力局”等不同名称作为政府部门运作。 1997年，“国家电力公司”“State Electric Company” STELCO成立。最初的客户数量在马累约有50个房屋。今天，不同岛屿的客户总数已增至37,660人，其他岛屿的客户数量增至14,462人（截至2016年6月）。每年约增长8%用户，目前总装机容量达到70MW。', '{6B8153B2CB3D4BBBB23769648AFD4AA4FFC3E6BB8328443AA9AAC603FC047FE8}_马尔代夫市场调查.docx', 'State Electric Company Limited', 'STE', '马尔代夫', 'Abdul Maliku Thaufeeq', '009603338122', 'AbdulMaliku.Thaufeeq@stelco.com.mv', 'STELCO电力公司从1949年开始发展，装机容量仅为14千瓦，并为马累的住宅提供电力。过去五十年来，公司以“电力部”和“马尔代夫电力局”等不同名称作为政府部门运作。 1997年，“国家电力公司”“State Electric Company” STELCO成立。最初的客户数量在马累约有50个房屋。今天，不同岛屿的客户总数已增至37,660人，其他岛屿的客户数量增至14,462人（截至2016年6月）。每年约增长8%用户，目前总装机容量达到70MW。');
INSERT INTO `crs_tabledata1530` VALUES ('133', '{94CBC276-8A85-4304-9E6D-5023B43DB956}', '61', 'INHE-0440', '2018-08-17 01:44:33', '0000-00-00 00:00:00', '2018-08-17 16:07:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018081701/TTC', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\r\r\r\n\"						\r\r\n', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），配电物料采购占每年财务预算的金额很大。						\r\r\r\n', '{94CBC2768A8543049E6D5023B43DB956FFC3E6BB8328443AA9AAC603FC047FE8}_General Procurement Notice  2018-2019.pdf', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', ' INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划投资其他配电产品的工厂，并将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('134', '{254E0723-0C26-4F60-906B-CD98D29B535A}', '61', 'INHE-0713', '2018-08-20 16:33:04', '0000-00-00 00:00:00', '2018-08-22 11:51:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082001/GDN', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('135', '{B665B9F4-BA82-46EF-A079-33F2A3093D65}', '61', 'INHE-0431', '2018-08-21 09:39:41', '0000-00-00 00:00:00', '2018-08-22 09:15:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082101/LMU', '', 'Pascal Computer Services Ltd', 'PCS', '毛里求斯', '', '+230 213 1518/213 1519', 'marketing@pascalcomputer.net', '客户是毛里求斯有三十年历史，做IT行业的。是联想，Dell,HP在当地的经销商。 有给电力公司CEB供过IT设备。', '{B665B9F4BA8246EFA07933F2A3093D6511015FBC745F4B1982FBEF12F4BBACD1}_Pascal Computer Services - Company Profile.pdf', 'Central Electricity Board', 'CEB', '毛里求斯', 'The Ag General Manager', '+(230) 404-2000', '', '该客户是毛里求斯电力公司，始建于1953年，归属毛里求斯政府所有，直接向能源部汇报。负责全国近40%的发电（其余由IPP提供），输电和配电。全国有近47万用户。', '', 'Central Electricity Board', 'CEB', '毛里求斯', 'The Ag General Manager', '+(230) 404-2000', '', '该客户是毛里求斯电力公司，始建于1953年，归属毛里求斯政府所有，直接向能源部汇报。负责全国近40%的发电（其余由IPP提供），输电和配电。全国有近47万用户。');
INSERT INTO `crs_tabledata1530` VALUES ('136', '{995383FA-532F-468F-953D-E376DBC09D63}', '61', 'INHE-0642', '2018-08-21 16:56:34', '0000-00-00 00:00:00', '2018-08-22 14:31:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082102/M15', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('137', '{87643EFB-6D72-48DA-9D30-42EBE88661BD}', '61', 'INHE-0695', '2018-08-27 10:01:48', '0000-00-00 00:00:00', '2018-08-28 10:52:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082702/KAZ', '', 'Kayz Consortium Ltd', 'KAY', '尼日利亚', 'Prince Kalu Ikpemini', 'Cell: +234 809 108 3800', 'prince.kalu@ymail.com', '客户是做旅游观光，能源电力等行业的，其中能源电力是新进取得NERC认证的VENDORS，原来是和三星合作，但是因为三星在项目安排上的冲突转而与我们谈判，现在据称有一个10万台的订单在进行中', '{87643EFB6D7248DA9D3042EBE88661BD11015FBC745F4B1982FBEF12F4BBACD1}_Kayz Corporte Profile Second Draft.pdf', 'Kayz Consortium Ltd', 'KAY', '尼日利亚', 'Prince Kalu Ikpemini', 'Cell: +234 809 108 3800', 'prince.kalu@ymail.com', '客户是做旅游观光，能源电力等行业的，其中能源电力是新进取得NERC认证的VENDORS，原来是和三星合作，但是因为三星在项目安排上的冲突转而与我们谈判，现在据称有一个10万台的订单在进行中', '{87643EFB6D7248DA9D3042EBE88661BDFFC3E6BB8328443AA9AAC603FC047FE8}_2017财报.pdf', 'Kayz Consortium Ltd', 'KAY', '尼日利亚', 'Prince Kalu Ikpemini', 'Cell: +234 809 108 3800', 'prince.kalu@ymail.com', '客户是做旅游观光，能源电力等行业的，其中能源电力是新进取得NERC认证的VENDORS，原来是和三星合作，但是因为三星在项目安排上的冲突转而与我们谈判，现在据称有一个10万台的订单在进行中');
INSERT INTO `crs_tabledata1530` VALUES ('138', '{5F216473-04D0-4125-A2B2-5E3FEFAE0312}', '61', 'INHE-0662', '2018-08-27 09:57:29', '0000-00-00 00:00:00', '2018-08-28 14:40:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082703/DOC', '', 'Dobos Elektronikai Kft', 'Dobos', '匈牙利', 'Viktor Csaki', '36709400726', 'csaki.v@dobosltd.hu', '该公司是一家研发和销售测量配件，提供系统服务的公司，产品包括手持数据采集终端，光学头，抄读工具，GPS等。是ADD Grup的合作伙伴。该公司是一家中小型公司，为当地电力公司ELMU（原为RWE子公司，现被EON收购），EON提供电表的软件服务以及电表配件。老板和MD都是工程师出身，做事较有冲劲，有前瞻性，懂运作，与匈牙利当地的电力公司有长久和稳定的业务联系。  ', '', 'ELMU Hálózati Kft', 'ELMU', '匈牙利', 'Nemes Krisztina', '+36 302119205', 'kozbeszerzes@elmu.hu', 'ELMU是匈牙利最大的公司之一，2017年营业额为HUF236.74B，约合8.3亿美金，净收入为HUF15.49B，约合5420万美金。子公司包括ELM? Hálózati Kft，ELM?-éMáSZ Hálózati Szolgáltató Kft. éMáSZ ügyfélszolgálati Kft，ELM?-éMáSZ 负责电力业务。该公司原母公司为RWE，今年年初被EON接管。2017年EON采购了简单表和预付费表，付款及时。', '', 'Dobos Elektronikai Kft', 'Dobos', '匈牙利', 'Viktor Csaki', '36709400726', 'csaki.v@dobosltd.hu', '该公司是一家研发和销售测量配件，提供系统服务的公司，产品包括手持数据采集终端，光学头，抄读工具，GPS等。是ADD Grup的合作伙伴。该公司是一家中小型公司，为当地电力公司ELMU（原为RWE子公司，现被EON收购），EON提供电表的软件服务以及电表配件。老板和MD都是工程师出身，做事较有冲劲，有前瞻性，懂运作，与匈牙利当地的电力公司有长久和稳定的业务联系。  						\r\n。');
INSERT INTO `crs_tabledata1530` VALUES ('139', '{F4B768C7-5278-470B-AA35-F4EC77532D9C}', '60', 'INHE-0760', '2018-08-28 15:29:47', '0000-00-00 00:00:00', '2018-08-30 08:57:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018082803/WKC', '', 'kommunar corporation', '乌克兰KC公司', '乌克兰', '伊戈里', '057-702-96-23', 'ksm@tvset.com.ua', '客户为乌克兰首屈一指的国防军工企业集团公司下属的计量表计分公司，该公司成立于2003年，有成熟的销售渠道，主要销往乌克兰的东部和中部地区，和较好的政府资源，经常与国企合作进行电表改造项目。在占据乌克兰电表20%左右的市场份额，是一位非常有潜力的合作伙伴。', '', '', '', '', '', '', '', '', '', 'kommunar corporation', '乌克兰KC公司', '乌克兰', '伊戈里', '057-702-96-23', 'ksm@tvset.com.ua', '客户为乌克兰首屈一指的国防军工企业集团公司下属的计量表计分公司，该公司成立于2003年，有成熟的销售渠道，主要销往乌克兰的东部和中部地区，和较好的政府资源，经常与国企合作进行电表改造项目。在占据乌克兰电表20%左右的市场份额，是一位非常有潜力的合作伙伴。');
INSERT INTO `crs_tabledata1530` VALUES ('140', '{41E94B8B-CDAF-47C5-A1BE-782C4FCD6910}', '61', 'INHE-0744', '2018-09-03 10:00:55', '0000-00-00 00:00:00', '2018-09-11 13:38:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090301/UDP', '请补充详细信息', '突尼斯国家电力与燃气有限公司', 'STEG', '突尼斯', 'Radhouane DAKHLI', '(+216) 71 341 311', 'radhouanedakhli@steg.com.tn', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户', '', '突尼斯国家电力与燃气有限公司', 'STEG', '突尼斯', 'Radhouane DAKHLI', '(+216) 71 341 311', 'radhouanedakhli@steg.com.tn', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户', '', '突尼斯国家电力与燃气有限公司', 'STEG', '突尼斯', 'Radhouane DAKHLI', '(+216) 71 341 311', 'radhouanedakhli@steg.com.tn', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户');
INSERT INTO `crs_tabledata1530` VALUES ('141', '{B6D99E53-D838-4509-A265-F7EAD6DD86D2}', '60', 'INHE-0549', '2018-09-04 09:38:10', '0000-00-00 00:00:00', '2018-09-12 15:22:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090401/PRE', '', 'KAMA.SA', '', '马里', 'Neneman CAMARA', '00 223 66 75 59 22', 'ncamara@kama-sa.com', '是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。', '', '', 'EDG', '几内亚', 'Neneman CAMARA', '00 223 66 75 59 22', '', '几内亚电力生产、运输和分配公用事业单位。EDG的上层结构包括四个董事、一个总秘书处和21个部门，拥有1400多名员工。目前电力公司内部几大高管由法国Veolia公司的人担任。						\r\n', '', 'KAMA.SA', '', '马里', 'Neneman CAMARA', '00 223 66 75 59 22', 'ncamara@kama-sa.com', '是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。');
INSERT INTO `crs_tabledata1530` VALUES ('142', '{6094887B-5643-4EB4-B4AE-E79D8E1496EF}', '61', 'INHE-0695', '2018-09-04 16:39:00', '0000-00-00 00:00:00', '2018-09-07 08:49:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090402/NBT(旧)', '', 'Vallin SIA', 'Vallin', '拉脱维亚', 'Aivars Malnacs', '+37129221237', 'aivars@vallin.lv', 'VALLIN公司自1994年以来一直从事电能，安装，仪表和会计，电信和工作安全领域的材料营销和营销。\r\r\n该公司业务范围包括拉脱维亚和立陶宛，办公室和仓库位于里加（拉脱维亚），销售办事处位于维尔纽斯（立陶宛）。\r\r\n该公司之前在代理 Actaris（现Itron）的产品，现因价格因素，寻求新的合作伙伴。', '', 'Energijos Skirstymo Operatorius AB', 'ESO', '立陶宛', '', '+370 5 277 75 24', 'info@eso.lt', 'Energijos Skirstymo Operatorius AB成立于2016年1月1日，合并LESTO AB和一家股份公司Lietuvos dujos。ESO由国有能源公司【Lietuvos Energija】控制，该公司是波罗的海国家最大的能源公司之一。\r\r\r\n\r\r\r\nESO的主要活动：电力供应和分配，天然气分配，电力和天然气供应保障，电力和天然气的引入，电力和燃气配电网络的维护和发展，能源分配保证的安全性和可靠性。\r\r\r\n\r\r\r\nESO为立陶宛的160万客户提供服务。公司服务面积平方公里达到65.3万。平方公里。', '', 'Energijos Skirstymo Operatorius AB', 'ESO', '立陶宛', '', '+370 5 277 75 24', 'info@eso.lt', 'ESO计划于今年十月份展开正式的NB-IoT智能电表试点招标项目，于八月发布了初版的技术规格等待各表厂分析。\r\r\n\r\r\n\r\r\n将于9月19日召开公开会议，代理会参与至该会议中。此后，将基于本技术规格及公开会议反馈结果，制定正式版的技术规格，于十月份正式开始试点招标。\r\r\n\r\r\n\r\r\n经评估后，若试点效果较好，预计四年内会有180万台的智能电表招标计划。');
INSERT INTO `crs_tabledata1530` VALUES ('143', '{730BDCCB-FFBB-40DB-96BD-7738D4157C04}', '61', 'INHE-0578', '2018-09-06 16:58:54', '0000-00-00 00:00:00', '2018-09-10 13:44:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090601/COP', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('144', '{DEB5760A-9D3B-49F9-A67A-0AC3B4712699}', '61', 'INHE-0725', '2018-09-07 10:23:08', '0000-00-00 00:00:00', '2018-09-11 13:39:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090701/IRL', '', 'Integrated Resources Limited', 'IRL', '尼日利亚', 'Mr.Duro', '+2348028490450', '', '尼日利亚能源公司，在电力能源行业有10年的经验，其主要的服务项目包括设计和建设输电/配电网络，供应和安装电力设备，项目风险评估和管理', '', 'Ibadan Electricity Distribution Company Plc', 'IBEDC', '尼日利亚', 'John Donnachie', '+234 809 990 9177', 'john.donnachie@ibedc.com', 'Ibadan Electricity Distribution Company Plc（IBEDC)是尼日利亚十一家电力公司之一，实力强劲，于2013年11月1日成立，现主要负责Oyo, Ogun, Osun及Kwara州的输配电工作，负责并监督该区域的电表采购。IBEDC是与菲律宾最大电力公司MERALCO是合作伙伴关系，每年对电表的需求量排在尼日利亚11家电力公司前列。', '', 'Ibadan Electricity Distribution Company Plc', 'IBEDC', '尼日利亚', 'John Donnachie', '+234 809 990 9177', 'john.donnachie@ibedc.com', 'Ibadan Electricity Distribution Company Plc（IBEDC)是尼日利亚十一家电力公司之一，实力强劲，于2013年11月1日成立，现主要负责Oyo, Ogun, Osun及Kwara州的输配电工作，负责并监督该区域的电表采购。IBEDC是与菲律宾最大电力公司MERALCO是合作伙伴关系，每年对电表的需求量排在尼日利亚11家电力公司前列。');
INSERT INTO `crs_tabledata1530` VALUES ('145', '{64D95DAD-4DB5-49B5-A04D-395E8363F12D}', '61', 'INHE-0440', '2018-09-09 16:52:34', '0000-00-00 00:00:00', '2018-09-11 13:39:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2018090901/TTL', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\r\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等）。电表采购已经分到全国的6个区域，国内限制招标，本地采购和本地生产。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\" INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r\n\"								\r\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('146', '{BF20A9E5-B011-4AE3-9E42-1F215AE3183C}', '66', 'INHE-0579', '2018-09-10 17:19:47', '0000-00-00 00:00:00', '2018-09-12 15:35:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091001/BRT', '', 'KLK Sprl', 'KLK', '布隆迪', 'Santillana Kamikazi', '+257 76 828 800', 'santillana@klksprl.com', 'KLK SPRL成立于2012年。业务范围涉及电气产品贸易，EPC工程项目等。近5年供货线缆，低高压电力产品以及水管等产品给电力公司。雇员数量根据项目情况而定，常驻员工15人。', '', '', '', '', '', '', '', '', '', 'KLK Sprl', 'KLK', '布隆迪', 'Santillana Kamikazi', '+257 76 828 800', 'santillana@klksprl.com', 'KLK SPRL成立于2012年。业务范围涉及电气产品贸易，EPC工程项目等。近5年供货线缆，低高压电力产品以及水管等产品给电力公司。雇员数量根据项目情况而定，常驻员工15人。');
INSERT INTO `crs_tabledata1530` VALUES ('147', '{8F6A6821-67DB-48BD-B10B-7C1EB1701DBF}', '93', 'INHE-0762', '2018-09-10 16:59:18', '0000-00-00 00:00:00', '2018-09-12 15:35:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091002/DAO', '', '', '', '', '', '', '', '', '', 'Regideso', 'Regideso', '布隆迪', 'Simeon Habonimana', '0025761205205', 'simhabonimana@gmail.com', '客户为布隆迪国家水电局公司，国有企业', '', 'Regideso', 'Regideso', '布隆迪', 'Simeon Habonimana', '0025761205205', 'simhabonimana@gmail.com', '客户为布隆迪国家水电局公司，国有企业');
INSERT INTO `crs_tabledata1530` VALUES ('148', '{857572E7-6653-4CA7-B40B-0281F4958E58}', '61', 'INHE-0434', '2018-09-17 03:12:12', '0000-00-00 00:00:00', '2018-09-19 09:10:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091701/SRM08', '', 'RAYMAN PLC', 'RAYMAN', '埃塞俄比亚', 'Abdulwase Ibrahim', '+251 912612444', 'abdexo@gmail.com', '1） R 公司是一家有店铺的电气经销商，主要经营断路器，简单的 DIN 分表，目测产品全部是自 己品牌。此公司有两家门店，做批发和零售，也做投标和代理。该公司据说有一支 5 人 的技术团队；有一个 800 平的仓库（据说原先计划组装手机卖）。 2） 拜访的是 R 公司的老板 F 和业\r\n务经理 A。沟通来看，F 清楚本地的税费（关税=高达 100%， 增值税=15%，所得税=高达 35%）。从开车，吃饭和家庭成员数量来看，F 估计有钱：开车是 奔驰，谈吐淡定，思路清晰。业务经理 A 是电气专业， 沟通来看熟悉配电业务（对银河 BOX300，LPU，DTMS，DA 和变电站方案感觉很兴奋，直接 表示自己可以拿到标书草稿，可以运作银河技术点进标书；有朋友，有办法）。另外，很有 意思的 F 和 R 去过深圳创银，说某项目代理创银（有 2016 年去创银的照片），一切都弄好， 创银最后一刻不开保函放弃了；导致他们对创银印象不好。 3） F 和我方洽谈，对我方要求投资 25 万美元建厂设备，表现的比较淡定。只是提到，一旦拿 单供货，需要银河做些支持。 4） 对于我方安排的任务，R 公司算是比较快', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('149', '{CD6DEB34-33DF-469C-B185-B005C580EFAF}', '61', 'INHE-0578', '2018-09-18 02:38:44', '0000-00-00 00:00:00', '2018-09-19 09:08:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2018091801/KLM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', 'matsotso.vuso@nyamezela.co.za', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', 'matsotso.vuso@nyamezela.co.za', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', 'matsotso.vuso@nyamezela.co.za', '');
INSERT INTO `crs_tabledata1530` VALUES ('150', '{259A4184-8B30-4483-906D-EAF04B05CE8F}', '60', 'INHE-0549', '2018-09-19 23:21:45', '0000-00-00 00:00:00', '2018-09-25 14:06:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092001/EPS', '', 'ENTREPRISE DE COMMERCE GENERAL EQUIPEMENTS ET INSTALLATIONS DIVERS', 'ECEID', '布基纳法索', 'KABRE KOUKA ERNEST', '+226 70 20 42 21', 'eceid_4790@yahoo.fr', '布基纳法索首都瓦加杜古的一家贸易公司', '', 'Société nationale d`électricité', 'SNEL', '刚果（金）', 'MIKAEL DUCHATEAU', '+243 81 607 62 54', 'md.gfi@forrestgroup.com', 'SNEL是刚果民主共和国的电力公司，负责电力生产、传输和配送。它是一家于1970年5月16日根据第70/033号法令成立的一家上市公司，根据2008年7月7日第08/007号法律第四条和2009年4月24日第09/12号法律修改，变为一家有限责任公司，刚果民主共和国为唯一股东，受有关责任公司的法律和法规管辖，受特定法律法规以及这些章程的约束。SNEL于2018年3月份正式推出预付费电表计划。', '', 'Eurafrican Power Solutions', 'EPS', '比利时', 'MIKAEL DUCHATEAU', '+32 (0)10.23.96.65', 'md.gfi@forrestgroup.com', '福雷斯特集团是一家成立于1922年的集团公司，目前活跃于中非和东非。该集团目前有21家分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，从事各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。                                   EPS是福雷斯特集团能源分支下的一家子公司，其目标是协调福雷斯特集团能源分支。它活跃在能源领域的集团公司的所有活动中。EPS于2014年，在巩固福雷斯特集团能源分支的框架下建立。该公司的使命是项目管理，采购，设计和工程，融资和国际发展。EPS完全由福雷斯特集团持有，总部位于比利时瓦夫尔。');
INSERT INTO `crs_tabledata1530` VALUES ('151', '{565367A5-4057-4782-949D-93EA9FF6C60C}', '61', 'INHE-0440', '2018-09-20 05:24:06', '0000-00-00 00:00:00', '2018-09-25 14:04:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092002/TTM', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"\"\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\r\r\"						\r\n', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。						\r\r\r\n', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r\n								\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('152', '{39E63B1D-8227-45BB-A97E-2CB2A33F86BC}', '61', 'INHE-0593', '2018-09-21 05:50:22', '0000-00-00 00:00:00', '2018-09-26 09:42:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092101/BFC', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户					\r\n', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户');
INSERT INTO `crs_tabledata1530` VALUES ('153', '{96692E97-2D73-4BBC-B8C6-91A811B7C356}', '61', 'INHE-0654', '2018-09-21 09:31:44', '0000-00-00 00:00:00', '2018-09-21 09:55:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092103/PSA20', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', '', '', '', '', '', '', '', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('154', '{6EB6D2B4-CBC8-459E-86D5-6EF54E843CEB}', '61', 'INHE-0500', '2018-09-24 10:40:29', '0000-00-00 00:00:00', '2018-09-29 10:19:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092401/BCA', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。');
INSERT INTO `crs_tabledata1530` VALUES ('155', '{A2B2E30A-0604-4BB9-B57D-9169570F8AEE}', '93', 'INHE-0762', '2018-09-25 03:24:45', '0000-00-00 00:00:00', '2018-09-29 10:18:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092501/SSP', '', 'Pascal Nsengiyumva', 'Pascal', '卢旺达', 'Pascal Nsengiyumva', '+250 78 854 1360', 'pas108@hotmai.com', '客户为个人佣金代理，其同时兼做卢旺达一家贸易公司ROUSANT的国家代表，ROUSANT主要为卢旺达国电提供电缆，电线等电网配套设备，与银河供货范围不冲突。代理每年通过ROUSANT给国电的供货金额达到600万美金上下，其与国电采购总监的关系非常好。', '', 'Energy Development Corporation (EDCL) Ltd', 'EDCL', '卢旺达', 'Managing director office', 'Tel.: (250) 787172265', 'procurement@edcl.reg.rw', '卢旺达国电下属分管电力生产，输送的公司。', '', 'Energy Development Corporation (EDCL) Ltd', 'EDCL', '卢旺达', 'Managing director office', 'Tel.: (250) 787172265', 'procurement@edcl.reg.rw', '卢旺达国电下属分管电力生产，输送的公司。');
INSERT INTO `crs_tabledata1530` VALUES ('156', '{D1A95BB9-6D6C-4E4F-B346-C474089B3507}', '61', 'INHE-0776', '2018-09-25 13:44:12', '0000-00-00 00:00:00', '2018-09-29 10:18:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092504/PAL', '急需技术支持', 'Power and Energy, Constructors, Suppliers and Consultants S.A.', '01PAL', '巴拿马', 'Rafeal Rios', '+507 66714986', 'rrios@pecsandc.com', '主营高压变电站和输电线路的保护和控制的电力业务，也为电力生产商提供技术支持', '', '', '', '', '', '', '', '', '', 'Power and Energy, Constructors, Suppliers and Consultants S.A.', '01PAL', '巴拿马', 'Rafeal Rios', '+507 66714986', 'rrios@pecsandc.com', '主营高压变电站和输电线路的保护和控制的电力业务，也为电力生产商提供技术支持');
INSERT INTO `crs_tabledata1530` VALUES ('157', '{4968F1EA-D35D-4E61-8796-D5E18B1D84EB}', '60', 'INHE-0549', '2018-09-25 17:22:29', '0000-00-00 00:00:00', '2018-09-29 10:16:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092506/EPA', '', 'Groupe Forrest International S.A.', '', '比利时', 'Frederic CHAUDOIR', '+32 (0)10.23.96.21', 'fchaudoir.gfi@forrestgroup.com', 'Forrest集团（也是福雷斯特集团）是一家成立于1922年的集团公司，目前活跃于中非和东非。 它由Malta Forrest创立，目前由新西兰血统的比利时企业家George Arthur Forrest持有。Forrest集团今天包括许多分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，包括各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。', '', 'Société nationale d`électricité', 'SNEL', '刚果（金）', 'MIKAEL DUCHATEAU', '+243 81 607 62 54', 'md.gfi@forrestgroup.com', 'SNEL是刚果民主共和国的电力公司，负责电力生产、传输和配送。它是一家于1970年5月16日根据第70/033号法令成立的一家上市公司，根据2008年7月7日第08/007号法律第四条和2009年4月24日第09/12号法律修改，变为一家有限责任公司，刚果民主共和国为唯一股东，受有关责任公司的法律和法规管辖，受特定法律法规以及这些章程的约束。SNEL于2018年3月份正式推出预付费电表计划。', '', 'Groupe Forrest International S.A.', '', '比利时', 'Frederic CHAUDOIR', '+32 (0)10.23.96.21', 'fchaudoir.gfi@forrestgroup.com', 'Forrest集团（也是福雷斯特集团）是一家成立于1922年的集团公司，目前活跃于中非和东非。 它由Malta Forrest创立，目前由新西兰血统的比利时企业家George Arthur Forrest持有。Forrest集团今天包括许多分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，包括各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。');
INSERT INTO `crs_tabledata1530` VALUES ('158', '{E65EE986-8AE0-4FF9-9187-EE8616954D17}', '61', 'INHE-0440', '2018-09-25 16:57:22', '0000-00-00 00:00:00', '2018-09-29 10:16:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092507/TTW', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"\"\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\r\r\"						\r\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。						\r\r\r', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r');
INSERT INTO `crs_tabledata1530` VALUES ('159', '{7E9D5BD8-7B0A-4C99-A7BB-11D5A418174D}', '60', 'INHE-0760', '2018-09-26 15:27:39', '0000-00-00 00:00:00', '2018-09-29 10:33:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092602/KLD', '', '', '', '', '', '', '', '', '', '克孜奥尔达配电公司', 'KZ', '哈萨克斯坦', '吉娜', '+77242902244', 'zakup.ebrd@krek.kz', '客户为哈萨克斯坦克孜奥尔达州的州配电公司', '', '克孜奥尔达配电公司', 'KZ', '哈萨克斯坦', '吉娜', '+77242902244', 'zakup.ebrd@krek.kz', '客户为哈萨克斯坦克孜奥尔达州的州配电公司');
INSERT INTO `crs_tabledata1530` VALUES ('160', '{C74F86CC-7A11-49F7-944F-85C71B1B0C81}', '60', 'INHE-0601', '2018-09-26 18:24:46', '0000-00-00 00:00:00', '2018-10-29 18:17:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092603/PTQ', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。', '', 'Provincial Electricity Authority', 'PEA', '泰国', 'MONGKHON PHETKAI', '（662）590-5638', 'mongkol.phe@pea.mail.go.th', 'PEA是泰国最大的电力公司，PEA的电网业务覆盖泰国99.98%的国土面积，拥有512个变电站和914个办公地点。\r\nPEA拥有2400万用户，是第二大电力公司MEA用户的3倍以上。');
INSERT INTO `crs_tabledata1530` VALUES ('161', '{0D63B6BE-7E74-4500-B520-3DB27DFDBA6E}', '61', 'INHE-0578', '2018-09-27 02:54:43', '0000-00-00 00:00:00', '2018-09-29 10:09:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092701/KWM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('162', '{62460E01-0C06-47C0-8BBA-BB79EECAF773}', '61', 'INHE-0770', '2018-09-27 11:45:03', '0000-00-00 00:00:00', '2018-09-28 09:07:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092703/ONL', '', 'OMNISWIFT NIGERIA LIMITED., LTD', 'ONL', '尼日利亚', 'Idris', '+234 701 582 0002', 'idris@omniswift.com', '该公司位于尼日利亚首都阿布贾，2011年创立，主营业务IT战略咨询、软件服务和基础设施解决方案。主要合作伙伴为微软、惠普、戴尔、思科系统等。2016年给当地配电公司Kaduna Disco提供过软件支持服务。', '{62460E010C0647C08BBABB79EECAF77311015FBC745F4B1982FBEF12F4BBACD1}_OmniSwift PROFILE 2018.pdf', 'Kaduna Electricity Distribution Plc', 'KNEDC', '尼日利亚', 'Mustapha', '', 'mustapha.ahmed@kadunaelectric.com', '该配电公司是尼日利亚11家配电公司之一，负责尼日利亚的Kaduna, Kebbi, Sokoto, Zamfara地区的售电业务，客户人数约为49万（2018年），家庭用户数量排名第六，尼日利亚排名前三的电力公司之一。', '', 'OMNISWIFT NIGERIA LIMITED., LTD', 'ONL', '尼日利亚', 'Idris', '+234 701 582 0002', 'idris@omniswift.com', '该公司位于尼日利亚首都阿布贾，2011年创立，主营业务IT战略咨询、软件服务和基础设施解决方案。主要合作伙伴为微软、惠普、戴尔、思科系统等。2016年给当地配电公司Kaduna Disco提供过软件支持服务。');
INSERT INTO `crs_tabledata1530` VALUES ('163', '{9C813246-DFF8-473C-BE69-A62383DDFD1A}', '61', 'INHE-0578', '2018-09-27 14:22:40', '0000-00-00 00:00:00', '2018-09-29 10:34:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092706/ELM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('164', '{B6AD8335-36F1-42D3-80FD-0FFD4AA32379}', '61', 'INHE-0744', '2018-09-27 15:05:09', '0000-00-00 00:00:00', '2018-09-29 10:31:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092802/CNU', '请附上标书', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。');
INSERT INTO `crs_tabledata1530` VALUES ('165', '{EF03C313-1B02-462E-9230-5C8DFC636B86}', '60', 'INHE-0769', '2018-09-28 16:21:26', '0000-00-00 00:00:00', '2018-09-30 18:59:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018092803/JJP', '', 'Irbid District Electricity Company', '', '约旦', 'Mohamed', '+ 96227104650', 'ideco@ideco.com.jo', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '', 'Jordanian Electric Power Company Limited', 'JEPCO', '约旦', 'Rami', '00962795136135', 'rami.khatib@ideco.com.jo', 'JEPCO成立于1938年。约旦66%的用电都是有JEPCO提供的，每年大约都有1-2次的采购计划，感兴趣的主要是预付费电表及AMI方案。Jepco 这边AMR 从CT/CTVT部分开始，已经完成了将近60%的部分，全部由 Landis-gyr负责，采用的是GPRS（2G）方案。单三相电能表方面，正在做G3PLC和高速PLC的试点，我们的竞争对手主要有海兴，华立，科陆等。代理和电力公司对我们现场演示的AMI方案都比较满意。', '', 'Jordanian Electric Power Company Limited', 'JEPCO', '约旦', 'Rami', '00962795136135', 'rami.khatib@ideco.com.jo', 'JEPCO成立于1938年。约旦66%的用电都是有JEPCO提供的，每年大约都有1-2次的采购计划，感兴趣的主要是预付费电表及AMI方案。Jepco 这边AMR 从CT/CTVT部分开始，已经完成了将近60%的部分，全部由 Landis-gyr负责，采用的是GPRS（2G）方案。单三相电能表方面，正在做G3PLC和高速PLC的试点，我们的竞争对手主要有海兴，华立，科陆等。代理和电力公司对我们现场演示的AMI方案都比较满意。');
INSERT INTO `crs_tabledata1530` VALUES ('166', '{623B1C3D-A308-4A86-A09D-A9F948AF211C}', '61', 'INHE-0642', '2018-10-06 05:04:14', '0000-00-00 00:00:00', '2018-10-08 11:13:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100601/M12-F1', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('167', '{A10845EC-7141-4A9A-A14C-ABE41B07EC16}', '61', 'INHE-0432', '2018-10-07 16:39:11', '0000-00-00 00:00:00', '2018-10-10 10:49:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100701/EIA', '', '', '', '', '', '', '', '', '', 'Arab Organization for Industrialization', 'AOI', '埃及', '', '', '', '阿拉伯工业化组织（AOI）是埃及，沙特阿拉伯王国，阿拉伯联合酋长国和卡塔尔国于1975年成立的埃及阿拉伯军事组织，负责监督阿拉伯国防工业的集体发展。随着AOI成员国之间关系的逐渐恶化，埃及于1993年成为AOI的唯一所有者。AOI现直属于埃及国防部管辖。', '', 'Arab Organization for Industrialization', 'AOI', '埃及', '', '', '', '阿拉伯工业化组织（AOI）是埃及，沙特阿拉伯王国，阿拉伯联合酋长国和卡塔尔国于1975年成立的埃及阿拉伯军事组织，负责监督阿拉伯国防工业的集体发展。随着AOI成员国之间关系的逐渐恶化，埃及于1993年成为AOI的唯一所有者。AOI现直属于埃及国防部管辖。');
INSERT INTO `crs_tabledata1530` VALUES ('168', '{8DF95881-03E9-4820-B5E4-1EFBF4F50940}', '61', 'INHE-0593', '2018-10-07 22:34:22', '0000-00-00 00:00:00', '2018-10-10 11:35:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100702/DEN', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('169', '{F42E2519-B80E-4150-8C16-46EF94085CC0}', '61', 'INHE-0642', '2018-10-07 23:39:42', '0000-00-00 00:00:00', '2018-10-10 10:49:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100704/M16(旧)', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('170', '{A275BD56-CA96-4C61-9C8E-3933CE4888F0}', '93', 'INHE-0091', '2018-10-08 10:50:38', '0000-00-00 00:00:00', '2018-10-10 10:49:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100801/DAM', '', 'Al-Tareq For Engineering Technology Co.', '', '约旦', 'Munzer Maraqa', '+962 (0) 6   556 25 02', 'munzer@tateco-eng.com', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '', 'Irbid District Electricity Co.Ltd.', 'Ideco', '约旦', '', '+962 2 7201500', 'ideco@IDECO.com.jo', '负责约旦北部的发电、输电和配电业务，涵盖整个约旦国家区域的25.6%', '', 'Irbid District Electricity Co.Ltd.', 'Ideco', '约旦', '', '+962 2 7201500', 'ideco@IDECO.com.jo', '负责约旦北部的发电、输电和配电业务，涵盖整个约旦国家区域的25.6%');
INSERT INTO `crs_tabledata1530` VALUES ('171', '{A85DD409-DEF8-4D2B-8135-10C162C3BCB0}', '60', 'INHE-0769', '2018-10-08 16:32:26', '0000-00-00 00:00:00', '2018-10-09 16:43:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100806/PED', '', 'NEW MACHINERY CO.', 'NEW MACHINERY', '叙利亚', 'Anas Hasan', '963 – 933 – 678 789', 'anash@amirgroup.com', '叙利亚当地服务经销商，是AL AMIR GROUP旗下的子公司。', '', 'Public Establishment for Transmission of Electricity', 'PETE', '叙利亚', 'Mohamed', '+963 11 2133972', 't.a.g.d@pete.gov.sy', 'PETE是于2011年由叙利亚总统巴沙尔亲自颁发号令成立，借此于电力系统发电和配电单独开来。PETE主要负责叙利亚输电网络的运营，维护以及开发，同时还负责接入该网络的用户的售电。', '', 'NEW MACHINERY CO.', 'NEW MACHINERY', '叙利亚', 'Anas Hasan', '963 – 933 – 678 789', 'anash@amirgroup.com', '叙利亚当地服务经销商，是AL AMIR GROUP旗下的子公司。');
INSERT INTO `crs_tabledata1530` VALUES ('172', '{3FE85CE7-06CF-414F-BE43-A738E33520DF}', '61', 'INHE-0772', '2018-10-08 16:50:58', '0000-00-00 00:00:00', '2018-10-10 11:34:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100807/GBA', '', 'SanaJaiteh CO LTD', 'SANA', '冈比亚', 'SANA', '+220 7500005', 'sanajaiteh4@gmail.com', '扶轮社冈比亚主席，菲律宾驻冈比亚使领馆领事，政治掮客；目前所知该代理有两次中国到访记录，第一次2017年随政府代表团到广州，以及本次中非论坛随代表团来北京。运作特变的输变电项目。与能源部，财政部和总统有较好关系。曾定居英国，为人健谈友善，做事谨慎', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室');
INSERT INTO `crs_tabledata1530` VALUES ('173', '{3BDEDB93-AC29-433F-8773-7B9714A1075B}', '61', 'INHE-0719', '2018-10-09 09:56:51', '0000-00-00 00:00:00', '2018-10-12 14:52:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100905/PLA', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。', '', 'Electro Oriente S.A.', '暂无', '秘鲁', 'Lic. Gustavo Jorge Domecq Domecq', '+ 51 0414-77010', 'gdomecq@elor.com.pe', 'Electro oriente S.A是国家电力公司，集发电，输电，配电和商业售电于一体，由国家全资拥有，FONAFE(秘鲁国家商业活动融资基金）负责，具有技术，行政，经济和财务自主权。该公司的服务必须以公共事业和广大群体的社会利益优先为准则。在1983年成立，主要的影响区域有478,415,.09平方公里（占全国的37.22%),主要包括洛雷托，圣马丁，亚马逊和卡哈马卡几个区域，在2015年底该公司的股本被全部认购，总价值大约为161,73百万美元。', '{3BDEDB93AC29433F87737B9714A1075BFFC3E6BB8328443AA9AAC603FC047FE8}_Electro Oriente 2018财政状况.pdf', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('174', '{C4547EB9-AF63-4C09-AD51-60DC0415745C}', '61', 'INHE-0772', '2018-10-09 15:23:20', '0000-00-00 00:00:00', '2018-10-12 14:49:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100906/MLO', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作。自2016年开始与我司合作，今年9月开始供货。', '', 'Energie du Mali –SA', 'EDM-SA', '马里', '', '223 20 23 30 60', '', '马里能源公司是一家工商业性质股份有限公司。于1960年10月14日由马里政府创办。\r\n创立初期马里能源公司涉及两个业务领域，第一是生产和配送可饮用水，第二部分是在马里共和国全境内发电生产、输电、供电。\r\n2011年1月1日生产和配送可应用水功能分离，从此马里能源公司仅负责电力部门的管理。马里政府持有马里能源公司66%股份，剩下的34%由IPS WA持有，马里能源公司服务402 000个客户，其中2000个高压用户，另外400 000个低压客户分布于全国各地。', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作。自2016年开始与我司合作，今年9月开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('175', '{705E9B85-856E-4AE3-AB07-6405864AAC33}', '60', 'INHE-0549', '2018-10-09 16:44:31', '0000-00-00 00:00:00', '2018-10-10 14:41:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018100907/CAM', '', 'Société IYA', '', '马里', 'Yacouba DIAKITE', '+223 6687 8891', 'yacou.diakite99@gmail.com', '马里本地一家做一般贸易，服务提供，勘探采矿和分包商采矿的公司。', '', '', 'EDM', '马里', 'Fodebc CAMARA', '+223 7620 8369', 'Fodebc@gmail.com', '马里电力公司', '', 'Société IYA', '', '马里', 'Yacouba DIAKITE', '+223 6687 8891', 'yacou.diakite99@gmail.com', '马里本地一家做一般贸易，服务提供，勘探采矿和分包商采矿的公司。');
INSERT INTO `crs_tabledata1530` VALUES ('176', '{6755339A-C744-424D-8059-675A32D6A380}', '61', 'INHE-0440', '2018-10-11 04:22:02', '0000-00-00 00:00:00', '2018-10-12 14:51:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101101/TTB', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					\r\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等）。电表采购已经分到全国的6个区域，国内限制招标，本地采购和本地生产。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\" INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r');
INSERT INTO `crs_tabledata1530` VALUES ('177', '{4A7A6472-0D80-4C4A-9128-AF05BECE827B}', '61', 'INHE-0440', '2018-10-11 17:07:54', '0000-00-00 00:00:00', '2018-10-16 09:09:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101102/TTD', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等）。电表采购已经分到全国的6个区域，国内限制招标，本地采购和本地生产。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\" INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								');
INSERT INTO `crs_tabledata1530` VALUES ('179', '{432842E3-4D5F-43B5-A755-DEBEA6C7FB4F}', '61', 'INHE-0500', '2018-10-14 13:29:32', '0000-00-00 00:00:00', '2018-10-16 16:33:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101401/BVM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('180', '{9FDF1A0D-7C10-4A8F-B468-AC251ECD72B7}', '61', 'INHE-0500', '2018-10-15 03:28:40', '0000-00-00 00:00:00', '2018-10-16 16:33:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101501/CDE', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('181', '{BC74E2D9-39A4-4049-ADDB-61336097698D}', '61', 'INHE-0744', '2018-10-15 09:44:01', '0000-00-00 00:00:00', '2018-10-16 16:33:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101502/CND', '', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。');
INSERT INTO `crs_tabledata1530` VALUES ('182', '{82C2498B-8620-4E16-9846-346BEB94346A}', '61', 'INHE-0578', '2018-10-16 14:13:25', '0000-00-00 00:00:00', '2018-10-17 17:30:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101601/COB', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('183', '{673045A8-B667-4777-B685-7F9104F771E1}', '61', 'INHE-0719', '2018-10-16 15:53:43', '0000-00-00 00:00:00', '2018-10-17 09:48:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101602/PLB', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。', '', 'ELECTRO UCAYALI S.A.', '暂无', '秘鲁', 'Ing. Celestino Rojas Gamarra', '(061) 59-6454 Anexos 420 ó 422', 'crojas@electroucayali.com.pe', '1995年成立，是一家国家电力公司，由Electrocentro SA出资建立，又名Empresa Concesionaria de Electricidad de Ucayali S.A.\r\n集发电，输电，配电于一体。主要影响区域是秘鲁的ucayali大区，用户数量大概为50000，拥有在Coronel Portillo，Padre Abad和Atalaya三个省份的特许经营权，前两个地区都已经连接进秘鲁唯一的国家大电网（SEIN)里了。', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('184', '{BCA8646D-C2F3-4DD1-8E6E-E5B0102BFB82}', '93', 'INHE-0762', '2018-10-16 17:56:39', '0000-00-00 00:00:00', '2018-10-18 10:55:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101603/LPU', '', 'Energy Utility Corporation Limited', 'EUCL', '卢旺达', 'Aimee M.UWANYILIGIRA', 'TEL:(+250)788 303 858', 'Email:auwanyiligira@eucl.reg.rw', 'KN82 ST3\r\nNyarugenge District\r\nKigali City\r\nP.O. Box 537 Kigali, Rwanda\r\nTel: +(250) (0) 78 818 1224\r\nEmail: info@reg.rw\r\nWebsite: www.reg.rw', '', '', '', '', '', '', '', '', '', 'Energy Utility Corporation Limited', 'EUCL', '卢旺达', 'Aimee M.UWANYILIGIRA', 'TEL:(+250)788 303 858', 'Email:auwanyiligira@eucl.reg.rw', 'KN82 ST3\r\nNyarugenge District\r\nKigali City\r\nP.O. Box 537 Kigali, Rwanda\r\nTel: +(250) (0) 78 818 1224\r\nEmail: info@reg.rw\r\nWebsite: www.reg.rw');
INSERT INTO `crs_tabledata1530` VALUES ('185', '{3809822F-C1D3-41C9-856C-F1FA22627FAB}', '60', 'INHE-0088', '2018-10-17 09:10:29', '0000-00-00 00:00:00', '2018-10-31 09:01:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101701/TNB', '此市场AMI一期项目立项流程为MSM，后改为TNB，现为二期项目正式完成流程立项', 'DELTAPRIMA METERING SDN BHD', 'DPM', '马来西亚', 'Malek Salleh', '+6017-3796358', 'malek.salleh@deltaprima.com.my', '该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持,对国内深开发、思达、科陆', '{3809822FC1D341C9856CF1FA22627FAB11015FBC745F4B1982FBEF12F4BBACD1}_DeltaPrima Metering - Company Profile.pdf', 'Tenaga Nasional Berhad', 'TNB', '马来西亚', 'Datin Saraswathy A/p Sinniah', 'Tel : +603 2296 5566', 'saraswathys@tnb.com.my', '马来西亚 TNB电力公司（TenagaNasional Berhad），负责马来西亚半岛的发电、输电和配电工作。TNB电力公司建于1990年9月，其前身为1949年建立的中央电力局（CEB），后更名为国家电力局（NEB）。TNB实行股份制，股东有国内的也有国际的，但马来西亚政府通过财政部继续保持着过半数的股份。1992年，TNB的股票在吉隆坡股票交易所上市。1996年1月，TNB百年债券成功发行。\r\nTNB积极推行发电燃料多样化的政策，采用天然气、煤、石油和水电4种燃料发电，以减少对石油的依赖。利用本上天然气发展高效能的燃气发电厂是TNB的长远计划。\r\nTNB在马来西亚半岛上架设的输电系统，主要电压等级是275kV、132kV和66kV。整个电网由位于吉隆坡的国家负荷调度中心和若干不同的区域控制中心所控制。TNB的电力系统还与新加坡、泰国的电网相连以交换电力。目前 TNB正着手建设一条500kV输电线路，它将成大国家电网的骨干线路。\r\nTNB的配电系统电压等级一般为33kV或更低。对需要较高电压的用户，则由变电站直接向用户供电。马来西亚的电力供应正向独立电力生产者（IPP）方向过渡。马', '', 'DELTAPRIMA METERING SDN BHD', 'DPM', '马来西亚', 'Malek Salleh', '+6017-3796358', 'malek.salleh@deltaprima.com.my', '该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持,对国内深开发、思达、科陆');
INSERT INTO `crs_tabledata1530` VALUES ('186', '{694772BA-F135-4A89-9ADD-2ABF9C784653}', '60', 'INHE-0769', '2018-10-17 09:15:06', '0000-00-00 00:00:00', '2018-10-31 09:02:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101702/MEW', '', 'UNITED GULF CONSTRUCTION CO W.L.L', 'UGCC', '科威特', 'Khaled Almanzalawy', '965 99753248', 'khaled.almanzalawy@ugcc.com', '科威特排名前六的工程建设公司\r\nUGCC隶属于科威特Jeeran Holding company，owner为美籍伊朗人Aliyar Dehghani，其目前长居美国，公司目前由其子Kevin实际运营，Holding下面有四家公司，UGCC（Construction EPC承包商）占Jerran Holding 60%的股份，总资产约为20亿美元，主要业务包括道路建设，管道建设，房屋建造，区域性综合体建设等；主要客户有科威特公共事业部，公共房屋福利部，科威特石油公司，科威特国家石油公司；另外，科威特是中冶在科威特的代理，据中冶的人反映，UGCC实力还不错。', '', 'Ministry of Electricity and Water of State of Kuwait', 'MEW', '科威特', 'Mohammad Alharibat', '965 2537 1000', 'info@mew.gov.kw', '科威特水电部（MEW）客户事业部副部长Dr. Misha’a Al-Otaibi 2017年底表示，为了提高国家智能电网的发展，科威特推出了旧电表更换成智能电表的计划。该项计划在2018年上半年开始进行项目招标，智能电表的招标数量是80万台，未来可能扩展到120万台。科威特电信公司Zain赢得科威特水电部（MEW）智能计量竞标项目，在未来七年负责科威特智能表计系统项目，包括维护、管理智能电表和水表抄表系统，培训客服中心人员，开发电子付费系统等。Zain会和E&Y公司、爱立信公司合作推进该项目，前两年主要安装智能仪表，后五年主要是维护管理抄表系统。按照科威特水电部的计划，第一批智能仪表将安装在基础设施建设部门、工业和农业部门的物业，其次是住宅用户。', '', 'Ministry of Electricity and Water of State of Kuwait', 'MEW', '科威特', 'Mohammad Alharibat', '965 2537 1000', 'info@mew.gov.kw', '科威特水电部（MEW）客户事业部副部长Dr. Misha’a Al-Otaibi 2017年底表示，为了提高国家智能电网的发展，科威特推出了旧电表更换成智能电表的计划。该项计划在2018年上半年开始进行项目招标，智能电表的招标数量是80万台，未来可能扩展到120万台。科威特电信公司Zain赢得科威特水电部（MEW）智能计量竞标项目，在未来七年负责科威特智能表计系统项目，包括维护、管理智能电表和水表抄表系统，培训客服中心人员，开发电子付费系统等。Zain会和E&Y公司、爱立信公司合作推进该项目，前两年主要安装智能仪表，后五年主要是维护管理抄表系统。按照科威特水电部的计划，第一批智能仪表将安装在基础设施建设部门、工业和农业部门的物业，其次是住宅用户。');
INSERT INTO `crs_tabledata1530` VALUES ('187', '{342105D7-A915-4CE2-AED0-14FF0EA81E2F}', '61', 'INHE-0500', '2018-10-17 15:43:13', '0000-00-00 00:00:00', '2018-10-22 11:43:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101704/EMU', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('188', '{EB8EDC50-6E4F-4573-827D-6E9D23A1248C}', '61', 'INHE-0593', '2018-10-17 22:43:25', '0000-00-00 00:00:00', '2018-10-31 09:02:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101706/BFD', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。');
INSERT INTO `crs_tabledata1530` VALUES ('189', '{2F2E4C20-F04A-4BBC-83B7-6C381A29B31B}', '60', 'INHE-0549', '2018-10-18 21:48:03', '0000-00-00 00:00:00', '2018-10-31 09:02:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101801/EPB', '', 'Groupe Forrest International S.A.', '', '比利时', 'Frederic CHAUDOIR', '+32 (0)10.23.96.21', 'fchaudoir.gfi@forrestgroup.com', 'Forrest集团（也是福雷斯特集团）是一家成立于1922年的集团公司，目前活跃于中非和东非。 它由Malta Forrest创立，目前由新西兰血统的比利时企业家George Arthur Forrest持有。Forrest集团今天包括许多分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，包括各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。', '', 'Société nationale d`électricité', 'SNEL', '刚果（金）', 'MIKAEL DUCHATEAU', '+243 81 607 62 54', 'md.gfi@forrestgroup.com', 'SNEL是刚果民主共和国的电力公司，负责电力生产、传输和配送。它是一家于1970年5月16日根据第70/033号法令成立的一家上市公司，根据2008年7月7日第08/007号法律第四条和2009年4月24日第09/12号法律修改，变为一家有限责任公司，刚果民主共和国为唯一股东，受有关责任公司的法律和法规管辖，受特定法律法规以及这些章程的约束。SNEL于2018年3月份正式推出预付费电表计划。', '', 'Eurafrican Power Solutions', 'EPS', '比利时', 'MIKAEL DUCHATEAU', '+32 (0)10.23.96.65', 'md.gfi@forrestgroup.com', '福雷斯特集团是一家成立于1922年的集团公司，目前活跃于中非和东非。该集团目前有21家分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，从事各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。                                   EPS是福雷斯特集团能源分支下的一家子公司，其目标是协调福雷斯特集团能源分支。它活跃在能源领域的集团公司的所有活动中。EPS于2014年，在巩固福雷斯特集团能源分支的框架下建立。该公司的使命是项目管理，采购，设计和工程，融资和国际发展。EPS完全由福雷斯特集团持有，总部位于比利时瓦夫尔。');
INSERT INTO `crs_tabledata1530` VALUES ('190', '{2575123F-C86C-43AE-8664-25D785DE47B9}', '61', 'INHE-0432', '2018-10-19 01:36:17', '0000-00-00 00:00:00', '2018-10-30 17:34:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101901/SGT', '', 'STALCO S.A.', '', '希腊', 'Panagiotis Manis', '0030 (210 68 24 538)', 'manispanagiotis@stalco.gr', 'STALCO SA是希腊一家实力较强的电网配电设备生产企业，其业务主要是给希腊的电力公司PPC提供中压和低压的输电设备，STALCO SA和希腊电力公司PPC有40多年的业务来往，经常参加电力公司的招投标项目，和希腊电力公司PPC的建立很好的关系。', '', 'HELLENIC ELECTRICITY DISTRIBUTION NETWORK OPERATOR S.A.', '', '希腊', 'Materials, Purchasing and Transportation Department', '210 909 0529', '', '希腊配电网络运营公司HEDNO是希腊公共电力公司（希腊最大的电力公司，为政府所有）的分公司，负责希腊配电网络的运营、维护及发展。', '', 'HELLENIC ELECTRICITY DISTRIBUTION NETWORK OPERATOR S.A.', '', '希腊', 'Materials, Purchasing and Transportation Department', '210 909 0529', '', '希腊配电网络运营公司HEDNO是希腊公共电力公司（希腊最大的电力公司，为政府所有）的分公司，负责希腊配电网络的运营、维护及发展。');
INSERT INTO `crs_tabledata1530` VALUES ('191', '{D9E751BB-6D5F-4EA1-B15E-2C9DAA41EB97}', '61', 'INHE-0725', '2018-10-19 14:48:33', '0000-00-00 00:00:00', '2018-10-24 14:42:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018101902/GLZ', '', 'Process * Plant Automation Ltd', '', '加纳', 'Mr.Adika Kwadzo', '+233-050-1256607', 'kadika@automationghana.com', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表', '', 'Ministry of Energy(Ghana)', 'MOE', '加纳', 'Joseph Cudjoe（能源部副部长）', '+233(0)302667090', 'joseph.cudjoe@energymin.gov.gh', '加纳能源部是加纳政府部门，负责能源政策的制订、执行、监测和评估，同时负责各能源部门活动的监督和协调。该部的任务是发展和维持一个有效力，实现财政创收的能源部门，提倡竞争，为当地人民提供安全、安全和可靠的能源供应，以满足加纳的发展需要。', '', 'Electricity Company of Ghana Limited', 'ECG', '加纳', 'Ing.S. Boakye-Appiah', '+233(0)208118709', 'sboakye-appiah@ecggh.com', '加纳电力公司(ECG)是加纳政府全资控股的电力公司。加纳电力公司(ECG)于1997年2月成立。它始于1947年4月1日的电力部，负责全国的配电，1967年改称为加纳电力公司。1987年北方电力公司（NED）成立，自此ECG主要负责加纳1/3的地区（南部人口密集地区）的输配电工作，现管理用户超过180万。');
INSERT INTO `crs_tabledata1530` VALUES ('192', '{52CFA997-B911-4491-B68C-C0050ED051EB}', '61', 'INHE-0434', '2018-10-23 11:42:12', '0000-00-00 00:00:00', '2018-10-30 17:36:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102301/GLA', '', 'Process * Plant Automation Ltd', '', '加纳', 'Mr.Adika Kwadzo', '+233-050-1256607', 'kadika@automationghana.com', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表', '', 'Ministry of Energy(Ghana)', 'MOE', '加纳', 'Joseph Cudjoe（能源部副部长）', '+233(0)302667090', 'joseph.cudjoe@energymin.gov.gh', '加纳能源部是加纳政府部门，负责能源政策的制订、执行、监测和评估，同时负责各能源部门活动的监督和协调。该部的任务是发展和维持一个有效力，实现财政创收的能源部门，提倡竞争，为当地人民提供安全、安全和可靠的能源供应，以满足加纳的发展需要。', '{52CFA997B9114491B68CC0050ED051EBFFC3E6BB8328443AA9AAC603FC047FE8}_GLA项目标书.docx', 'Electricity Company of Ghana Limited', 'ECG', '加纳', 'Ing.S. Boakye-Appiah', '+233(0)208118709', 'sboakye-appiah@ecggh.com', '加纳电力公司(ECG)是加纳政府全资控股的电力公司。加纳电力公司(ECG)于1997年2月成立。它始于1947年4月1日的电力部，负责全国的配电，1967年改称为加纳电力公司。1987年北方电力公司（NED）成立，自此ECG主要负责加纳1/3的地区（南部人口密集地区）的输配电工作，现管理用户超过180万。');
INSERT INTO `crs_tabledata1530` VALUES ('193', '{0FB8A7D6-EB86-4250-BE0F-1CD4BBB2AF2B}', '60', 'INHE-0560', '2018-10-23 17:05:26', '0000-00-00 00:00:00', '2018-11-07 18:48:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102303/MEA', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'ОАО *Меридиан* им. С.П. Королёва', 'ОАО *Меридиан*', '乌克兰', 'Александр', '(+38050) 380-03-61', 'sales@merydian.kiev.ua', '“Meridian”n.S.P Korolov股份公司是一家现代化企业，专门从事各种用途的电子设备的开发和批量生产，制造和供应机械单元和组件，提供符合欧洲标准的广泛服务。除此之外，也涉猎无人机系统，大型注塑模具制造，3D测量设备及电镀等产业。在乌克兰已有65年的经营历史及品牌经验，拥有丰富的客户资源及人脉关系。');
INSERT INTO `crs_tabledata1530` VALUES ('194', '{9F664E80-F1FE-4F77-9B96-2C0986D369BB}', '61', 'INHE-0500', '2018-10-24 12:41:28', '0000-00-00 00:00:00', '2018-10-30 17:37:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102402/ZCO', '', 'Econet Wireless Zimbabwe', 'EWZ', '津巴布韦', 'Taona Sylvester Jakachira', '+263772222118', 'Taona.Jakachira@econet.co.zw', '1.津巴布韦最大的电信运行商，市场份额50%，也是津巴布韦最大私人集团公司，主营业务以电信通讯基础设施建设和运行、有线和无线网络运营、EFT电子转账ECOCASH运营、IPP独立发电等为主；\r\n2.客户正在计划实施智能电表战略规划，即第一阶段：通过其自营的IPP太阳能发电站建立其完善的智能计量网络，第二阶段：通过和津巴布韦电力公司ZETDC联合，将智能计量的方案推广到全国；\r\n3.当前银河是第一个给此客户做宣讲的智能表计厂商，并进行了正式宣讲，初步得到了客户的认可。', '', 'Econet Wireless Zimbabwe', 'EWZ', '津巴布韦', 'Taona Sylvester Jakachira', '+263772222118', 'Taona.Jakachira@econet.co.zw', '1.津巴布韦最大的电信运行商，市场份额50%，也是津巴布韦最大私人集团公司，主营业务以电信通讯基础设施建设和运行、有线和无线网络运营、EFT电子转账ECOCASH运营、IPP独立发电等为主；\r\n2.客户正在计划实施智能电表战略规划，即第一阶段：通过其自营的IPP太阳能发电站建立其完善的智能计量网络，第二阶段：通过和津巴布韦电力公司ZETDC联合，将智能计量的方案推广到全国；\r\n3.当前银河是第一个给此客户做宣讲的智能表计厂商，并进行了正式宣讲，初步得到了客户的认可。', '', 'Econet Wireless Zimbabwe', 'EWZ', '津巴布韦', 'Taona Sylvester Jakachira', '+263772222118', 'Taona.Jakachira@econet.co.zw', '1.津巴布韦最大的电信运行商，市场份额50%，也是津巴布韦最大私人集团公司，主营业务以电信通讯基础设施建设和运行、有线和无线网络运营、EFT电子转账ECOCASH运营、IPP独立发电等为主；\r\n2.客户正在计划实施智能电表战略规划，即第一阶段：通过其自营的IPP太阳能发电站建立其完善的智能计量网络，第二阶段：通过和津巴布韦电力公司ZETDC联合，将智能计量的方案推广到全国；\r\n3.当前银河是第一个给此客户做宣讲的智能表计厂商，并进行了正式宣讲，初步得到了客户的认可。');
INSERT INTO `crs_tabledata1530` VALUES ('195', '{B0B6136C-FAE9-4DAB-B0FB-A5A6DCF17E4D}', '93', 'INHE-0789', '2018-10-26 18:43:31', '0000-00-00 00:00:00', '2018-10-30 17:32:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102603/MCT', '', 'IMSAQA ELECTRIC, Lda', 'IMSAQA', '莫桑比克', 'Ivo Alves', 'Tel : +258 21 400 102', 'imalves@imsaqa.co.mz', '主要做莫桑比克电力公司生意，给电力公司供产品。', '', '', '', '', '', '', '', '', '', 'IMSAQA ELECTRIC, Lda', 'IMSAQA', '莫桑比克', 'Ivo Alves', 'Tel : +258 21 400 102', 'imalves@imsaqa.co.mz', '主要做莫桑比克电力公司生意，给电力公司供产品。');
INSERT INTO `crs_tabledata1530` VALUES ('196', '{8C59DADA-BA87-423E-A1DA-D2BDAB15F486}', '66', 'INHE-0628', '2018-10-29 11:31:21', '0000-00-00 00:00:00', '2018-10-30 17:38:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2018102904/SLE', '', 'Vulcan Holdings Ltd', 'Vulcan', '塞拉利昂', 'Jiad', '+23276612500', 'vulcan@vulcanholdings.co.uk', 'Vulcan旗下有多家公司，从事工业、能源、房地产、农业、进出口贸易行业。企业控制人为黎巴嫩人，黎巴嫩裔在塞拉利昂一直控制经济命脉，较有实力。能源部电表招标项目刚刚启动，目前能源部公开的只有3万台，客户没有参与过，但曾中标过同属能源部管辖的水表(含软件)项目招标，合同金额432万美元。', '', 'ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', '', '', 'inquiry@edsa.sl', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。', '', 'Vulcan Holdings Ltd', 'Vulcan', '塞拉利昂', 'Jiad', '+23276612500', 'vulcan@vulcanholdings.co.uk', 'Vulcan旗下有多家公司，从事工业、能源、房地产、农业、进出口贸易行业。企业控制人为黎巴嫩人，黎巴嫩裔在塞拉利昂一直控制经济命脉，较有实力。能源部电表招标项目刚刚启动，目前能源部公开的只有3万台，客户没有参与过，但曾中标过同属能源部管辖的水表(含软件)项目招标，合同金额432万美元。');
INSERT INTO `crs_tabledata1530` VALUES ('197', '{3F5B647A-F44F-4536-9507-D0C15CECAB1F}', '60', 'INHE-0781', '2018-10-30 13:45:41', '0000-00-00 00:00:00', '2018-11-07 18:27:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2018103003/DSC\r\n', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Electric Supply Company Limited', 'DESCO', '孟加拉国', 'Mohd. Raihan Habib', '0088 01713090611', 'raiham@desco.org.bd', '达卡两大电力公司之一，负责达卡北部几个区的供电，客户数约90万。', '', 'Dhaka Electric Supply Company Limited', 'DESCO', '孟加拉国', 'Mohd. Raihan Habib', '0088 01713090611', 'raiham@desco.org.bd', '达卡两大电力公司之一，负责达卡北部几个区的供电，客户数约90万。');
