INSERT INTO `crs_tabledata1530` VALUES ('201', '{AAA6B5C0-C254-4AA4-B7E9-88340B967BDB}', '61', 'INHE-0500', '2018-11-02 15:46:31', '0000-00-00 00:00:00', '2018-11-06 10:01:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110203/LLM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('202', '{3378F1A2-9444-497E-BBB8-C652A3BDC291}', '93', 'INHE-0789', '2018-11-02 15:44:50', '0000-00-00 00:00:00', '2018-11-06 09:51:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110204/LCA', '', '', '', '', '', '', '', '', '', 'Millennium ChallengeAccount - Liberia', 'MCA-Liberia', '利比里亚', 'Jacob Slewion', '+231770144444', 'jacobslewion@gmail.com', '2004年初，美国总统布什在墨西哥的蒙特雷发出“世界发展新协调”的倡议，将发达国家更多的援助与发展中国家更大的责任相结合，并为此提议建立了一种机制，既“千年挑战帐户”，或称作“利于千年发展的帐户”即MCC。在此机制下，大量的发展援助基金将提供给那些实施良政、促进人类发展及鼓励经济自由化的国家。 MCA-Liberia 是利比里亚政府于2015年10月23日根据国家立法机构法案设立的一个合法，独立和自治机构。它负责管理利比里亚政府与美利坚合众国政府之间千年账户的钱款，主要集中在解决利比里亚发展中存在的两种限制性约束，可获得和负担得起的电力以及改善道路。', '', 'Millennium ChallengeAccount - Liberia', 'MCA-Liberia', '利比里亚', 'Jacob Slewion', '+231770144444', 'jacobslewion@gmail.com', '2004年初，美国总统布什在墨西哥的蒙特雷发出“世界发展新协调”的倡议，将发达国家更多的援助与发展中国家更大的责任相结合，并为此提议建立了一种机制，既“千年挑战帐户”，或称作“利于千年发展的帐户”即MCC。在此机制下，大量的发展援助基金将提供给那些实施良政、促进人类发展及鼓励经济自由化的国家。 MCA-Liberia 是利比里亚政府于2015年10月23日根据国家立法机构法案设立的一个合法，独立和自治机构。它负责管理利比里亚政府与美利坚合众国政府之间千年账户的钱款，主要集中在解决利比里亚发展中存在的两种限制性约束，可获得和负担得起的电力以及改善道路。');
INSERT INTO `crs_tabledata1530` VALUES ('203', '{F8CC4FDE-E0DB-4B95-9833-4D81EDE76DED}', '61', 'INHE-0722', '2018-11-02 20:13:12', '0000-00-00 00:00:00', '2018-11-07 18:34:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110205/HRA', '', '', '', '', '', '', '', '', '', 'Empresa Energía Honduras', 'EEH', '洪都拉斯', 'Andres Felipe Soto Mejia', '+504 9439-3780', 'andres.soto@eeh.hn', 'EEH为洪都拉斯目前唯一电力分销商，由哥伦比亚电力公司EPM(Empresas Públicas de Medellín E.S.P.)投资成立。洪都拉斯国电ENEE由于经营不善，以竞标方式将部分电力业务承包了EEH。EEH目前主要业务为中低压的输、配、售电，拥有自主采购权。EEH拥有180万用户，从2017年开始计划部署智能电表，截止2018年10月已经部署27万只智能电表。', '', 'Empresa Energía Honduras', 'EEH', '洪都拉斯', 'Andres Felipe Soto Mejia', '+504 9439-3780', 'andres.soto@eeh.hn', 'EEH为洪都拉斯目前唯一电力分销商，由哥伦比亚电力公司EPM(Empresas Públicas de Medellín E.S.P.)投资成立。洪都拉斯国电ENEE由于经营不善，以竞标方式将部分电力业务承包了EEH。EEH目前主要业务为中低压的输、配、售电，拥有自主采购权。EEH拥有180万用户，从2017年开始计划部署智能电表，截止2018年10月已经部署27万只智能电表。');
INSERT INTO `crs_tabledata1530` VALUES ('204', '{F911FECD-40AE-4B75-A007-8BE49172B830}', '61', 'INHE-0500', '2018-11-03 03:11:20', '0000-00-00 00:00:00', '2018-11-07 18:40:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110301/NML', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('205', '{3E01B1DF-5837-4400-8109-43044A8FA0A2}', '61', 'INHE-0725', '2018-11-06 08:59:28', '0000-00-00 00:00:00', '2018-11-07 18:14:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2018110603/EKO', '', 'Integrated Resources Limited', 'IRL', '尼日利亚', 'Mr.Duro', '+2348028490450', '', '尼日利亚能源公司，在电力能源行业有10年的经验，其主要的服务项目包括设计和建设输电/配电网络，供应和安装电力设备，项目风险评估和管理', '', 'Eko Electricity Distribution Plc', 'EKEDP', '尼日利亚', 'Mr Adeoye', '+234 708 065 5555', 'supplier@ekedp.com', 'Eko Electricity Distribution Plc（EKEDP)是尼日利亚十一家电力公司之一，实力强劲，现主要负责10个区域（西部：Agbara, Ojo, Festac；中部：Ijora, Mushin, Orile, Apapa；东部：Lekki, Ibeju, Lagos南部）的输配电工作，负责并监督该区域的电表采购，每年对电表需求及采购量位居11家电力公司前列。', '', 'Eko Electricity Distribution Plc', 'EKEDP', '尼日利亚', 'Mr Adeoye', '+234 708 065 5555', 'supplier@ekedp.com', 'Eko Electricity Distribution Plc（EKEDP)是尼日利亚十一家电力公司之一，实力强劲，现主要负责10个区域（西部：Agbara, Ojo, Festac；中部：Ijora, Mushin, Orile, Apapa；东部：Lekki, Ibeju, Lagos南部）的输配电工作，负责并监督该区域的电表采购，每年对电表需求及采购量位居11家电力公司前列。');
INSERT INTO `crs_tabledata1530` VALUES ('206', '{0CE68383-6016-42D2-9CB4-378F4A327E2F}', '61', 'INHE-0722', '2018-11-12 14:02:18', '0000-00-00 00:00:00', '2018-11-14 16:50:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111201/ENB', '', 'Telefónica Digital Espa?a,S.L.', 'Telefónica', '西班牙', 'Francisco Ibá?ez González', '34  689 37 02 92', 'mailto:francisco.ibanezgonzalez@telefonica.com', 'Telefónica Digital Espa?a,S.L.（西班牙电信集团）是是世界上最大的电讯公司之一，成立于1924年，业务包括固定通讯线路、移动电话、互联网、数据、有线电视等。业务范围主要集中在欧洲和拉美地区。目前在智利有个10万台的项目。', '{0CE68383601642D29CB4378F4A327E2F11015FBC745F4B1982FBEF12F4BBACD1}_20181107Telefonica展会会谈纪要.pdf', '', '', '', '', '', '', '', '', 'Telefónica Digital Espa?a,S.L.', 'Telefónica', '西班牙', 'Francisco Ibá?ez González', '34  689 37 02 92', 'mailto:francisco.ibanezgonzalez@telefonica.com', 'Telefónica Digital Espa?a,S.L.（西班牙电信集团）是是世界上最大的电讯公司之一，成立于1924年，业务包括固定通讯线路、移动电话、互联网、数据、有线电视等。业务范围主要集中在欧洲和拉美地区。目前在智利有个10万台的项目。');
