INSERT INTO `crs_tabledata1530` VALUES ('209', '{DD88F9E5-EC01-4529-8F47-CA2F1E99EA75}', '61', 'INHE-0793', '2018-12-14 14:12:06', '0000-00-00 00:00:00', '2018-12-25 20:52:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111303/SEP', '请业务深入了解合作方情况，调研市场晶振个特点和合作方市场竞争策略。不建议盲目推进。', 'SAV ENGINEERS PRIVATE LIMITED.', 'SEPL', '印度', 'Gagan Deep Ahluwalia', '011-26349075', 'marketing@savengineer.in', '该客户主要在新德里及其周边地区做智能电表经销，据其披露，其公司上半年总共销售收入913.8万人民币，公司规模为30人，其业务负责人为Gagan,学历为电力工程学学士，做事风格方面态度好，很配合，价格，条款，技术，合作方面磋商空间大。							', '{DD88F9E5EC0145298F47CA2F1E99EA7511015FBC745F4B1982FBEF12F4BBACD1}_Company Profile -SEPL.docx', 'SAV ENGINEERS PRIVATE LIMITED.', 'SEPL', '印度', 'Gagan Deep Ahluwalia', '011-26349075', 'marketing@savengineer.in', '该客户目前总资产47万人民币，负债12万人民币，上一年度利润8万人民币，现金流结余5.6万人民币，组织框架较简单，管理者两人，其余有行政，商业项目经理等，详情请见附件。该客户本体资金实力不是很强，但是客户方面表示其拥有稳定的下游客户，而且其亲属，银行处可以借到较大款项用以大项目运营，初期合作愿意采用L/C形式。', '{DD88F9E5EC0145298F47CA2F1E99EA75FFC3E6BB8328443AA9AAC603FC047FE8}_Organisaiton Chart-SAV ENGINEERS PVT. LTD..xls', 'SAV ENGINEERS PRIVATE LIMITED.', 'SEPL', '印度', 'Gagan Deep Ahluwalia', '011-26349075', 'marketing@savengineer.in', '该客户主要在新德里及其周边地区做智能电表批发，据其披露，其公司上半年总共销售收入913.8万人民币，公司规模为30人，其业务负责人为Gagan,学历为电力工程学学士，做事风格方面态度好，很配合，价格，条款，技术，合作方面磋商空间大。');
