INSERT INTO `crs_tabledata1530` VALUES ('212', '{A59F991B-2224-4BC1-98EA-545C26EA3513}', '61', 'INHE-0772', '2018-11-19 16:28:59', '0000-00-00 00:00:00', '2018-11-23 10:42:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2018111901/SBS', '请补充项目本身信息，如截标时间，允许几家中标等', 'BOCAI IMPORT EXPORT TRADE LIMITED', 'BOCAI', '塞拉利昂', '张燕村', '', '278434383@qq.com', '在该市场经商中国商人，有一定人脉关系。通过共同电力行业朋友联系上。表示当地人脉是总统亲戚。希望银河授权，支持其投标。不需要银河开保函。中标后，由银河供货。', '', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', 'Monody Mansaray', '', 'momodumansaray2@gmail.com', '该市场的国有配电公司，拿到非发行的资金用于改善入户情况，现在对5万多预付费电表，表箱，PLC电线等零配件招标。', '', 'BOCAI IMPORT EXPORT TRADE LIMITED', 'BOCAI', '塞拉利昂', '张燕村', '', '278434383@qq.com', '在该市场经商中国商人，有一定人脉关系。通过共同电力行业朋友联系上。表示当地人脉是总统亲戚。希望银河授权，支持其投标。不需要银河开保函。中标后，由银河供货。');
INSERT INTO `crs_tabledata1530` VALUES ('213', '{C2241382-2676-41F6-A1C5-74F209C9ED7D}', '60', 'INHE-0088', '2018-11-20 10:15:30', '0000-00-00 00:00:00', '2018-11-23 10:52:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112001/EDS', '', 'Electrical Dealer S. de D. L. de C.V.', 'EDS', '洪都拉斯', 'Raquel Mendoza Flores', '(504) -2558-1400', 'contabilidad@electrical-dealer.com', '洪都拉斯本地私人企业，在当地开展照明等低压电力工程项目，供应电力设备，工具，材料给私人项目及电力公司。2012年开始合作联系，推广PLC/GPRS圆表，2014年来访我司并采购了CT GPRS表运作试点。', '{C2241382267641F6A1C574F209C9ED7D11015FBC745F4B1982FBEF12F4BBACD1}_E05项目会谈纪要.doc', 'Empresa Nacional de Energía Eléctrica', 'ENEE', '洪都拉斯', 'María Elena Quan de Martínez', '2232-8000', 'atencionalcliente@enee#FE54`licitaciones@enee.hn', 'ENEE是由洪都拉斯政府拥有和运营的一家电力公司。洪都拉斯国家电力能源公司拥有4500多名员工；为130万户家庭和10多万家商业，工业客户提供服务；2012年6月约占洪都拉斯电力需求的84.8％。洪都拉斯约一半的电力部门是私人拥有的，其余的发电能力由ENEE负责\r\n\r\nEmpresa Energía Honduras（EEH）是洪都拉斯国家电力公司，由财团组建，该财团在墨西哥，巴拿马，危地马拉，哥伦比亚和智利拥有40多年的运营经验。由于洪都拉斯能源公司（EEH）负责所有电力线路，布线和所有系统的维护，所产生的总能量仅分配给城市和家庭。 私营部门只负责发电。通过国际招标成为洪都拉斯国家能源分布系统的执行公司，主要负责电网分布及维修，售电，征收以及减少和控制科技和非科技损失。', '{C2241382267641F6A1C574F209C9ED7DFFC3E6BB8328443AA9AAC603FC047FE8}_E05项目会谈纪要.doc', 'Electrical Dealer S. de D. L. de C.V.', 'EDS', '洪都拉斯', 'Raquel Mendoza Flores', '(504) -2558-1400', 'contabilidad@electrical-dealer.com', '洪都拉斯本地私人企业，在当地开展照明等低压电力工程项目，供应电力设备，工具，材料给私人项目及电力公司。2012年开始合作联系，推广PLC/GPRS圆表，2014年来访我司并采购了CT GPRS表运作试点。');
INSERT INTO `crs_tabledata1530` VALUES ('214', '{8BA8EC49-BC3D-411C-9703-4C4E9C01C269}', '97', 'INHE-0549', '2018-11-20 14:01:04', '0000-00-00 00:00:00', '2018-11-27 09:24:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112002/PCB', '', 'KAMA.SA', '', '马里', 'Neneman CAMARA', '00 223 66 75 59 22', 'ncamara@kama-sa.com', '是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。', '', 'SOCIETE NIGERIENNED`ELECTRICITE', 'NIGELEC', '尼日尔', 'ALHASSANE HALID', '227 20 72 26 92', 'nigelec@intnet.ne', '尼日尔电力公司,是尼日尔的极地发电输电配电公用事业。在特许经营制度下实现尼日尔电力公共服务的使命，以期实现生产，购买，进口，运输和分配电能的目的。创建时间：1968年9月1日,尼日利亚政府有多数股权，其管理由矿业和能源部监督，经营四座发电厂。资本约33.56亿非郎（合610万美元），总部位于尼日尔的首都及最大城市尼亚美。', '', 'SOCIETE NIGERIENNED`ELECTRICITE', 'NIGELEC', '尼日尔', 'ALHASSANE HALID', '227 20 72 26 92', 'nigelec@intnet.ne', '尼日尔电力公司,是尼日尔的极地发电输电配电公用事业。在特许经营制度下实现尼日尔电力公共服务的使命，以期实现生产，购买，进口，运输和分配电能的目的。创建时间：1968年9月1日,尼日利亚政府有多数股权，其管理由矿业和能源部监督，经营四座发电厂。资本约33.56亿非郎（合610万美元），总部位于尼日尔的首都及最大城市尼亚美。');
INSERT INTO `crs_tabledata1530` VALUES ('215', '{44763785-653D-47DB-B173-CBF6DE3BB32E}', '61', 'INHE-0578', '2018-11-21 09:28:42', '0000-00-00 00:00:00', '2018-11-23 11:03:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112101/ESB', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('216', '{AB3FD41D-E4C7-44EA-B7B8-63A8CBDE88F2}', '61', 'INHE-0713', '2018-11-22 14:43:43', '0000-00-00 00:00:00', '2018-11-28 10:03:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112201/GEB', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'Entreprise d?Electricité et Eau de Guinée-Bissau', 'EAGB', '几内亚比绍', 'M. Luís Alberto Cruz Gomes', '00(245)95559 91 13', 'puasee@outlook.pt#FE54` joaoantoniosilva@yahoo.com.br', '几内亚比绍电力水务公司', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('218', '{0625CB9E-2C18-4471-83D7-147F4A3378FA}', '60', 'INHE-0601', '2018-11-23 10:48:36', '0000-00-00 00:00:00', '2018-11-27 08:56:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112302/PTM', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。', '', 'Provincial Electricity Authority', 'PEA', '泰国', 'MONGKHON PHETKAI', '（662）590-5638', 'mongkol.phe@pea.mail.go.th', 'PEA是泰国最大的电力公司，PEA的电网业务覆盖泰国99.98%的国土面积，拥有512个变电站和914个办公地点。\r\nPEA拥有2400万用户，是第二大电力公司MEA用户的3倍以上。', '', 'Provincial Electricity Authority', 'PEA', '泰国', 'MONGKHON PHETKAI', '（662）590-5638', 'mongkol.phe@pea.mail.go.th', 'PEA是泰国最大的电力公司，PEA的电网业务覆盖泰国99.98%的国土面积，拥有512个变电站和914个办公地点。\r\nPEA拥有2400万用户，是第二大电力公司MEA用户的3倍以上。');
INSERT INTO `crs_tabledata1530` VALUES ('219', '{C013B01A-9759-41E2-BB31-F29A6A70276E}', '61', 'INHE-0713', '2018-11-23 14:19:37', '0000-00-00 00:00:00', '2018-11-27 08:43:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112303/SEN', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('221', '{0E7103DF-ED5E-41CD-B848-5390AEB3D57B}', '61', 'INHE-0721', '2018-11-26 16:22:26', '0000-00-00 00:00:00', '2018-11-30 08:48:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112602/NCU', '', 'Anxor Ingeniería S.A', 'Anxor', '尼加拉瓜', 'James Ariza', '+505 83960521', 'james.ariza@anxor.com', '工业解决方案供应商，为电气行业提供工程服务，并为全球公认的电气行业制造商提供代理服务。是尼加拉瓜国有电力公司DISNORTE-DISSUR以及配电公司ENATREL的供应商之一。', '', '', '', '', '', '', '', '', '', 'Anxor Ingeniería S.A', 'Anxor', '尼加拉瓜', 'James Ariza', '+505 83960521', 'james.ariza@anxor.com', '工业解决方案供应商，为电气行业提供工程服务，并为全球公认的电气行业制造商提供代理服务。是尼加拉瓜国有电力公司DISNORTE-DISSUR以及配电公司ENATREL的供应商之一。');
INSERT INTO `crs_tabledata1530` VALUES ('222', '{B36322DD-3F14-4C3E-8E45-414894A960F2}', '61', 'INHE-0440', '2018-11-26 20:24:27', '0000-00-00 00:00:00', '2018-11-30 09:45:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112603/TTF', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。					', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等）。2019年的电表需求为80万台，电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\" INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等，目前已经在供货5月份中标的TTA项目17.5万台，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								');
INSERT INTO `crs_tabledata1530` VALUES ('223', '{96313E72-0F6A-46C2-AA8B-07CE554C8BB1}', '61', 'INHE-0770', '2018-11-26 23:37:52', '0000-00-00 00:00:00', '2018-11-30 12:51:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112701/BOP', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。', '', 'Botswana Power Corporation', 'BPC', '博茨瓦纳', '', '+2673607000', 'contactcentre@bpc.bw', '博茨瓦纳电力公司（BPC）是博茨瓦纳的一家国有公司，负责发电，输电和配电。它成立于1970年，目前是该国唯一的电力供应商。Morupule电站（燃煤）供应国内发电的80％，但是该国依赖从邻国进口能源。该地区经常面临供电不足而停电的问题。', '', 'FactorFast (PTY) Ltd', 'FFL', '博茨瓦纳', 'Zaheer Bhoola', '267390 6636', 'zaheer@factorfast.co.bw', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。');
INSERT INTO `crs_tabledata1530` VALUES ('224', '{6502F8A3-AE2B-4A98-9074-5DB02C1E9381}', '61', 'INHE-0770', '2018-11-28 23:57:43', '0000-00-00 00:00:00', '2018-12-25 20:58:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112901/MPP', '请业务加强市场调查和项目运作，规避完全不符合资质的情况投标。', 'Pascal Computer Services Ltd (PCS)', 'PCS', '毛里求斯', 'Ashvina Ramnarain', '+230 213 1518', 'sales@pascalcomputer.net', 'Pascal Computer Service Ltd自1990年以来一直从事IT行业。凭借20多年的经验，PCS已成为毛里求斯IT行业中的市场领先公司，致力于为毛里求斯本地和海外市场提供高端IT产品和广泛的IT解决方案。 在银行、资本市场、医疗保健、保险和制造业拥有庞大的客户群。PCS的主要产品包括电脑硬件设备和软件设备，客户有ASUS、HP、Fujitsu、DELL、LENOVO、Microsoft等。', '', 'Central Electricity Board（CEB）', 'CEB', '毛里求斯', '', '+230 404-2000', 'ceb@intnet.mu', '中央电力委员会(CEB)是毛里求斯政府全资拥有的附属机构，向能源和公用事业部报告。行政首长协调会成立于1952年，受1964年1月25日《中央电力委员会法》的授权，CEB的业务是“制定和执行发展计划，总体目标是促进、协调和改善电力的发电、传输、分配和销售”。毛里求斯自1982以来已实现100%电气化。CEB通过自有的4个火力发电站和8个水电站生产满足约40%的全国总电力需求，其余60%从独立发电厂购买。目前，它是唯一负责向民众输送、分配和供应电力的组织。', '', 'Pascal Computer Services Ltd (PCS)', 'PCS', '毛里求斯', 'Ashvina Ramnarain', '+230 213 1518', 'sales@pascalcomputer.net', 'Pascal Computer Service Ltd自1990年以来一直从事IT行业。凭借20多年的经验，PCS已成为毛里求斯IT行业中的市场领先公司，致力于为毛里求斯本地和海外市场提供高端IT产品和广泛的IT解决方案。 在银行、资本市场、医疗保健、保险和制造业拥有庞大的客户群。PCS的主要产品包括电脑硬件设备和软件设备，客户有ASUS、HP、Fujitsu、DELL、LENOVO、Microsoft等。');
INSERT INTO `crs_tabledata1530` VALUES ('225', '{25703A62-AEC1-4495-9686-E49CBD390376}', '61', 'INHE-0654', '2018-11-29 09:39:43', '0000-00-00 00:00:00', '2018-12-07 18:38:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112902/ADF', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', 'Edenor S.A.', '', '阿根廷', 'Juliana Estefania MATA', '4346-5400', '', '阿根廷最大的电力公司，总部在首都布宜诺斯艾利斯', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。');
INSERT INTO `crs_tabledata1530` VALUES ('226', '{DE90C16C-0E8D-4BE5-8EAB-58E03600F6B1}', '66', 'INHE-0634', '2018-11-29 14:23:22', '0000-00-00 00:00:00', '2018-12-04 08:56:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018112904/KNT', '', 'Kinetic Myanmar Technology Co., Ltd', 'Kinetic', '缅甸', 'Kyaw Zin Latt', '', 'kyawzinlatt71188@gmail.com', '成立于2008年，公司主营业务范围：电信、ISP、IOT，员工总人数超过600人。', '{DE90C16C0E8D4BE58EAB58E03600F6B111015FBC745F4B1982FBEF12F4BBACD1}_Profile.pdf', '', '', '', '', '', '', '', '', 'Kinetic Myanmar Technology Co., Ltd', 'Kinetic', '缅甸', 'Kyaw Zin Latt', '', 'kyawzinlatt71188@gmail.com', '成立于2008年，公司主营业务范围：电信、ISP、IOT，员工总人数超过600人。');
INSERT INTO `crs_tabledata1530` VALUES ('227', '{1DD80941-5CA8-45FD-8008-2AEDA445410E}', '60', 'INHE-0601', '2018-12-04 15:05:53', '0000-00-00 00:00:00', '2018-12-19 20:37:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120401/ETA', '', 'BCI Company Limited', 'BCI', '老挝', 'Phannakone Phanyoulath', '856-20 22858585', 'PHANNAKONE1@HOTMAIL.COM', 'BCI是老挝国家电力公司EDL的工程承包商和项目咨询公司，和EDL有长期的合作关系和商业往来。', '{1DD809415CA845FD80082AEDA445410E11015FBC745F4B1982FBEF12F4BBACD1}_BCI.jpg', 'Electricite du Laos', 'EDL', '老挝', 'Anuntarumporn', '(856-21) 316133', 'Anuntarumporn @edl.com.la', '老挝电力公司（Electricite du Laos，EDL）是一家老挝国有企业，它拥有并经营老挝全国的发电，输电和配电\r\n。公司还管理老挝国家电网的电力进口和出口。老挝电力公司在1959年创建，总部位于万象。\r\n2010年7月，国际金融公司借给1500万美元给老挝电力公司在老挝农村地区来扩建电力网络和变电站。公司还\r\n从亚洲开发银行获得债务融资。到2020年，老挝政府预计将为90％的老挝家庭提供电力。', '', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Prasitchai Veerayuttwilai', '', 'prasitchai@interlink.co.th', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。');
INSERT INTO `crs_tabledata1530` VALUES ('228', '{2B6154EA-9619-4868-8DBF-86C0DFBEF592}', '66', 'INHE-0634', '2018-12-05 09:19:32', '0000-00-00 00:00:00', '2019-06-25 14:42:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120502/VIC', '', '深圳友讯达科技股份有限公司', '友讯达', '中国', 'Vicky Huang', '', 'vicky.huang@friendcom.com', '成立于2002年，是一家集研究、生产、开发于一体的高科技企业。公司主要生产集中器、采集器等电力计量设备，同时生产应用于各种水、电、气计量装置的无线数传模块，是专业的无线数据采集设备制造商。', '', '', '', '', '', '', '', '', '', '深圳友讯达科技股份有限公司', '友讯达', '中国', 'Vicky Huang', '', 'vicky.huang@friendcom.com', '成立于2002年，是一家集研究、生产、开发于一体的高科技企业。公司主要生产集中器、采集器等电力计量设备，同时生产应用于各种水、电、气计量装置的无线数传模块，是专业的无线数据采集设备制造商。');
