INSERT INTO `crs_tabledata1530` VALUES ('230', '{67B61407-F1BD-45AE-A517-BA25A2A73DBA}', '66', 'JXINHE-2559', '2018-12-06 22:08:58', '0000-00-00 00:00:00', '2019-01-04 08:28:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120603/PMT', '', 'Shahzad International(Pvt)limited', 'Shahzad International', '巴基斯坦', 'SALMAN MASOOD', '+92-51-2299031-36', 'salman@shahzadintl.com.pk', '巴基斯坦专业石油开采集团，旗下拥有石油和煤矿开采，能源，航空，保险和旅游等多家子公司，与NTDC（国家输配电公司）关系良好。', '', 'National Transmission and Despatch Company', 'NTDC', '巴基斯坦', 'Chief Engineer', '92-42-99202597', 'cempm@ntdc.com.pk', '巴基斯坦国家输配电公司，管理全国范围内的电网和输配电设施。', '', 'National Transmission and Despatch Company', 'NTDC', '巴基斯坦', 'Chief Engineer', '92-42-99202597', 'cempm@ntdc.com.pk', '巴基斯坦国家输配电公司，管理全国范围内的电网和输配电设施。');
INSERT INTO `crs_tabledata1530` VALUES ('231', '{A2A624AE-60C9-463A-931F-2C1FC83FA936}', '61', 'INHE-0744', '2018-12-10 15:31:36', '0000-00-00 00:00:00', '2018-12-10 15:31:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121001/CNT', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务');
INSERT INTO `crs_tabledata1530` VALUES ('232', '{DF8F2EA0-A9D4-4B25-98D4-AA6564A57658}', '61', 'INHE-0432', '2018-12-11 03:57:19', '0000-00-00 00:00:00', '2018-12-19 20:42:20', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121103/ELT', '', '安讯通科技有限公司', '安讯通', '中国', '黄伟', '', '', '1.成立于2016年，隶属于中国公安部，负责对接中国公安部一所、二所、三所研究院在海外的国家网络与信息安全业务拓展。                  \r\r\r\n2.注册地址为香港，因其特殊身份，网上没有公开信息。                     3.该公司为我们已立项的EIA项目合作方：埃及政府正在建设新首都并将打造为智慧城市，搭建智慧控制平台，涉及智慧交通、智慧能源、智慧控制等多方面业务，其中包含涉及国家信息与安全的业务，智能表计（三表合一）只是其中很小的一块业务。而安讯通则是中国公安部负责该项目的中国对接方，负责当地业务开发和政府关系建设、维护。                                                                            \r\r\r\n4.2018年11月业务因EIA项目出差至现场，与安讯通一起拜访了当地的另外一家国防部下属的民用工厂AIO（Arab International Optronics）,促成了电表本地建厂、本地生产的合作意向。', '', '', '', '', '', '', '', '', '', 'Arab International Optronics', 'AIO', '埃及', '', '', '', '1.正式成立于1984年，埃及国防部占51%股份，法国泰利斯集团占股49%（是设计、开发和生产航空、防御及信息技术服务产品的专业电子高科技公司，同时是法国最大的防务类机械电子科技公司）。                                                                                2.AIO是埃及国防部下属的一家民用企业，生产民用电子产品、LED灯、电子显示屏、太阳能板等。                                          \r\r\r\n3.2018年11月业务出差时，与合作伙伴一起拜访了该公司，本来是要谈EIA三表合一项目合作，却意外促成了电表本地建厂、本地生产的合作意向。');
INSERT INTO `crs_tabledata1530` VALUES ('233', '{6CB1C91C-BC3A-4C04-B253-FB719C8F3256}', '93', 'INHE-0811', '2018-12-12 17:17:53', '0000-00-00 00:00:00', '2018-12-13 11:44:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121204/SCE', '', 'E.G.C2.I SARL', 'E.G.C2.I', '塞内加尔', 'Saliou', '+221 77 614 13 35', 'saliou.fall@soprestsarl.com', '该公司是塞内加尔达喀尔地区的建筑工程公司，在建筑、安装、电焊，电力施工方面有非常丰富的经验。与塞内加尔电力公司SENELEC，ICS，SOCOCIM，SONACOS等公司都有过合作', '', 'Port Autonome de Dakar', 'PAD', '塞内加尔', 'CPM', '+221 33 849 45 45', 'cpm@portdakar.sn', '达喀尔自治港口是塞内加尔最大的贸易港口，是西非第三大港口，塞内加尔将近95%的出口物资都从该港口出口。', '', 'E.G.C2.I SARL', 'E.G.C2.I', '塞内加尔', 'Saliou', '+221 77 614 13 35', 'saliou.fall@soprestsarl.com', '该公司是塞内加尔达喀尔地区的建筑工程公司，在建筑、安装、电焊，电力施工方面有非常丰富的经验。与塞内加尔电力公司SENELEC，ICS，SOCOCIM，SONACOS等公司都有过合作');
INSERT INTO `crs_tabledata1530` VALUES ('234', '{8C4CB134-3348-4DDE-BEA9-755425DFA990}', '61', 'INHE-0744', '2018-12-13 23:48:10', '0000-00-00 00:00:00', '2018-12-19 20:21:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121401/UDZ', '', '', '', '', '', '', '', '目前共有5家代理可供选择，待考察后再决定使用哪一家', '', '突尼斯国家电力与燃气有限公司', 'STEG', '突尼斯', 'Radhouane DAKHLI', '(+216) 71 341 311', 'radhouanedakhli@steg.com.tn', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户', '', '突尼斯国家电力与燃气有限公司', 'STEG', '突尼斯', 'Radhouane DAKHLI', '(+216) 71 341 311', 'radhouanedakhli@steg.com.tn', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户');
