INSERT INTO `crs_tabledata1530` VALUES ('236', '{239B5AEE-EC9C-4761-8868-4D9DC6A45221}', '61', 'INHE-0432', '2018-12-17 05:24:25', '0000-00-00 00:00:00', '2018-12-19 20:28:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121701/MBP', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('237', '{2C451C90-14D7-4C11-AC9F-A74AAD5836C7}', '61', 'INHE-0695', '2018-12-17 10:06:16', '0000-00-00 00:00:00', '2018-12-17 11:27:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121702/SLV02', '', 'D.A.L.I. - M.N., s.r.o.', 'DALI MN', '斯洛伐克', 'Munir Pasagic', '+421 904 271 240(主要联系电话)', 'tab-mezica@tab-mezica.sk', 'ISKRAMECO在斯洛伐克及捷克的代理。\r\n公司主要代理产品包括：电池，电表，变压器，高压开关，以及电力监测系统。\r\n代理较为靠谱，在斯洛伐克本地，该代理同电力公司关系较好，同该市场三家电力公司均有业务往来，对当地的电表市场较为熟悉。\r\n同时，该公司在邻国捷克有有相应的代理业务。待关系建立成熟后，可同期将业务扩展至捷克。', '', 'Stredoslovenska distribucna, a.s.', 'SSD', '斯洛伐克', '', '', '', '斯洛伐克当地三大配电公司之一，51%股份为国有，剩余49%股份属于E.ON。\r\n主要负责斯洛伐克中部市场(Zilina, Banska). 大约有70万客户。', '', 'Stredoslovenska distribucna, a.s.', 'SSD', '斯洛伐克', '', '', '', '斯洛伐克当地三大配电公司之一，51%股份为国有，剩余49%股份属于E.ON。\r\n主要负责斯洛伐克中部市场(Zilina, Banska). 大约有70万客户。');
INSERT INTO `crs_tabledata1530` VALUES ('238', '{B2588815-B0FE-4D82-801D-A922302E32FA}', '61', 'INHE-0695', '2018-12-17 11:45:47', '0000-00-00 00:00:00', '2018-12-19 20:51:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121703/SSD', '', 'D.A.L.I. - M.N., s.r.o.', 'DALI MN', '斯洛伐克', 'Munir Pasagic', '+421 904 271 240(主要联系电话)', 'tab-mezica@tab-mezica.sk', 'ISKRAMECO在斯洛伐克及捷克的代理。\r\n公司主要代理产品包括：电池，电表，变压器，高压开关，以及电力监测系统。\r\n代理较为靠谱，在斯洛伐克本地，该代理同电力公司关系较好，同该市场三家电力公司均有业务往来，对当地的电表市场较为熟悉。\r\n同时，该公司在邻国捷克有有相应的代理业务。待关系建立成熟后，可同期将业务扩展至捷克。', '', 'Stredoslovenska distribucna, a.s.', 'SSD', '斯洛伐克', '', '', '', '斯洛伐克当地三大配电公司之一，51%股份为国有，剩余49%股份属于E.ON。\r\n主要负责斯洛伐克中部市场(Zilina, Banska). 大约有70万客户。', '', 'D.A.L.I. - M.N., s.r.o.', 'DALI MN', '斯洛伐克', 'Munir Pasagic', '+421 904 271 240(主要联系电话)', 'tab-mezica@tab-mezica.sk', 'ISKRAMECO在斯洛伐克及捷克的代理。\r\n公司主要代理产品包括：电池，电表，变压器，高压开关，以及电力监测系统。\r\n代理较为靠谱，在斯洛伐克本地，该代理同电力公司关系较好，同该市场三家电力公司均有业务往来，对当地的电表市场较为熟悉。\r\n同时，该公司在邻国捷克有有相应的代理业务。待关系建立成熟后，可同期将业务扩展至捷克。');
INSERT INTO `crs_tabledata1530` VALUES ('239', '{746F4A26-0C3D-4A9A-8778-FDC823197B14}', '66', 'INHE-0628', '2018-12-18 17:08:57', '0000-00-00 00:00:00', '2018-12-25 15:09:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2018121801/SLG', '', 'Vulcan Holdings Ltd', 'Vulcan', '塞拉利昂', 'Jiad', '+23276612500', 'vulcan@vulcanholdings.co.uk', 'Vulcan旗下有多家公司，从事工业、能源、房地产、农业、进出口贸易行业。企业控制人为黎巴嫩人，黎巴嫩裔在塞拉利昂一直控制经济命脉，较有实力。能源部电表招标项目刚刚启动，目前能源部公开的只有3万台，客户没有参与过，但曾中标过同属能源部管辖的水表(含软件)项目招标，合同金额432万美元。\r\n\r\n\r\n', '', 'ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', '', '', 'inquiry@edsa.sl', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。', '', 'Delta International limited', 'Delta', '塞拉利昂', 'Jiad', '+2327661250', '', 'Delta公司是银河SLE项目代理实际控制公司之一，目前在执行塞拉利昂电力部太阳能路灯项目。Delta将直接投标，银河作为供应商。');
INSERT INTO `crs_tabledata1530` VALUES ('240', '{3EFDA195-F89A-4E9B-99B9-B3306008B3B6}', '66', 'INHE-0774', '2018-12-24 14:41:31', '0000-00-00 00:00:00', '2018-12-27 18:28:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122401/IDE', '', 'M/S Multi Electromechanical Trading Co.', 'MEMCO', '约旦', 'Mohammad Badawieh', '+962-6-5513693', 'mohammadbadawieh@orange.jo', '（1）成立于2002年，在约旦主要经营机电产品，包括：电缆和通信电缆，负载开关和隔离器，柴油发电机，输电变压器，LV&MV 开关设备，测试设备，电缆接头，电表和水表，防爆材料等。服务电力公司，水和矿产资源主管部门，机电承包商和终端用户；\r\r\n（2）获得ISO9001:2008认证；\r\r\n（3）电表中标记录： 标号：IDECO6/2004  采购公司：IDECO，表商：ISKRAMECO 产品：3相电表 合同金额：7005 欧元\r\r\n                   标号：IDECO15/2008 采购公司：IDECO，表商：MEMF      产品：3相电表 合同金额：89000美元', '', 'Irbid District Electricity Co.,Ltd', 'IDECO', '约旦', 'Ahmed Zinat', '962-2 7201500', 'ideco@ideco.com.jo', '成立于1957年，原名Irbid National Electricity Company,经营发电，输电和Irbid,Mafraq,Jerash,Balqa等地区的配电，1967年公司更名为Irbid Electricity Company Public Shareholding Company Limited，是也门3大电力公司之一。', '', 'Irbid District Electricity Co.,Ltd', 'IDECO', '约旦', 'Ahmed Zinat', '962-2 7201500', 'ideco@ideco.com.jo', '成立于1957年，原名Irbid National Electricity Company,经营发电，输电和Irbid,Mafraq,Jerash,Balqa等地区的配电，1967年公司更名为Irbid Electricity Company Public Shareholding Company Limited，是也门3大电力公司之一。');
INSERT INTO `crs_tabledata1530` VALUES ('241', '{42D7BC09-F32C-4915-A968-0114BCA748EB}', '61', 'INHE-0722', '2018-12-25 15:33:35', '0000-00-00 00:00:00', '2018-12-27 18:10:56', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122501/HRC', '', 'RMD Energy Honduras', 'RMD', '洪都拉斯', 'Alberto Lazarus', '(+504)9918-1218', 'alberto@rmdenergy.net', 'RMD Energy,成立于2015年，主要经营太阳能等绿色能源的方案咨询，提供方案，系统安装、维护等服务。业务服务面向商业区、旅游区和居民区。在官网也见了通讯塔方面相关业务。', '{42D7BC09F32C4915A9680114BCA748EB11015FBC745F4B1982FBEF12F4BBACD1}_20181127 洪都拉斯RMD客户会谈报告.pdf', '', '', '', '', '', '', '', '', 'RMD Energy Honduras', 'RMD', '洪都拉斯', 'Alberto Lazarus', '(+504)9918-1218', 'alberto@rmdenergy.net', 'RMD Energy,成立于2015年，主要经营太阳能等绿色能源的方案咨询，提供方案，系统安装、维护等服务。业务服务面向商业区、旅游区和居民区。在官网也见了通讯塔方面相关业务。');
INSERT INTO `crs_tabledata1530` VALUES ('242', '{D0BB4524-0BE1-47B6-8861-7B1E09AFBEEF}', '66', 'INHE-0579', '2018-12-28 13:40:11', '0000-00-00 00:00:00', '2019-01-03 09:21:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2018122801/IEG', '', 'INTERFACE ENGINEERING GROUP LTD.', 'IEG', '黎巴嫩', 'Samir Jurdak', '961 3882551', 'ieg@ieglb.com', 'IEG成立于1995年\r\n公司性质：系统集成商\r\n公司规模：固定员工15人左右。根据项目增加临时雇员。\r\n公司经营范围：智能电网项目提供系统服务。\r\n项目经验：①参加阿布扎比智能电网项目。部署基于西门子SACDA的DMS系统。\r\n         ②作为NDB Technologies（加拿大）代理，为沙特阿拉配电站提供并安装完整的监控系统。', '', '', '', '', '', '', '', '', '', 'INTERFACE ENGINEERING GROUP LTD.', 'IEG', '黎巴嫩', 'Samir Jurdak', '961 3882551', 'ieg@ieglb.com', 'IEG成立于1995年\r\r\n公司性质：系统集成商\r\r\n公司规模：固定员工15人左右。根据项目增加临时雇员。\r\r\n公司经营范围：智能电网项目提供系统服务。\r\r\n项目经验：①参加阿布扎比智能电网项目。部署基于西门子SACDA的DMS系统。\r\r\n         ②作为NDB Technologies（加拿大）代理，为沙特阿拉配电站提供并安装完整的监控系统。');
INSERT INTO `crs_tabledata1530` VALUES ('243', '{A596203C-B020-4176-A792-ACE5EAE70DAB}', '66', 'INHE-0774', '2019-01-02 15:57:46', '0000-00-00 00:00:00', '2019-01-08 08:52:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019010201/EVN', '', '', '', '', '', '', '', '', '', 'EVN Macedonia AD, Skopje', 'EVN', '马其顿', 'Elena Gjorgon', '389 2 3205000-43030', 'mailto:elena.gjorgon@evn.mk', 'EVN集团是一家总部位于奥地利的电力生产商和运输商，是欧洲最大的电力生产商之一，在14个国家拥有300多万客户。该公司还经营水处理，天然气供应和废物管理业务领域。它是奥地利第二大公用事业公司。 EVN Macedonia AD, Skopje 于2006年进入马其顿，作为EVN集团的一部分，主要经营马其顿共和国的配电和供电业务。2013年售电量为5.028GW', '', 'EVN Macedonia AD, Skopje', 'EVN', '马其顿', 'Elena Gjorgon', '389 2 3205000-43030', 'mailto:elena.gjorgon@evn.mk', 'EVN集团是一家总部位于奥地利的电力生产商和运输商，是欧洲最大的电力生产商之一，在14个国家拥有300多万客户。该公司还经营水处理，天然气供应和废物管理业务领域。它是奥地利第二大公用事业公司。 EVN Macedonia AD, Skopje 于2006年进入马其顿，作为EVN集团的一部分，主要经营马其顿共和国的配电和供电业务。2013年售电量为5.028GW');
INSERT INTO `crs_tabledata1530` VALUES ('244', '{4F160DF1-9CBC-4340-A528-BA61AEF601B3}', '66', 'INHE-0634', '2019-01-09 17:25:04', '0000-00-00 00:00:00', '2019-01-15 08:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019010901/SOP', '', 'iCTS (Myanmar) Company Limited', 'ICTS', '缅甸', 'Dr.Aye Chan Myae Kyaw', '', 'ayechanmyaekyaw@ictsmyanmar.com', '2012年成立，主要做政府项目：11KV,400V输配电线EPC项目，销售电缆ACSR,OPGW,SAC，离网太阳能项目，等。', '', 'Electricity Supply Enterprise', 'ESE', '缅甸', '', '', '', '缅甸内比都电力局。内比都是缅甸首都，人口约115.8万。', '', 'iCTS (Myanmar) Company Limited', 'ICTS', '缅甸', 'Dr.Aye Chan Myae Kyaw', '', 'ayechanmyaekyaw@ictsmyanmar.com', '2012年成立，主要做政府项目：11KV,400V输配电线EPC项目，销售电缆ACSR,OPGW,SAC，离网太阳能项目，等。');
INSERT INTO `crs_tabledata1530` VALUES ('245', '{3EE5820F-9CD1-4FCA-AEAA-556B28B4CB90}', '60', 'INHE-0680', '2019-01-10 15:14:44', '0000-00-00 00:00:00', '2019-02-27 18:11:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011001/POS', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星');
