INSERT INTO `crs_tabledata1530` VALUES ('247', '{BD4D1D60-2355-4BB4-9889-905A4A1FC6FA}', '61', 'INHE-0776', '2019-01-11 17:08:29', '0000-00-00 00:00:00', '2019-01-14 10:32:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011102/PAW', '', 'Sichergrid INC', 'Sichergrid', '巴拿马', 'Jorge Enrique Cede?o A', '(507)394-2326', 'project@sichergrid.com', '巴拿马电力产品采购商和智能电网服务商，与中美洲大部分国家的电力公司有业务往来。', '', '', '', '', '', '', '', '', '', 'Sichergrid INC', 'Sichergrid', '巴拿马', 'Jorge Enrique Cede?o A', '(507)394-2326', 'project@sichergrid.com', '巴拿马电力产品采购商和智能电网服务商，与中美洲大部分国家的电力公司有业务往来。');
INSERT INTO `crs_tabledata1530` VALUES ('248', '{71B4D3B2-CE64-4380-A8A3-51269C54E5F3}', '61', 'INHE-0381', '2019-01-15 14:30:51', '0000-00-00 00:00:00', '2019-01-28 10:38:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011501/GNE', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('249', '{1A12C19E-1F1F-41B0-90BF-20B2EC88A2D1}', '60', 'INHE-0535', '2019-01-15 17:30:17', '0000-00-00 00:00:00', '2019-01-28 10:46:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011502/JBV', 'JBV', 'JP MINDA GROUP', 'JPM', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', 'JP MINDA GROUP集团，旗下多个子公司包括JNS Instruments，JPM工具，JPM汽车， JAY钢铁，JNJ电子等14个子公司。JPM的汽车业务过去5年是印度第一。旗下JNS Instruments主业是给汽车和摩托车生产速度表，与日本Nippon Seiki Co.,Ltd有合资工厂，当地市场占有率超过40%。电表这块属于JNS Instruments的业务范围。主要给韩国客户OEM，产品供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，电表生产具备SMT生产和注塑生产能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '', 'Jharkhand Bijli Vitran Nigam Limited', 'JBVNL', '印度', 'Mr. Sanjay Kumar, GM (IT)', '+91-651-2400826', 'piujbvnl@gmail.com', '印度Jharkhand邦的JBVNL电力公司', '', 'JP MINDA GROUP', 'JPM', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', 'JP MINDA GROUP集团，旗下多个子公司包括JNS Instruments，JPM工具，JPM汽车， JAY钢铁，JNJ电子等14个子公司。JPM的汽车业务过去5年是印度第一。旗下JNS Instruments主业是给汽车和摩托车生产速度表，与日本Nippon Seiki Co.,Ltd有合资工厂，当地市场占有率超过40%。电表这块属于JNS Instruments的业务范围。主要给韩国客户OEM，产品供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，电表生产具备SMT生产和注塑生产能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。');
INSERT INTO `crs_tabledata1530` VALUES ('250', '{15EDD254-7EF3-4B9A-BBE3-E8F49AF3DBCD}', '60', 'INHE-0535', '2019-01-15 19:29:14', '0000-00-00 00:00:00', '2019-01-28 10:54:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011503/UPD', 'UPD', '', '', '', '', '', '', '', '', 'Uttar Pradesh Power Corporation Limited', 'UPPCL', '印度', 'Superintending Engineer', '', 'serapdrpparta@gmail.com', '印度UP邦电力公司，Uttar Pradesh Power Corporation Limited（UPPCL）是根据1956/2013年公司法的规定注册的公司，是北方邦政府的全资实体。\r\n除了作为发电和输电实体的控股公司外，UPPCL还是UP邦五家区域电力公司的控股公司，即Paschimanchal Vidyut Vitaran Nigam Limited（PVVNL），Purvanchal Vidyut Vitaran Nigam Limited（PuVVNL），Madhyanchal Vidyut Vitaran Nigam Limited（MVVNL），Dakshinanchal Vidyut Vitaran Limited（DVVNL）和Kanpur电力供应公司（KESCO）。', '', 'Uttar Pradesh Power Corporation Limited', 'UPPCL', '印度', 'Superintending Engineer', '', 'serapdrpparta@gmail.com', '印度UP邦电力公司，Uttar Pradesh Power Corporation Limited（UPPCL）是根据1956/2013年公司法的规定注册的公司，是北方邦政府的全资实体。\r\n除了作为发电和输电实体的控股公司外，UPPCL还是UP邦五家区域电力公司的控股公司，即Paschimanchal Vidyut Vitaran Nigam Limited（PVVNL），Purvanchal Vidyut Vitaran Nigam Limited（PuVVNL），Madhyanchal Vidyut Vitaran Nigam Limited（MVVNL），Dakshinanchal Vidyut Vitaran Limited（DVVNL）和Kanpur电力供应公司（KESCO）。');
INSERT INTO `crs_tabledata1530` VALUES ('251', '{E9E0F210-9218-48FF-BFE1-DA30473D1CB1}', '66', 'INHE-0774', '2019-01-18 13:48:54', '0000-00-00 00:00:00', '2019-01-28 11:13:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019011801/HRV', '', 'Energy Code d.o.o', 'Energy Code d.o.o', '克罗地亚', 'Njavro Boris', '', 'njavro.boris@gmail.com', '1997年-1998年在Koncar（Electotechnical Institute) 做变压器研究；\r\n1998年-2004年在OKit d.o.o.任项目经理，开发电力机构信息系统；\r\n2007年-2014年在Koncar-KET d.d. 任副总监，负责商业燃气调度的IT Development 项目；\r\n2014年-2016年担任Koncar（Power plant and Electric Traction Engineering Inc）BU Process information system总监；\r\n2016年-至今在施耐德做Smartgrid销售经理，同时开了自己的公司Energy Code d.o.o.做能源领域的指导、咨询业务。', '', 'Hrvatska Elektroprivreda', 'HEP', '克罗地亚', 'Sector for Procurement', '385 1 63 22 111', 'strateski@hep.hr', 'HEP集团是一个克罗地亚国有电力公司，一个多世纪以来从事发电、输电和配电业务，过去几十年开始从事供热和天然气配送。\r\nHEP集团拥有多家子公司，以控股公司的形式组建。集团母公司HEP d.d.履行集团公司管理的职能，为客户提供安全可靠的电力供应条件。', '', 'Hrvatska Elektroprivreda', 'HEP', '克罗地亚', 'Sector for Procurement', '385 1 63 22 111', 'strateski@hep.hr', 'HEP集团是一个克罗地亚国有电力公司，一个多世纪以来从事发电、输电和配电业务，过去几十年开始从事供热和天然气配送。\r\nHEP集团拥有多家子公司，以控股公司的形式组建。集团母公司HEP d.d.履行集团公司管理的职能，为客户提供安全可靠的电力供应条件。');
INSERT INTO `crs_tabledata1530` VALUES ('252', '{7BDA7C46-F346-4102-AA3F-80190686A4BE}', '60', 'INHE-0790', '2019-01-22 08:53:00', '0000-00-00 00:00:00', '2019-01-28 11:05:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012201/MGM', '', 'Alyaqeen Engineering Co. LLC.', 'OM', '阿曼苏丹国', 'Abdelhamied Nashabat', 'Tel.: +96824591142 Ext 105 GSM: +96897414307', '', 'Al Yaqeen Engineering是阿曼Al Yaqeen Group旗下的一家公司，专门从事电力工程和水务工程建设的专业公司，业务范围覆盖整个阿曼。', '', '', '', '', '', '', '', '', '', 'Alyaqeen Engineering Co. LLC.', 'OM', '阿曼苏丹国', 'Abdelhamied Nashabat', 'Tel.: +96824591142 Ext 105 GSM: +96897414307', '', 'Al Yaqeen Engineering是阿曼Al Yaqeen Group旗下的一家公司，专门从事电力工程和水务工程建设的专业公司，业务范围覆盖整个阿曼。');
INSERT INTO `crs_tabledata1530` VALUES ('253', '{5BD3E78D-283D-47E7-AB0B-9865EC53541E}', '61', 'INHE-0500', '2019-01-22 14:15:56', '0000-00-00 00:00:00', '2019-01-28 11:35:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012202/LTM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Lekwa-Teemane Local Municipality(LTLM)', 'LTLM', '南非', 'MR O. SEBOLAI', '(053) 441 2207/8', '', '1.南非西北省地方性市政公司，2017年人口统计58 534，家庭户数统计16 496；预付费用户约28000个；2017年电费收入约68 987 805兰特，线损约10%,线损总计约6 763 114兰特。\r\n2.新市政客户，银河和NYC第一次投标，暂无客户关系，对是市政公司的需求和痛点，以及竞争对手的状况有待年后出差此市场拜访客户了解。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('254', '{69552377-5BE5-446A-A5E4-ACAE7D3D7240}', '61', 'INHE-0793', '2019-01-23 10:37:26', '0000-00-00 00:00:00', '2019-01-28 11:44:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012302/PUM\r\n', '瑞典市场Vattenfall电力公司投标项目', 'Trilliant Incorporated', 'TID', '美国', 'Par Schroder', '+460708901655', 'par.schroder@trilliant.com', '该客户是美国著名的通讯系统软件及解决方案提供商，在全球电表系统提供商中可以排名前三，其与加拿大的Hydro One Networks，英国的British Gas和美国的Iberdrola Central Maine Power等著名能源供应商都有合作。其融资超过2.12亿美元，预计今年收入1500万美元，公司规模300人以上（数据来源于网络搜索www.owler.com）。该公司和我司在马来西亚的项目有过合作，目前业务与该公司项目经理PAR取得联系，此人工作细致，能力较强。', '', 'Vattenfall Eldistribution AB', 'VEA', '瑞典', 'Attn. Jelica Djeke', '+46 70 39 61 970', 'jelica.djeke@vattenfall.com', 'Vattenfall Eldistribution AB 是瑞典国家全资电力公司Vattenfall AB下辖的子公司，是瑞典最大的电力公司之一，该公司在瑞典西部，中部和北部均有电网部署，部分电网也会通过其子公司VasterbergslagensElnatAB和GotlandsElnatAB来运营。其总供电客户户数约为85万户（瑞典低压用户总数520万户以上，高压用户6500户以上）。Vattenfall Eldistribution 资金来源于瑞典政府，员工规模750人以上，在瑞典四个地点设有办事处：Jokkmokk，Lulea，Solna和Trollhattan；该公司2018年投资约40亿瑞典克朗（合30.2亿人民币）进行电网系统，电表方面的全面升级。（以上数据来源于该公司官网和互联网搜索）', '', 'Trilliant Incorporated', 'TID', '美国', 'Par Schroder', '+460708901655', 'par.schroder@trilliant.com', '该客户是美国著名的通讯系统软件及解决方案提供商，在全球电表系统提供商中可以排名前三，其与加拿大的Hydro One Networks，英国的British Gas和美国的Iberdrola Central Maine Power等著名能源供应商都有合作。其融资超过2.12亿美元，预计今年收入1500万美元，公司规模300人以上（数据来源于网络搜索www.owler.com）。该公司和我司在马来西亚的项目有过合作，目前业务与该公司项目经理PAR取得联系，此人工作细致，能力较强。');
INSERT INTO `crs_tabledata1530` VALUES ('255', '{697732A7-9EC4-44CC-B523-9D5352690C85}', '61', 'INHE-0719', '2019-01-23 13:31:59', '0000-00-00 00:00:00', '2019-01-28 11:54:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012304/PLD', '三相直通表建议价格过低，请和客户重新沟通，建议调价110美元以上。具体价格，请申请公司审批。', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。', '', '', '', '', '', '', '', '', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('256', '{8BEBFE4C-3149-47DF-98D5-BCAC2DB91BBE}', '61', 'INHE-0500', '2019-01-25 11:09:49', '0000-00-00 00:00:00', '2019-01-26 17:42:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012501/MLM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Moqhaka Local Municipality', 'MLM', '南非', 'Willemina Motaumg(Miss)', 'Tel:+27 56 216 9316', 'motaungt@moqhaka.gov.za', '自由州省主要的地方性市政公司之一，2017年人口154 732，总家庭用户数53 601 ，其中低压普通居民预付费用户约3万个，	低压普通居民后付费用户约2万个，年均用户增加约5%；					\r\r\r\n2017年电费总计收入255 592 385兰特，2017年配电侧收入损失为 38 582 954兰特，配电线损约15.5%。当前主要电表供应商为Conlog和兰吉尔', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('257', '{22C49B0D-B5A2-44F7-8F8C-FEA457C04DF7}', '60', 'INHE-0781', '2019-01-26 17:01:47', '0000-00-00 00:00:00', '2019-02-26 16:56:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2019012602/PDC', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。');
INSERT INTO `crs_tabledata1530` VALUES ('258', '{F2553C90-5BDF-4CF4-B5CE-45A0F31EF0C2}', '66', 'INHE-0634', '2019-02-11 15:28:46', '0000-00-00 00:00:00', '2019-02-18 13:52:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021102/RMY', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '{F2553C905BDF4CF4B5CE45A0F31EF0C211015FBC745F4B1982FBEF12F4BBACD1}_SIPROMAD Company Profile.pdf', '', '', '', '', '', '', '', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('259', '{441B1591-8F51-4072-9F2B-BFF47A72C40C}', '61', 'INHE-0772', '2019-02-13 00:28:12', '0000-00-00 00:00:00', '2019-02-18 13:44:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021302/GBB', '', 'SanaJaiteh CO LTD', 'SANA', '冈比亚', 'SANA', '+220 7500005', 'sanajaiteh4@gmail.com', '扶轮社冈比亚主席，菲律宾驻冈比亚使领馆领事，政治掮客；目前所知该代理有两次中国到访记录，第一次2017年随政府代表团到广州，以及本次中非论坛随代表团来北京。运作特变的输变电项目。与能源部，财政部和总统有较好关系。曾定居英国，为人健谈友善，做事谨慎', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室');
INSERT INTO `crs_tabledata1530` VALUES ('260', '{277C61EA-580E-4098-AC19-19625CB63B51}', '61', 'INHE-0431', '2019-02-14 17:58:15', '0000-00-00 00:00:00', '2019-02-18 14:45:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021404/SBM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'SALDANHA BAY MUNICIPALITY', 'SBM', '南非', 'Cassie du Preez', 'Tel: 022 701 7123Fax: 086 216 4457', '', '南非市政之一，管理19000用户，现在计划招标为期三年的售电系统。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('261', '{9E7E63E3-5EBE-4B50-9872-F73487B27617}', '61', 'INHE-0500', '2019-02-15 11:12:37', '0000-00-00 00:00:00', '2019-02-18 11:50:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021501/CDL', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'CENTLEC (SOC) Ltd', 'CENTLEC', '南非', 'Mr. AN MgoqiChief Executive OfficerMr. Kenneth Mohlakane', 'Tel: +27 51 - 412 2753', 'Kenneth.Mohlakane@centlec.co.za', '1.位于南非自由州省，是自由州省唯一的大都市市政公司Mangaung Metropolitan Municipality 直接下属负责输配电公司，南非8大大都市市政公司之一，2016年总人口统计为约80万，家庭户数约27万户，电力用户约20万，为银河在南非市政的重要目标客户之一；\r\r\r\n2.2017年年度电费收入为22亿兰特，其中预付费电费收入为7亿兰特，中大型商业工业后付费电费收入为15亿兰特，年度线损10.77%，总计线损金额为1.7亿兰特。技术线损金额为1.1亿兰特，非技术线损金额为6千万兰特；\r\r\r\n3.当前市政公司的集抄系统供应商为AURECON Group和Jagertech（PTY）LTD，2016年授标，为三年期合同；售电系统服务提供商：海兴，2016年授标，为三年期合同。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('262', '{7C54989C-DADD-475C-AFF4-7A2850151275}', '60', 'INHE-0535', '2019-02-18 00:49:59', '0000-00-00 00:00:00', '2019-02-26 09:28:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021802/JPY', 'JPY', 'JAY AUTOCOMPONENTS LIMITED', 'JAC', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '', 'Energy Efficiency Services Limited', 'EESL', '印度', 'Ajay Kumar Sharma', '0120-4908000', 'asharma1@eesl.co.in', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：\r\n1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；\r\n2.	执行中央或邦政府或其代理机构的计划，项目和政策；\r\n3.	与私有ESCOs和其他公司合作促进能源效率；\r\n4.	在能源效率，CDM项目和其他有关领域提供咨询服务；\r\n5.	传授培训，培养股东能力。', '', 'JAY AUTOCOMPONENTS LIMITED', 'JAC', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。');
INSERT INTO `crs_tabledata1530` VALUES ('263', '{010B7779-60C3-401C-AB8B-4CA828A02290}', '66', 'JXINHE-2559', '2019-02-18 15:19:20', '0000-00-00 00:00:00', '2019-02-20 10:40:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019021805/PVT', '', '成都长城开发科技有限公司', '长城开发', '中国', '王红', '8618140091200', 'hongwang@kaifa.cn', '成都长城开发科技有限公司（以下简称“深科技成都公司”），是深圳长城开发科技股份有限公司（以下简称 “深科技”，证券代码：000021）的下属控股子公司，前身为深科技的计量系统事业部（1995年-2016年），是集研发、生产、销售、服务为一体的智能计量产品及能源管理解决方案提供商', '', 'Islamabad Energy Supply Company', 'IESCO', '巴基斯坦', '', '0092519252978', 'iescoami@iesco.com.pk', '巴基斯坦首都伊斯兰堡电力公司，管理270万用户，共计5个区，19个部门。', '', '成都长城开发科技有限公司', '长城开发', '中国', '王红', '8618140091200', 'hongwang@kaifa.cn', '成都长城开发科技有限公司（以下简称“深科技成都公司”），是深圳长城开发科技股份有限公司（以下简称 “深科技”，证券代码：000021）的下属控股子公司，前身为深科技的计量系统事业部（1995年-2016年），是集研发、生产、销售、服务为一体的智能计量产品及能源管理解决方案提供商');
INSERT INTO `crs_tabledata1530` VALUES ('264', '{9ADFE8A7-CE0E-4CDA-9CBC-48B88FCA8F3A}', '61', 'INHE-0725', '2019-02-20 10:13:16', '0000-00-00 00:00:00', '2019-02-25 14:06:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2019022001/ACO', '', 'ACOB Lighting Technology Limited', 'ACO', '尼日利亚', 'Alexander C. Obiechina', '+2348032902825', 'o.alexander@acoblighting.com', 'ACOB Lighting Technology Limited主要在尼日利亚和非洲地区推广可持续LED产品（LED灯）、可再生能源和通用电气化项目。目前正在借由微型电网项目推动其在尼日利亚地区的业务发展。同时ACOB是AMDA:Africa Mini-grid Developers Association (由11家盈利性主营微型电网项目的公司组成的协会组织）的一员，ACOB的President Mr Alexander同时是AMDA的两名执行秘书之一。', '', '', '', '', '', '', '', '', '', 'ACOB Lighting Technology Limited', 'ACO', '尼日利亚', 'Alexander C. Obiechina', '+2348032902825', 'o.alexander@acoblighting.com', 'ACOB Lighting Technology Limited主要在尼日利亚和非洲地区推广可持续LED产品（LED灯）、可再生能源和通用电气化项目。目前正在借由微型电网项目推动其在尼日利亚地区的业务发展。同时ACOB是AMDA:Africa Mini-grid Developers Association (由11家盈利性主营微型电网项目的公司组成的协会组织）的一员，ACOB的President Mr Alexander同时是AMDA的两名执行秘书之一。');
INSERT INTO `crs_tabledata1530` VALUES ('265', '{6A774889-5026-445B-9AC0-829E0E5AC563}', '61', 'INHE-0431', '2019-02-25 09:42:13', '0000-00-00 00:00:00', '2019-02-26 10:45:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019022502/NWA', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '', 'Rural Electrification Agency', 'REA', '乌干达', 'Turyagyenda John Abouf', '+256 712807984', 'jturyagyenda@rea.or.ug', '乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验');
INSERT INTO `crs_tabledata1530` VALUES ('266', '{49203A60-E206-4517-9ACC-E9FC24890457}', '61', 'INHE-0772', '2019-03-03 23:32:29', '0000-00-00 00:00:00', '2019-03-06 11:27:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2019030301/GBC', '', 'SanaJaiteh CO LTD', 'SANA', '冈比亚', 'SANA', '+220 7500005', 'sanajaiteh4@gmail.com', '扶轮社冈比亚主席，菲律宾驻冈比亚使领馆领事，政治掮客；目前所知该代理有两次中国到访记录，第一次2017年随政府代表团到广州，以及本次中非论坛随代表团来北京。运作特变的输变电项目。与能源部，财政部和总统有较好关系。曾定居英国，为人健谈友善，做事谨慎', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室', '', '冈比亚国家水电公司', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室');
INSERT INTO `crs_tabledata1530` VALUES ('267', '{5A8EA61E-04C0-4479-A60B-D76D998499BA}', '66', 'JXINHE-2559', '2019-03-11 14:40:52', '0000-00-00 00:00:00', '2019-03-12 18:04:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031101/EDP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'ELECTRICIDADE DE MOCAMBIQUE', 'EDM', '莫桑比克', 'Nelson Chiziane', '', 'Nelson.Chiziane@edm.co.mz', '莫桑比克国家电力公司，国营上市企业，管理全国境内的发电，输电和配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('268', '{ABEF276E-08E1-4201-8B8F-D016851C9C16}', '66', 'INHE-0774', '2019-03-14 10:19:17', '0000-00-00 00:00:00', '2019-03-21 11:37:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031403/LIT', '', '', '', '', '', '', '', '', '', 'UAB Verslo aptarnavimo centras', 'VAC', '立陶宛', 'Alina Kolosova', '370 61861689', 'alina.kolosova@le.lt', '立陶宛电力公司ESO授权VAC执行此项目合同前的所有采购程序，Verslo Aptarnavimo Centras UAB（VAC）隶属于国家控制的国家能源集团Lietuvos Energija（以下简称集团）。该公司成立于2014年，旨在改善支持本集团核心业务的流程并降低成本。\r\r\r\r\r\n\r\r\r\r\r\nVAC的活动旨在通过提供公共采购，会计和劳务关系管理服务来支持和服务集团公司。通过将服务功能集中在一家公司，VAC团队由上述集团公司授权的所有领域的专家组成。\r\r\r\r\r\n\r\r\r\r\r\n通过集中公共采购，会计和劳动关系管理流程，VAC正在努力使其标准化，提高透明度和效率，并确保其完成。该支持服务集中模型符合世界上应用的最佳实践。\r\r\r\r\r\n\r\r\r\r\r\n提供专业服务的公司的成立标志着实施集团公司治理模式的重要一步。它为实现2014年至2020年Lietuvos Energija的战略目标提供了大量可能性，即集团公司活动的多样化，提高运营效率，形成新的组织文化。', '', 'UAB Verslo aptarnavimo centras', 'VAC', '立陶宛', 'Alina Kolosova', '370 61861689', 'alina.kolosova@le.lt', '立陶宛电力公司ESO授权VAC执行此项目合同前的所有采购程序，Verslo Aptarnavimo Centras UAB（VAC）隶属于国家控制的国家能源集团Lietuvos Energija（以下简称集团）。该公司成立于2014年，旨在改善支持本集团核心业务的流程并降低成本。\r\r\r\r\r\r\n\r\r\r\r\r\r\nVAC的活动旨在通过提供公共采购，会计和劳务关系管理服务来支持和服务集团公司。通过将服务功能集中在一家公司，VAC团队由上述集团公司授权的所有领域的专家组成。\r\r\r\r\r\r\n\r\r\r\r\r\r\n通过集中公共采购，会计和劳动关系管理流程，VAC正在努力使其标准化，提高透明度和效率，并确保其完成。该支持服务集中模型符合世界上应用的最佳实践。\r\r\r\r\r\r\n\r\r\r\r\r\r\n提供专业服务的公司的成立标志着实施集团公司治理模式的重要一步。它为实现2014年至2020年Lietuvos Energija的战略目标提供了大量可能性，即集团公司活动的多样化，提高运营效率，形成新的组织文化。');
INSERT INTO `crs_tabledata1530` VALUES ('269', '{2B85FA60-DEE3-4BB1-8865-828CA550A808}', '60', 'INHE-0781', '2019-03-14 10:24:33', '0000-00-00 00:00:00', '2019-03-18 16:01:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031404/NCO', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Northern Electricity Supply Company Limited', 'NESCO', '孟加拉国', 'Md.Zakir.Hossain', '+88 01709 996748', 'pd.smp@nesco.gov.bd', '近两年新成立电力公司，由BPDB分离出去，负责孟加拉西北地区供电，用户数约110万。', '', 'Northern Electricity Supply Company Limited', 'NESCO', '孟加拉国', 'Md.Zakir.Hossain', '+88 01709 996748', 'pd.smp@nesco.gov.bd', '近两年新成立电力公司，由BPDB分离出去，负责孟加拉西北地区供电，用户数约110万。');
INSERT INTO `crs_tabledata1530` VALUES ('270', '{71E2D5AF-B46E-460D-91F6-33A99217F4B7}', '61', 'INHE-0642', '2019-03-15 16:17:20', '0000-00-00 00:00:00', '2019-03-18 15:26:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019031501/M16', '项目代号为M16。', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', '马拉维', 'Emmilius KandapoSenior Procurement Officer （2015）', '(265) 01 822 000/02 12 957 370', '', '电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('271', '{B4B3C0E6-F891-45A3-8F1E-9F1055CD05BA}', '61', 'INHE-0695', '2019-03-20 14:30:20', '0000-00-00 00:00:00', '2019-03-25 15:52:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032001/NBT', '', '', '', '', '', '', '', '', '', 'Energijos Skirstymo Operatorius AB', 'ESO', '立陶宛', '', '+370 5 277 75 24', 'info@eso.lt', 'Energijos Skirstymo Operatorius AB成立于2016年1月1日，合并LESTO AB和一家股份公司Lietuvos dujos。ESO由国有能源公司【Lietuvos Energija】控制，该公司是波罗的海国家最大的能源公司之一。\r\r\n\r\r\nESO的主要活动：电力供应和分配，天然气分配，??电力和天然气供应保障，电力和天然气的引入，电力和燃气配电网络的维护和发展，能源分配保证的安全性和可靠性。\r\r\n\r\r\nESO为立陶宛的160万客户提供服务。公司服务面积平方公里达到65.3万。平方公里。', '', 'Verslo Aptarnavimo Centras', 'VAC', '立陶宛', 'Alina Kolosova', '+370 618 61689', 'Alina.Kolosova@le.lt', 'ESO母公司Lietuvos Energija (Lithuania Energy-立陶宛能源)旗下的子公司之一，专门负责为立陶宛能源集团提供公共采购，财会，人力行政管理服务。');
INSERT INTO `crs_tabledata1530` VALUES ('272', '{ABADE294-A61E-458B-AD1A-CE9BBB8E75C4}', '61', 'INHE-0381', '2019-03-25 18:30:28', '0000-00-00 00:00:00', '2019-03-26 15:44:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032501/CDN-EPT', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('273', '{F1BD2C69-6E4E-4F25-96C3-9A92B5125D6C}', '66', 'INHE-0579', '2019-03-26 10:01:54', '0000-00-00 00:00:00', '2019-03-27 16:34:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032601/TGP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'The Green Pact SAL', 'TGP', '黎巴嫩', 'Bernard Ammoun', '+96170850525', 'ceo@thegreenalliance.co.uk', '1. The Green Pact 致力于可再生资源，清洁能源的项目，在黎巴嫩进行光伏产品的项目。\r\n2. 该公司实施EPC项目，包括光伏设备的建立，发电机设备的建立，并网工作等。\r\n3.该客户为集团公司，包括Green Future, The Green Pact, Green Arms, Rational Financial以及RNA energy。');
INSERT INTO `crs_tabledata1530` VALUES ('274', '{E6C3431A-0F41-470F-81D5-0AA0D8FEBCFD}', '61', 'INHE-0713', '2019-03-28 15:17:46', '0000-00-00 00:00:00', '2019-03-29 13:27:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032803/GNF', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('275', '{F8D0851B-B78C-48A9-BC8A-C6A3ED881D77}', '0', 'INHE-0770', '2019-03-28 16:05:14', '0000-00-00 00:00:00', '2019-04-24 13:29:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032804/EPU', '', 'ZOBIL GLOBAL BUSINESS', 'ZGB', '埃塞俄比亚', 'Eskinder Asddisu', '+251911406140', 'zobilglobal@gmail.com', '该公司于2003年成立，位于埃塞俄比亚，主要和政府部门(EEPCO，后分成两部分EEPO和EEU)合作，有成功向电力公司销售过输电变压器，开关设备，保险丝的案例。注册资本11万人民币左右。', '', 'Ethiopian Electric Power', 'EEP', '埃塞俄比亚', 'Aden Kidane', '+251 912487772', 'am276335@gmail.com', '埃塞俄比亚电力公司(主管发电和输电)', '', 'Ethiopian Electric Power', 'EEP', '埃塞俄比亚', 'Aden Kidane', '+251 912487772', 'am276335@gmail.com', '埃塞俄比亚电力公司(主管发电和输电)');
INSERT INTO `crs_tabledata1530` VALUES ('276', '{06DE08E8-567C-445D-B03A-971172EA104B}', '61', 'INHE-0440', '2019-03-28 19:09:05', '0000-00-00 00:00:00', '2019-04-02 18:24:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032901/TTE', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约180万，每年采购约25万-30万台电表（包含单相智能预付费表，三相AMR预/后付费电表），以及部分的11KV和33KV组合计量设备。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约180万，每年采购约25万-30万台电表（包含单相智能预付费表，三相AMR预/后付费电表），以及部分的11KV和33KV组合计量设备。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('277', '{C733D9EB-E021-47E8-BE33-0C6509E2B0B1}', '66', 'INHE-0628', '2019-03-29 10:56:34', '0000-00-00 00:00:00', '2019-04-01 17:58:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032903/PRU（旧）', '', 'Proyectos y Calculos S.A.C.', 'Procal', '秘鲁', 'Pedro', '(511) 422 4967', 'ptejada@procal.pe', '', '', 'Tecsur', 'Tecsur', '秘鲁', 'Sr. Victor Quispe Huarcaya', '', 'vquispe@tecsur.com.pe', '秘鲁国家电力局LDS的电力采购和电力项目实施公司，由LDS决定技术需求，Tecsur按照要求采购和施工。', '', 'Tecsur', 'Tecsur', '秘鲁', 'Sr. Victor Quispe Huarcaya', '', 'vquispe@tecsur.com.pe', '秘鲁国家电力局LDS的电力采购和电力项目实施公司，由LDS决定技术需求，Tecsur按照要求采购和施工。');
INSERT INTO `crs_tabledata1530` VALUES ('278', '{8F7254E9-C8CB-4003-85EB-E374B3FE95D6}', '60', 'INHE-0434', '2019-03-29 16:06:24', '0000-00-00 00:00:00', '2019-04-01 18:18:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2019032905/NFA', '', 'HIMVEST HOLDING', 'HM', '摩洛哥', 'Hamza Harbaz', '00212 670980890', 'hamzaharbaz@himvestholding.com', '1. 客户当前主要从事投资，有自己的矿业，同时也做汽车修理，房地产\r\n2. 客户在卡萨布兰卡有自己的一栋楼，在Grand Mogador酒店附近。楼高7层，1~6层出租，客户办公室在第7层。\r\n3. 客户帮引荐了ONEE负责特高压/高压的技术负责人Abdulhaldi先生，于发标前提供了项目标书。\r\n4. 客户在不同的工业园分别有一块2000平方米和2200平方米的地，有意投资建厂。\r\n5. 据了解，客户的前妻是国王的妹妹。客户有跟北方国际，中国中车合作项目。', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212 5 22 30 15 67', 'm.mustapha@ges.ma,globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212 5 22 30 15 67', 'm.mustapha@ges.ma,globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('279', '{CD589D67-2F2D-4ACA-807E-E6B8864BB462}', '61', 'INHE-0432', '2019-04-02 14:38:13', '0000-00-00 00:00:00', '2019-04-03 16:53:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040201/ITR', '', 'Intrasoft International SA', 'Intrasoft', '希腊', 'Dimitris Mitsainas', '306955281610', 'dmitsainas@gmail.com', '欧洲领先的IT方案和服务供应商，在世界多个国家有自己的分公司，2016年汤伟和郭总监有去拜访，讨论希腊市场合作事宜。对希腊电力公司及电力市场情况很熟悉，也是电表及集抄项目的主要玩家之一。目前其主要的合作伙伴，有SAGEMCOM和EDMI。但其负责人认为SAGEMCOM和EDMI的价格太高，在找合适的替代者。Intrasfot和其兄弟公司Intracom出自同一家集团公司，也是目前市场上的主要竞争对手。而电力公司对于大型集抄项目，也是更倾向于同这两家公司合作。', '', 'HELLENIC ELECTRICITY DISTRIBUTION NETWORK OPERATOR S.A.', '', '希腊', 'Materials, Purchasing and Transportation Department', '210 909 0529', '', '希腊配电网络运营公司HEDNO是希腊公共电力公司（希腊最大的电力公司，为政府所有）的分公司，负责希腊配电网络的运营、维护及发展。', '', 'Intrasoft International SA', 'Intrasoft', '希腊', 'Dimitris Mitsainas', '306955281610', 'dmitsainas@gmail.com', '欧洲领先的IT方案和服务供应商，在世界多个国家有自己的分公司，2016年汤伟和郭总监有去拜访，讨论希腊市场合作事宜。对希腊电力公司及电力市场情况很熟悉，也是电表及集抄项目的主要玩家之一。目前其主要的合作伙伴，有SAGEMCOM和EDMI。但其负责人认为SAGEMCOM和EDMI的价格太高，在找合适的替代者。Intrasfot和其兄弟公司Intracom出自同一家集团公司，也是目前市场上的主要竞争对手。而电力公司对于大型集抄项目，也是更倾向于同这两家公司合作。');
INSERT INTO `crs_tabledata1530` VALUES ('280', '{99F0F0F1-40C6-4DB0-BF87-0EECD5897ACC}', '61', 'INHE-0840', '2019-04-03 16:35:59', '0000-00-00 00:00:00', '2019-04-09 17:45:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040301/MKE', '', 'Enterprise Data Services Ltd', 'EDS', '毛里求斯', 'Kavish Ramsewak', '(230) 465-1700', 'kavish.ramsewak@eds.mu', '1999年成立，为企业和政府部门提供电力电信设备及解决方案，公司员工45人', '', 'The Central Electricity Board (CEB)', 'CEB', '毛里求斯', 'N/A', '(230) 454-7630/32', 'Electronic mail address: ctc@ceb.intnet.mu', '1、毛里求斯国家电力公司，负责配售电业务；毛里求斯国家总人口：2013年数据约130万，总电力用户（居民、普通商用、LPU用户）：45万（13年数据）；当前电表供应商：EDMI，Elster，Iskraemeco，Landis*Gyr，Actaris（Itron） ；AMR软件供应商：EDMI Multidrive，Hexing AMI software。                                                                                                  2、此次招标2万台单相模块智能表，表箱，AMI集抄系统以及相关配置的服务器和配件。', '', 'Enterprise Data Services Ltd', 'EDS', '毛里求斯', 'Kavish Ramsewak', '(230) 465-1700', 'kavish.ramsewak@eds.mu', '1999年成立，为企业和政府部门提供电力电信设备及解决方案，公司员工45人');
INSERT INTO `crs_tabledata1530` VALUES ('281', '{D6651723-CE6D-407F-86F3-85B500C90552}', '66', 'INHE-0774', '2019-04-04 08:37:37', '0000-00-00 00:00:00', '2019-04-09 17:44:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040403/SDE', '', 'AEM S.A.', 'AEM', '罗马尼亚', 'Monica Maria BUCUR', '40728228995', 'monica.bucur@aem.ro', 'AEM成立45年以来主要生产和销售电能表和气表，也生产部分配电设备。想从我们直接采购配件和特定项目中的电表。', '{D6651723CE6D407F86F385B500C9055211015FBC745F4B1982FBEF12F4BBACD1}_Aem leaflet.pdf', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.', 'SDEE Distributie Muntenia Nord SA', '罗马尼亚', 'MARIANA CORNEANU', '40 244405350', 'Mariana.Corneanu@distributie-energie.ro', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.（SDEE Muntenia Nord）是Electrica集团的一部分，是为Muntenia北部提供服务的配电运营商。 该公司在Vrancea，Galati，Buzau，Braila，Prahova和Dambovita县开展业务，覆盖面积约29.000平方公里。\r\n凭借120年的传统，SDEE Muntenia Nord通过一个长度超过73,000公里的分销网络和超过2.260名员工，为约130万消费者提供服务。', '', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.', 'SDEE Distributie Muntenia Nord SA', '罗马尼亚', 'MARIANA CORNEANU', '40 244405350', 'Mariana.Corneanu@distributie-energie.ro', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.（SDEE Muntenia Nord）是Electrica集团的一部分，是为Muntenia北部提供服务的配电运营商。 该公司在Vrancea，Galati，Buzau，Braila，Prahova和Dambovita县开展业务，覆盖面积约29.000平方公里。\r\n凭借120年的传统，SDEE Muntenia Nord通过一个长度超过73,000公里的分销网络和超过2.260名员工，为约130万消费者提供服务。');
INSERT INTO `crs_tabledata1530` VALUES ('282', '{5EA01D65-8117-4B16-B21D-2D6EAF716B66}', '66', 'INHE-0634', '2019-04-04 14:59:47', '0000-00-00 00:00:00', '2019-04-09 17:32:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040404/HOM', '', 'iCTS (Myanmar) Company Limited', 'ICTS', '缅甸', 'Dr.Aye Chan Myae Kyaw', '', 'ayechanmyaekyaw@ictsmyanmar.com', '2012年成立，主要做政府项目：11KV,400V输配电线EPC项目，销售电缆ACSR,OPGW,SAC，离网太阳能项目，等。', '', 'Mandalay City Development Committee', 'MCDC', '缅甸', '', '', '', 'MCDC曼德勒市发展委员会是缅甸第二大城市曼德勒的行政机构。 MCDC负有广泛的责任，包括城市规划，土地管理，税收和城市发展。 MCDC通过税收，费用，许可证和房地产开发来增加自己的收入。 MCDC的主席担任曼德勒市市长，并担任曼德勒地区政府的市政部长。 MCDC目前由市长Ye Lwin担任主席。', '', 'iCTS (Myanmar) Company Limited', 'ICTS', '缅甸', 'Dr.Aye Chan Myae Kyaw', '', 'ayechanmyaekyaw@ictsmyanmar.com', '2012年成立，主要做政府项目：11KV,400V输配电线EPC项目，销售电缆ACSR,OPGW,SAC，离网太阳能项目，等。');
INSERT INTO `crs_tabledata1530` VALUES ('283', '{E0FF0AC6-E96D-4C81-89B9-41E2A495DAB9}', '61', 'INHE-0776', '2019-04-04 10:37:25', '0000-00-00 00:00:00', '2019-04-09 17:33:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040405/PRU', '', 'INTELMETER S.A.C\r\n', 'INTELMETER', '秘鲁', 'Eli Zaidan Sweiss', 'Telf: +51 203-2400', 'ezaidan@intelmeter.com.pe', 'INTELMETER是一家从事能源行业的秘鲁公司，是重要亚洲公司的本地代理，已与欧洲，北美和国内供应商建立了合作关系。致力于高，中，低压电气系统，测量，医疗卫生，机械和液压，可再生能源的高质量产品创新，项目开发（EPC）以及工程实施和咨询，特别着重于电气，电子和节能基础设施项目开发，实施完整的解决方案，并将继续跟随保证前期，中期和后期的商业运营。', '', 'Tecsur S.A', 'Tecsur', '秘鲁', 'Victor Quispe', '700-2589', 'vquispe@tecsur.com.pe', '秘鲁国家电力局LDS的电力采购和电力项目实施公司，由LDS决定技术需求，Tecs\r\nur按照要求采购和施工。', '', 'INTELMETER S.A.C\r\n', 'INTELMETER', '秘鲁', 'Eli Zaidan Sweiss', 'Telf: +51 203-2400', 'ezaidan@intelmeter.com.pe', 'INTELMETER是一家从事能源行业的秘鲁公司，是重要亚洲公司的本地代理，已与欧洲，北美和国内供应商建立了合作关系。致力于高，中，低压电气系统，测量，医疗卫生，机械和液压，可再生能源的高质量产品创新，项目开发（EPC）以及工程实施和咨询，特别着重于电气，电子和节能基础设施项目开发，实施完整的解决方案，并将继续跟随保证前期，中期和后期的商业运营。');
INSERT INTO `crs_tabledata1530` VALUES ('284', '{9BC2E975-6529-41E7-A13D-3963FC9519C3}', '61', 'INHE-0431', '2019-04-08 10:28:45', '0000-00-00 00:00:00', '2019-04-09 01:29:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040801/CYB', '请提供准确的技术规格以及标书（商务条件）和电力公司项目背景调查，规避对方就是替竞争对手做调查，花点钱买样机。', 'cyberteq', 'CYB', '波兰', 'Micha? Suchocki（VP）', 'Mobile: +971 50 108 4843, +48 690 882 900', 'Michal.Suchocki@cyberteq.com', '该客户是做ICT设备的，在波兰和阿联酋以及新加坡和卢旺达有分公司', '', '', '', '', '', '', '', '', '', 'cyberteq', 'CYB', '波兰', 'Micha? Suchocki（VP）', 'Mobile: +971 50 108 4843, +48 690 882 900', 'Michal.Suchocki@cyberteq.com', '该客户是做ICT设备的，在波兰和阿联酋以及新加坡和卢旺达有分公司');
INSERT INTO `crs_tabledata1530` VALUES ('285', '{F98DCF10-E098-4619-B016-FEB3E3592A90}', '61', 'INHE-0381', '2019-04-09 17:42:18', '0000-00-00 00:00:00', '2019-04-11 14:23:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019040901/PLF', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', '', '', '', '', '', '', '', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CIE', '科特迪瓦', 'Mathias KOUASSI', '+22521233602', 'mkouassi@cie.ci', '科特迪瓦电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('286', '{8A872327-6F58-4383-9A02-8B144C501596}', '66', 'JXINHE-2559', '2019-04-16 17:46:41', '0000-00-00 00:00:00', '2019-04-18 10:00:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041602/MSL', '', '', '', '', '', '', '', '', '', 'ELECTRICIDADE DE MOCAMBIQUE', 'EDM', '莫桑比克', 'Joao Catine', '+25821353632', 'Joao.catine@edm.com.mz', '莫桑比克国家电力公司，国营上市企业，管理全国境内的发电，输电和配电业务。', '', 'ELECTRICIDADE DE MOCAMBIQUE', 'EDM', '莫桑比克', 'Joao Catine', '+25821353632', 'Joao.catine@edm.com.mz', '莫桑比克国家电力公司，国营上市企业，管理全国境内的发电，输电和配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('287', '{93AC2402-0E3B-4B9D-BFA3-4A19434E02FB}', '171', 'INHE-0772', '2019-04-16 23:03:35', '0000-00-00 00:00:00', '2020-09-30 11:47:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041701/GBD', '', 'SanaJaiteh CO LTD', 'SANA', '冈比亚', 'SANA', '+220 7500005', 'sanajaiteh4@gmail.com', '扶轮社冈比亚主席，菲律宾驻冈比亚使领馆领事，政治掮客；目前所知该代理有两次中国到访记录，第一次2017年随政府代表团到广州，以及本次中非论坛随代表团来北京。运作特变的输变电项目。与能源部，财政部和总统有较好关系。曾定居英国，为人健谈友善，做事谨慎', '', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD', 'NAWEC', '冈比亚', 'NANI JUWARA', '+220 4375957', 'njuwara72@gmail.com', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室', '', '特变电工国际工程有限公司', 'TBEA', '中国', '任航', '18322102388', '', '世界500强， 国际总承包商全球排名 80 位');
INSERT INTO `crs_tabledata1530` VALUES ('288', '{37947387-D1CD-4B90-BB38-881BBD34E17A}', '61', 'INHE-0819', '2019-04-17 06:56:33', '0000-00-00 00:00:00', '2019-04-18 09:48:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041702/DMC', '项目背景：马达加斯加电力公司需要采购STS系统，前期电力公司总经理来访银河有过沟通，之后方案跟系统总监确认，现在准备签合同。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '马达加斯加电力公司', 'jirama', '马达加斯加', 'xavier RAKOTOZAFY', '+261348305230', 'xavier.rakotozafy@jirama-mg.com', 'JIRAMA成立于1975年10月17日，部位于首都塔那那利佛，直到1999年，他都是该国唯一的国有电力公司。1999年之后，JIRAMA继续垄断配电网络。2018年6月，JIRAMA正在考虑修复其配电网络。');
INSERT INTO `crs_tabledata1530` VALUES ('289', '{5C4BBA65-9438-455F-BCEF-CE5946BA2786}', '61', 'INHE-0805', '2019-04-18 10:36:05', '0000-00-00 00:00:00', '2019-04-30 17:24:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041801/ECI', '项目代号为ECI。已安装要求附上代理对产品规格要求，请求立项通过！', 'Blindobarras By Cedal Cia Ltda .', 'Blindobarras', '厄瓜多尔', 'Cesar Jimenez', '+593999913215', 'cjimenez@blindobarras.com', '厄瓜多尔市场新开发代理商。国企股东背景，资金实力比较雄厚。主要负责人Cesar曾经主持过银河产品在哥伦比亚的认证工作，对我司产品熟识度高。合作意愿强烈，预计可助我司尽快打开厄瓜多尔市场。', '', 'Blindobarras By Cedal Cia Ltda .', 'Blindobarras', '厄瓜多尔', 'Cesar Jimenez', '+593999913215', 'cjimenez@blindobarras.com', '厄瓜多尔市场新开发代理商。国企股东背景，资金实力比较雄厚。主要负责人Cesar曾经主持过银河产品在哥伦比亚的认证工作，对我司产品熟识度高。合作意愿强烈，预计可助我司尽快打开厄瓜多尔市场。', '', 'Blindobarras By Cedal Cia Ltda .', 'Blindobarras', '厄瓜多尔', 'Cesar Jimenez', '+593999913215', 'cjimenez@blindobarras.com', '厄瓜多尔市场新开发代理商。国企股东背景，资金实力比较雄厚。主要负责人Cesar曾经主持过银河产品在哥伦比亚的认证工作，对我司产品熟识度高。合作意愿强烈，预计可助我司尽快打开厄瓜多尔市场。');
INSERT INTO `crs_tabledata1530` VALUES ('290', '{5D3ACD24-1964-463A-9A6B-ACEFABA7D2EB}', '61', 'INHE-0500', '2019-04-18 13:25:03', '0000-00-00 00:00:00', '2019-04-22 18:08:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019041802/LEC', '', 'SAP Technologies PTY LTD', 'SAP', '莱索托', 'Papiso Rakhoboso', '+266 58408084', 'prakhoboso@gmail.com', '1.成立于2017年，主营业务为电器和电子类设备经销商；\r\n2.公司的老板Papiso Rakhoboso为莱索托电力公司LEC董事会主席的妻弟，通过内部关系取得了部分电力公司的项目；\r\n3.LES招标发布前其找到银河告知近期会有智能电表和系统的招标，询问合作机会。', '', 'LESOTHO ELECTRICITY COMPANY (PTY) LTD', 'LEC', '莱索托', 'Leketekete Ketso (Dr.)', '22312236', 'monokoa@lec.co.ls；tsiu@lec.co.ls', '1.莱索托国家电力公司，国有企业性质，负责全国独家输售配电业，用户总数约21万，其中22万约普通居民用表，约1万个LPU用户，全国通电率约47%；\r\r\n\r\r\n2.当前电表供应商主要为兰吉尔和Conlog，以及部分Itron电表，供应商主要来自南非本地；\r\r\n3.当前售电系统供应商为兰吉尔；\r\r\n4.此市场潜在的竞争对手为：兰吉尔，Conlog，Ontect(Itron),EDMI和海兴。', '', 'SAP Technologies PTY LTD', 'SAP', '莱索托', 'Papiso Rakhoboso', '+266 58408084', 'prakhoboso@gmail.com', '1.成立于2017年，主营业务为电器和电子类设备经销商；\r\n2.公司的老板Papiso Rakhoboso为莱索托电力公司LEC董事会主席的妻弟，通过内部关系取得了部分电力公司的项目；\r\n3.LES招标发布前其找到银河告知近期会有智能电表和系统的招标，询问合作机会。');
