INSERT INTO `crs_tabledata1530` VALUES ('294', '{CF781477-C4C0-4B1A-88F8-DF762AB0B7D1}', '61', 'INHE-0431', '2019-04-26 21:03:31', '0000-00-00 00:00:00', '2019-04-29 15:16:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019042602/TEB', '', '', '', '', '', '', '', '', '', 'TBEA Uganda', 'TBEA', '乌干达', '谢德金', '+256784052089', 'tbea_xiedj@126.com', '特变电工股份有限公司 （乌干达项目部） 特变在乌干达农网取得一个2亿美金的配网EPC工程，里面包含15万只电表', '', 'TBEA Uganda', 'TBEA', '乌干达', '谢德金', '+256784052089', 'tbea_xiedj@126.com', '特变电工股份有限公司 （乌干达项目部） 特变在乌干达农网取得一个2亿美金的配网EPC工程，里面包含15万只电表');
INSERT INTO `crs_tabledata1530` VALUES ('295', '{085466D9-747D-4B7B-A16F-13E9B64831CC}', '61', 'INHE-0654', '2019-05-05 15:54:53', '0000-00-00 00:00:00', '2019-05-09 13:52:19', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050503/BGL', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', 'ADMINISTRACION NACIONAL DE ELECTRICIDAD(ANDE)', 'ANDE', '巴拉圭', '', '', '', '巴拉圭国家电力公司，主要经营输电和配电，是该国唯一一个电力公司，员工人数约为5千。', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。');
INSERT INTO `crs_tabledata1530` VALUES ('296', '{7735A366-F914-4859-BDC4-3577CEEA2E0C}', '60', 'INHE-0790', '2019-05-05 16:39:57', '0000-00-00 00:00:00', '2019-05-07 12:48:02', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050504/JIC', '', 'JES Instrumentation * Controls', 'JES', '巴基斯坦', 'SAIFUDDIN MANDVIWALA', '+（92）300 8206465', 'jamali5152@gmail.com', '', '', 'JES Instrumentation * Controls', 'JES', '巴基斯坦', 'SAIFUDDIN MANDVIWALA', '+（92）300 8206465', 'jamali5152@gmail.com', '', '', 'JES Instrumentation * Controls', 'JES', '巴基斯坦', 'SAIFUDDIN MANDVIWALA', '+（92）300 8206465', 'jamali5152@gmail.com', '客户为JES项目客户。表计规格参考附件客户BOQ和JES09规格要求。表计的规格与JES09一样，区别在于此次订单要求表计与集中器用PLC通讯，双费率，双寄存器分别记录双电源用电。经过和技术支持沟通，只需在一代代码表上修改程序即可满足要求。	\r\r\r\r\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('297', '{1ADD2445-6BC5-4A3C-A6D5-5B150772E279}', '61', 'INHE-0805', '2019-05-06 13:37:52', '0000-00-00 00:00:00', '2019-05-09 13:50:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050601/CME', '项目代号CME, 请批准立项', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'ELECTROHUILA S.A. E.S.P.', 'ELECTROHUILA', '哥伦比亚', 'MARIO ANDRES JIMENEZ', '573158432739', '', '我司在哥伦比亚重要的目标电力公司。20万用户规模，未来五年用于AMI投资预计达1000万美元。与我司哥伦比亚代理有着良好的客户关系！', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('298', '{5B5552C1-3C4E-46C8-8A4F-E47BB53710B1}', '60', 'INHE-0560', '2019-05-06 09:28:03', '0000-00-00 00:00:00', '2019-05-09 14:00:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019050602/EMH', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'ООО \"энергопромсис\"', 'Энергопромсис', '乌克兰', 'Алексей', '+38 (067) 503-65-49', 'alex.kofs@gmail.com', 'ООО энергопромсис主要从事的贸易领域有：自动化能源商业核算系统\r\r\r\n电表EMH，Elster，ZMD，Actaris\r\r\r\n项目安装，启动和实施AMI计量系统\r\r\n\r\r\n销售智能表计，校准器和校准支架MTE，Zera，Actaris\r\r\r\nShield Digital Devices Satec\r\r\r\n电能质量分析仪LEM，Fluke\r\r\r\n补偿装置Nokian电容器\r\r\r\n测量仪器\r\r\r\n信息系统\r\r\r\n计量与标准化相关产品');
INSERT INTO `crs_tabledata1530` VALUES ('299', '{BF6028C4-FF6E-426F-B379-64C1C0B8B5EB}', '61', 'INHE-0721', '2019-05-16 15:16:22', '0000-00-00 00:00:00', '2019-05-16 15:16:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019051602/UKA', '', 'Anxor Ingeniería S.A', 'Anxor', '尼加拉瓜', 'James Ariza', '+505 83960521', 'james.ariza@anxor.com', '工业解决方案供应商，为电气行业提供工程服务，并为全球公认的电气行业制造商提供代理服务。是尼加拉瓜国有电力公司DISNORTE-DISSUR以及配电公司ENATREL的供应商之一。', '', 'Anxor Ingeniería S.A', 'Anxor', '尼加拉瓜', 'James Ariza', '+505 83960521', 'james.ariza@anxor.com', '工业解决方案供应商，为电气行业提供工程服务，并为全球公认的电气行业制造商提供代理服务。是尼加拉瓜国有电力公司DISNORTE-DISSUR以及配电公司ENATREL的供应商之一。', '', 'Administración Nacional de Usinas y Trasmisiones Eléctricas', 'UTE', '乌拉圭', '', '', '', 'UTE是乌拉圭国有公司，致力于发，输，配电和售电，提供配套服务和咨询。为了满足位于全国176,215平方公里的120万客户的需求，UTE拥有水力，风力和热力发电厂。来自萨尔托格兰德水电站（阿根廷和乌拉圭之间的两国合资企业）的能源以及来自第三方拥有的发电厂的能源补充UTE产能。');
INSERT INTO `crs_tabledata1530` VALUES ('300', '{A947AF71-A0DA-4EF1-8C56-83C3C0D738BA}', '61', 'INHE-0776', '2019-05-20 16:43:14', '0000-00-00 00:00:00', '2019-05-24 09:30:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019052001/PRH', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。', '', 'HIDRANDINA S.A.', '', '秘鲁', 'Cecilia Morales', '（511）044 – 481300', 'pperezb@distriluz.com.pe', '秘鲁国有特许经营配电公司之一，现有87万用户，2017年财报显示其总资产为5亿美元，负债2亿美元，年营业收入2.8亿美元，年净利润3000万美元，年毛利润率为8.8%；其是秘鲁国有电力集团Distriluz的全资子公司，旗下有共四家子公司，分别为：HIDRANDINA, ELECTRONORTE, ELECTROESTE, ELECTROCENTRO四家电力公司，共有超过260万用户，客户数量占秘鲁市场的31%份额。', '', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '秘鲁', 'Jamier Chafloque Silva', '+（511）572 9160', 'jchafloque@teching.com.pe', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('301', '{CD38A4B7-DFF4-40C4-A065-6A20975349AB}', '61', 'INHE-0725', '2019-05-27 16:51:13', '0000-00-00 00:00:00', '2019-06-05 09:12:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019052702/IEL', '', 'Energy-Lux', 'EL', '埃及', 'Hatem El Tantawy', '+201223112623', 'hatem-t@link.net', '该公司于2014年成立，主做LED灯及防火报警设备，中压配电设备及线缆等产品，在当地市场协助国外厂商拓展业务，老板Mr Hatem在El Sewedy (Ahemd一脉）以项目总监职位工作20年以上，公司实力较强，目前正与其洽谈EIA市场本地建厂合作事宜。\r\r\r\n【客户关系】：因其在El Sewedy工作20年，且其现有业务范围涉及电力行业，因此对电力行业主管部门EEHC的高层（主管电力公司副主席，表计部门技术总监，项目总监）较为熟识；与North Cairo及Alexander电力公司高层有客户关系；同时与军方合作过LED项目，与军方关系较好；\r\r\r\n【对电表项目的积极性】：其朋友在本地有工厂（原生产老式机械表），客户希望充分利用其客户关系做成电表项目，扩大公司规模，因此在平时沟通包括资料提供，安排客户见面等方面较为积极，且愿意采购建厂设备；\r\r\r\n【业绩】：近两年尤其在LED产品方面取得较大业务突破，大多与军方合作项目，具体项目经验可查阅附件：Energy-Lux公司介绍第4-9页，据悉今年三月份在埃及获得了约300万美金的LED大单。', '{CD38A4B7DFF440C4A0656A20975349AB11015FBC745F4B1982FBEF12F4BBACD1}_Energy-Lux 公司介绍.pdf', 'Alexander Electricity Distribution Company', 'AEDC', '埃及', 'Salwa Abdel Rahman', '+201289463339', 'dchairman_net@aedc.gov.eg', 'Alexander Electricity Distribution Company是埃及市场九家电力公司之一，目前管理用户260万，未来一年预计采购电表25万台（2019年9-10月招标10万台，2020年1-2月份执行，2020年4-5月份招标剩余15万台），在当地九家电力公司中实力位居前列，受当地电力行业主管部门Egyptian Electricity Holding Company（EEHC）管辖，在今年9-10月份预计招收10万台预付费IC卡表', '', 'Energy-Lux', 'EL', '埃及', 'Hatem El Tantawy', '+201223112623', 'hatem-t@link.net', '该公司于2014年成立，主做LED灯及防火报警设备，中压配电设备及线缆等产品，在当地市场协助国外厂商拓展业务，老板Mr Hatem在El Sewedy (Ahemd一脉）以项目总监职位工作20年以上，公司实力较强，目前正与其洽谈EIA市场本地建厂合作事宜.\r\r\n【客户关系】：因其在El Sewedy工作20年，且其现有业务范围涉及电力行业，因此对电力行业主管部门EEHC的高层（主管电力公司副主席，表计部门技术总监，项目总监）较为熟识；与North Cairo及Alexander电力公司高层有客户关系；同时与军方合作过LED项目，与埃及军方关系较好；\r\r\n【对电表项目的积极性】：其朋友在本地有工厂（原生产老式机械表），客户希望充分利用其客户关系做成电表项目，扩大公司规模，因此在平时沟通包括资料提供，安排客户见面等方面都较为积极，且愿意采购建厂设备；\r\r\n【业绩】：近两年尤其在LED产品方面取得较大业务突破，大多与军方合作项目，具体项目经验可查阅附件：Energy-Lux公司介绍第4-9页，据悉今年3月份在埃及获得了约300万美元的LED大单。');
INSERT INTO `crs_tabledata1530` VALUES ('302', '{A803FEB6-72B8-455D-8A72-A90E54C84238}', '61', 'INHE-0431', '2019-05-30 20:53:04', '0000-00-00 00:00:00', '2019-06-03 09:39:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019053001/TLS', '', '', '', '', '', '', '', '', '', 'Umeme Limited', '', '乌干达', 'Amatos Mwebeiha', '+256312360600', '', '', '', 'Umeme Limited', '', '乌干达', 'Amatos Mwebeiha', '+256312360600', '', 'UMEME是乌干达配电市场占比超过97%的电力公司。是乌干达证券交易所和内罗毕证券交易所两地上市的公司。截止至2018年12月，UMEME的公司总资产约为6.7亿美金。2018年税后收益为3600万美金。公司第一大股东为国家养老基金。前五位分别为：\r\r\n1.National Social Security Fund   23.20%\r\r\r\n2.Allan Gray   9.60%\r\r\r\n3.Kimberlite Frontier Africa Master Fund	8.30%\r\r\r\n4.Investec Asset Management Africa	4.40%\r\r\r\n5.Utilico Emerging Markets Limited	4.30%');
