INSERT INTO `crs_tabledata1530` VALUES ('304', '{6376B8F7-5834-4630-B597-0D0AEDA388AF}', '61', 'INHE-0381', '2019-05-31 17:51:55', '0000-00-00 00:00:00', '2019-06-19 18:25:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019053103/MTM', '', 'SIECOM', 'SIE', '缅甸', 'Lee Kwangmoo', '', 'vnlee8913@daum.net', '韩国公司，1970年成立，主要做电力设备产品，如变压器、保险系、断路器以及一些管理系统。', '', '', '', '', '', '', '', '', '', 'SIECOM', 'SIE', '缅甸', 'Lee Kwangmoo', '', 'vnlee8913@daum.net', '韩国公司，1970年成立，主要做电力设备产品，如变压器、保险系、断路器以及一些管理系统。');
INSERT INTO `crs_tabledata1530` VALUES ('305', '{54B46B5E-4754-4C07-8378-25CF09F207F4}', '61', 'INHE-0840', '2019-06-05 04:07:50', '0000-00-00 00:00:00', '2019-06-12 09:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060501/EER', '', 'Ceyma - Solu??es Energéticas e Manuten??o Industrial, Lda', 'CML', '安哥拉', 'Rui Andre', '+244926236443', 'ceyma.angola@gmail.com', '2015年成立的当地公司，主营承接电力公司或电力项目承包商的电表安装与连接等业务，老板R先生从有60多年经营电力项目历史的Ambergol出身，与其Ceyma的老板合作发展业务，他们在电力行业人脉广泛，并与电力公司及能源部长经营着良好的关系，寻求与我司合作向电力公司及其承包商提供电表及系统业务，目前接到承包商ANERGY的订单13000台电表，本月内先下6500台，合作成功后续会有更多的项目机会', '', '', '', '', '', '', '', '', '', 'Ceyma - Solu??es Energéticas e Manuten??o Industrial, Lda', 'CML', '安哥拉', 'Rui Andre', '+244926236443', 'ceyma.angola@gmail.com', '2015年成立的当地公司，主营承接电力公司或电力项目承包商的电表安装与连接等业务，老板R先生从有60多年经营电力项目历史的Ambergol出身，与其Ceyma的老板合作发展业务，他们在电力行业人脉广泛，并与电力公司及能源部长经营着良好的关系，寻求与我司合作向电力公司及其承包商提供电表及系统业务，目前接到承包商ANERGY的订单13000台电表，本月内先下6500台，合作成功后续会有更多的项目机会');
INSERT INTO `crs_tabledata1530` VALUES ('306', '{AFC59D15-D6DE-4F10-BA03-38889DCF88EB}', '61', 'INHE-0500', '2019-06-05 05:44:48', '0000-00-00 00:00:00', '2019-06-06 08:46:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060503/COC', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'City of Cape Town', '', '南非', 'Eugene Coetzee', '+27 (021) 444 2772', 'Eugene.Coetzee@capetown.gov.za \r\n', '1.招标方为南非市场8大大都市市政之一，用户数量第一，普通居民用户数量约为80万个，工商业用户约为3万个；\r\r\r\n2.招标方市政公司普通居民用表主要为兰吉尔和Conlog，工商业用户电表主要为兰吉尔、Itron和Elster，当前售电系统供应商为Ontect（Itron），AMR供应商为Itron和兰吉尔分别供应，暂无中国厂商供货电表；\r\r\n3.此次招标主要内容为LPU智能电表，两年期框架合同招标。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('307', '{DA1D27CE-B70E-43E8-9AB4-1140B5EAEE0C}', '60', 'INHE-0680', '2019-06-06 21:23:02', '0000-00-00 00:00:00', '2019-07-02 08:56:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2019060602/EOS', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星', '', '奥什电力', '奥什电力', '吉尔吉斯斯坦', 'Nursultan Zhoroev', '+996 700118787', 'oshelectro_oppe@mail.ru', '用户：400,000，已经更换数量: 3500 , 剩余待更换数量: 396500，   过去3年供应商为：哈萨克Smart Engineering Group ，三星');
INSERT INTO `crs_tabledata1530` VALUES ('308', '{F80570AE-5E94-4204-9520-8215B114A0A1}', '61', 'INHE-0593', '2019-06-12 14:25:44', '0000-00-00 00:00:00', '2019-06-27 10:15:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061201/SBC', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', '', '', '', '', '', '', '', '', 'SOCIETE BENINOISE D’ENERGIE ELECTRONIQUE', 'SBEE', '贝宁', 'Chantal C. DOSSOU', '00229 21 37 73 84/85', 'daem_pase@yahoo.com', '贝宁国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('309', '{25DB8EBA-5995-404C-A5A8-2A932291F534}', '66', 'JXINHE-2559', '2019-06-14 11:41:54', '0000-00-00 00:00:00', '2019-06-17 09:28:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061401/SRP', '', 'Rotax Ltd.com', 'Rotax', '斯里兰卡', 'Anne Christopher', '94 0714 893634', 'annec@rochegroup.lk', '公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('310', '{443B94A4-1875-43F1-9903-181347D5EE84}', '61', 'INHE-0843', '2019-06-17 12:52:55', '0000-00-00 00:00:00', '2019-06-24 15:40:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019061701/EDA\r\n', '', 'DISGARPAR S.A.', 'DISGARPAR', '厄瓜多尔', 'Michael Garzón', '+593 9 89544026', 'disgarpar@netlife.ec', 'DISGARPAR成立于1996年，家族式企业，从事电力行业15年，主营中高压输变电材料及设备，与当地电力局有多年的密切关系，是厄瓜多尔四大电力局之一CENTROSUR的供应商。', '', 'ElecGalapagos S.A.', 'ElecGalapagos', '厄瓜多尔', '', '052 520 136', '', 'ElecGalapagos是在厄瓜多尔加拉帕戈斯省的省电力局，主营电力生产、运输、分配和商业化，从事配电网项目、系统、设施、厂房的规划、建设、开发、扩建、管理、购销、租赁以及实施替代能源的各项活动；以及与电能和替代能源相关的机械设备和设施的操作和维护。', '', 'DISGARPAR S.A.', 'DISGARPAR', '厄瓜多尔', 'Michael Garzón', '+593 9 89544026', 'disgarpar@netlife.ec', 'DISGARPAR成立于1996年，家族式企业，从事电力行业15年，主营中高压输变电材料及设备，与当地电力局有多年的密切关系，是厄瓜多尔四大电力局之一CENTROSUR的供应商。');
INSERT INTO `crs_tabledata1530` VALUES ('311', '{7625F0C2-BAC1-4499-BA9C-A57F4B6F4D3E}', '60', 'INHE-0868', '2019-06-21 13:26:04', '0000-00-00 00:00:00', '2019-06-21 13:26:04', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062103/SRA', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '{7625F0C2BAC14499BA9CA57F4B6F4D3E11015FBC745F4B1982FBEF12F4BBACD1}_Rotax Pvt Ltd - Company Profile 2018 - LQ.PDF', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94112433117', 'dgmpldr2@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94112433117', 'dgmpldr@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('312', '{0F878EED-1F8D-4EFA-82E5-7A8E4CAAD932}', '60', 'INHE-0535', '2019-06-21 09:11:28', '0000-00-00 00:00:00', '2019-06-24 09:37:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062104/LVT', 'LVT', 'Al Mostajed Technologies', 'AMT', '阿联', 'Fahad Hashmi', '', 'fahad@gblenergy.com', '该公司总部位于英国，在中东设有区域办事处。是发电，输电，配电，自动化，智能电网，石油化学加工，水利项目等的总解决方案供应商。提供各种EPC工程，项目管理，项目设计，兼容，测试，运维，安装，售后服务，培训等服务。', '', 'Lahore Electric Supply Company Limited', 'LESCO', '巴基斯坦', 'Chief Engineer (Dev) PMU LESCO', '+92 42 99214410', 'cedev@lesco.gov.pk/pdami.lesco@gmail.com', '巴基斯坦政府（GoP）正在启动一项在亚行资助下的巴基斯坦电力公司的大规模AMI规划。 投资计划分阶段实施，目标是在巴基斯坦的主要城市和工业活动中心实现重大的AMI覆盖。该项目的第一阶段旨在覆盖Lahore（LESCO）地区的170万消费者。LESCO电力公司覆盖以下8个配电区域：North Lahore  Circle#FE54`Central Lahore Circle#FE54`Eastern Lahore  Circle#FE54`Okara Circle#FE54`South-Eastern LHR Circle#FE54`Sheikhupura Circle#FE54`Kasur Circle#FE54`Nankana Circle', '', 'Al Mostajed Technologies', 'AMT', '阿联', 'Fahad Hashmi', '', 'fahad@gblenergy.com', '该公司总部位于英国，在中东设有区域办事处。是发电，输电，配电，自动化，智能电网，石油化学加工，水利项目等的总解决方案供应商。提供各种EPC工程，项目管理，项目设计，兼容，测试，运维，安装，售后服务，培训等服务。');
INSERT INTO `crs_tabledata1530` VALUES ('313', '{8F94F832-8C45-4A46-ACB4-EDC3847DA240}', '61', 'INHE-0853', '2019-07-18 11:00:00', '0000-00-00 00:00:00', '2020-06-18 12:15:43', 'unchecked', 'n', 'n', '', '1', 'lxdj20190718/DFN', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('314', '{07E58E43-703B-4F88-9D4D-E665496E8379}', '60', 'INHE-0781', '2019-06-25 03:00:27', '0000-00-00 00:00:00', '2019-06-27 17:35:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062502/PDD', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('315', '{DD04AF4D-E11B-4568-A95A-04353EE0BD2E}', '66', 'JXINHE-2559', '2019-06-25 14:48:07', '0000-00-00 00:00:00', '2019-06-27 17:27:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062504/GPR', '', 'Protasis Engineering*Consulting', 'PROTASIS', '希腊', 'Manis Panagiotis', '+30 210 9561 154', 'pmanis@protasis.net.gr', 'Protasis 是一家电能系统工程和顾问公司，公司成立于2002年，致力于向电力公司的输配部门，发电公司，工业企业等提供能源解决方案。业务涉及发电，绿色能源，电能输送，工业包括油气，石化，钢铁，铝等。公司为电力保护，控制，自动化和计量系统行业的引导者。', '', 'Hellenic Electricity Distribution Network Operator', 'HEDNO', '希腊', 'Papailiou Nikolaos', '210 9090528', 'n.papailiou@deddie.gr', 'PPC SA的合资子公司，希腊电力配电网络运营商，负责管理营运希腊32非连接岛屿的电力系统，约占全国人口的15%和总营收的14￥。', '', 'Protasis Engineering*Consulting', 'PROTASIS', '希腊', 'Manis Panagiotis', '+30 210 9561 154', 'pmanis@protasis.net.gr', 'Protasis 是一家电能系统工程和顾问公司，公司成立于2002年，致力于向电力公司的输配部门，发电公司，工业企业等提供能源解决方案。业务涉及发电，绿色能源，电能输送，工业包括油气，石化，钢铁，铝等。公司为电力保护，控制，自动化和计量系统行业的引导者。');
