INSERT INTO `crs_tabledata1530` VALUES ('317', '{3DDE799B-3511-4C7A-A7A9-099881CA5F36}', '61', 'INHE-0642', '2019-06-26 16:30:19', '0000-00-00 00:00:00', '2019-07-09 18:58:12', 'unchecked', 'n', 'n', '', '1', 'lxdj2019062603/BAC', '请核实是否延标；是否有靠谱的合作方。', 'Keysource (Pty)Ltd', '', '博茨瓦纳', 'Duncan Gaolebogwe', '+267 71278649', 'duncan@keysourcebotswana.com', '本地代理公司，主要业务为项目安装以及代理供货业务，次代理与BPC电力公司有过项目来往，具备一定客户关系。', '{3DDE799B35114C7AA7A9099881CA5F3611015FBC745F4B1982FBEF12F4BBACD1}_Keysource Corporate Presentation 2019-compressed.pdf', 'Botswana power corporation', 'BPC', '博茨瓦纳', 'BPC', '+2673607000', 'contactcentre@bpc.bw', '博茨瓦纳电力公司', '', 'Keysource (Pty)Ltd', '', '博茨瓦纳', 'Duncan Gaolebogwe', '+267 71278649', 'duncan@keysourcebotswana.com', '本地代理公司，主要业务为项目安装以及代理供货业务，次代理与BPC电力公司有过项目来往，具备一定客户关系。');
INSERT INTO `crs_tabledata1530` VALUES ('318', '{2FF65E33-0B35-4D9A-9012-6B1D445C663E}', '60', 'INHE-0535', '2019-06-30 21:08:47', '0000-00-00 00:00:00', '2019-07-03 09:10:49', 'unchecked', 'n', 'n', '', '1', 'lxdj2019063001/MTC', 'MTC', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。', '', 'MAHARASHTRA STATE ELECTRICITY TRANSMISSION CO. LTD', 'MSETCL', '印度', 'Chief Engineer', '022 27600405 (O)', 'ceaci@mahatransco.in', '马哈拉施特邦电力传输有限公司（MSETCL）是印度最大的州立传输电力公司，拥有46217 circuit KM输电线路的输电网络和具有123846MVA变压能力的660EHV变电站。孟买国家负荷调度中心（SLDC）负责运营，监测和控制电力系统。2007年5月17日，根据Hon.MERC的2006第42号命令，基于可用性的费率和偏差处理机制，要在马哈拉施特邦实施ABT电表。SLDC要求ABT电表数据约3000个接口地点要根据MSETCL的地域进行每周DSM计费。目前，所有这些数据都是手动人工获取，在SLDC验证和处理。且调度和处理机制期限为15分钟。而根据监管机构论坛（FOR）新指南，现在需要将调度和处理周期改为15分钟。', '', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。');
INSERT INTO `crs_tabledata1530` VALUES ('319', '{17E45B9B-C14D-4B41-B633-55D6EF103710}', '60', 'INHE-0434', '2019-07-04 18:50:57', '0000-00-00 00:00:00', '2019-07-09 09:10:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070408/CBM', '', 'Société IYA', '', '马里', 'Yacouba DIAKITE', '+223 6687 8891', 'yacou.diakite99@gmail.com', '马里本地一家做一般贸易，服务提供，勘探采矿和分包商采矿的公司。', '', '', 'EDM', '马里', 'Fodebc Camara', '+223 7620 8369', 'Fodebc@gmail.com', '马里电力公司', '', 'Société IYA', '', '马里', 'Yacouba DIAKITE', '+223 6687 8891', 'yacou.diakite99@gmail.com', '马里本地一家做一般贸易，服务提供，勘探采矿和分包商采矿的公司。');
