INSERT INTO `crs_tabledata1530` VALUES ('321', '{A7E76A3B-6595-4878-896A-B23BF04FDD39}', '60', 'INHE-0781', '2019-07-09 02:15:30', '0000-00-00 00:00:00', '2019-07-10 15:43:16', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070901/BPP', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Bangladesh Power Development Board', 'BPDB', '孟加拉国', 'Director', '+88029550532', '', '用户数约350万，后分离出NESCO(约110万用户)用户数为240万。受电力部直属管辖。WZPDCL, NESCO都是从BPDB分离出去的电力公司。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('322', '{24009647-8AA8-43C5-8929-864EC4E0A2EE}', '61', 'INHE-0654', '2019-07-09 09:18:17', '0000-00-00 00:00:00', '2019-07-10 15:37:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070903/ADG', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', 'Edenor S.A.', '', '阿根廷', 'Juliana Estefania MATA', '4346-5400', '', '阿根廷最大的电力公司，总部在首都布宜诺斯艾利斯', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。');
INSERT INTO `crs_tabledata1530` VALUES ('323', '{38DE0B80-277F-4849-A647-72BA5A69AF23}', '61', 'INHE-0593', '2019-07-09 09:56:14', '0000-00-00 00:00:00', '2019-07-10 15:34:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2019070904/PDA', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户');
INSERT INTO `crs_tabledata1530` VALUES ('324', '{92BFD950-A975-42ED-BD11-96192820850D}', '61', 'INHE-0593', '2019-07-11 13:56:32', '0000-00-00 00:00:00', '2019-07-15 10:21:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071101/ABE', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户', '', 'Agence Burkinabè d’Electrification Rurale (ABER)', 'ABER', '布基纳法索', '', '226 25 37 45 01', 'contact@aber.bf / fde@fasonet.bf', '布基纳法索农村电力局（农电）。根据2017年4月20日第014/2017号法律第11条，农电负责任务为：\r\n\r\n1. 通过以较低的成本发展农村电气化，促进国家电力领域的公平覆盖#FE54`\r\n2. 助力实施国家电气化计划#FE54`\r\n3. 促进农村人口获得电力#FE54`\r\n4. 确保在基础设施发展框架内委派项目所有权#FE54`\r\n5. 监督活跃在这些地区的其他机构开展的农村电气化和农村能源使用活动#FE54`\r\n6. 为能源部长和监管机构编写关于农村电气化活动的年度报告。', '', 'La Société d’Installation Maintenance et d’Etude d’Equipement Electrique', 'SIMEEEL', '布基纳法索', 'Abdramane SIENOU', '00226 25 34 37 78', 'a.sienou@simeeel.com', '1998年7月8日成立的Burkina法律下的私人公司，注册资本为1.5亿西非法郎。\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n他们的目标是在任何需要的地方提供电力，特别是在布基纳法索的城市和乡村以及西非和中非，总要的业务范围为配电网络建设，提供防火及监控设备，太阳能相关的项目。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n胡蝶备注：潜在的另一家买方为ROAD ENERGY CONSTRUCTION，为BFN当地的建筑公司，该公司也收到了农电询标并将询标函发给我司，此处补充。');
INSERT INTO `crs_tabledata1530` VALUES ('325', '{472D7A22-5A6B-46C0-95E1-FE2E2344148C}', '66', 'INHE-0634', '2019-07-12 13:35:57', '0000-00-00 00:00:00', '2019-07-17 08:53:43', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071201/MMR', '', 'Khin Maung Nyunt Trading Company Limited', 'KMN', '缅甸', 'Htun Lin Kyaw', '+ 95943030071', 'htunlinkyaw@kmngroupmm.com', 'KMN是Khin Maung Nyunt Group of Companies下属最大历史最长的子公司，于1995年成立，从一家小型本地供应商发展壮大，成为缅甸电力行业最值得信赖、最可靠的产品和服务供应商之一。', '{472D7A225A6B46C095E1FE2E2344148C11015FBC745F4B1982FBEF12F4BBACD1}_No 4. KMN Profile with Project Referce (24.5.2018).pdf', 'Electricity Supply Enterprise', 'ESE', '缅甸', '', '', '', '缅甸内比都电力局。内比都是缅甸首都，人口约115.8万。', '', 'Khin Maung Nyunt Trading Company Limited', 'KMN', '缅甸', 'Htun Lin Kyaw', '+ 95943030071', 'htunlinkyaw@kmngroupmm.com', 'KMN是Khin Maung Nyunt Group of Companies下属最大历史最长的子公司，于1995年成立，从一家小型本地供应商发展壮大，成为缅甸电力行业最值得信赖、最可靠的产品和服务供应商之一。');
INSERT INTO `crs_tabledata1530` VALUES ('326', '{4C32C4F8-1CF5-4493-AB29-214CBFA7C40D}', '60', 'INHE-0560', '2019-07-12 13:44:33', '0000-00-00 00:00:00', '2019-07-16 17:35:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071203/BAT', '', 'HAZAARBAT LLC', 'HAZAARBAT LLC', '蒙古', 'Gan-Erdene Erdenesaikhan', '+97688079979', 'ganaa5573@mail.ru', 'Hazaarbat LLC 为蒙古国乌兰巴托的进出口贸易公司，在当地专门做政府投标项目和工程，主要行业有：机电产品、汽车配件、电站通信设备等。和俄罗斯公司ООО Наран-экспорт有12年的普通电表合作经验。现希望寻求中国表厂合作智能电表项目。7月初我方和客户沟通需求并提供了初步报价后，客户决定来访公司。据客户透露：他们和当地政府和电力公司有非常好的关系，深谙和政府部门打交道。当地所有政府采购都通过招标实现，但是需要客户关系及提前运作。银河只需保证技术、质量和价格，剩下的工作交给他们做。（此点有待证明）\r\r\n', '', '', '', '', '', '', '', '', '', 'HAZAARBAT LLC', 'HAZAARBAT LLC', '蒙古', 'Gan-Erdene Erdenesaikhan', '+97688079979', 'ganaa5573@mail.ru', 'Hazaarbat LLC 为蒙古国乌兰巴托的进出口贸易公司，在当地专门做政府投标项目和工程，主要行业有：机电产品、汽车配件、电站通信设备等。和俄罗斯公司ООО Наран-экспорт有12年的普通电表合作经验。现希望寻求中国表厂合作智能电表项目。\r\r\n						\r\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('328', '{76046E1B-78A2-4DDE-9F54-696786902F79}', '61', 'INHE-0500', '2019-07-12 22:25:07', '0000-00-00 00:00:00', '2019-07-16 17:29:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071205/EOR', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '招标方：ESKOM，南非国家电力公司，ESA、EST和DXE项目招标方业主					\r\n', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('329', '{D4815667-5DDC-470F-AC90-F9FF78B7C99A}', '61', 'INHE-0819', '2019-07-16 21:30:26', '0000-00-00 00:00:00', '2019-08-14 13:46:33', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071604/MDA', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '马达加斯加电力公司', 'jirama', '马达加斯加', 'xavier RAKOTOZAFY', '+261348305230', 'xavier.rakotozafy@jirama-mg.com', 'JIRAMA成立于1975年10月17日，部位于首都塔那那利佛，直到1999年，他都是该国唯一的国有电力公司。1999年之后，JIRAMA继续垄断配电网络。2018年6月，JIRAMA正在考虑修复其配电网络。');
INSERT INTO `crs_tabledata1530` VALUES ('330', '{3CD73000-EB03-4AF8-848B-82252A3315A6}', '61', 'INHE-0819', '2019-07-17 00:33:57', '0000-00-00 00:00:00', '2019-08-14 13:45:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071701/MDB', '按公司意见，三部参与，二部退出此项目', '', '', '', '', '', '', '', '', '马达加斯加电力公司', 'jirama', '马达加斯加', 'xavier RAKOTOZAFY', '+261348305230', 'xavier.rakotozafy@jirama-mg.com', 'JIRAMA成立于1975年10月17日，部位于首都塔那那利佛，直到1999年，他都是该国唯一的国有电力公司。1999年之后，JIRAMA继续垄断配电网络。2018年6月，JIRAMA正在考虑修复其配电网络。', '{3CD73000EB034AF8848B82252A3315A6FFC3E6BB8328443AA9AAC603FC047FE8}_20190706马达加斯加市场调查.pdf', '马达加斯加电力公司', 'jirama', '马达加斯加', 'xavier RAKOTOZAFY', '+261348305230', 'xavier.rakotozafy@jirama-mg.com', 'JIRAMA成立于1975年10月17日，部位于首都塔那那利佛，直到1999年，他都是该国唯一的国有电力公司。1999年之后，JIRAMA继续垄断配电网络。2018年6月，JIRAMA正在考虑修复其配电网络。');
INSERT INTO `crs_tabledata1530` VALUES ('331', '{B14E6CBA-EAFB-49F4-9AAB-5844EFC5AA7D}', '60', 'INHE-0790', '2019-07-17 11:11:03', '0000-00-00 00:00:00', '2019-07-22 15:51:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019071702/JOD', '', 'Al-Tareq Engineering Technology Co', 'TATECO', '约旦', 'Zohier', '962796750361', 'tateco@gmail.com', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '', 'Irbid District Electricity Company', 'IDECO', '约旦', 'Mohammed', '7201500 2-962', 'ideco@ideco.com.jo', 'IDECO公司成立于1957年的民用电力公司，属私营企业，负责包括伊尔比德马弗拉克杰拉什阿杰隆的拜勒加省的和行政区的发电，输电和电力的分配。1967年该公司的名称改为Irbid Electricity Company Public Shareholding Company Limite', '', 'Al-Tareq Engineering Technology Co', 'TATECO', '约旦', 'Zohier', '962796750361', 'tateco@gmail.com', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。');
INSERT INTO `crs_tabledata1530` VALUES ('332', '{ED676D85-9871-465E-A559-6D1227DDBDB9}', '66', 'INHE-0774', '2019-07-23 10:00:49', '0000-00-00 00:00:00', '2019-07-29 17:43:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072301/ETS', '', 'SC ENERGOBIT SA', 'ENERGOBIT', '罗马尼亚', 'Lucian Calugar', '40 264 207 510', 'lucian.calugar@energobit.com', '成立于25年前，约700名员工，主要做开关柜、输电变压器、低压输电设备和工业自动化设备等电气设备；提供中、高、低压输电交钥匙工程，室内外照明方案，智能计量，SCADA系统，电气维护、咨询服务等业务。', '', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE TRANSILVANIA SUD S.A.', 'SDEE Transilvania Sud SA', '罗马尼亚', 'Petru Nastasa', '40 0268305308', 'petru.nastasa@distributie-energie.ro', 'SDEE Transilvania Sud SA 是罗马尼亚八大配电公司之一，主要为管辖区域内的260万居民提供输、配电，在相关领域有超过100年的经验。它由6家分子机构组成，给Alba, Bra?ov, Covasna, Harghita, Mure? 和 Sibiu 6个县提供电力，服务覆盖面积3,4100KM2。此外，SDEE Transilvania Sud SA 负责其自有电力设施的运行、维护和升级满足安全、质量、经济和环保的要求。 公司的主管机构是股东大会，负责决定业务及其经济和商业政策。由董事会负责公司的日常管理。此机制从2007年8月份根据 HGR 675/2007开始实施。', '', 'SC ENERGOBIT SA', 'ENERGOBIT', '罗马尼亚', 'Lucian Calugar', '40 264 207 510', 'lucian.calugar@energobit.com', '成立于25年前，约700名员工，主要做开关柜、输电变压器、低压输电设备和工业自动化设备等电气设备；提供中、高、低压输电交钥匙工程，室内外照明方案，智能计量，SCADA系统，电气维护、咨询服务等业务。');
INSERT INTO `crs_tabledata1530` VALUES ('333', '{9A97D57B-DFA1-40D3-B40C-9942BE5A4559}', '61', 'INHE-0431', '2019-07-22 14:34:52', '0000-00-00 00:00:00', '2019-07-24 17:00:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072302/UDL', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '', 'Uganda Electricity Distribution Company Limited', 'UEEDCL', '乌干达', 'The Head, PDU', '0312 330300', 'mwine@uedcl.co.ug', '乌干达国家配网公司。配网的主要业务外包给UMEME运营。但是UEDCL也部分采购小批量订单。', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验');
INSERT INTO `crs_tabledata1530` VALUES ('334', '{FEDCA7FE-7857-4A28-B027-ACF20FA7DEBD}', '60', 'INHE-0868', '2019-07-24 09:30:47', '0000-00-00 00:00:00', '2019-07-26 10:48:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072401/PAP', '', 'Infotech Group', 'Infotech', '巴基斯坦', 'Muhammad Bilal Saeed', '+923018492782', 'bilal.saeed@infotechgroup.com', '我们的总部位于新加坡，在全球各地设有办事处，从伦敦到阿克拉，是全球增长最快的信息技术集团之一。在过去20多年里，信息技术公司在世界各地的重要项目上投入了数百万美元，为企业提供了丰富的解决方案。', '{FEDCA7FE78574A28B027ACF20FA7DEBD11015FBC745F4B1982FBEF12F4BBACD1}_InfoTech Corporate Profile (Updated).pdf', 'Tetra Tech', 'Tetra Tech', '美国', 'Engineer', '', 'SEP.Bids@tetratech.com', 'Tetra Tech是全球领先的咨询，工程和技术服务提供商。 我们的声誉取决于我们的员工的技术专长和奉献精神 -  20,000名员工跨学科和时区合作，为具有挑战性的项目提供智能，可持续的解决方案。 我们很自豪能够成为水，环境，基础设施，资源管理，能源和国际发展方面的领先技术专家。 Tetra Tech将全球数十亿美元的公司资源与全球450个地点的本地，以客户为中心的交付相结合。', '', 'Infotech Group', 'Infotech', '巴基斯坦', 'Muhammad Bilal Saeed', '+923018492782', 'bilal.saeed@infotechgroup.com', '我们的总部位于新加坡，在全球各地设有办事处，从伦敦到阿克拉，是全球增长最快的信息技术集团之一。在过去20多年里，信息技术公司在世界各地的重要项目上投入了数百万美元，为企业提供了丰富的解决方案。');
INSERT INTO `crs_tabledata1530` VALUES ('336', '{9EC67097-7FEE-4861-AFEB-E01946B5B6E2}', '60', 'INHE-0868', '2019-07-25 16:37:58', '0000-00-00 00:00:00', '2019-07-30 17:01:00', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072504/LAP', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '{9EC670977FEE4861AFEBE01946B5B6E2FFC3E6BB8328443AA9AAC603FC047FE8}_Rotax Pvt Ltd - Company Profile 2018 - LQ.PDF', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('337', '{2EA47610-A407-4589-81F1-4CB61C1BC504}', '60', 'INHE-0868', '2019-07-25 17:04:10', '0000-00-00 00:00:00', '2019-07-29 17:38:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072505/LAQ', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '{2EA47610A407458981F14CB61C1BC50411015FBC745F4B1982FBEF12F4BBACD1}_Rotax Pvt Ltd - Company Profile 2018 - LQ.PDF', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('338', '{D793A285-936A-4373-8CDA-D27B7910ACB3}', '61', 'INHE-0843', '2019-07-26 16:11:58', '0000-00-00 00:00:00', '2019-09-09 08:56:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072601/EGA', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'ALEMINSA S.A.', 'ALEMINSA', '厄瓜多尔', 'Rodrigo Guayaquil', '+593985404827', 'rodrigog@aleminsa.com', 'ALEMINSA是厄瓜多尔一家致力于高、中、低压电气材料和电气设备销售的私营公司，拥有超过20年的行业经验，业务遍布整个厄瓜多尔领土。客户与厄瓜多尔国电CNEL、首都电力局EEQ有多个项目合作；曾负责过厄瓜多尔10万台AMI圆表项目。');
INSERT INTO `crs_tabledata1530` VALUES ('339', '{27D0B3C3-81D3-4FFA-9ABC-C6FE6FA80B30}', '60', 'INHE-0535', '2019-07-29 11:01:31', '0000-00-00 00:00:00', '2019-08-01 13:43:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2019072901/BOD', 'BOD', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。', '{27D0B3C381D34FFA9ABCC6FE6FA80B3011015FBC745F4B1982FBEF12F4BBACD1}_Blue_Ocean_System_Smart-City_Corporate_Profile.pdf', 'MAHARASHTRA STATE ELECTRICITY DISTRIBUTION CO. LTD.', 'MSEDCL', '印度', 'CHIEF ENGINEER', '', 'cestores@mahadiscom.in', '马哈拉施特邦配电公司MSEDCL负责孟买东北部地区电力业务，用户基数达2480万。投入大量经历和资源实现“确保客户服务卓越”的使命。', '', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。');
INSERT INTO `crs_tabledata1530` VALUES ('340', '{6CDF887B-44A8-40BA-89C6-31890EA4D806}', '61', 'INHE-0885', '2019-07-30 13:26:21', '0000-00-00 00:00:00', '2019-08-02 16:48:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019073003/BWC', '', 'Almaz (Pty)Ltd', 'Almaz', '博茨瓦纳', '', '+267 390 1339', 'info@almaz.co.bw', '博茨瓦纳当地公司，主营业务为电子设备组装工厂，为博茨瓦纳当地政府提供笔记本电脑以及本地预付费电水表项目。具有一定的政府关系，在博茨瓦纳有一定的市场基础。', '{6CDF887B44A840BA89C631890EA4D80611015FBC745F4B1982FBEF12F4BBACD1}_Almaz Company Profile.pdf', 'Botswana Power Corporation', 'BPC', '博茨瓦纳', 'BPC', '+2673607000', 'contactcentre@bpc.bw', '博茨瓦纳电力公司', '', 'FACTORFAST METERING (PTY) LTD', '无', '博茨瓦纳', 'Chibana Carter Louis（General Manager）', '+267 3163114', 'louis@factorfast.co.bw', '主营电力设备相关业务,已经在BPC公布的项目上有过多次合作，该公司在电力公司有一定的客户关系。');
INSERT INTO `crs_tabledata1530` VALUES ('341', '{C880FFF5-2FF8-4089-BFD5-29FE0209BE23}', '66', 'JXINHE-2559', '2019-08-02 11:52:35', '0000-00-00 00:00:00', '2019-08-06 08:43:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080201/GPZ', '', 'ZOUBOULAKIS SA', 'ZOUBOULAKIS', '希腊', 'Makis Karalis', '+30 2105732084', 'e.karalis@zouboulakis.gr', '公司成立于1979年，希腊雅典，为政府部门如事工部门，军队，大学，公用企业，州政府，市政，安全部队，公立和私营学校和私立公司的供应商。客户超过1000家，经过40多年的运营，成为政府和私营企业业务的是大合同供应商，向HEDNO供应过非电表的非电力类项目。', '', 'Hellenic Electricity Distribution Network Operator', 'HEDNO', '希腊', 'Papailiou Nikolaos', '210 9090528', 'n.papailiou@deddie.gr', 'PPC SA的合资子公司，希腊电力配电网络运营商，负责管理营运希腊32非连接岛屿的电力系统，约占全国人口的15%和总营收的14￥。', '', 'ZOUBOULAKIS SA', 'ZOUBOULAKIS', '希腊', 'Makis Karalis', '+30 2105732084', 'e.karalis@zouboulakis.gr', '公司成立于1979年，希腊雅典，为政府部门如事工部门，军队，大学，公用企业，州政府，市政，安全部队，公立和私营学校和私立公司的供应商。客户超过1000家，经过40多年的运营，成为政府和私营企业业务的是大合同供应商，向HEDNO供应过非电表的非电力类项目。');
INSERT INTO `crs_tabledata1530` VALUES ('342', '{622FADF8-7A69-4B30-9A82-C76BC67352FD}', '66', 'INHE-0628', '2019-08-05 10:07:26', '0000-00-00 00:00:00', '2019-08-08 10:06:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080501/POL', '', 'ZEUP POZYTON', '', '波兰', 'Marek Krakowian', '034-366-4495', 'm.krakowian@pozyton.com.pl', '波兰Pozyton 电表厂成立于1989年，目前生产多种型号的单相表、三相表和多功能CT表，且单、三相表均有四相限、复费率、带负荷曲线和无线通讯要求，全部符合欧盟MID标准，向波兰多个电力局都有供货经验。Pozyton对已经参观银河并进行了技术交流。银河也参观了Pozytond的工厂，并达成了合作意向。目前客户积极为银河翻译标书和提供当地支持，希望一起进行投标。', '', 'Polska Grupa Energetyczna', 'PGE', '波兰', 'Piotr Pondo', '', 'piotr.pondo@pgedystrybucja.pl', '业务简介\r\nPGE Capital Group是波兰最大的能源部门公司，涉及销售收入和净利润。由于自身燃料资源，发电和配电网络的结合，PGE为500多万个家庭，企业和机构提供安全可靠的电力供应。\r\n\r\n使命和愿景\r\nPGE的使命是确保基于供应可靠性，卓越技术，现代服务和合作伙伴关系的安全性和增长。PGE集团业务的总体目标是提高其股东价值以及确保波兰能源安全的关键作用。根据其长期增长愿景，PGE将成为：\r\n\r\n- 发电领导者，积极利用增长机会\r\n\r\n- 可靠，活跃的媒体和服务供应商\r\n\r\n- 波兰最高效，最灵活的能源集团 \r\n\r\n- 开发新业务模式和业务线的领导者\r\n\r\n保持在发电领域的领先地位将涉及在2020年以后在波兰的发电市场中实现至少40％的份额。', '{622FADF87A694B309A82C76BC67352FDFFC3E6BB8328443AA9AAC603FC047FE8}_PGE profile.pdf', 'Polska Grupa Energetyczna', 'PGE', '波兰', 'Piotr Pondo', '', 'piotr.pondo@pgedystrybucja.pl', '业务简介\r\nPGE Capital Group是波兰最大的能源部门公司，涉及销售收入和净利润。由于自身燃料资源，发电和配电网络的结合，PGE为500多万个家庭，企业和机构提供安全可靠的电力供应。\r\n\r\n使命和愿景\r\nPGE的使命是确保基于供应可靠性，卓越技术，现代服务和合作伙伴关系的安全性和增长。PGE集团业务的总体目标是提高其股东价值以及确保波兰能源安全的关键作用。根据其长期增长愿景，PGE将成为：\r\n\r\n- 发电领导者，积极利用增长机会\r\n\r\n- 可靠，活跃的媒体和服务供应商\r\n\r\n- 波兰最高效，最灵活的能源集团 \r\n\r\n- 开发新业务模式和业务线的领导者\r\n\r\n保持在发电领域的领先地位将涉及在2020年以后在波兰的发电市场中实现至少40％的份额。');
INSERT INTO `crs_tabledata1530` VALUES ('343', '{2EDC7D78-BDC3-46A5-BD4D-74813EFCA0E8}', '61', 'INHE-0772', '2019-08-08 09:54:41', '0000-00-00 00:00:00', '2019-08-12 13:51:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080802/MAA', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。');
INSERT INTO `crs_tabledata1530` VALUES ('344', '{CF7C2C82-104B-40C9-B330-3B4C3160B32F}', '61', 'INHE-0865', '2019-08-09 09:43:44', '0000-00-00 00:00:00', '2019-08-12 13:45:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019080902/CDZ', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'Groupement des services Eau et électricité', 'GS2E', '科特迪瓦', 'Eric Guillaume OSSIENY', '+225 21-23-68-49 /  36849', 'eossieny@gs2e.ci', 'ERANOVE在科特迪瓦市场的子公司。主要服务于科特迪瓦的电力公司和水务公司的IT部门。', '', 'Groupement des services Eau et électricité', 'GS2E', '科特迪瓦', 'Eric Guillaume OSSIENY', '+225 21-23-68-49 /  36849', 'eossieny@gs2e.ci', 'ERANOVE在科特迪瓦市场的子公司。主要服务于科特迪瓦的电力公司和水务公司的IT部门。');
INSERT INTO `crs_tabledata1530` VALUES ('345', '{268DDD11-4F97-49CD-8740-D2B60B64FE97}', '66', 'INHE-0634', '2019-08-13 14:29:16', '0000-00-00 00:00:00', '2019-08-16 17:35:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081301/URV ', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'JIRAMA', 'JIRAMA', '马达加斯加', '', '', '', '马达本地水电部', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('346', '{EA6CE8E0-FD64-4FF0-8EB7-6E076D577C12}', '61', 'INHE-0725', '2019-08-14 05:44:52', '0000-00-00 00:00:00', '2019-08-20 17:07:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081401/MNP', '', 'ACOB Lighting Technology Ltd', 'MNP', '尼日利亚', 'Alexander C. Obiechina', '+2348032902825', 'infoacob@gmail.com', 'ACOB Lighting Technology Ltd是一家尼日利亚主做LED及发电业务的公司，为本地微型电网运营商之一，其公司老板Mr Alex同时也是本地微网项目运营联盟AMDA(African Minigrids Development Association)的CEO，此机构已受政府授权管理尼日利亚微网项目。与本地多家微网运营商关系密切，与政府部门关系较好，同时同美国公司有一定的关系，上个月刚刚获得10万美金投资。\r\nNG市场目前的微网项目正在兴起，目前业务正在联系的微网客户有ACOB Lighting Technology, Ureka Content Distribution Limited, 以及主要微网运营机构REA(Rural Electrification Agency), GIZ(Deutsche Internationale Zusammenarbeil)以及AMDA(African Minigrids Development Association)。这些机构在本地有较强的客户关系（尤其与本地政府），一定的经济实力及表计需求。目前尼日利亚仍有8000万人左右', '', '', '', '', '', '', '', '', '', 'ACOB Lighting Technology Ltd', 'MNP', '尼日利亚', 'Alexander C. Obiechina', '+2348032902825', 'infoacob@gmail.com', 'ACOB Lighting Technology Ltd是一家尼日利亚主做LED及发电业务的公司，为本地微型电网运营商之一，其公司老板Mr Alex同时也是本地微网项目运营联盟AMDA(African Minigrids Development Association)的CEO，此机构已受政府授权管理尼日利亚微网项目。与本地多家微网运营商关系密切，与政府部门关系较好，同时同美国公司有一定的关系，上个月刚刚获得10万美金投资。\r\nNG市场目前的微网项目正在兴起，目前业务正在联系的微网客户有ACOB Lighting Technology, Ureka Content Distribution Limited, 以及主要微网运营机构REA(Rural Electrification Agency), GIZ(Deutsche Internationale Zusammenarbeil)以及AMDA(African Minigrids Development Association)。这些机构在本地有较强的客户关系（尤其与本地政府），一定的经济实力及表计需求。目前尼日利亚仍有8000万人左右');
INSERT INTO `crs_tabledata1530` VALUES ('347', '{6223C4C6-9C47-4386-849F-21E6BECCEE62}', '61', 'INHE-0440', '2019-08-14 09:14:10', '0000-00-00 00:00:00', '2019-08-20 17:03:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019081402/TTY', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。', '', 'ZANZIBAR ELECTRICITY CORPORATION', 'ZECO', '坦桑尼亚', 'Eng. Hassan Ali Mbarouk', '+255 2452255', 'info@zeco.co.tz', '桑给巴尔电力公司ZANZIBAR ELECTRICITY CORPORATION (ZECO)，100%属于桑岛政府，归属能源部管辖。ZECO主要从TANESCO购电，然后供岛上居民使用，每年新增约3-5万新用户,是坦桑除国电（TANESCO)、农村电力公司（REA）后的第三个电力公司。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。');
INSERT INTO `crs_tabledata1530` VALUES ('348', '{5A944715-E078-491B-970E-44A3AA82A36F}', '66', 'INHE-0634', '2019-08-21 15:50:41', '0000-00-00 00:00:00', '2019-08-23 19:17:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2019082102/YGN', '', 'Khin Maung Nyunt Trading Company Limited', 'KMN', '缅甸', 'Htun Lin Kyaw', '+ 95943030071', 'htunlinkyaw@kmngroupmm.com', 'KMN是Khin Maung Nyunt Group of Companies下属最大历史最长的子公司，于1995年成立，从一家小型本地供应商发展壮大，成为缅甸电力行业最值得信赖、最可靠的产品和服务供应商之一。', '', 'Yangon Electricity Supply Corporation', 'YESC', '缅甸', '', '', '', '能源部下负责仰光范围的电力局。', '', 'Khin Maung Nyunt Trading Company Limited', 'KMN', '缅甸', 'Htun Lin Kyaw', '+ 95943030071', 'htunlinkyaw@kmngroupmm.com', 'KMN是Khin Maung Nyunt Group of Companies下属最大历史最长的子公司，于1995年成立，从一家小型本地供应商发展壮大，成为缅甸电力行业最值得信赖、最可靠的产品和服务供应商之一。');
INSERT INTO `crs_tabledata1530` VALUES ('349', '{7CCC112C-EE14-47A1-9E97-E2C2DC899709}', '61', 'INHE-0843', '2019-08-23 17:03:19', '0000-00-00 00:00:00', '2019-08-27 16:18:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019082303/MXP', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Protecsa Ingeniería S.A. de C.V.', 'Protecsa', '墨西哥', 'Ruben Sanchez Rojo', '52 442 313 1109', 'ruben@protecsa.lat', 'Protecsa在墨西哥的主营业务是为电力行业提供智能电表、计量设备、AMI方案、TPCyM方案和智能电网解决方案，拥有20年的行业经验，本地有大型工厂生产自主品牌产品。墨西哥国家电力局CFE供应商。');
INSERT INTO `crs_tabledata1530` VALUES ('350', '{25C4D7D1-3032-498C-AF6F-5E090873BC45}', '66', 'INHE-0579', '2019-09-03 09:45:33', '0000-00-00 00:00:00', '2019-09-04 16:11:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090301/TUS', '', 'ICE ENGINEERING', 'ICE', '突尼斯', 'Moez.loulou', '+216 22332211', 'moez.loulou@ice-engineering.net', '1.成立于2016年，公司营业范围为电气产品、机械和液压设备等。\r\r\r\n2. 2015年-2018年均给电力公司STEG供过货（中标供货），合同有七十万人民币，九十万人民币，三百万，七百万的合同等。\r\r\r\n3. 在突尼斯电力公司内部有一定关系，帮助银河拿到新版技术以及商务草稿。\r\r\r\n4.公司所在地为突尼斯智能电表项目实施地sfax省。\r\r\n\r\r\n', '', 'Tunisian Company of Electricity and Gas', 'STEG', '突尼斯', 'Abdelkhalek BEN KHEDHER', '+ 216 71 341 449', 'abkhedher@steg.com.tn', '1. 成立于1962年，是突尼斯全国政府性上市的电力公司。\r\r\r\n2. STEG管理全国四百万用户，其中低压用户三百九十万个。\r\r\r\n3. STEG内部分为四个职能级别：董事会、部门、分部、服务部门。\r\r\r\n4. STEG垄断突尼斯全国的发电和配电。', '', 'Tunisian Company of Electricity and Gas', 'STEG', '突尼斯', 'Abdelkhalek BEN KHEDHER', '+ 216 71 341 449', 'abkhedher@steg.com.tn', '1. 成立于1962年，是突尼斯全国政府性上市的电力公司。\r\r\n2. STEG管理全国四百万用户，其中低压用户三百九十万个。\r\r\n3. STEG内部分为四个职能级别：董事会、部门、分部、服务部门。\r\r\n4. STEG垄断突尼斯全国的发电和配电。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('351', '{5D75666B-F991-471A-AC82-2DFBD99E9C49}', '61', 'INHE-0876', '2019-09-04 16:25:42', '0000-00-00 00:00:00', '2019-09-09 18:41:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090402/MEE', '', '', '', '', '', '', '', '', '', 'Electricidade de Mocambique, E.P', 'EDM', '莫桑比克', 'Benjamim', '+258-823029777', 'benjamim.fernandes@edm.co.mz', '目前全国电网主要由两家公司运行，分别是EDM和HCB。其中EDM主要负责莫桑国内电力的购买、输送和配售。HCB主要负责其Cahora Bassa水电站向南非和津巴等输送电力。莫桑最大的电源点是HCB拥有的Cahora Bassa水电站，其余电站除少量EDM开发拥有的小型水电、燃气电站和燃油电站外，均为私人投资商开发。', '', 'Electricidade de Mocambique, E.P', 'EDM', '莫桑比克', 'Benjamim', '+258-823029777', 'benjamim.fernandes@edm.co.mz', '目前全国电网主要由两家公司运行，分别是EDM和HCB。其中EDM主要负责莫桑国内电力的购买、输送和配售。HCB主要负责其Cahora Bassa水电站向南非和津巴等输送电力。莫桑最大的电源点是HCB拥有的Cahora Bassa水电站，其余电站除少量EDM开发拥有的小型水电、燃气电站和燃油电站外，均为私人投资商开发。');
