INSERT INTO `crs_tabledata1530` VALUES ('353', '{00912C30-4722-4F8A-AFE1-9F5E2D7B1F67}', '60', 'INHE-0868', '2019-09-06 10:58:52', '0000-00-00 00:00:00', '2019-09-10 13:46:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090602/LAK', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('354', '{94393265-9A1A-45BF-8A76-4A49260B9196}', '61', 'INHE-0642', '2019-09-09 05:49:25', '0000-00-00 00:00:00', '2019-09-11 15:05:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019090902/SRM11', '代号为SRE。', 'Metals and Engineering Corporation Hi-tech Engineering Industry', 'Hi-tech', '埃塞俄比亚', 'Logistics & supply management\"', '+251 913358173', 'hitechplan06@gmail.com', '埃塞军企的下属企业，涉及业务面广且实力较强；提格雷人当政的时候十分强势，新总理上台后该企业高层全面洗牌，但公司由于业务面广，公司得以保留。', '', 'Metals and Engineering Corporation Hi-tech Engineering Industry', 'Hi-tech', '埃塞俄比亚', 'Logistics & supply management\"', '+251 913358173', 'hitechplan06@gmail.com', '埃塞军企的下属企业，涉及业务面广且实力较强；提格雷人当政的时候十分强势，新总理上台后该企业高层全面洗牌，但公司由于业务面广，公司得以保留。', '', 'Metals and Engineering Corporation Hi-tech Engineering Industry', 'Hi-tech', '埃塞俄比亚', 'Logistics & supply management\"', '+251 913358173', 'hitechplan06@gmail.com', '埃塞军企的下属企业，涉及业务面广且实力较强；提格雷人当政的时候十分强势，新总理上台后该企业高层全面洗牌，但公司由于业务面广，公司得以保留。');
