INSERT INTO `crs_tabledata1530` VALUES ('357', '{C94F3DAD-7589-4077-B30C-4092E8CDA7D6}', '66', 'INHE-0634', '2019-09-12 18:13:02', '0000-00-00 00:00:00', '2019-09-16 17:54:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091201/GTM', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'JIRAMA', 'JIRAMA', '马达加斯加', '', '', '', '马达本地水电部', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('358', '{13E665E5-001E-40DF-871D-03098460D640}', '61', 'INHE-0642', '2019-09-17 18:50:06', '0000-00-00 00:00:00', '2019-10-25 10:24:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091701/SRD', '', 'RAYMAN PLC', 'RAYMAN', '埃塞俄比亚', 'Abdulwase Ibrahim', '+251 912612444', 'abdexo@gmail.com', '1） R 公司是一家有店铺的电气经销商，主要经营断路器，简单的 DIN 分表，目测产品全部是自 己品牌。此公司有两家门店，做批发和零售，也做投标和代理。该公司据说有一支 5 人 的技术团队；有一个 800 平的仓库（据说原先计划组装手机卖）。 2） 拜访的是 R 公司的老板 F 和业\r\n务经理 A。沟通来看，F 清楚本地的税费（关税=高达 100%， 增值税=15%，所得税=高达 35%）。从开车，吃饭和家庭成员数量来看，F 估计有钱：开车是 奔驰，谈吐淡定，思路清晰。业务经理 A 是电气专业， 沟通来看熟悉配电业务（对银河 BOX300，LPU，DTMS，DA 和变电站方案感觉很兴奋，直接 表示自己可以拿到标书草稿，可以运作银河技术点进标书；有朋友，有办法）。另外，很有 意思的 F 和 R 去过深圳创银，说某项目代理创银（有 2016 年去创银的照片），一切都弄好， 创银最后一刻不开保函放弃了；导致他们对创银印象不好。 3） F 和我方洽谈，对我方要求投资 25 万美元建厂设备，表现的比较淡定。只是提到，一旦拿 单供货，需要银河做些支持。 4） 对于我方安排的任务，R 公司算是比较快', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('359', '{3F0578EC-0121-F1B7-739A-910963D498B2}', '61', 'INHE-0500', '2019-09-18 04:14:04', '0000-00-00 00:00:00', '2019-09-19 14:24:16', 'unchecked', 'n', 'n', '', '1', 'CPM', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'City PowerJohannesburg (SOC) Ltd', 'City Power', '南非', 'Masego Moiloa', '011 490 7209', 'mmoiloa@citypower.co.zaE-MAIL', '1.招标方为南非市场8大大都市市政之一，用户数量约50万，普通居民用户数量约为45万个，工商业用户约为5万个；2.招标方市政公司普通居民用表主要为兰吉尔、海兴和Itron，工商业用户电表主要为兰吉尔、Itron和海兴，当前售电系统供应商为Ontect（Itron），AMR供应商为Itron和海兴分别供应；3.此次招标主要内容为后付费中小型商业、大型商业用户智能电表，三年期框架合同招标。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('360', '{81BE232E-2F04-4290-908F-517314AC54ED}', '61', 'INHE-0500', '2019-09-19 02:45:30', '0000-00-00 00:00:00', '2019-09-20 16:31:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091901/CPJ', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '', '', 'City PowerJohannesburg (SOC) Ltd', 'City Power', '南非', 'Masego Moiloa', '011 490 7209', 'mmoiloa@citypower.co.zaE-MAIL', '1.招标方为南非市场8大大都市市政之一，用户数量约50万，普通居民用户数量约为45万个，工商业用户约为5万个；2.招标方市政公司普通居民用表主要为兰吉尔、海兴和Itron，工商业用户电表主要为兰吉尔、Itron和海兴，当前售电系统供应商为Ontect（Itron），AMR供应商为Itron和海兴分别供应；3.此次招标主要内容为后付费中小型商业、大型商业用户智能电表，三年期框架合同招标。', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'NYC(ZEC2)', '南非', 'Matsotso Vuso', '0027 11 675 7669', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('361', '{CC98FBF5-413B-4D9F-B682-C0AE4EE64695}', '66', 'INHE-0774', '2019-09-19 10:48:04', '0000-00-00 00:00:00', '2019-09-20 16:30:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091902/BAL', '', 'MOSECO C Modern Scientific & Electronics Co.', 'MOSECO', '约旦', 'Mohammad Shubietah', '962 6 5548800', 'mohammad.shubietah@moseco.com.jo', 'MOSECO集团是一家领先的阿拉伯系统集成商，在IT电信市场拥有超过38年的经验。 MOSECO能够以全面且经济高效的方式独特地安装和支持电信基础设施解决方案及其互补的运营和业务支持解决方案。 Moseco集团总部位于约旦安曼，在沙特阿拉伯，卡塔尔，巴勒斯坦和伊拉克北部开展业务。 集团在阿拉伯地区雇用了超过600名专业人员，服务于阿拉伯地区的客户群。同时也是诺基亚在巴勒斯坦的分销商。', '', 'Palestinian energy and Natural Resources Authority', 'PENRA', '巴勒斯坦', 'Eng. Abdul Hadi Barakat', '9722 2984752', 'procurement@menr.org', '巴勒斯坦能源和自然资源管理局（PENRA）成立于1994年，负责监督能源部门的发展。它负责能源部门的政策，协调和部门发展，并向巴勒斯坦总统汇报。它负责执行巴勒斯坦权力机构1997年部门政策函的规定，其中概述了西岸和加沙电力部门发展的未来体制框架。根据这项政策，它将向部门实体颁发许可证，并授权进出口电力。\r\nPENRA负责将西岸的供电和配电安排整合为五个配电公用事业，这是巴勒斯坦行业政策下的一项重大改革。它创建了五个公用事业：北方电力分配公司（NEDCO），希伯伦电力公司（HEPCO）和南方电力公司（SELCO）以及Tubas电力分配公司（TEDCO）。这些电力公司加入了为耶路撒冷中心区域周边服务的历史悠久的电力公司- 耶路撒冷地区电力公司（JDECO）。加沙电力分配公司（DISCO）负责加沙的输电和配电。', '', 'MOSECO C Modern Scientific & Electronics Co.', 'MOSECO', '约旦', 'Mohammad Shubietah', '962 6 5548800', 'mohammad.shubietah@moseco.com.jo', 'MOSECO集团是一家领先的阿拉伯系统集成商，在IT电信市场拥有超过38年的经验。 MOSECO能够以全面且经济高效的方式独特地安装和支持电信基础设施解决方案及其互补的运营和业务支持解决方案。 Moseco集团总部位于约旦安曼，在沙特阿拉伯，卡塔尔，巴勒斯坦和伊拉克北部开展业务。 集团在阿拉伯地区雇用了超过600名专业人员，服务于阿拉伯地区的客户群。同时也是诺基亚在巴勒斯坦的分销商。');
INSERT INTO `crs_tabledata1530` VALUES ('362', '{F70EB29A-97D4-4894-BEA3-E12F6EECD730}', '61', 'INHE-0721', '2019-09-19 10:44:00', '0000-00-00 00:00:00', '2019-09-27 09:57:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091903/ECA', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'Electrificadora del Caribe S.A. E.S.P.', 'ECA', '哥伦比亚', 'Electrificadora del Caribe S.A. E.S.P.', '(035) 3500444', '', 'Electricaribe是一家哥伦比亚电力公司，成立于1998年，由该地区七个部门的7家现有公共电气化公司合并而成。共有270多万客户，约80多万用户，负责Atlántico ， Bolívar ， Sucre ， Córdoba ， Cesar ， Magdalena和La Guajira等省的电能分配和商业化。', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('363', '{73C22856-1188-42E8-B418-5232F7F79D62}', '61', 'INHE-0843', '2019-09-19 16:15:41', '0000-00-00 00:00:00', '2019-09-20 00:25:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091904/EXA			', '', 'ALEMINSA S.A.', 'ALEMINSA', '厄瓜多尔', 'Rodrigo Guayaquil', '+593985404827', 'rodrigog@aleminsa.com', 'ALEMINSA是厄瓜多尔一家致力于高、中、低压电气材料和电气设备销售的私营公司，拥有超过20年的行业经验，业务遍布整个厄瓜多尔领土。客户与厄瓜多尔国电CNEL、首都电力局EEQ有多个项目合作；曾负责过厄瓜多尔10万台AMI圆表项目。', '', 'Empresa Eléctrica Regional Centro Sur C.A.', 'CENTROSUR', '厄瓜多尔', '', '', '', '厄瓜多尔排名前五的电力公司，成立于1979年，主要负责厄瓜多尔中南部地区的电力供应。', '', 'ALEMINSA S.A.', 'ALEMINSA', '厄瓜多尔', 'Rodrigo Guayaquil', '+593985404827', 'rodrigog@aleminsa.com', 'ALEMINSA是厄瓜多尔一家致力于高、中、低压电气材料和电气设备销售的私营公司，拥有超过20年的行业经验，业务遍布整个厄瓜多尔领土。客户与厄瓜多尔国电CNEL、首都电力局EEQ有多个项目合作；曾负责过厄瓜多尔10万台AMI圆表项目。');
INSERT INTO `crs_tabledata1530` VALUES ('364', '{F9BBD417-606B-4E6B-A533-B751684F552E}', '61', 'INHE-0721', '2019-09-19 15:57:14', '0000-00-00 00:00:00', '2019-09-27 09:53:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019091905/ACN', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'Codensa S.A. ESP', 'Codensa', '哥伦比亚', '', '+57 7115115', '', 'CODENSA哥伦比亚电力公司，主管波哥大地区，被意大利电力公司ENEL收购，用户总数量约为350万，其中大用\r\n户为13000。', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('365', '{846C2DCD-4EFD-4116-95C4-A2666F9715F2}', '61', 'INHE-0843', '2019-10-05 05:24:15', '0000-00-00 00:00:00', '2019-11-08 10:03:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100501/MIC', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Protecsa Ingeniería S.A. de C.V.', 'Protecsa', '墨西哥', 'Ruben Sanchez Rojo', '52 442 313 1109', 'ruben@protecsa.lat', 'Protecsa在墨西哥的主营业务是为电力行业提供智能电表、计量设备、AMI方案、TPCyM方案和智能电网解决方案，拥有20年的行业经验，本地有大型工厂生产自主品牌产品。');
INSERT INTO `crs_tabledata1530` VALUES ('366', '{D63C7674-AFAD-4032-AE58-C9A58F02C4BE}', '60', 'INHE-0560', '2019-10-08 14:52:34', '0000-00-00 00:00:00', '2019-10-09 17:30:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100801/IFB', '', '', '', '', '', '', '', '', '', '', '', '蒙古国', 'Tuul Davaa', '+976-77008544', 'procurement@esp2.mn', '蒙古国能源部，系蒙古国政府机构，主要负责电力能源工程项目的统筹采购工作。', '', '“Mon-Energy Consult” Co., Ltd', 'Mon-energy', '蒙古', 'Roy royland', '976-11-323167', 'info@mon.energy.mn', '“ Mon-Energy Consult”有限公司成立于1994年，是一家咨询和工程公司，主要经营能源/电力，供热，能源效率，节能，电力，电力管理，市政，基础设施，已在咨询，工程，建筑设计，建筑工程，贸易，维修/大修以及电力设备采购和建筑业务方面实现多元化经营。已累计参与60多个项目，旨在改善蒙古主要城市， 小城市中心和农村地区的能源系统和电力管理。');
INSERT INTO `crs_tabledata1530` VALUES ('367', '{E9FA33C1-5949-430E-98DD-CED72F3C2F31}', '60', 'INHE-0560', '2019-10-15 16:01:26', '0000-00-00 00:00:00', '2019-10-15 16:01:26', 'unchecked', 'n', 'n', '', '1', 'lxdj2019100801/IFB（2个标）-新', '', '', '', '', '', '', '', '', '', '', '', '蒙古国', 'Tuul Davaa', '+976-77008544', 'procurement@esp2.mn', '蒙古国能源部，系蒙古国政府机构，主要负责电力能源工程项目的统筹采购工作。', '', '“Mon-Energy Consult” Co., Ltd', 'Mon-energy', '蒙古', 'Roy royland', '976-11-323167', 'info@mon.energy.mn', '“ Mon-Energy Consult”有限公司成立于1994年，是一家咨询和工程公司，主要经营能源/电力，供热，能源效率，节能，电力，电力管理，市政，基础设施，已在咨询，工程，建筑设计，建筑工程，贸易，维修/大修以及电力设备采购和建筑业务方面实现多元化经营。已累计参与60多个项目，旨在改善蒙古主要城市， 小城市中心和农村地区的能源系统和电力管理。');
INSERT INTO `crs_tabledata1530` VALUES ('368', '{100A4C12-4AEF-4BE1-BB42-FC481C2E5E5A}', '75', 'INHE-0432', '2019-10-15 17:25:53', '0000-00-00 00:00:00', '2019-10-21 09:47:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101501/KE04', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('369', '{EDD68CB5-CE2E-44AB-9062-0CF2C8C1EBAD}', '66', 'INHE-0634', '2019-10-16 08:54:52', '0000-00-00 00:00:00', '2019-10-21 09:45:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101601/HAS', '', '', '', '', '', '', '', '', '', 'Electricity Distribution and Supply Authority （EDSA）', 'EDSA', '塞拉利昂', '', '', '', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。', '', 'Electricity Distribution and Supply Authority （EDSA）', 'EDSA', '塞拉利昂', '', '', '', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。');
INSERT INTO `crs_tabledata1530` VALUES ('372', '{16BFE7B9-552F-4542-A254-9CE50602D1C2}', '61', 'INHE-0885', '2019-10-17 05:20:20', '0000-00-00 00:00:00', '2019-11-19 04:34:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019101701/BWU', '代理商不靠谱，屡次投标无下文。请提高立项命中率。', 'FACTORFAST METERING (PTY) LTD', '无', '博茨瓦纳', 'Chibana Carter Louis（General Manager）', '+267 3163114', 'louis@factorfast.co.bw', '主营电力设备相关业务,已经在BPC公布的项目上有过多次合作，该公司在电力公司有一定的客户关系。', '', 'Botswana Power Corporation', 'BPC', '博茨瓦纳', 'BPC', '+2673607000', 'contactcentre@bpc.bw', '博茨瓦纳电力公司', '', 'FACTORFAST METERING (PTY) LTD', '无', '博茨瓦纳', 'Chibana Carter Louis（General Manager）', '+267 3163114', 'louis@factorfast.co.bw', '主营电力设备相关业务,已经在BPC公布的项目上有过多次合作，该公司在电力公司有一定的客户关系。');
INSERT INTO `crs_tabledata1530` VALUES ('373', '{B34D2837-1628-4EAD-964F-07EB083BC14F}', '61', 'INHE-0772', '2019-10-22 10:38:10', '0000-00-00 00:00:00', '2019-10-23 17:09:14', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102201/SLA', '', 'INTERNATIONAL MINING LOGISTIC', 'IML', '塞拉利昂', 'Abu Bakarr Turay', '+232 (0)76 403 400', 'info@integratedmining.com', '22 Siaka Steven Street Freetown Sierra Leone', '', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', 'Monody Mansaray', '', 'momodumansaray2@gmail.com', '该市场的国有配电公司，拿到非发行的资金用于改善入户情况，现在对5万多预付费电表，表箱，PLC电线等零配件招标。', '', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', 'Monody Mansaray', '', 'momodumansaray2@gmail.com', '该市场的国有配电公司，拿到非发行的资金用于改善入户情况，现在对5万多预付费电表，表箱，PLC电线等零配件招标。');
INSERT INTO `crs_tabledata1530` VALUES ('374', '{1FD5C4EF-D415-4CB8-879F-97FA9F815C1B}', '61', 'INHE-0642', '2019-10-22 20:40:53', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', 'lxdj2019102202/SRS', '', 'RAYMAN PLC', 'RAYMAN', '埃塞俄比亚', 'Abdulwase Ibrahim', '+251 912612444', 'abdexo@gmail.com', '1） R 公司是一家有店铺的电气经销商，主要经营断路器，简单的 DIN 分表，目测产品全部是自 己品牌。此公司有两家门店，做批发和零售，也做投标和代理。该公司据说有一支 5 人 的技术团队；有一个 800 平的仓库（据说原先计划组装手机卖）。 2） 拜访的是 R 公司的老板 F 和业\r\n务经理 A。沟通来看，F 清楚本地的税费（关税=高达 100%， 增值税=15%，所得税=高达 35%）。从开车，吃饭和家庭成员数量来看，F 估计有钱：开车是 奔驰，谈吐淡定，思路清晰。业务经理 A 是电气专业， 沟通来看熟悉配电业务（对银河 BOX300，LPU，DTMS，DA 和变电站方案感觉很兴奋，直接 表示自己可以拿到标书草稿，可以运作银河技术点进标书；有朋友，有办法）。另外，很有 意思的 F 和 R 去过深圳创银，说某项目代理创银（有 2016 年去创银的照片），一切都弄好， 创银最后一刻不开保函放弃了；导致他们对创银印象不好。 3） F 和我方洽谈，对我方要求投资 25 万美元建厂设备，表现的比较淡定。只是提到，一旦拿 单供货，需要银河做些支持。 4） 对于我方安排的任务，R 公司算是比较快', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司', '', 'Ethiopian Electric Utility', 'EEU', '埃塞俄比亚', 'Elias Shibabaw', '+251 930412019', 'elias@bridgetechplc.comeliasshibabaw@gmail.com', '埃塞俄比亚国家电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('375', '{FDCECE6B-1C0E-4EC4-ADF5-C16E7BF23968}', '66', 'JXINHE-2559', '2019-10-23 08:58:48', '0000-00-00 00:00:00', '2019-10-23 17:02:10', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102301/PCN', '', 'CNS ENGINEERING', 'CNS', '巴基斯坦', 'Farukh Mehmood Keyani', '924232560257', 'farukh.mehmood@cns-e.com', '巴基斯坦当地的工程公司,承建土木,电力等项目', '', '', '', '', '', '', '', '', '', 'CNS ENGINEERING', 'CNS', '巴基斯坦', 'Farukh Mehmood Keyani', '924232560257', 'farukh.mehmood@cns-e.com', '巴基斯坦当地的工程公司,承建土木,电力等项目');
