INSERT INTO `crs_tabledata1530` VALUES ('377', '{9FC4E9F9-842A-44DB-BE3F-5DFC83208F3C}', '60', 'INHE-0680', '2019-10-24 00:50:08', '0000-00-00 00:00:00', '2019-10-28 17:32:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019102401/TAK', '', '塔吉克水电安装', '塔吉克水电', '塔吉克斯坦', 'Rakhimov', '(+992 37) 2381111, 2381313', 'info@tgem.tj', 'TAK项目是中亚地区较大的项目,总承包商是当地比较有实力的公司，总承包商情况介绍：\r\n在年轻的塔吉克斯坦的能源发展历史中，占据了举足轻重的地位，因为在当时的塔吉克装配部门水电蒙太奇的工程师和工人的帮助下竖立了大型项目，现在已成为塔吉克市场能源设施建设的领先公司。 公司技术和人员的潜力不仅可以在能源领域，而且可以在其他行业中实施任何复杂的项目。', '', '塔国家电力', '塔国家电力', '塔吉克斯坦', 'Habibov', '+992 372 295-578', '', '', '', '塔吉克水电安装', '塔吉克水电', '塔吉克斯坦', 'Rakhimov', '(+992 37) 2381111, 2381313', 'info@tgem.tj', 'TAK项目是中亚地区较大的项目,总承包商是当地比较有实力的公司，总承包商情况介绍：\r\n在年轻的塔吉克斯坦的能源发展历史中，占据了举足轻重的地位，因为在当时的塔吉克装配部门水电蒙太奇的工程师和工人的帮助下竖立了大型项目，现在已成为塔吉克市场能源设施建设的领先公司。 公司技术和人员的潜力不仅可以在能源领域，而且可以在其他行业中实施任何复杂的项目。');
INSERT INTO `crs_tabledata1530` VALUES ('378', '{7CCC22BE-6356-4E6C-B608-6D8E6B606C75}', '60', 'INHE-0781', '2019-11-04 03:47:03', '0000-00-00 00:00:00', '2019-11-07 10:37:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110401/DSO', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Electric Supply Company Limited', 'DESCO', '孟加拉国', 'Mohd. Raihan Habib', '0088 01713090611', 'raiham@desco.org.bd', '达卡两大电力公司之一，负责达卡北部几个区的供电，客户数约90万。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('379', '{CEBC4F43-4E59-4DE1-AD31-4DEAFBBFD15B}', '60', 'INHE-0868', '2019-11-06 09:40:07', '0000-00-00 00:00:00', '2019-11-12 11:05:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110601/LDC', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('380', '{BECC37D0-9514-4C56-9A8E-FF9471AF465E}', '60', 'INHE-0868', '2019-11-06 10:07:49', '0000-00-00 00:00:00', '2019-11-12 11:04:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2019110602/LCT', '', 'Rotax Pvt Ltd', 'Rotax', '斯里兰卡', 'Anne Christopher', '00940714893634', 'annec@rochegroup.lk', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。', '', 'ceylon electricity board', 'CEB', '斯里兰卡', '', '+94114204015', 'dgmpddd4@ceb.lk', '斯里兰卡国家电力公司成立于1969年，管理整个国家的发电，输电，配电业务。');
INSERT INTO `crs_tabledata1530` VALUES ('381', '{5886C6BD-D12C-4E84-9594-0DBC12A2B5B1}', '60', 'INHE-0781', '2019-11-11 03:22:07', '0000-00-00 00:00:00', '2019-11-18 15:33:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111101/PCT', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('382', '{E2F9BBDF-E1A1-4C34-96A8-93A863939AF2}', '60', 'INHE-0881', '2019-11-13 10:02:24', '0000-00-00 00:00:00', '2019-11-18 15:27:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111301/FDE', '三相表的PLN技术规格，客户目前还在翻译成英文，后续会补交。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Fuji Dharma Electric', 'FDE', '印尼', 'Hendrik Tasek', '+62 21 4600143', 'hendriktasek@fujidharma.co.id', 'FDE(Fuji Dharma Electric) 是印尼大型控股集团CCM (CENTRAL CIPTA MURDAYA ) 旗下一家子公司。该控股公司旗下共有五十多家子公司，涉及电力，石油，房地产，会展，鞋加工厂等等行业。该集团公司和印尼国家电力公司PLN关系十分密切，其子公司产品覆盖电力公司发电，运输电和配电。FDE是和日本公司Fuji Electric在1983年合资成立，成为印尼当地最早的电表厂之一，后来FDE收购了Fuji Electric在印尼的百分百股权。');
INSERT INTO `crs_tabledata1530` VALUES ('383', '{BC60B00F-A79B-431B-9368-0C678BE36509}', '61', 'INHE-0431', '2019-11-15 14:32:30', '0000-00-00 00:00:00', '2019-11-18 15:24:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111503/UNX', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '', 'Rural Electrification Agency', 'REA', '乌干达', 'Turyagyenda John Abouf', '+256 712807984', 'jturyagyenda@rea.or.ug', '乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目', '', 'Rural Electrification Agency', 'REA', '乌干达', 'Turyagyenda John Abouf', '+256 712807984', 'jturyagyenda@rea.or.ug', '乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目');
INSERT INTO `crs_tabledata1530` VALUES ('384', '{46EEBE3C-001F-400F-8D52-FA9A0E2244DD}', '61', 'INHE-0744', '2019-11-18 04:28:39', '0000-00-00 00:00:00', '2019-11-19 16:38:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111801/GNI', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司', '', 'ELECTRICITE DE GUINEE', 'EDG', '几内亚', 'Gérard TROUSSICOT', '(00224) 623 56 01 49', 'gérard.troussicot@epteg.com', '几内亚电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('385', '{264E4C0E-4AEB-4436-AD9A-0B14B7580CE3}', '60', 'INHE-0535', '2019-11-19 13:38:50', '0000-00-00 00:00:00', '2019-11-21 08:50:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019111902/GEE', 'GEE', 'Genus Innovation Limited', 'GENUS', '印度', 'Jitendra K. Agarwal', '+91 9829016456', 'jk@genus.in', 'Genus Innovation成立于1998年，主要设计，开发和制造各种环境友好型太阳能产品如太阳能逆变器，太阳能电池板，太阳能调节装置，电池等，还为在电源备份领域寻求制造专业知识的公司提供OEM服务。\r\n\r\n母公司Genus Power Infrastructure Limited是印度最大的电表制造公司，已经在印度安装了数百万台电表。', '', 'Energy Efficiency Services Limited', 'EESL', '印度', 'Ajay Kumar Sharma', '0120-4908000', 'asharma1@eesl.co.in', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：\r\n1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；\r\n2.	执行中央或邦政府或其代理机构的计划，项目和政策；\r\n3.	与私有ESCOs和其他公司合作促进能源效率；\r\n4.	在能源效率，CDM项目和其他有关领域提供咨询服务；\r\n5.	传授培训，培养股东能力。', '', 'Genus Innovation Limited', 'GENUS', '印度', 'Jitendra K. Agarwal', '+91 9829016456', 'jk@genus.in', 'Genus Innovation成立于1998年，主要设计，开发和制造各种环境友好型太阳能产品如太阳能逆变器，太阳能电池板，太阳能调节装置，电池等，还为在电源备份领域寻求制造专业知识的公司提供OEM服务。\r\n\r\n母公司Genus Power Infrastructure Limited是印度最大的电表制造公司，已经在印度安装了数百万台电表。');
INSERT INTO `crs_tabledata1530` VALUES ('386', '{1AC9A0E3-1A31-40B2-9C5D-6EC78920512C}', '61', 'INHE-0911', '2019-11-27 15:14:20', '0000-00-00 00:00:00', '2019-11-29 10:34:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112702/ZUP', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '', 'Uganda Electricity Distribution Company Limited', 'UEEDCL', '乌干达', 'The Head, PDU', '0312 330300', 'mwine@uedcl.co.ug', '乌干达国家配网公司。配网的主要业务外包给UMEME运营。但是UEDCL也部分采购小批量订单。', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验');
INSERT INTO `crs_tabledata1530` VALUES ('387', '{4C29E79E-7DD0-4D89-874B-28FC1A7C091A}', '61', 'INHE-0853', '2019-11-28 18:30:33', '0000-00-00 00:00:00', '2019-12-03 16:10:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112801/DGN', '请先做内部技术评审。如果可以采用已有方案，投标；否，放弃。', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'COMPAGNIE ENERGIE ELECTRIQUE DU TOGO', 'CEET', '多哥', 'Kwami', '228 22 21 2743/44', 'kwami.appeti@ceet.tg', '多哥国家电力公司', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('388', '{AC89DF86-C504-40D2-8E34-E9A41CDB55E0}', '66', 'INHE-0634', '2019-11-29 11:00:47', '0000-00-00 00:00:00', '2019-12-02 09:43:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112903/RLJ', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'MINISTERE, DE L’ECONOMIE, DES INVESTISSEMENTS ET DE L’ENERGIE', 'MEIE', '科摩罗', '', '', '', '电网老化严重，据测算，约7兆瓦电力在输电过程中的损耗率高达40%，为此，亟待对电网进行改造。目前，Majoyezi-ya-Mbude、 Sambamadi、Sada、Nkurani、Mlimani和Dzahani-ya-Washi 等6个地区尚未被电网覆盖。', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('389', '{18DD5E4C-06AE-4258-A34B-C2E96054D274}', '61', 'INHE-0440', '2019-11-29 11:28:50', '0000-00-00 00:00:00', '2019-12-03 09:14:22', 'unchecked', 'n', 'n', '', '1', 'lxdj2019112904/TTX', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。										\r\r\r\r\r\n', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。						\r\r\r', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，的实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，已建成绝缘子工厂，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								\r\r');
INSERT INTO `crs_tabledata1530` VALUES ('390', '{71112604-1D54-4208-B931-E1831F89E355}', '61', 'INHE-0819', '2019-12-03 10:28:19', '0000-00-00 00:00:00', '2019-12-05 09:54:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120302/NFB', '', '', '', '', '', '', '', '', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'FATIMA ZAHARA LAHSINIA', '+212662182507', 'C', '', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'FATIMA ZAHARA LAHSINIA', '+212662182507', 'LAHSINIA@ONEE.MA', '');
INSERT INTO `crs_tabledata1530` VALUES ('391', '{E9413A54-B6C9-4AE1-B726-06FCF7FC4C3C}', '61', 'INHE-0853', '2019-12-04 15:32:15', '0000-00-00 00:00:00', '2019-12-09 09:45:46', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120401/CMN', '', '', '', '', '', '', '', '', '', 'The energy of cameroon', 'ENEO', '喀麦隆', 'Jean Mathieu Tchuisseu', '+237 690020147', 'jmathieu.tchuisseu@eneo.cm', 'Eneo由英联集团（Actis）持有51％的股份，Eneo员工则为5％，喀麦隆国家控股44％。它的活动受喀麦隆政府与英联社之间签署的特许协议的约束。', '', 'The energy of cameroon', 'ENEO', '喀麦隆', 'Jean Mathieu Tchuisseu', '+237 690020147', 'jmathieu.tchuisseu@eneo.cm', 'Eneo由英联集团（Actis）持有51％的股份，Eneo员工则为5％，喀麦隆国家控股44％。它的活动受喀麦隆政府与英联社之间签署的特许协议的约束。');
INSERT INTO `crs_tabledata1530` VALUES ('392', '{466D7079-611A-4206-A1BA-395732AF42AA}', '61', 'INHE-0654', '2019-12-05 11:35:51', '0000-00-00 00:00:00', '2019-12-09 09:53:59', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120503/EPE', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '', 'EPEC Córdoba', 'EPEC', '阿根廷', '客服电话', '0800 777 0000', '', 'EPEC是阿根廷科尔多万地区的电力公司，总用户数量约为100万。EPEC诞生于1953年，由两个公共机构合并而成，提供和管理电力服务：电力总局和科尔多瓦公共电力服务局（SPEC）。', '', 'Cashpower Sudamericana S.A.', 'CSA', '阿根廷', 'Mr.Ricardo Brugger', '', 'ricardo.brugger@cashpower.com.ar', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。');
INSERT INTO `crs_tabledata1530` VALUES ('393', '{5E662FBA-43AA-4734-882A-C018B152229C}', '61', 'INHE-0772', '2019-12-05 15:32:24', '0000-00-00 00:00:00', '2019-12-09 09:51:03', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120504/MLD', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作，目前在寻找新的合作伙伴。', '', 'Energie du Mali –SA', 'EDM-SA', '马里', '', '223 20 23 30 60', '', '马里能源公司是一家工商业性质股份有限公司。于1960年10月14日由马里政府创办。\r\n创立初期马里能源公司涉及两个业务领域，第一是生产和配送可饮用水，第二部分是在马里共和国全境内发电生产、输电、供电。\r\n2011年1月1日生产和配送可应用水功能分离，从此马里能源公司仅负责电力部门的管理。马里政府持有马里能源公司66%股份，剩下的34%由IPS WA持有，马里能源公司服务402 000个客户，其中2000个高压用户，另外400 000个低压客户分布于全国各地。', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作，目前在寻找新的合作伙伴。');
INSERT INTO `crs_tabledata1530` VALUES ('394', '{E3F7BBF2-8934-435C-8D15-DDBF69502179}', '60', 'INHE-0881', '2019-12-09 15:58:36', '0000-00-00 00:00:00', '2019-12-12 14:53:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120901/GMS', '', 'Golden Man Saq Solidos Holdings Limited', 'GM', '哈萨克斯坦', 'Amantaiuly Araibek', '+7 7023043888', 'amantailya@gmail.com', '代理GM公司是根据哈萨克斯坦共和国法律成立的商业组织形式的法人企业，公司的主营业务包括信托，基金和其他金融投资业务。代理之前是在中信资本担任投资部门总经理助理和顾问，帮助中信资本投资和收购哈萨克斯坦的油田以及矿业，由此跟哈萨克斯坦现任能源部长建立了非常好的私人关系。2015年，武汉凯迪电力股份有限公司也是通过代理负责洽谈跟哈萨克斯坦国家电网KEGOC发电项目合作，由此跟KEGOC第一副总建立良好的私人关系。', '{E3F7BBF28934435C8D15DDBF6950217911015FBC745F4B1982FBEF12F4BBACD1}_GM公司执照.pdf', '', '', '', '', '', '', '', '', 'Golden Man Saq Solidos Holdings Limited', 'GM', '哈萨克斯坦', 'Amantaiuly Araibek', '+7 7023043888', 'amantailya@gmail.com', '代理GM公司是根据哈萨克斯坦共和国法律成立的商业组织形式的法人企业，公司的主营业务包括信托，基金和其他金融投资业务。此外，代理还有涉及到基建，油田和矿业等相关业务，在哈萨克斯坦和中亚地区拥有丰富的人脉资源。');
INSERT INTO `crs_tabledata1530` VALUES ('395', '{F0BF5F8A-21C1-47C3-AC35-AFD4600D9C7A}', '61', 'INHE-0432', '2019-12-12 18:02:53', '0000-00-00 00:00:00', '2019-12-16 16:26:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121206/KCB', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'Mary Mbacha', '00 254 20 320 1336 ext 10900254 721 697472', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('396', '{4D69574E-A644-40B3-A049-01B378ECBFDD}', '61', 'INHE-0381', '2019-12-16 15:05:38', '0000-00-00 00:00:00', '2019-12-18 11:34:07', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121604/CNV', '', 'Voltalia', 'Voltalia', '法国', 'Vincent Tinot', 'M.+33 (0)7 60 53 11 86', 'v.tinot@voltalia.com', '成立于2005年的Voltalia是一家利用太阳能，风能，水能和生物质能（结合存储解决方案）生产可再生电力的电力生产商和服务提供商。作为一家综合性公司，Voltalia在整个可再生项目的价值链中拥有丰富的专业知识：项目开发，项目融资，EPC以及运营与维护。该集团活跃在20个国家/地区，能够为全球客户提供服务。', '', '', '', '', '', '', '', '', '', 'Voltalia', 'Voltalia', '法国', 'Vincent Tinot', 'M.+33 (0)7 60 53 11 86', 'v.tinot@voltalia.com', '成立于2005年的Voltalia是一家利用太阳能，风能，水能和生物质能（结合存储解决方案）生产可再生电力的电力生产商和服务提供商。作为一家综合性公司，Voltalia在整个可再生项目的价值链中拥有丰富的专业知识：项目开发，项目融资，EPC以及运营与维护。该集团活跃在20个国家/地区，能够为全球客户提供服务。');
INSERT INTO `crs_tabledata1530` VALUES ('397', '{B7D8553A-59C6-4D32-A407-B6E85967A375}', '61', 'INHE-0911', '2019-12-17 09:02:16', '0000-00-00 00:00:00', '2019-12-18 18:05:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2019121701/URB', '', 'Powerline Solutions&Investments Ltd.', 'PSI', '乌干达', 'Noel', '+256772348390', 'noel.rutebemberwa@gmail.com', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '', 'Rural Electrification Agency', 'REA', '乌干达', 'Turyagyenda John Abouf', '+256 712807984', 'jturyagyenda@rea.or.ug', '乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目', '', 'Rural Electrification Agency', 'REA', '乌干达', 'Turyagyenda John Abouf', '+256 712807984', 'jturyagyenda@rea.or.ug', '乌干达农电是乌干达除了UMEME之外的另一家配电公司，主要负责农村电力电气化的相关项目');
INSERT INTO `crs_tabledata1530` VALUES ('398', '{BBDD3E20-ECA5-4E60-95CC-BE9BC9DC315C}', '61', 'INHE-0853', '2019-12-20 09:00:31', '0000-00-00 00:00:00', '2020-01-06 10:38:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2019122001/EDN', '', 'REDONDO Y GARCIA, S.A.', '', '西班牙', 'Lola Lopera Molina', '+34-91 691 82 20', 'export@redondoygarcia.com', '雷东多·加西亚集团（Redondo yGarcíaGroup）是一家成立于1944年的西班牙公司，工业供应领域的领导者，致力于满足工业，建筑业和公共部门专业人士的特定需求，并提供最广泛的国内外品牌。代理的产品涵盖与公司和政府机构工业供应相关的所有领域。', '', 'Electricity Development Corporation', 'EDC', '喀麦隆', 'Mezzanine', '+237 222 23 19 30', 'info@edc.cm', '喀麦隆电力发展公司（EDC），成立于2006年，由喀麦隆政府所有，主要负责喀麦隆电站的规划和建设，实施电力基础建设项目。', '', 'REDONDO Y GARCIA, S.A.', '', '西班牙', 'Lola Lopera Molina', '+34-91 691 82 20', 'export@redondoygarcia.com', '雷东多·加西亚集团（Redondo yGarcíaGroup）是一家成立于1944年的西班牙公司，工业供应领域的领导者，致力于满足工业，建筑业和公共部门专业人士的特定需求，并提供最广泛的国内外品牌。代理的产品涵盖与公司和政府机构工业供应相关的所有领域。');
INSERT INTO `crs_tabledata1530` VALUES ('399', '{C505F6DF-2895-47AC-9E0A-C4CED087A7A6}', '66', 'INHE-0634', '2019-12-29 04:18:07', '0000-00-00 00:00:00', '2020-01-06 12:37:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2019122901/TLR', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'JIRAMA', 'JIRAMA', '马达加斯加', '', '', '', '马达本地水电部', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('400', '{D729EB72-67F2-4BE7-9C9D-34F5755BAA38}', '60', 'INHE-0868', '2019-12-30 17:47:43', '0000-00-00 00:00:00', '2020-01-07 14:12:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2019123001/AFH', '', 'CANUCK LOGISTICS & SUPPLY SERVICES CO', 'CANUCK', '阿富汗', 'Michael Edie', '', 'michael.edie@gmail.com', 'Canuck Logistics & Supply Services Co 位于喀布尔，电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。', '', 'Da Afghanistan Breshna Sherkat', 'DABS', '阿富汗', 'Habibullah bakhtyal', '0795219045', 'info@dabs.af    habib.bakhtyal@dabs.af', 'DABS是一家由阿富汗政府（GoA）拥有所有股权的有限责任公司。 该公司成立于2008年5月4日（Saur 1387年5月15日），并取代了达富·布雷希纳·穆阿萨萨（DABM）作为国家电力公司。 DABS将在整个商业范围内运营和管理整个阿富汗的发电，进口，输电和配电。', '', 'CANUCK LOGISTICS & SUPPLY SERVICES CO', 'CANUCK', '阿富汗', 'Michael Edie', '', 'michael.edie@gmail.com', 'Canuck Logistics & Supply Services Co 位于喀布尔，电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。');
INSERT INTO `crs_tabledata1530` VALUES ('401', '{E371EE88-2751-4CB8-96F5-CFAC9C4876F9}', '60', 'INHE-0434', '2020-01-04 10:59:01', '0000-00-00 00:00:00', '2020-01-07 13:52:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010401/TND', '', 'DELTAPRIMA METERING SDN BHD', 'DPM', '马来西亚', 'Malek Salleh', '+6017-3796358', 'malek.salleh@deltaprima.com.my', '该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持,对国内深开发、思达、科陆', '{E371EE8827514CB896F5CFAC9C4876F911015FBC745F4B1982FBEF12F4BBACD1}_Sijil Pra-kelayakan DPM.pdf', 'Tenaga Nasional Berhad', 'TNB', '马来西亚', 'Datin Saraswathy A/p Sinniah', 'Tel : +603 2296 5566', 'saraswathys@tnb.com.my', '马来西亚 TNB电力公司（TenagaNasional Berhad），负责马来西亚半岛的发电、输电和配电工作。TNB电力公司建于1990年9月，其前身为1949年建立的中央电力局（CEB），后更名为国家电力局（NEB）。TNB实行股份制，股东有国内的也有国际的，但马来西亚政府通过财政部继续保持着过半数的股份。1992年，TNB的股票在吉隆坡股票交易所上市。1996年1月，TNB百年债券成功发行。\r\nTNB积极推行发电燃料多样化的政策，采用天然气、煤、石油和水电4种燃料发电，以减少对石油的依赖。利用本上天然气发展高效能的燃气发电厂是TNB的长远计划。\r\nTNB在马来西亚半岛上架设的输电系统，主要电压等级是275kV、132kV和66kV。整个电网由位于吉隆坡的国家负荷调度中心和若干不同的区域控制中心所控制。TNB的电力系统还与新加坡、泰国的电网相连以交换电力。目前 TNB正着手建设一条500kV输电线路，它将成大国家电网的骨干线路。\r\nTNB的配电系统电压等级一般为33kV或更低。对需要较高电压的用户，则由变电站直接向用户供电。马来西亚的电力供应正向独立电力生产者（IPP）方向过渡。马', '', 'DELTAPRIMA METERING SDN BHD', 'DPM', '马来西亚', 'Malek Salleh', '+6017-3796358', 'malek.salleh@deltaprima.com.my', '该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持,对国内深开发、思达、科陆');
INSERT INTO `crs_tabledata1530` VALUES ('402', '{6C23C641-2294-4C9F-BC3E-F75085D8D954}', '60', 'INHE-0781', '2020-01-04 17:15:05', '0000-00-00 00:00:00', '2020-01-07 13:56:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010501/BPA', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Bangladesh Power Development Board', 'BPDB', '孟加拉国', 'Director', '+88029550532', '', '用户数约350万，后分离出NESCO(约110万用户)用户数为240万。受电力部直属管辖。WZPDCL, NESCO都是从BPDB分离出去的电力公司。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('403', '{B6C5A585-02C4-4419-9106-69230D6EAF5C}', '60', 'INHE-0781', '2020-01-09 04:22:19', '0000-00-00 00:00:00', '2020-01-13 10:05:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010901/WZP', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'West Zone Power Distributin Company Limited', 'WZPDCL', '孟加拉国', 'Md.Rakibul Islam', '008801721197674', 'rakibislam04@gmail.com', '孟加拉西部电力公司，用户数100万，负责孟加拉西部地区的供电。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('404', '{762E7EB9-43E6-4661-8BC9-3706232CFF5F}', '60', 'INHE-0781', '2020-01-09 13:23:03', '0000-00-00 00:00:00', '2020-01-13 10:00:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020010902/WEP', '', 'Western Engineers（Pvt）Ltd.', 'Western', '孟加拉国', 'Tarun Biswas', '8801705416064', 'info@www.westernengineeringbd.com', '公司与军方企业Disel Plan关系良好，专业做DPM项目出身，所做的项目包括发动机，水泵等等。与科陆合作了多个DPM项目，现在准备跟我们合作DPDC的直采项目。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。', '', 'Western Engineers（Pvt）Ltd.', 'Western', '孟加拉国', 'Tarun Biswas', '8801705416064', 'info@www.westernengineeringbd.com', '公司与军方企业Disel Plan关系良好，专业做DPM项目出身，所做的项目包括发动机，水泵等等。与科陆合作了多个DPM项目，现在准备跟我们合作DPDC的直采项目。');
INSERT INTO `crs_tabledata1530` VALUES ('405', '{ED2235BA-96BF-49B0-BE2B-EB63EC5CE0C8}', '61', 'INHE-0772', '2020-01-10 16:10:04', '0000-00-00 00:00:00', '2020-01-13 14:54:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011001/MLH', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。', '', 'La Société Nationale dElectricité du Burkina', 'SONABEL', '布基纳法索', 'Zongo Souleymane', '00 226 70202631', 'zongosouleymane@ymail.com', '布基纳法索国家电力公司，100%国有企业，注册资本为63 308 270 000西法（约6亿人民币）。');
INSERT INTO `crs_tabledata1530` VALUES ('406', '{8336808C-B42A-4214-9D46-BFCB1D42C768}', '61', 'INHE-0885', '2020-01-17 18:45:33', '0000-00-00 00:00:00', '2020-01-18 14:01:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011701/BST', '1.请核实代理实力和客情；2.请整理不服，说明应对策略；3.请延标。而后，再决定是否竞投。市场需要调研，提前开发，不能守株待兔。							', 'Business Systems Experts Proprietary Limited', '', '博茨瓦纳', 'BONIFACE MOKGANEDI MODISE', '+267 71262377', 'boniface@bsexperts.org', '2020年1月接到询盘邮件，对于BPC招标比较感兴趣。', '{8336808CB42A42149D46BFCB1D42C76811015FBC745F4B1982FBEF12F4BBACD1}_PROFILE?BSE.pdf', 'Botswana Power Corporation', 'BPC', '博茨瓦纳', 'BPC', '+2673607000', 'contactcentre@bpc.bw', '博茨瓦纳电力公司', '', 'Business Systems Experts Proprietary Limited', '', '博茨瓦纳', 'BONIFACE MOKGANEDI MODISE', '+267 71262377', 'boniface@bsexperts.org', '2020年1月接到询盘邮件，对于BPC招标比较感兴趣。');
INSERT INTO `crs_tabledata1530` VALUES ('408', '{4DC50CFC-BD30-4EBD-A859-9022CFDC42F8}', '17', 'INHE-0450', '2020-01-18 18:22:31', '0000-00-00 00:00:00', '2020-01-18 18:22:31', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011803/t1132', '', '荷花', '', '阿尔及利亚', 'tina', '', '', '', '', 'test111', 'test', '百慕大', '6', '6', '6', 'test\r\ntest1213\r\nqweqwetestr', '', '客户名称', '简称', '百慕大', '姓名', '电话1', '邮箱', '客户概述');
INSERT INTO `crs_tabledata1530` VALUES ('409', '{F6F24FF6-E19B-44D7-A2B0-F4A5275D9F26}', '61', 'INHE-0440', '2020-01-18 18:25:40', '0000-00-00 00:00:00', '2020-02-13 10:24:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2020011804/TTJ', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '客户在坦桑尼亚是一个非常大的企业，涵盖房地产，进出口贸易，交通运输，电力等行业。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），预算金额约为2000万美元（DDP）价格条款。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。');
INSERT INTO `crs_tabledata1530` VALUES ('410', '{F7C7C124-1229-4CA2-A851-F39497CF7E35}', '61', 'INHE-0500', '2020-02-05 16:25:19', '0000-00-00 00:00:00', '2020-02-13 10:27:35', 'unchecked', 'n', 'n', '', '1', 'lxdj2020020501/ZIT', '', 'TelOne (Private) Limited', 'TelOne', '津巴布韦', 'Maidei Mugodo', '263 – 242 – 2795499', 'Emails: Cladios.chenga@telone.co.zw Lesail.karimbika@telone.co.zw#FE54` munyaradzi.shoko@telone.co.zw#FE54` cladios.chenga@telone.co.zw', '1.津巴布韦半国有企业，为津巴布韦第二大通讯运行商，主营业务涉及通讯基础建设、运营和服务以及相关通讯产品的供应。旗下2017年新成立一个制造工厂子公司，当前主要进行PC、个人电脑和相关ICT设备的本地SKD组装，其有意向增加电能表的SKD组装线，并于2019年10月到访了银河总部考察和关于新工厂建设的交流；\r\n2.其于2020年2月3日发布关于寻求厂商合作建设本地电能表组装厂的限制性招标，2月27日截标，待安排投标。', '', 'TelOne (Private) Limited', 'TelOne', '津巴布韦', 'Maidei Mugodo', '263 – 242 – 2795499', 'Emails: Cladios.chenga@telone.co.zw Lesail.karimbika@telone.co.zw#FE54` munyaradzi.shoko@telone.co.zw#FE54` cladios.chenga@telone.co.zw', '1.津巴布韦半国有企业，为津巴布韦第二大通讯运行商，主营业务涉及通讯基础建设、运营和服务以及相关通讯产品的供应。旗下2017年新成立一个制造工厂子公司，当前主要进行PC、个人电脑和相关ICT设备的本地SKD组装，其有意向增加电能表的SKD组装线，并于2019年10月到访了银河总部考察和关于新工厂建设的交流；\r\n2.其于2020年2月3日发布关于寻求厂商合作建设本地电能表组装厂的限制性招标，2月27日截标，待安排投标。', '', 'TelOne (Private) Limited', 'TelOne', '津巴布韦', 'Maidei Mugodo', '263 – 242 – 2795499', 'Emails: Cladios.chenga@telone.co.zw Lesail.karimbika@telone.co.zw#FE54` munyaradzi.shoko@telone.co.zw#FE54` cladios.chenga@telone.co.zw', '1.津巴布韦半国有企业，为津巴布韦第二大通讯运行商，主营业务涉及通讯基础建设、运营和服务以及相关通讯产品的供应。旗下2017年新成立一个制造工厂子公司，当前主要进行PC、个人电脑和相关ICT设备的本地SKD组装，其有意向增加电能表的SKD组装线，并于2019年10月到访了银河总部考察和关于新工厂建设的交流；\r\n2.其于2020年2月3日发布关于寻求厂商合作建设本地电能表组装厂的限制性招标，2月27日截标，待安排投标。');
