INSERT INTO `crs_tabledata1530` VALUES ('416', '{01389694-46CD-4F22-9E8D-0A296C1EF236}', '61', 'INHE-0913', '2020-02-25 09:47:34', '0000-00-00 00:00:00', '2020-02-26 18:45:53', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022502/MEB', '', 'SETH', '', '莫桑比克', 'Gisela Manhi', '', 'gisela.manhica@seth.pt', '\"SETH\"是莫桑比克能源市场上的主要承包商之一，承包过多个知名项目（HV OHL，MV OHL和Underground，SS等），金额总计约2亿欧元，在过去的12年中成功交付超过10万台各种品牌的电表。目前SETH总部位于葡萄牙，同时在非洲的莫桑比克和安哥拉设立有分部。', '', 'Electricidade de Mocambique, E.P', 'EDM', '莫桑比克', 'Benjamim', '+258-823029777', 'benjamim.fernandes@edm.co.mz', '目前全国电网主要由两家公司运行，分别是EDM和HCB。其中EDM主要负责莫桑国内电力的购买、输送和配售。HCB主要负责其Cahora Bassa水电站向南非和津巴等输送电力。莫桑最大的电源点是HCB拥有的Cahora Bassa水电站，其余电站除少量EDM开发拥有的小型水电、燃气电站和燃油电站外，均为私人投资商开发。', '', 'SETH', '', '莫桑比克', 'Gisela Manhi', '', 'gisela.manhica@seth.pt', '\"SETH\"是莫桑比克能源市场上的主要承包商之一，承包过多个知名项目（HV OHL，MV OHL和Underground，SS等），金额总计约2亿欧元，在过去的12年中成功交付超过10万台各种品牌的电表。目前SETH总部位于葡萄牙，同时在非洲的莫桑比克和安哥拉设立有分部。');
INSERT INTO `crs_tabledata1530` VALUES ('417', '{B8A19CD3-060E-45B7-8348-7004D3CA6294}', '93', 'INHE-0811', '2020-02-25 13:30:14', '0000-00-00 00:00:00', '2020-02-26 09:55:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022503/BGC', '市场总监选杨爱军（杨总）', 'AFRICA WAY SHIPPING LIMITED', 'A.W.S\r\n', '肯尼亚', 'Berty GATOTOZI\r\n\r\n', '+257 22278709\r\n', 'africaway01@gmail.com\r\n', 'A.W.S是一家从事贸易和航运的企业，他们的业务主要分布在东非地区，如布隆迪、肯尼亚等。						\r\n				\r\n\r\n', '', 'REGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE', '', '布隆迪', 'Emmanuel Barinzigo', '+257 62201146', 'emmanuel_barinzigo@yahoo.com', '布隆迪国家水电局成立于1962年，主要负责布隆迪国家水利和电力的发展与建设。REGIDESO was created in 1962 after the independence of Burundi to take charge of the supply of drinking water and electricity.						\r\nREGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE', '', 'REGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE', 'REGIDESO\r\n', '布隆迪\r\n', 'Emmanuel Barinzigo\r\n', '+257 62201146\r\n', 'emmanuel_barinzigo@yahoo.com\r\n', '布隆迪国家水电局成立于1962年，主要负责布隆迪国家水利和电力的发展与建设。REGIDESO was created in 1962 after the independence of Burundi to take charge of the supply of drinking water and electricity.						\r\nREGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE\r\n						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('418', '{D5D4C588-9C56-429E-9896-5E27F416742D}', '61', 'INHE-0885', '2020-02-25 13:43:01', '0000-00-00 00:00:00', '2020-05-28 11:05:18', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022504/SRI', '', 'RAYMAN PLC', 'RAYMAN', '埃塞俄比亚', 'Abdulwase Ibrahim', '+251 912612444', 'abdexo@gmail.com', '1） R 公司是一家有店铺的电气经销商，主要经营断路器，简单的 DIN 分表，目测产品全部是自 己品牌。此公司有两家门店，做批发和零售，也做投标和代理。该公司据说有一支 5 人 的技术团队；有一个 800 平的仓库（据说原先计划组装手机卖）。 2） 拜访的是 R 公司的老板 F 和业\r\n务经理 A。沟通来看，F 清楚本地的税费（关税=高达 100%， 增值税=15%，所得税=高达 35%）。从开车，吃饭和家庭成员数量来看，F 估计有钱：开车是 奔驰，谈吐淡定，思路清晰。业务经理 A 是电气专业， 沟通来看熟悉配电业务（对银河 BOX300，LPU，DTMS，DA 和变电站方案感觉很兴奋，直接 表示自己可以拿到标书草稿，可以运作银河技术点进标书；有朋友，有办法）。另外，很有 意思的 F 和 R 去过深圳创银，说某项目代理创银（有 2016 年去创银的照片），一切都弄好， 创银最后一刻不开保函放弃了；导致他们对创银印象不好。 3） F 和我方洽谈，对我方要求投资 25 万美元建厂设备，表现的比较淡定。只是提到，一旦拿 单供货，需要银河做些支持。 4） 对于我方安排的任务，R 公司算是比较快', '', 'Ethiopian Electric Utility – Universal Electricity Access Program', 'UEAP', '埃塞俄比亚', 'Frealem Kure', '00251-11-1263155', 'kurefrealem@gmail.com', 'UEAP是专门为EEU、EEP对接金融机构，执行大型项目的项目部，有独立办公室。', '', 'Ethiopian Electric Utility – Universal Electricity Access Program', 'UEAP', '埃塞俄比亚', 'Frealem Kure', '00251-11-1263155', 'kurefrealem@gmail.com', 'UEAP是专门为EEU、EEP对接金融机构，执行大型项目的项目部，有独立办公室。');
INSERT INTO `crs_tabledata1530` VALUES ('419', '{0685ACA4-215D-4522-941A-A4EEB15720EF}', '66', 'INHE-0634', '2020-02-25 16:26:56', '0000-00-00 00:00:00', '2020-02-26 13:30:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022505/WLM', '', 'Canopy Power Pte Ltd', 'Canopy Power', '新加坡', 'William PYAE', '+65 81657147', '', '2016年成立于新加坡，主要做微电网项目和提供技术咨询顾问等服务。', '', '', '', '', '', '', '', '', '', 'Earth Renewable Co Ltd', 'EREC', '缅甸', '', '', '', '缅甸EPC工程公司，自2002年以来，一直进口日本 Kyocera太阳能电池板，在东南亚国家提供太阳能发电厂，离网太阳能，并网并网太阳能发电厂的新服务（系统设计，现场勘测，安装和调试，售后服务，维护等）。');
INSERT INTO `crs_tabledata1530` VALUES ('420', '{EB002D6C-0E7F-4551-BF7A-362BB399FA37}', '60', 'INHE-0781', '2020-02-26 08:58:18', '0000-00-00 00:00:00', '2020-02-26 20:06:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022601/PDT', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Dhaka Power Distribution Company Limited', 'DPDC', '孟加拉国', 'Engr. Md. Maibubur Rahman', '880-2-9567258', 'secp@dpdc.org.bd', '负责达卡南部片区供电，用户数约100万，计划采购85万台智能表。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('421', '{2F4F36EB-5783-469D-AEA1-8E316A2ECE77}', '93', 'INHEGRID-0013', '2020-02-26 10:17:12', '0000-00-00 00:00:00', '2020-02-27 15:51:23', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022602/RCI', '配电补流程项目', '', '', '', '', '', '', '', '', 'Energy Utility Corporation Limited', 'EUCL', '卢旺达', 'Aimee M.UWANYILIGIRA', 'TEL:(+250)788 303 858', 'Email:auwanyiligira@eucl.reg.rw', 'KN82 ST3\r\nNyarugenge District\r\nKigali City\r\nP.O. Box 537 Kigali, Rwanda\r\nTel: +(250) (0) 78 818 1224\r\nEmail: info@reg.rw\r\nWebsite: www.reg.rw', '', 'Energy Utility Corporation Limited', 'EUCL', '卢旺达', 'Aimee M.UWANYILIGIRA', 'TEL:(+250)788 303 858', 'Email:auwanyiligira@eucl.reg.rw', 'KN82 ST3\r\nNyarugenge District\r\nKigali City\r\nP.O. Box 537 Kigali, Rwanda\r\nTel: +(250) (0) 78 818 1224\r\nEmail: info@reg.rw\r\nWebsite: www.reg.rw');
INSERT INTO `crs_tabledata1530` VALUES ('422', '{85B88EBE-0D79-41C4-AD15-24D3FE478A05}', '61', 'INHE-0913', '2020-02-26 20:45:31', '0000-00-00 00:00:00', '2020-02-28 16:56:06', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022603/MEC', '', 'SETH', '', '莫桑比克', 'Gisela Manhi', '', 'gisela.manhica@seth.pt', '\"SETH\"是莫桑比克能源市场上的主要承包商之一，承包过多个知名项目（HV OHL，MV OHL和Underground，SS等），金额总计约2亿欧元，在过去的12年中成功交付超过10万台各种品牌的电表。目前SETH总部位于葡萄牙，同时在非洲的莫桑比克和安哥拉设立有分部。', '', 'Electricidade de Mocambique, E.P', 'EDM', '莫桑比克', 'Benjamim', '+258-823029777', 'benjamim.fernandes@edm.co.mz', '目前全国电网主要由两家公司运行，分别是EDM和HCB。其中EDM主要负责莫桑国内电力的购买、输送和配售。HCB主要负责其Cahora Bassa水电站向南非和津巴等输送电力。莫桑最大的电源点是HCB拥有的Cahora Bassa水电站，其余电站除少量EDM开发拥有的小型水电、燃气电站和燃油电站外，均为私人投资商开发。', '', 'SETH', '', '莫桑比克', 'Gisela Manhi', '', 'gisela.manhica@seth.pt', '\"SETH\"是莫桑比克能源市场上的主要承包商之一，承包过多个知名项目（HV OHL，MV OHL和Underground，SS等），金额总计约2亿欧元，在过去的12年中成功交付超过10万台各种品牌的电表。目前SETH总部位于葡萄牙，同时在非洲的莫桑比克和安哥拉设立有分部。');
INSERT INTO `crs_tabledata1530` VALUES ('423', '{A33A2FE2-8217-4B95-AD3D-C7A6D67EF49C}', '61', 'INHE-0744', '2020-02-27 06:02:10', '0000-00-00 00:00:00', '2020-02-27 16:54:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022701/NGA', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。');
INSERT INTO `crs_tabledata1530` VALUES ('424', '{2F083742-0C6A-4CC7-9A79-9B5CBD74EBB9}', '61', 'INHE-0772', '2020-02-27 10:42:53', '0000-00-00 00:00:00', '2020-02-28 16:50:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2020022702/MLL', '', 'KAMA.SA', '', '马里', 'Neneman CAMARA', '00 223 66 75 59 22', 'ncamara@kama-sa.com', '是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。', '', 'AGENCE MALIENNE POUR LE DEVELOPPEMENT DE L ELECTRIFICATION RURALE  ET DE L ENERGIE DOMESTIQUE', 'AMA', '马里', 'Mamadou OUATTARA', '+223 20 23 85 67', 'amader@amadermali.net', '马里的农网主管部门，负责马里的农村地区的电力化项目：发电，输电，配电，入户等。', '', 'KAMA.SA', '', '马里', 'Neneman CAMARA', '00 223 66 75 59 22', 'ncamara@kama-sa.com', '是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。');
INSERT INTO `crs_tabledata1530` VALUES ('425', '{BB2BC077-D334-40F2-84F7-2A821FF21EDA}', '60', 'INHE-0781', '2020-03-03 16:27:52', '0000-00-00 00:00:00', '2020-03-16 09:54:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030301/BPE', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '', 'Bangladesh Power Development Board', 'BPDB', '孟加拉国', 'Director', '+88029550532', '', '用户数约350万，后分离出NESCO(约110万用户)用户数为240万。受电力部直属管辖。WZPDCL, NESCO都是从BPDB分离出去的电力公司。', '', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '孟加拉国', 'A.K.Sarker', '+88 02 9551938', 'sarkerak@gmail.com', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。');
INSERT INTO `crs_tabledata1530` VALUES ('426', '{41A71C34-11F0-4D6B-98B3-AB7EFA58CBA0}', '61', 'INHE-0772', '2020-03-04 08:42:46', '0000-00-00 00:00:00', '2020-04-09 10:58:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030401/MFF', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作，目前在寻找新的合作伙伴。', '', 'Energie du Mali –SA', 'EDM-SA', '马里', '', '223 20 23 30 60', '', '马里能源公司是一家工商业性质股份有限公司。于1960年10月14日由马里政府创办。\r\n创立初期马里能源公司涉及两个业务领域，第一是生产和配送可饮用水，第二部分是在马里共和国全境内发电生产、输电、供电。\r\n2011年1月1日生产和配送可应用水功能分离，从此马里能源公司仅负责电力部门的管理。马里政府持有马里能源公司66%股份，剩下的34%由IPS WA持有，马里能源公司服务402 000个客户，其中2000个高压用户，另外400 000个低压客户分布于全国各地。', '', 'Amadou Baiba KOUMA', 'Amadou', '马里', 'Bouare', '(00223) 20 23 04 41', 'ousmanebouare@yahoo.fr', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作，目前在寻找新的合作伙伴。');
INSERT INTO `crs_tabledata1530` VALUES ('427', '{48073C3C-0655-4879-BF07-76202B9FAC66}', '61', 'INHE-0744', '2020-03-05 01:55:59', '0000-00-00 00:00:00', '2020-03-09 09:11:27', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030501/NGB', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。');
INSERT INTO `crs_tabledata1530` VALUES ('428', '{71E24AB4-3715-4644-A54A-239AA4388AB3}', '153', 'INHE-0535', '2020-03-06 18:28:41', '0000-00-00 00:00:00', '2020-03-09 17:36:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020030601/APS', 'APS-EOI', 'BCITS Prviate Limited', 'BCITS', '印度', 'Sridhar Tummala', '+91 9538884484', 'ceo@bcits.co.in', '位于印度班加罗尔，主要提供电力公司，电子政府，云计算，数据分析，智能电网，智能城市，和系统兼容解决方案和服务。', '', 'SOUTHERN POWER DISTRIBUTION COMPANY OF A.P. LTD', 'APSPDCL', '印度', 'Chief General Manager/Projects', '8332999985', 'apspdclpiu@gmail.com', 'APSPDCL,印度AP邦南部配电公司，正在承担多个配电强化工程，包括APSPDCL辖区下Chittoor，Kadapa，Nellore，Anantapur，Kurnool等5个地区和APCPDCL辖区下Krishna，Guntur，Prakasam等3个地区的564,000个农业配电变压器低压侧三相四线全电流CT电表（10A-60A）的勘测，设计，供应，安装，调试，兼容，以获取农业耗能数据，减少窃电现象，并最大程度减少窃电。', '', 'BCITS Prviate Limited', 'BCITS', '印度', 'Sridhar Tummala', '+91 9538884484', 'ceo@bcits.co.in', '位于印度班加罗尔，主要提供电力公司，电子政府，云计算，数据分析，智能电网，智能城市，和系统兼容解决方案和服务。');
INSERT INTO `crs_tabledata1530` VALUES ('429', '{0E61EA14-C6D9-40B1-B973-3CDE0D0BB54E}', '66', 'INHE-0634', '2020-03-11 10:02:48', '0000-00-00 00:00:00', '2020-03-12 15:10:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031101/PNY', '', 'WEnergy Global', 'WEnergy Global', '新加坡', '', '', '', '开发，设计，建造，融资和运营可再生能源电力基础设施，包括发电，储能以及输配电系统。为建筑物或工业区的业主提供解决方案 降低能耗成本，并增加清洁能源在其产品组合中的比例。', '', '', '', '', '', '', '', '', '', 'WEnergy Global', 'WEnergy Global', '新加坡', '', '', '', '开发，设计，建造，融资和运营可再生能源电力基础设施，包括发电，储能以及输配电系统。为建筑物或工业区的业主提供解决方案 降低能耗成本，并增加清洁能源在其产品组合中的比例。');
INSERT INTO `crs_tabledata1530` VALUES ('430', '{5A3E0CAC-7441-4F63-BCF8-21D21777B289}', '66', 'INHE-0634', '2020-03-12 17:11:37', '0000-00-00 00:00:00', '2020-03-13 09:21:57', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031201/WLT', '', 'ECT GROUP', 'ECT', '土耳其', '', '', '', 'ECT于1999年成立，在土耳其和周边国家提供电能质量和电力效率的相关方案20年，主要产品有：低压配电板， MCC面板，控制面板，谐波滤波器面板，工业自动化面板，OG / YG保护控制面板生产。', '', '', '', '', '', '', '', '', '', 'ECT GROUP', 'ECT', '土耳其', '', '', '', 'ECT于1999年成立，在土耳其和周边国家提供电能质量和电力效率的相关方案20年，主要产品有：低压配电板， MCC面板，控制面板，谐波滤波器面板，工业自动化面板，OG / YG保护控制面板生产。');
INSERT INTO `crs_tabledata1530` VALUES ('431', '{F562F171-DF64-4B3B-97BB-DCDE1D60E293}', '66', 'INHE-0634', '2020-03-18 09:18:37', '0000-00-00 00:00:00', '2020-03-18 13:18:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031801/BOS', '', 'Lanaco Informacione Tehnologije', 'Lanaco', '波黑', '', '', '', '1990年成立于波黑，迄今已经30年，是波黑最早的网络供应商，开发设计各式系统软件、通讯方案和云平台等，与世界知名企业有战略合作关系（ DTK, Panasonic, Cisco, Ericsson and Microsoft，HP, Oracle, SAP, Intel, Kaspersky, Fujitsu, VMware, EMC2, Fortinet, Schneider electric 和华为 ），2016年被微软授予年度最佳合作伙伴称号。', '', 'ZP Elektrokrajina a.d. Banja Luka', 'Krajina', '波黑', '', '', '', '波黑电力公司', '', 'ZP Elektrokrajina a.d. Banja Luka', 'Krajina', '波黑', '', '', '', '波黑电力公司');
INSERT INTO `crs_tabledata1530` VALUES ('432', '{411A9260-DD5F-4CAF-9102-E73447A5451D}', '61', 'INHE-0793', '2020-03-18 14:00:42', '0000-00-00 00:00:00', '2020-03-20 15:42:34', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031803/TTH', '坦桑250A低压计量箱招标', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '客户在坦桑尼亚是一个非常大的企业，涵盖房地产，进出口贸易，交通运输，电力等行业。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），预算金额约为2000万美元（DDP）价格条款。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。');
INSERT INTO `crs_tabledata1530` VALUES ('433', '{8BD05154-AEBD-4D5F-927A-37CC07AFD270}', '61', 'INHE-0432', '2020-03-19 14:34:04', '0000-00-00 00:00:00', '2020-03-20 15:38:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020031901/KF04', '项目代号为KFD', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。');
INSERT INTO `crs_tabledata1530` VALUES ('434', '{24B344BE-D036-4097-AD99-D0BEA45CE1E2}', '66', 'INHE-0634', '2020-03-20 08:53:54', '0000-00-00 00:00:00', '2020-03-20 15:49:32', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032001/FNS', '', 'TES-AMM (Singapore) Pte Ltd', 'TES', '新加坡', '', '', '', '2005年成立，主营业务：电子产品回收利用和储能设备等，每年在澳大利亚，新西兰，新加坡，中国，台湾，香港，日本，韩国，马来西亚，泰国，印度尼西亚，菲律宾，越南，法国，瑞典，西班牙，意大利，德国， 英国和美国等为原始设备制造商，蓝筹跨国公司，金融和租赁业务，州/联邦政府等提供服务。', '', '', '', '', '', '', '', '', '', 'TES-AMM (Singapore) Pte Ltd', 'TES', '新加坡', '', '', '', '2005年成立，主营业务：电子产品回收利用和储能设备等，每年在澳大利亚，新西兰，新加坡，中国，台湾，香港，日本，韩国，马来西亚，泰国，印度尼西亚，菲律宾，越南，法国，瑞典，西班牙，意大利，德国， 英国和美国等为原始设备制造商，蓝筹跨国公司，金融和租赁业务，州/联邦政府等提供服务。');
INSERT INTO `crs_tabledata1530` VALUES ('435', '{59192EB5-C553-4FFE-A915-B0496C20278F}', '61', 'INHE-0793', '2020-03-23 15:33:05', '0000-00-00 00:00:00', '2020-03-24 14:40:21', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032302/TTO', '33KV柱上安装自动重合器配电产品投标 			', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。										\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），预算金额约为2000万美元（DDP）价格条款。本次采购实体为ELECTRICAL TRANSMISSION AND DISTRIBUTION CONSTRUCTION AND MAINTENANCE COMPANY LTD（ETDCO），TANESCO的子公司。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。');
INSERT INTO `crs_tabledata1530` VALUES ('436', '{BD6A2D6E-8731-4B60-A66C-48773FD27465}', '61', 'INHE-0793', '2020-03-23 16:56:18', '0000-00-00 00:00:00', '2020-03-24 14:26:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020032303/TTQ', '33KV 负荷开关配电产品招标', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', '\"TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。						此标为TANESCO子公司ETDC招标的中压负荷开关。\"						\r\n', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。');
