INSERT INTO `crs_tabledata1530` VALUES ('440', '{8A5A273E-2D3E-435A-872E-E61EFC2AA1A4}', '93', 'INHEGRID-0013', '2020-04-13 10:40:47', '0000-00-00 00:00:00', '2020-04-15 09:54:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041302/TEN', '', 'T.E.T Sarl', 'TET', '多哥', 'Philippe B. KAKASSINA', '+228 90 02 95 55', 'tet.sarl@yahoo.fr', '多哥本地施工企业，业务范围为电力、电信及土木工程，超过15年项目经验，主要业务分布在多哥、布基纳法索、科特迪瓦等中西非国家。', '', 'Ministère des Mines et des Energies', 'MINES', '多哥', 'BANIMPO GBENGBERTANE', '00228 70 43 58 81', 'prmp.mme@minenergie.gouv.tg', '多哥能源部，负责管理多哥电力公司(CEET）、电力通讯社（CEB）、电气化技术监督局（ARSE）等电力组织及多哥矿业组织。', '', 'Ministère des Mines et des Energies', 'MINES', '多哥', 'BANIMPO GBENGBERTANE', '00228 70 43 58 81', 'prmp.mme@minenergie.gouv.tg', '多哥能源部，负责管理多哥电力公司(CEET）、电力通讯社（CEB）、电气化技术监督局（ARSE）等电力组织及多哥矿业组织。');
INSERT INTO `crs_tabledata1530` VALUES ('441', '{20B8FF59-AE05-4576-8393-B7AE6DAD9BB4}', '61', 'INHE-0913', '2020-04-14 09:01:20', '0000-00-00 00:00:00', '2020-04-24 13:33:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041402/MATB', '', '', '', '', '', '', '', '', '', 'Société Mauritanienne d`électricité', 'SOMELEC', '毛里塔尼亚', 'Dahane TALEB ETHMANE', '+ 222 45296604', 'somelec@somelec.mr', 'SOMELEC (毛里塔尼亚电力公司)成立于2001，是从1975年成立的毛里塔尼亚水电公司分离出来的。它负责整个毛里塔尼亚境内城市及其周边的发电，输电，配电和用电.', '', 'Société Mauritanienne d`électricité', 'SOMELEC', '毛里塔尼亚', 'Dahane TALEB ETHMANE', '+ 222 45296604', 'somelec@somelec.mr', 'SOMELEC (毛里塔尼亚电力公司)成立于2001，是从1975年成立的毛里塔尼亚水电公司分离出来的。它负责整个毛里塔尼亚境内城市及其周边的发电，输电，配电和用电.');
INSERT INTO `crs_tabledata1530` VALUES ('442', '{30DBD4BD-C340-402F-B114-89664D52DDF6}', '61', 'INHE-0721', '2020-04-15 11:06:45', '0000-00-00 00:00:00', '2020-04-17 09:49:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041502/ESE', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '', 'Electrificadora de Santander S.A. ESP.', 'ESSA', '哥伦比亚', '', '01-800-0971903', '', 'Electrificadora de Santander S.A. ESP.电力公司为哥伦比亚第二大电力公司国电Empresas Públicas de Medellín（简称EPM,约220万用户）旗下子电力公司，用户数量约有75万。', '', 'MESSEN S.A.S', 'STSA', '哥伦比亚', 'Mario Andrés Jiménez Díaz', '57 315 843 2739', 'mario.jimenez@messen.com.co', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。');
INSERT INTO `crs_tabledata1530` VALUES ('443', '{0594CE62-1F46-4A59-A1F4-B918B6F8E448}', '61', 'INHE-0793', '2020-04-18 01:39:12', '0000-00-00 00:00:00', '2020-04-20 15:40:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2020041801/TTK', '坦桑单三相电表招标（标前立项，已获文件）', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', '\"Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', '\"TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。此标为总部更换旧表的招标。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', '\"INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，已建成绝缘子工厂，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。');
INSERT INTO `crs_tabledata1530` VALUES ('444', '{29B99C6B-389F-41B7-8A00-C5175028B9ED}', '61', 'INHE-0744', '2020-04-22 00:23:10', '0000-00-00 00:00:00', '2020-04-23 14:40:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2020042201/NGC', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。', '', '尼日尔国家电力公司', 'Nigelec', '尼日尔', 'Balla Mamane MAISHAROU', '+227 90 01 03 26', 'maisharou_balla@yahoo.de', '尼日尔国家电力公司（Nigelec）是一家国家控股的有限责任公司（尼日尔政府持股95%，而法国发展署持股0.43%，其他为私人持股），拥有国家电力的特许运营权，在整个国家范围内发电、进口电、输电、配电和售电，尤其是垄断了输电和电力进口，但尼日尔的新电力法规也允许其他独立厂商经营发电和配电。');
INSERT INTO `crs_tabledata1530` VALUES ('445', '{73BE5644-00DF-4094-9F52-31102661E937}', '66', 'INHE-0634', '2020-04-27 09:19:46', '0000-00-00 00:00:00', '2020-04-27 17:11:05', 'unchecked', 'n', 'n', '', '1', 'lxdj2020042701/AKD', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'The United Nations Development Programme', 'UNDP', '美国', '', '', '', '联合国开发计划署是世界上最大的负责进行技术援助的多边机构。它是联合国的一个下属机构，总部位于纽约。其主要工作是为发展中国家提供技术上的建议、培训人才并提供设备，特别是为最不发达国家进行帮助。', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('446', '{F2AC65ED-BE66-432B-BF9B-8E830E444563}', '61', 'INHE-0793', '2020-05-01 23:12:01', '0000-00-00 00:00:00', '2020-05-06 10:57:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050101/TTP\r\n', '坦桑市场电表周边产品“塑胶旋钮卷线铅封”招标，银河直投', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。										\r\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', '\"TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。此标为电表铅封采购，采购数量为2百万个。', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', '\"TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。此标为电表铅封采购，采购数量为2百万个。');
INSERT INTO `crs_tabledata1530` VALUES ('447', '{D3CA2794-6A13-4859-B395-199140E7A95C}', '66', 'INHE-0634', '2020-05-08 09:38:50', '0000-00-00 00:00:00', '2020-05-12 08:49:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050801/KKA', '', 'Peace Myanmar Electric Holding Co.,Ltd', 'PME', '缅甸', '', '', '', '于1994年成立，在仰光有一个服务中心，在曼德勒和内比都分别有一个分公司，总员工人数超过1000人，还是三菱电机在缅甸长达25年的忠诚合作伙伴。PME的销售产品种类较多，主要有如下几个大类：空调、冰箱、工业通风设备、水泵、安保设备、电缆以及输配电设备（66 kV雷击避雷器、66kV气体绝缘金属封闭式开关设备、12 kV环网柜、66kV户外气体绝缘开关设备、66 kV户外气体断路器、66 kV电压互感器）。PME有推广过三菱的电表，但估计是价格因素，未在缅甸电表市场取得很好的成绩，希望与银河就智能电表开展长期合作关系。', '', 'Ministry of Electricity and Energy', 'MOEE', '缅甸', '', '', '', '缅甸国家能源部，下有3家电力局（ESE，YESC和MESC）。', '', 'Peace Myanmar Electric Holding Co.,Ltd', 'PME', '缅甸', '', '', '', '于1994年成立，在仰光有一个服务中心，在曼德勒和内比都分别有一个分公司，总员工人数超过1000人，还是三菱电机在缅甸长达25年的忠诚合作伙伴。PME的销售产品种类较多，主要有如下几个大类：空调、冰箱、工业通风设备、水泵、安保设备、电缆以及输配电设备（66 kV雷击避雷器、66kV气体绝缘金属封闭式开关设备、12 kV环网柜、66kV户外气体绝缘开关设备、66 kV户外气体断路器、66 kV电压互感器）。PME有推广过三菱的电表，但估计是价格因素，未在缅甸电表市场取得很好的成绩，希望与银河就智能电表开展长期合作关系。');
INSERT INTO `crs_tabledata1530` VALUES ('448', '{FC8EB4F5-1577-4AA6-B214-66EB8B7F5D53}', '61', 'INHE-0432', '2020-05-08 15:47:02', '0000-00-00 00:00:00', '2020-05-12 08:47:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020050802/KFE', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。');
INSERT INTO `crs_tabledata1530` VALUES ('449', '{663FB66A-0D1B-4E5D-8605-DB41F4219268}', '61', 'INHE-0440', '2020-05-14 02:31:08', '0000-00-00 00:00:00', '2020-05-15 18:04:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051401/TTU', '', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。										\r\r\r', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。READY BOARD 主要给偏远的农村地区，通电使用。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，已建成绝缘子工厂，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。');
INSERT INTO `crs_tabledata1530` VALUES ('450', '{FBF9AD5C-2FD7-4584-A48E-05CCDA427B46}', '61', 'INHE-0772', '2020-05-14 16:19:56', '0000-00-00 00:00:00', '2020-05-15 18:18:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051402/ABF', '', 'SACOTEN Sarl', 'SAC', '布基纳法索', 'Benkadi G. A ZERBO', 'Tel(+226) 25 34 00 67', 'dg@sacoten.com', 'DRC介绍BFN本地公司，配合农电项目投标，据介绍SAC中了SONABEL很多投标', '', 'AGENCE BURKINABE DE L`ELECTRIFICATION RURALE', 'ABER', '布基纳法索', 'Ismael Somlawende NACOULMA', '+226 25 37 45 01', 'info@aber.bf', '布基纳法索农电局', '', 'SACOTEN Sarl', 'SAC', '布基纳法索', 'Benkadi G. A ZERBO', 'Tel(+226) 25 34 00 67', 'dg@sacoten.com', 'DRC介绍BFN本地公司，配合农电项目投标，据介绍SAC中了SONABEL很多投标');
INSERT INTO `crs_tabledata1530` VALUES ('451', '{BAF2F0A1-387A-4122-A2E6-995A795B4057}', '61', 'INHE-0885', '2020-05-18 15:19:27', '0000-00-00 00:00:00', '2020-05-20 09:03:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020051802/MER', '', 'Ark Agencies', '', '马拉维', 'Abdul Vindhani', '+265999928143', 'arkagenciesmw@gmail.com', 'MER项目询盘，马拉维投标代理商。', '', 'Republic of Malawi MINISTRY OF ENERGY', '马拉维国家能源部', '马拉维', '', '+265 1 770 688', 'info@energy.gov.mw', '马拉维国家能源部', '', 'Ark Agencies', '', '马拉维', 'Abdul Vindhani', '+265999928143', 'arkagenciesmw@gmail.com', 'MER项目询盘，马拉维投标代理商。');
INSERT INTO `crs_tabledata1530` VALUES ('452', '{98D744CB-79A0-403F-8E72-EAFA619CDFEB}', '66', 'INHE-0634', '2020-05-22 14:07:55', '0000-00-00 00:00:00', '2020-05-26 10:58:13', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052201/NAL', '', 'DigiNET International Co., Ltd', 'DigiNET', '缅甸', '', '', '', '该公司主要在缅甸和新加坡做自动化相关的方案和技术交钥匙工程，提供多种多样的技术服务，现有主要方案包含：·M2M /物联网解决方案\r\r\n\r\r\n·工厂和机器自动化\r\r\n\r\r\n·油箱，油流量，漏油等监控系统…\r\r\n\r\r\n·智能酒店和智能家居自动化\r\r\n\r\r\n·智能会议室和数字会议系统\r\r\n\r\r\n·具有能源监控功能的建筑物管理系统（绿色能源）\r\r\n\r\r\n·带有自动/手动付款的停车场引导系统\r\r\n\r\r\n·带有企业级CCTV产品的高级视频分析解决方案\r\r\n\r\r\n·环境和设施监控解决方案\r\r\n\r\r\n·太阳能和风力发电机解决方案\r\r\n\r\r\n·卡车，出租车和船舶的车队管理系统\r\r\n\r\r\n·国际解决方案和系统集成商代表机构\r\r\n\r\r\n·免费咨询各种自动化机器和配件的采购\r\r\n\r\r\n·定制软件和编程服务', '', 'Ministry of Electricity and Energy', 'MOEE', '缅甸', '', '', '', '缅甸国家能源部，下有3家电力局（ESE，YESC和MESC）。', '', 'DigiNET International Co., Ltd', 'DigiNET', '缅甸', '', '', '', '该公司主要在缅甸和新加坡做自动化相关的方案和技术交钥匙工程，提供多种多样的技术服务，现有主要方案包含：·M2M /物联网解决方案\r\r\n\r\r\n·工厂和机器自动化\r\r\n\r\r\n·油箱，油流量，漏油等监控系统…\r\r\n\r\r\n·智能酒店和智能家居自动化\r\r\n\r\r\n·智能会议室和数字会议系统\r\r\n\r\r\n·具有能源监控功能的建筑物管理系统（绿色能源）\r\r\n\r\r\n·带有自动/手动付款的停车场引导系统\r\r\n\r\r\n·带有企业级CCTV产品的高级视频分析解决方案\r\r\n\r\r\n·环境和设施监控解决方案\r\r\n\r\r\n·太阳能和风力发电机解决方案\r\r\n\r\r\n·卡车，出租车和船舶的车队管理系统\r\r\n\r\r\n·国际解决方案和系统集成商代表机构\r\r\n\r\r\n·免费咨询各种自动化机器和配件的采购\r\r\n\r\r\n·定制软件和编程服务');
INSERT INTO `crs_tabledata1530` VALUES ('453', '{988397BE-1013-47F0-97C2-F082D542BB57}', '61', 'INHE-0793', '2020-05-25 04:21:45', '0000-00-00 00:00:00', '2020-05-25 18:09:39', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052501/TPA\r\n', 'TPA项目坦桑湖区招标采购11KV&33KV自动重合器和负荷开关', 'Africarriers Ltd', 'Africarriers Ltd', '坦桑尼亚', 'Mr. Fidahussein N. Rashid', '+255 22 2865018', 'africarriers110@gmail.com', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河按照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。	Africarriers集团公司，主要业务为汽贸，房地产，银行，保险，投资等。										\r\r\n', '', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '坦桑尼亚', 'Dr.Tito Mwinuka', '(+255) 752 224 279', 'tito.mwinuka@tanesco.co.tz', 'TANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）和周边国家。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电CT/VT表等），目前电表采购的总量有所增加40-50万台。电表采购已经分到全国的7个区域，国内限制招标，本地采购和本地生产。						此标为TANESCO湖区的重合器和负荷开关采购项目。', '', 'INHEMETER (T) LIMITED', 'ITL', '坦桑尼亚', 'Abraham Rajakil', '+255653254452', 'abraham.btek@gmail.com', 'INHEMETER (T) LIMITED 是坦桑尼亚第一家年产能约50万台的智能电表组装厂，实际控制人是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Rashid的Africarriers集团公司投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和技术支持本地工厂建设。ITL的主要业务是电表生产和销售，已建成绝缘子工厂，主要客户为TANESCO,REA,ZECO等，计划将业务拓展到周边市场如刚果金，卢旺达，乌干达等。								电表业务已经比较稳定，想往配电业务方面发展，获取更多的收入来源。');
INSERT INTO `crs_tabledata1530` VALUES ('454', '{1B3C957F-0FAF-4869-BC62-D4A6968C7049}', '61', 'INHE-0772', '2020-05-27 18:33:10', '0000-00-00 00:00:00', '2020-06-05 13:38:51', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052701/LBB', '', 'Electrical Technologies S.A.L', 'ETLB', '黎巴嫩', 'Elie Khoury', '+961 1 512 830 ext.105', 'elie.khoury@et-lb.com', '再黎巴嫩从事中高压输电项目的公司，是ABB， Baur， Sudkabel，Omicron等厂家的代理', '', 'ELECTRICITE DU LIBAN', 'EDL', '黎巴嫩', '', '961-1-442720', '', '黎巴嫩的国电，用户数达140万，电表为PLC PRIME， 目前因获得世行融资，对AMI=HES+MDM+BILLING+CRM EPC项目招标中。', '', 'ELECTRICITE DU LIBAN', 'EDL', '黎巴嫩', '', '961-1-442720', '', '黎巴嫩的国电，用户数达140万，电表为PLC PRIME， 目前因获得世行融资，对AMI=HES+MDM+BILLING+CRM EPC项目招标中。');
INSERT INTO `crs_tabledata1530` VALUES ('455', '{2DFC6540-A63D-4236-985E-792856D56AEA}', '61', 'INHE-0853', '2020-05-28 18:46:43', '0000-00-00 00:00:00', '2020-06-02 10:48:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052801/GSB', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '西非法语区老代理', '', 'Entreprise d?Electricité et Eau de Guinée-Bissau', 'EAGB', '几内亚比绍', 'M. Luís Alberto Cruz Gomes', '00(245)95559 91 13', 'puasee@outlook.pt#FE54` joaoantoniosilva@yahoo.com.br', '几内亚比绍电力水务公司', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '西非法语区老代理\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('456', '{C9792FFA-AED9-4901-B4A8-3B531EE7A820}', '66', 'INHE-0774', '2020-05-29 15:44:49', '0000-00-00 00:00:00', '2020-06-01 11:49:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020052901/ECP', '', 'ELEKTROCENTAR PETEK d.o.o.', 'ECP', '克罗地亚', 'Ivana Tumpak', '385 (0)1 5558 213', 'ivana.tumpak@ecp.hr', '克罗地亚领先的电网、电信工程公司，致力于发电站建设，低压配电网络工程和各种电气安装（工业、民用和电信），照明工程，电机和控制系统安装。', '', 'Hrvatska Elektroprivreda', 'HEP', '克罗地亚', 'Sector for Procurement', '385 1 63 22 111', 'strateski@hep.hr', 'HEP集团是一个克罗地亚国有电力公司，一个多世纪以来从事发电、输电和配电业务，过去几十年开始从事供热和天然气配送。\r\nHEP集团拥有多家子公司，以控股公司的形式组建。集团母公司HEP d.d.履行集团公司管理的职能，为客户提供安全可靠的电力供应条件。', '', 'ELEKTROCENTAR PETEK d.o.o.', 'ECP', '克罗地亚', 'Ivana Tumpak', '385 (0)1 5558 213', 'ivana.tumpak@ecp.hr', '克罗地亚领先的电网、电信工程公司，致力于发电站建设，低压配电网络工程和各种电气安装（工业、民用和电信），照明工程，电机和控制系统安装。');
INSERT INTO `crs_tabledata1530` VALUES ('457', '{C8B7AEAE-4E36-45DD-A1C6-C9DE794FE83D}', '61', 'INHE-0432', '2020-06-12 17:00:46', '0000-00-00 00:00:00', '2020-06-16 09:32:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061201/KFF', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。');
INSERT INTO `crs_tabledata1530` VALUES ('458', '{BFC58582-2DF3-424A-BF0A-B0FDEE64CD53}', '61', 'INHE-0913', '2020-06-16 09:27:18', '0000-00-00 00:00:00', '2020-06-18 15:06:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061501/CMC', '售电系统', 'Arabsoft', '', '突尼斯', 'Taha Triki', '+216 98 76 95 38', 'taha.triki@arabsoft.com.tn', '创建于1985年，致力于开发和分发管理解决方案，尤其是针对公共部门的管理解决方案。ARAB SOFT主要提供法语和阿拉伯语双语解决方案。', '', 'Gouvernement de l`Union des Comores', 'GDC', '科摩罗', '项目办公室', '+269 773 99 00', 'comoresol.procure@gmail.com', '科摩罗政府专门设立的项目小组：Projet Comorsol, 负责与Projet Comorsol项目所有的事务。\r\n当地市场的水电机构为Sonelec（国家电力公司）和Sonede（国家水开采和分配公司）。', '', 'Arabsoft', '', '突尼斯', 'Taha Triki', '+216 98 76 95 38', 'taha.triki@arabsoft.com.tn', '创建于1985年，致力于开发和分发管理解决方案，尤其是针对公共部门的管理解决方案。ARAB SOFT主要提供法语和阿拉伯语双语解决方案。');
INSERT INTO `crs_tabledata1530` VALUES ('459', '{A2343223-109E-4535-A175-02EF92B4748D}', '61', 'INHE-0843', '2020-06-16 10:41:54', '0000-00-00 00:00:00', '2020-06-17 11:26:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061601/MXP02', '项目代号为MXC。', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'Protecsa Ingeniería S.A. de C.V.', 'Protecsa', '墨西哥', 'Ruben Sanchez Rojo', '52 442 313 1109', 'ruben@protecsa.lat', 'Protecsa在墨西哥的主营业务是为电力行业提供智能电表、计量设备、AMI方案、TPCyM方案和智能电网解决方案，拥有20年的行业经验，本地有大型工厂生产自主品牌产品。');
INSERT INTO `crs_tabledata1530` VALUES ('460', '{5FEB40EB-CCF9-48AB-BD93-51108624EE33}', '153', 'INHE-0535', '2020-06-16 13:54:18', '0000-00-00 00:00:00', '2020-06-17 11:22:52', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061602/MEP', '代号为MPD', 'JPM Industries Limited', 'JPM', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '', 'Meghalaya Power Distribution Corporation Limited', 'MePDCL', '印度', 'Mr U N Madan, Chief Engineer(Projects)', '', 'cere_meseb@rediffmail.com', 'MePDCL电力公司位于印度Meghalaya邦，旨在为Maghalaya邦的民众提供普遍、充足、负担得起、可靠和可持续的电力，并确保长期提供电力分配服务的可持续性和财务可行性。减少配电中的技术和商业损失。\r\n作为重要的项目干预措施之一，MePDCL计划通过将智能电表替换约45％的现有电表（主要是旧的机电式电表）来更新和现代化其现有的电表基础设施，以减少商业损失，提高账单效率和收款。', '', 'JPM Industries Limited', 'JPM', '印度', 'Dr.Rajesh Singh', '0124-4395500', 'rsingh@jnsil.com', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。');
INSERT INTO `crs_tabledata1530` VALUES ('461', '{E42147C7-E94A-4107-9E51-324FF1988E18}', '61', 'INHE-0432', '2020-06-17 02:54:22', '0000-00-00 00:00:00', '2020-06-18 15:03:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061701/KFG', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。');
INSERT INTO `crs_tabledata1530` VALUES ('462', '{7C0F5C67-7B2B-43A0-B085-513227CC78B6}', '66', 'INHE-0774', '2020-06-17 08:59:17', '0000-00-00 00:00:00', '2020-06-18 14:25:01', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061704/BLS', '', 'International Telecommunication and Electronic Corporation', 'ITEC', '巴勒斯坦', 'Mohammad Shubietah', '970 599 674 489', 'mohammad.shubietah@itec.ps', 'ITEC是MOSECO集团在巴勒斯坦的子公司，MOSECO集团是一家领先的阿拉伯系统集成商，在IT电信市场拥有超过38年的经验。 ITEC能够以全面且经济高效的方式独特地安装和支持电信基础设施解决方案及其互补的运营和业务支持解决方案', '', 'The International Committee of the Red Cross', 'ICRC', '约旦', 'Bader Rahahle', '962 6 460 4300', 'amm_logtender_services@icrc.org', '红十字会在各地区，尤其是在亚非中东地区都有援助项目，每年会发起电表的招标采购。', '', 'The International Committee of the Red Cross', 'ICRC', '约旦', 'Bader Rahahle', '962 6 460 4300', 'amm_logtender_services@icrc.org', '红十字会在各地区，尤其是在亚非中东地区都有援助项目，每年会发起电表的招标采购。');
INSERT INTO `crs_tabledata1530` VALUES ('463', '{3B233CF5-9AEB-4159-A5CB-8B99CDD7319C}', '61', 'INHE-0916', '2020-06-17 11:20:12', '0000-00-00 00:00:00', '2020-06-20 15:24:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061705/ZBD', '', 'Finmark Industries (Pvt) Ltd.', 'FHL', '津巴布韦', 'David Yosa Zulu', '00263 732296979', '', '', '', 'Zimbabwe National Water Authority', 'ZINWA', '津巴布韦', '', '', '', 'Zimbabwe National Water Authority（ZINWA）为津巴布韦国家水务局，负责津巴布韦水资源的管理', '', 'Finmark Industries (Pvt) Ltd.', 'FHL', '津巴布韦', 'David Yosa Zulu', '00263 732296979', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('464', '{3B549857-DD37-4107-A404-E4D773BB4536}', '61', 'INHE-0819', '2020-06-18 05:24:39', '0000-00-00 00:00:00', '2020-06-22 09:27:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061803/NFC', '', '', '', '', '', '', '', '', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'fatimazahara lahsinia', '+212662182507', 'lahsinia@onee.ma', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'fatimazahara lahsinia', '+212662182507', 'lahsinia@onee.ma', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('465', '{8EFA7C92-30F0-4B46-9C83-D2C4C8EF3B21}', '61', 'INHE-0725', '2020-06-18 10:09:58', '0000-00-00 00:00:00', '2020-06-20 15:19:30', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061806/AGP', '', 'ACOB Lighting Technology Limited', 'ACO', '尼日利亚', 'Alexander C. Obiechina', '+2348032902825', 'o.alexander@acoblighting.com', 'ACOB Lighting Technology Limited主要在尼日利亚和非洲地区推广可持续LED产品（LED灯）、可再生能源和通用电气化项目。目前正在借由微型电网项目推动其在尼日利亚地区的业务发展。同时ACOB是AMDA:Africa Mini-grid Developers Association (由11家盈利性主营微型电网项目的公司组成的协会组织）的一员，ACOB的President Mr Alexander同时是AMDA的两名执行秘书之一。', '', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit', 'GIZ', '尼日利亚', 'Fatoki Olumide', '+2348037164170', 'olumide.fatoki@giz.de', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit(GIZ)又称德国国际合作机构创建于1975年，总部在法兰克福附近的Eschborn，是德国政府所有的一家推动国际合作的服务型企业，主要接受德国经济合作与发展部（BMZ)等德国政府部门及别国政府委托，支持德国伙伴国的发展和改革。目前在世界各地同130多个国家以及世界银行、欧盟、联合国开发计划署、亚洲开发银行等国际组织和机构开展合作。\r\n\r\nGIZ在2018年与尼日利亚政府达成协议，受NERC（尼日利亚电力行业监管机构）指派负责本地微网项目招标（包含太阳能发电，输配电及计量设备及方案），享受尼政府优惠政策（免税），2018-2019年处于业务积累阶段，目前已完成微网市场布局，本地客户如GVE(GA），Nayo Tropical(AN)，ACOB Lighting(MNP)相继与GIZ展开合作，有整合尼日利亚微网市场的计划，能力和人脉。', '', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit', 'GIZ', '尼日利亚', 'Fatoki Olumide', '+2348037164170', 'olumide.fatoki@giz.de', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit(GIZ)又称德国国际合作机构创建于1975年，总部在法兰克福附近的Eschborn，是德国政府所有的一家推动国际合作的服务型企业，主要接受德国经济合作与发展部（BMZ)等德国政府部门及别国政府委托，支持德国伙伴国的发展和改革。目前在世界各地同130多个国家以及世界银行、欧盟、联合国开发计划署、亚洲开发银行等国际组织和机构开展合作。\r\r\n\r\r\nGIZ在2018年与尼日利亚政府达成协议，受NERC（尼日利亚电力行业监管机构）指派负责本地微网项目招标（包含太阳能发电，输配电及计量设备及方案），享受尼政府优惠政策（免税），2018-2019年处于业务积累阶段，目前已完成微网市场布局，本地客户如GVE(GA），Nayo Tropical(AN)，ACOB Lighting(MNP)相继与GIZ展开合作，有整合尼日利亚微网市场的计划，能力和人脉。');
INSERT INTO `crs_tabledata1530` VALUES ('466', '{2BCB3F7D-4889-41B8-8B83-E23178DC036F}', '61', 'INHE-0434', '2020-06-19 08:26:54', '0000-00-00 00:00:00', '2020-06-23 17:58:45', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061901/NED', '', 'El Sewedy Electrometer Group', 'EMG', '埃及', 'Gamal Sayed', '00201003679943', 'gsayed@sewedy.com.eg', '1. 埃及主要本地表厂之一，常年供货埃及各配电公司\r\n2. 客户此前与CLOU合作，但CLOU已在本地设厂，所以客户另寻合作\r\n3. 客户在埃塞，加纳，赞比亚，墨西哥，巴西都设有工厂或办事处', '', 'Northern Electricity Distribution Company', 'NEDCO', '加纳', 'Gamal', '00233372022381', 'info@nedcogh.com', '加纳北方配电电力公司，与ECG属同一性质。服务范围覆盖加纳64%区域，用户从1987年的2万至2015年增长至近70万。', '', 'El Sewedy Electrometer Group', 'EMG', '埃及', 'Gamal Sayed', '00201003679943', 'gsayed@sewedy.com.eg', '1. 埃及主要本地表厂之一，常年供货埃及各配电公司\r\n2. 客户此前与CLOU合作，但CLOU已在本地设厂，所以客户另寻合作\r\n3. 客户在埃塞，加纳，赞比亚，墨西哥，巴西都设有工厂或办事处');
INSERT INTO `crs_tabledata1530` VALUES ('467', '{B634EFAE-13CE-436A-B939-FB762DAEE472}', '153', 'INHE-0535', '2020-06-19 10:35:35', '0000-00-00 00:00:00', '2020-06-23 11:49:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020061902/ADA', 'ADA', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。', '', 'Adani Electricity Mumbai Ltd', 'AEML', '印度', 'Kandarp Patel（CEO）', '', 'ceo.mumbaielectricity@adani.com', 'AEML是Adani输电公司收购Reliance基建有限公司的综合发电，输电和配电公用事业后成立的一个子公司，该公司为孟买市提供电力。其配电网络跨越400平方千米，服务超过290万客户的电力需求，范围包括孟买郊区地区从西侧的Bandra到Bhayander，从东侧的Sion到Mankhurd。', '', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '印度', 'Ashutosh', '+91 9167217812', 'ashutosh.bhatnagar@blueocean.systems', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。');
INSERT INTO `crs_tabledata1530` VALUES ('468', '{7FD5276E-6D6E-4DCF-B9E4-5A79DDAEE36D}', '153', 'INHE-0922', '2020-06-23 17:41:15', '0000-00-00 00:00:00', '2020-06-30 09:24:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2020062301/XLY', '下一步请选择王维总监', 'Persia consortium of energy', 'Persia', '伊朗', 'Habib Ghasemi', '+989125829755', 'h.ghasemi515@gmail.com', '\r\nSanjesh Energy Pars Alborz公司； SEP Alborz Co.在电子和智能电表的研发，销售工程，IT，商业和制造方面拥有经验丰富的高管和专家，旨在满足智能电表和能源管理方面日益增长的需求。该客户有自己的电表设计，生产工厂，在伊朗和叙利亚等中东国家有过很多电表项目，也与各电力公司的业主有很好的关系。						\r\n', '', 'PUBLIC ESTABLISHMENT FOR DISTRIBUTION OF ELECTRICAL ENERGY', 'PEDE', '叙利亚', 'Mostafa Shaikhani', '00963-11-2127660', 'engshichanee@gmail.com', '叙利亚配电和开发总局成立于1994年，承担着叙配电和开发工作及相关的招标、承包和投资项目的业务。该局下属有14个分布在全国各个省市的公司，职员2.8万人。该局用户用电量为28138GWH；配送动力电能7807GWH；照明电能13095GWH。配电需求量为28242GWH。配电缺口为104GWH。配电网有变电站218个(66/20KV)，总容量为9156MVA。共完成配电线路14.5万公里（其中66K长6502公里，20K长5.7万多公里，0.4K长8.2万多公里）。到目前共有变压器（20/0.4KV）43597个。目前共有1.23万个村庄已实现通电。', '{7FD5276E6D6E4DCFB9E45A79DDAEE36DFFC3E6BB8328443AA9AAC603FC047FE8}_PEDE AMI system 2018final.pdf', 'Persia consortium of energy', 'Persia', '伊朗', 'Habib Ghasemi', '+989125829755', 'h.ghasemi515@gmail.com', '\r\nSanjesh Energy Pars Alborz公司； SEP Alborz Co.在电子和智能电表的研发，销售工程，IT，商业和制造方面拥有经验丰富的高管和专家，旨在满足智能电表和能源管理方面日益增长的需求。该客户有自己的电表设计，生产工厂，在伊朗和叙利亚等中东国家有过很多电表项目，也与各电力公司的业主有很好的关系。						\r\n');
INSERT INTO `crs_tabledata1530` VALUES ('469', '{EBEDB153-D0F8-4808-BD42-B4B8DEC57001}', '60', 'INHE-0868', '2020-06-29 09:04:14', '0000-00-00 00:00:00', '2020-07-21 14:56:24', 'unchecked', 'n', 'n', '', '1', 'lxdj2020062901/BTM', '项目代号为BTM', 'INTERLINK COMMINICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Mr.Janatpol', '662-666-1111', 'project@interlink.co.th', 'Ineterlink Communication Public Company Limited成立于1995年，2004年上市，是集团公司。其母公司为Interlink Holding Company Limited，又有子公司：Interlink Telecom Public Company Limited，Interlink Power and Energy Company Limited。主要业务分为三大板块：经销板块（电缆光纤类），电力工程板块（电力系统和通讯），电信板块。电力公司PEA和MEA在全国的光纤均由Interlink提供，国家铁路及MEA，PEA电线杆的电信网络也都是由Interlink安装运营。', '', 'Provincial Electricity Authority（PEA）', 'PEA', '泰国', 'Call center', '02-589-0100', 'info@pea.co.th', 'Provincial Electricity Authority,负责除大曼谷地区外的配电和售电业务。电表招标主要由PEA发标。', '', 'INTERLINK COMMINICATION PUBLIC COMPANY LIMITED', 'Interlink', '泰国', 'Mr.Janatpol', '662-666-1111', 'project@interlink.co.th', 'Ineterlink Communication Public Company Limited成立于1995年，2004年上市，是集团公司。其母公司为Interlink Holding Company Limited，又有子公司：Interlink Telecom Public Company Limited，Interlink Power and Energy Company Limited。主要业务分为三大板块：经销板块（电缆光纤类），电力工程板块（电力系统和通讯），电信板块。电力公司PEA和MEA在全国的光纤均由Interlink提供，国家铁路及MEA，PEA电线杆的电信网络也都是由Interlink安装运营。');
INSERT INTO `crs_tabledata1530` VALUES ('470', '{2AA4576F-14B7-40EA-8616-3765C9A0F3CE}', '66', 'INHE-0634', '2020-07-03 09:03:46', '0000-00-00 00:00:00', '2020-07-06 12:40:38', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070301/SWG', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'JIRAMA', 'JIRAMA', '马达加斯加', '', '', '', '马达本地水电部', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('471', '{4D207726-0ED9-482B-A611-0FCDFE3270AF}', '61', 'INHE-0725', '2020-07-06 09:36:07', '0000-00-00 00:00:00', '2020-07-20 15:14:42', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070601/PFL', '', 'Power Factor Limited', 'PF', '加纳', 'Frank Kulor', '+233577314582', 'frank.kulor@powerfactorgh.com', 'Power Factor Limited是一家加纳EPC工程公司，在阿克拉郊区有办公室，主做变压器（和某中国厂商合作），在能源部及电力公司处有客情，公司有一万平米的地皮（便于后续建厂），也有运载货物用的大卡车（运货）；整体而言公司实力较强。本次有意与我方合作', '', 'Electricity Company of Ghana Limited', 'ECG', '加纳', 'Ing.S. Boakye-Appiah', '+233(0)208118709', 'sboakye-appiah@ecggh.com', '加纳电力公司(ECG)是加纳政府全资控股的电力公司。加纳电力公司(ECG)于1997年2月成立。它始于1947年4月1日的电力部，负责全国的配电，1967年改称为加纳电力公司。1987年北方电力公司（NED）成立，自此ECG主要负责加纳1/3的地区（南部人口密集地区）的输配电工作，现管理用户超过380万。', '', 'Power Factor Limited', 'PF', '加纳', 'Frank Kulor', '+233577314582', 'frank.kulor@powerfactorgh.com', 'Power Factor Limited是一家加纳EPC工程公司，在阿克拉郊区有办公室，主做变压器（和某中国厂商合作），在能源部及电力公司处有客情，公司有一万平米的地皮（便于后续建厂），也有运载货物用的大卡车（运货）；整体而言公司实力较强。本次有意与我方合作');
INSERT INTO `crs_tabledata1530` VALUES ('472', '{235FD9FE-2693-4317-AF4E-2AD0789344DF}', '66', 'INHE-0634', '2020-07-06 16:08:34', '0000-00-00 00:00:00', '2020-07-08 09:11:08', 'unchecked', 'n', 'n', '', '1', 'lxdj2020070602/SHP', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', '', '', '', '', '', '', '', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('473', '{7FBCEB75-FAD6-4AA0-8415-01B7DBE06F17}', '61', 'INHE-0654', '2020-07-10 05:24:25', '0000-00-00 00:00:00', '2020-07-13 13:53:09', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071001/MCM', '', 'MEDIDAS ELECTRONICAS CENTRALIZADAS', 'MEC BPO SAS', '哥伦比亚', 'Mario Freyre', '+57 311 3768689', 'gerencia@mec-bpo.com', '主营业务：电力营销,同时也做运维服务，给当地的电力公司做线损管理等，公司员工：40人', '', '', '', '', '', '', '', '', '', 'MEDIDAS ELECTRONICAS CENTRALIZADAS', 'MEC BPO SAS', '哥伦比亚', 'Mario Freyre', '+57 311 3768689', 'gerencia@mec-bpo.com', '主营业务：电力营销,同时也做运维服务，给当地的电力公司做线损管理等，公司员工：40人');
INSERT INTO `crs_tabledata1530` VALUES ('474', '{23876030-A5AB-4ECB-8F0B-8568C1402093}', '61', 'INHE-0876', '2020-07-11 03:24:51', '0000-00-00 00:00:00', '2020-07-14 09:50:41', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071101/SNA', '', '', '', '', '', '', '', '', '', 'SENELEC', 'SENELEC', '塞内加尔', 'Makhtar cisse', '221 786371240', 'Makhtar.cisse@senelec.sn', '塞国家电力公司由塞政府控股，目前几乎垄断了全国的电力生产、输配业务。2008年，塞全国生产电力（包括进口）近24亿度。塞电力公司销售约17.86亿度电；营业额：1805亿非郎，约合3.6亿美元；客户数量：71万户；员工人数：2492人。塞电力公司2007年并网发电共计14.92亿度电，比2006年增加了10.4%；独立用户发电为1.03亿度。塞国家电力公司从独立发电厂购买电量为70万度左右。', '', 'SENELEC', 'SENELEC', '塞内加尔', 'Makhtar cisse', '221 786371240', 'Makhtar.cisse@senelec.sn', '塞国家电力公司由塞政府控股，目前几乎垄断了全国的电力生产、输配业务。2008年，塞全国生产电力（包括进口）近24亿度。塞电力公司销售约17.86亿度电；营业额：1805亿非郎，约合3.6亿美元；客户数量：71万户；员工人数：2492人。塞电力公司2007年并网发电共计14.92亿度电，比2006年增加了10.4%；独立用户发电为1.03亿度。塞国家电力公司从独立发电厂购买电量为70万度左右。');
INSERT INTO `crs_tabledata1530` VALUES ('475', '{2F31D49A-BFB2-41AB-ABEF-5F6DD3768C95}', '61', 'INHE-0744', '2020-07-13 00:00:04', '0000-00-00 00:00:00', '2020-07-14 09:46:44', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071301/CNE', '', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。', '', 'Societe National de Electricite de Congo', 'SNEL', '刚果（金）', 'Jean Bosco', '2430816076254', '', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '', '中国水利水电第一工程局有限公司', '中水一局', '中国', '张建', '18243158360', '', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。');
INSERT INTO `crs_tabledata1530` VALUES ('476', '{0F70503E-83FB-411C-A285-ED2912AB13EB}', '66', 'INHE-0774', '2020-07-14 08:54:54', '0000-00-00 00:00:00', '2020-07-16 12:41:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020071401/NAS', '', 'Qarnass Group', 'Qarnass Group', '伊拉克', 'Ahmed Abulsalam Ali', '9647806231414', 'procurement@qarnass.com', '位于伊拉克和约旦， 成立于2001年5月30日，主要从事一般贸易与承包公司，子公司Al-Rama在约旦注册，从事仓储和一般贸易。 AL-Qarnass集团拥有20多名工程师和10名专业管理人员。', '', '', '', '', '', '', '', '', '', 'Qarnass Group', 'Qarnass Group', '伊拉克', 'Ahmed Abulsalam Ali', '9647806231414', 'procurement@qarnass.com', '位于伊拉克和约旦， 成立于2001年5月30日，主要从事一般贸易与承包公司，子公司Al-Rama在约旦注册，从事仓储和一般贸易。 AL-Qarnass集团拥有20多名工程师和10名专业管理人员。');
