INSERT INTO `crs_tabledata1530` VALUES ('479', '{94686F22-CACD-4C06-BB59-3D93E07624CC}', '61', 'INHE-0434', '2020-07-24 11:47:33', '0000-00-00 00:00:00', '2020-07-27 21:17:40', 'unchecked', 'n', 'n', '', '1', 'lxdj2020072401/AGL', '直接收钱做货吧。', 'JTDL HOLDING, LDA', 'JTD', '安哥拉', 'Jose Tati', '0027 722440590', 'JoseTati@jedig.biz', '客户从事电表业务多年，与银河有过AZA01(电表)，AZA02(BOX300)业务，也从银河电网采购了CT表\r\r\n客户与安哥拉国电ENDE有一定客户关系，此前将银河DIN-III以及BOX300卖给了ENDE', '', '', '', '', '', '', '', '', '', 'JTDL HOLDING, LDA', 'JTD', '安哥拉', 'Jose Tati', '0027 722440590', 'JoseTati@jedig.biz', '客户从事电表业务多年，与银河有过AZA01(电表)，AZA02(BOX300)业务，也从银河电网采购了CT表\r\r\n客户与安哥拉国电ENDE有一定客户关系，此前将银河DIN-III以及BOX300卖给了ENDE');
INSERT INTO `crs_tabledata1530` VALUES ('480', '{70449F02-1061-4CA9-AF09-50120A4E8657}', '153', 'INHE-0015', '2020-08-06 09:09:04', '0000-00-00 00:00:00', '2020-08-07 11:03:58', 'unchecked', 'n', 'n', '', '1', 'lxdj2020080601/ZHX', '', 'ZH Technologies International Pte Ltd', 'ZHT', '新加坡', 'Liu Han 刘涵', '+6591335548', 'Liuhan@zhtechintl.com', 'ZH国际70%新加坡股东 30%福建智恒科技，智恒2003年成立 60%营收为水表相关业务。目前与SSN进行兼容工作。水电气中智恒无电表相关经验。目前是三家入选新加坡电力运行水电气 NB 集抄的公司之一，唯一一家与国内公司有联系。', '', 'SP Group', 'SP', '新加坡', 'Procurement team', '+65 6916 8839', 'srmsupport@spgroup.com.sg', 'SP Group is a leading energy utilities group in the Asia Pacific. It owns and operates electricity and gas transmission and distribution businesses in Singapore and Australia, and district cooling businesses in Singapore and China. SP Group is committed to providing customers with reliable and efficient energy utilities services. About 1.6 million industrial, commercial and residential customers in Singapore benefit from SP Group\'s world-class transmission, distribution and market support servic', '', 'ZH Technologies International Pte Ltd', 'ZHT', '新加坡', 'Liu Han 刘涵', '+6591335548', 'Liuhan@zhtechintl.com', 'ZH国际70%新加坡股东 30%福建智恒科技，智恒2003年成立 60%营收为水表相关业务。目前与SSN进行兼容工作。水电气中智恒无电表相关经验。目前是三家入选新加坡电力运行水电气 NB 集抄的公司之一，唯一一家与国内公司有联系。');
INSERT INTO `crs_tabledata1530` VALUES ('481', '{C8704210-A117-49A0-B46E-729171E87861}', '60', 'INHE-0680', '2020-08-11 10:20:11', '0000-00-00 00:00:00', '2020-08-11 17:20:47', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081101/AFD', '', 'CANUCK LOGISTICS & SUPPLY SERVICES CO1', 'CANUCK01', '阿富汗', 'Michael Edie', '', 'michael.edie@gmail.com', 'Canuck Logistics & Supply Services Co 位于喀布尔，电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。', '', 'Da Afghanistan Breshna Sherkat01', 'DABS01', '阿富汗', 'Habibullah bakhtyal', '0795219045', 'info@dabs.af    habib.bakhtyal@dabs.af', 'DABS是一家由阿富汗政府（GoA）拥有所有股权的有限责任公司。 该公司成立于2008年5月4日（Saur 1387年5月15日），并取代了达富·布雷希纳·穆阿萨萨（DABM）作为国家电力公司。 DABS将在整个商业范围内运营和管理整个阿富汗的发电，进口，输电和配电。', '', 'Da Afghanistan Breshna Sherkat01', 'DABS01', '阿富汗', 'Habibullah bakhtyal', '0795219045', 'info@dabs.af    habib.bakhtyal@dabs.af', 'DABS是一家由阿富汗政府（GoA）拥有所有股权的有限责任公司。 该公司成立于2008年5月4日（Saur 1387年5月15日），并取代了达富·布雷希纳·穆阿萨萨（DABM）作为国家电力公司。 DABS将在整个商业范围内运营和管理整个阿富汗的发电，进口，输电和配电。');
INSERT INTO `crs_tabledata1530` VALUES ('482', '{06DC208C-CF60-4E8D-B6EF-601D12C242BA}', '61', 'INHE-0772', '2020-08-12 17:21:35', '0000-00-00 00:00:00', '2020-08-18 09:16:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081201/SAO', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '', '', 'Fiduciary Agency for Project Implementation', 'AFAP', '圣多美和普林西比', 'Alberto Fernandes Leal', '+239 2225205', 'afap2@yahoo.com.br                 psrpafap@gmail.com                                   faustinoneto58@gmail.com', '圣多美民主共和国政府已从欧洲投资银行获得了电力部门恢复项目的资金，并打算将部分收益用于根据计量解决方案的设备供应和安装合同进行的付款。AFAP是该国家贷款项目的主管单位。', '', 'TOGO ASSISTANCE SERVICES', 'TAS', '多哥', 'AZON GUILLAUME', '0022822221355', '', '');
INSERT INTO `crs_tabledata1530` VALUES ('483', '{08D2863F-3253-2A70-489A-35229C41A57B}', '61', 'INHE-0819', '2020-08-12 22:48:16', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', '', '1', 'NFD', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', null, '摩洛哥', 'fatima lahsinia', '+212662182507', 'lahsinia@onee.ma', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。      \n');
INSERT INTO `crs_tabledata1530` VALUES ('484', '{50ED93E8-B810-485D-AE8E-931BD5B91777}', '61', 'INHE-0819', '2020-08-13 16:55:21', '0000-00-00 00:00:00', '2020-08-14 17:19:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081302/NFE', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'l`Office National de l`Electricité et de l`Eau potable - Branche Electricité', '', '摩洛哥', 'Dalaa Mohamed Mustapha', '00212 5 22 30 15 67', 'm.mustapha@ges.ma,globalenergysystem01@gmail.com', '摩洛哥水电局电力部，对改善摩洛哥人名的生活和国家的竞争力起着很重要的作用。掌管全国55%的用户，约6百万。2.5万中压用户。      ');
INSERT INTO `crs_tabledata1530` VALUES ('485', '{FE51E5CF-8DBC-4CD9-A3BF-1A28FEA5A15B}', '93', 'INHEGRID-0048', '2020-08-14 10:14:44', '0000-00-00 00:00:00', '2020-08-18 10:29:29', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081402/SPM', '', 'CENTRO INDUSTRIAL ELETROMECANICO', 'CIEM', '圣多美和普林西比', 'António Lima', '(+239) 9872140', 'antoniolima<antoniolima@ciem.st>', '圣普当地标书一般由当地信托管理机构AFAP发出，圣普当地电力公司为EMAE。CIEM业务涉及汽车经销，医疗设备，发电机安装。\r\r\nCIEM与AFAP和EMAE有着良好的客情关系，并且为AFAP合EMAE提供过发电机产品和安装服务。', '', 'Agência Fiduciária de Administracao de Projectos', 'AFAP', '圣多美和普林西比', 'Faustino Neto', '+239 2225205', 'faustinoneto58@gmail.com', '圣多美和普林西比政府项目管理的信托机构。圣普当地的电力项目资金来源一般是由圣普政府向国际组织或者银行贷款，AFAP作为招标方。', '', 'Agência Fiduciária de Administracao de Projectos', 'AFAP', '圣多美和普林西比', 'Faustino Neto', '+239 2225205', 'faustinoneto58@gmail.com', '圣多美和普林西比政府项目管理的信托机构。圣普当地的电力项目资金来源一般是由圣普政府向国际组织或者银行贷款，AFAP作为招标方。');
INSERT INTO `crs_tabledata1530` VALUES ('486', '{B3ABA4C7-EC07-4289-9BAB-00EEB4602A26}', '172', 'INHE-0913', '2020-08-18 17:09:57', '0000-00-00 00:00:00', '2020-08-24 09:16:17', 'unchecked', 'n', 'n', '', '1', 'lxdj2020081801/GAB', '', 'Société PROSALES', 'PROSALES', '加蓬', 'Yves Florian GOKOU', '+241 77 15 64 84', 'prosalesgabon@gmail.com', '加蓬代理，主要进行水电表经销以及相关系统业务，此前已经与SEEG有过电表和系统合作经验', '', 'Société d`Energie et d`Eau du Gabon', 'SEEG', '加蓬', '', '+241 01761282', 'communication@seeg-gabon.com', '加蓬能源和水公司（SEEG）创建于1950，自1997年实现起私有化，由法国Veolia水务集团拥有51%的股份，加蓬政府、加蓬私人投资者和公司员工拥有49%的股份，垄断了加蓬的水电供应。', '', 'Société d`Energie et d`Eau du Gabon', 'SEEG', '加蓬', '', '+241 01761282', 'communication@seeg-gabon.com', '加蓬能源和水公司（SEEG）创建于1950，自1997年实现起私有化，由法国Veolia水务集团拥有51%的股份，加蓬政府、加蓬私人投资者和公司员工拥有49%的股份，垄断了加蓬的水电供应。');
INSERT INTO `crs_tabledata1530` VALUES ('487', '{CCE7D345-42D9-405D-B6B6-0CFEB06AC8CC}', '75', 'INHE-0432', '2020-09-01 01:44:46', '0000-00-00 00:00:00', '2020-09-02 10:52:25', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090101/KDA', '', '', '', '', '', '', '', '', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '', 'The Kenya Power * Lighting Company Limited', 'KPLC', '肯尼亚', 'William Mathu', '+254 722 984 439', 'WMathu@kplc.co.ke', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。');
INSERT INTO `crs_tabledata1530` VALUES ('488', '{D5F761C7-24DA-42E6-8D8C-D870D616F23D}', '60', 'INHE-0680', '2020-09-01 09:37:09', '0000-00-00 00:00:00', '2020-09-07 10:07:36', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090102/EGM', '', 'Ets Abdou Hayek', 'EAH', '黎巴嫩', 'Simon', 'Tel: +961 1 902 973 - 902 974', 'e-mail: simpass@destination.com.lb', 'EAH是一家领先的公司，专门从事黎巴嫩和邻国中，低压线路以及变电站的建设。\r\nEts Abdou Hayek包含Simpass和Simek。\r\nSimpass专门从事与中高压线路，变电站和公共照明建设有关的产品和材料的贸易和供应的承包商。 Simek有两项业务，第一项专注于与电气工程和传输网络有关的产品和配件的制造和组装，第二项与“承包和交钥匙工程”。\r\n该集团成立于1950年，目前拥有约60名员工。\r\n该集团是黎巴嫩电力公司（Electricitédu Liban-EDL）的主要供应商和承包商。 该集团已经获得了许多投标和合同，可以保持其在其市场领域内的领先地位。', '{D5F761C724DA42E68D8CD870D616F23D11015FBC745F4B1982FBEF12F4BBACD1}_Group Profile-EAH.pdf', '', '', '利比里亚', '', '', '', '本项目由黎巴嫩EAH公司作承包商，参与利比里亚输电线路设计，供货，施工，安装投标项目，EAH要求银河作为电表供应商，提供技术资料，应答文件，样机，授权投标函。二部赵政洁同意由一部推进本项目。', '{D5F761C724DA42E68D8CD870D616F23DFFC3E6BB8328443AA9AAC603FC047FE8}_赵政洁同意证明.jpg', 'Ets Abdou Hayek', 'EAH', '黎巴嫩', 'Simon', 'Tel: +961 1 902 973 - 902 974', 'e-mail: simpass@destination.com.lb', 'EAH是一家领先的公司，专门从事黎巴嫩和邻国中，低压线路以及变电站的建设。\r\nEts Abdou Hayek包含Simpass和Simek。\r\nSimpass专门从事与中高压线路，变电站和公共照明建设有关的产品和材料的贸易和供应的承包商。 Simek有两项业务，第一项专注于与电气工程和传输网络有关的产品和配件的制造和组装，第二项与“承包和交钥匙工程”。\r\n该集团成立于1950年，目前拥有约60名员工。\r\n该集团是黎巴嫩电力公司（Electricitédu Liban-EDL）的主要供应商和承包商。 该集团已经获得了许多投标和合同，可以保持其在其市场领域内的领先地位。');
INSERT INTO `crs_tabledata1530` VALUES ('489', '{75290C5E-B026-4068-BEA3-18FAF012DD24}', '173', 'INHE-0500', '2020-09-04 14:27:59', '0000-00-00 00:00:00', '2020-09-08 09:07:15', 'unchecked', 'n', 'n', '', '1', 'lxdj2020090402/BCM', '', 'Tsogatec (Pty) Ltd', 'TST', '南非', 'Mmatholo Mabotja', '+27 81 748 2105', 'mmatholom@tsogatec.co.za', '1.此公司为2016年新成立的第三方售电系统ICT类型公司，公司主营业务范围主要从事为南非市政公司提供涵盖新能源系统管理、新型第三方售电平台及相关软件系统业务，公司正式员工9名（4名管理人员，5名程序开发工程师），其独立开发的本地第三方售电平台在当地已和各大银行、Whatsup平台完成兼容交互；\r\r\n\r\r\n2.截止目前为主，该公司已中标如下第三方售电/售水授权合同：\r\r\n*** 大都市市政公司City of Ekurhuleni的第三方售电（4个第三方售电平台之一）\r\r\n*** Sekhukhune地区市政公司售水系统平台和水表项目（目前正在和其洽谈银河提供水表一体化方案）', '', 'Buffalo City Metropolitan Municipality', 'BCMM', '南非', 'Mr. Anton Roux', '+27 43 705 9266', 'AntonR@buffalocity.gov.za', '南非市场8大大都市市政之一，位于东开普省East London，为东开普省两个大都市市政公司之一，电表用户基数约为40万户，其中90%为普通低压单相居民用电。\r\r\n\r\r\n\r\r\n此次为银河第一次联合代理投标该市政项目。', '', 'Tsogatec (Pty) Ltd', 'TST', '南非', 'Mmatholo Mabotja', '+27 81 748 2105', 'mmatholom@tsogatec.co.za', '1.此公司为2016年新成立的第三方售电系统ICT类型公司，公司主营业务范围主要从事为南非市政公司提供涵盖新能源系统管理、新型第三方售电平台及相关软件系统业务，公司正式员工9名（4名管理人员，5名程序开发工程师），其独立开发的本地第三方售电平台在当地已和各大银行、Whatsup平台完成兼容交互；\r\n\r\n2.截止目前为主，该公司已中标如下第三方售电/售水授权合同：\r\n*** 大都市市政公司City of Ekurhuleni的第三方售电（4个第三方售电平台之一）\r\n*** Sekhukhune地区市政公司售水系统平台和水表项目（目前正在和其洽谈银河提供水表一体化方案）');
INSERT INTO `crs_tabledata1530` VALUES ('490', '{C9E59979-EF1D-4F61-B449-8432F85943D8}', '66', 'INHE-0774', '2020-09-16 11:03:07', '0000-00-00 00:00:00', '2020-09-17 18:25:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2020091605/SIP', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '', 'JIRAMA', 'JIRAMA', '马达加斯加', '', '', '', '马达本地水电部', '', 'Sipromad Group Company Limited', 'SG', '马达加斯加', 'Remy', '', 'rlajoie@sipromad.com', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。');
INSERT INTO `crs_tabledata1530` VALUES ('491', '{E3FDCB6A-3D50-491C-83D8-9C55B2F93C0F}', '66', 'INHE-0774', '2020-09-17 09:38:12', '0000-00-00 00:00:00', '2020-09-21 13:58:37', 'unchecked', 'n', 'n', '', '1', 'lxdj2020091701/PEK', '', 'Elektrocentar Petek', 'Elektrocentar Petek', '克罗地亚', 'Andrija Petek', '385 (0)1 5558 213', '', 'Elektrocentar Petek 是电厂建设，低压输电和各种电力安装，照明安装，电动机和系统管理的领军企业。\r\n该公司由一家传统的私人企业，现发展为克罗地亚在电力，电信和建筑领域中提供服务和工程实施的领军企业之一。也销售电气设备，建筑材料和设备。 HR商会代表处主任介绍合作HRV项目，对方一直未联系谈合作的事情。近期发邮件说当地有个通信模块采购的标，要我们报价', '', 'Hrvatska Elektroprivreda', 'HEP', '克罗地亚', 'Sector for Procurement', '385 1 63 22 111', 'strateski@hep.hr', 'HEP集团是一个克罗地亚国有电力公司，一个多世纪以来从事发电、输电和配电业务，过去几十年开始从事供热和天然气配送。\r\nHEP集团拥有多家子公司，以控股公司的形式组建。集团母公司HEP d.d.履行集团公司管理的职能，为客户提供安全可靠的电力供应条件。', '', 'Elektrocentar Petek', 'Elektrocentar Petek', '克罗地亚', 'Andrija Petek', '385 (0)1 5558 213', '', 'Elektrocentar Petek 是电厂建设，低压输电和各种电力安装，照明安装，电动机和系统管理的领军企业。\r\n该公司由一家传统的私人企业，现发展为克罗地亚在电力，电信和建筑领域中提供服务和工程实施的领军企业之一。也销售电气设备，建筑材料和设备。 HR商会代表处主任介绍合作HRV项目，对方一直未联系谈合作的事情。近期发邮件说当地有个通信模块采购的标，要我们报价');
INSERT INTO `crs_tabledata1530` VALUES ('492', '{532EC81B-3935-402E-9AD5-2B0CCE3E3BE8}', '169', 'INHE-0381', '2020-09-21 09:04:22', '0000-00-00 00:00:00', '2020-09-22 16:22:55', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092101/CMD', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户', '', 'Gouvernement de l`Union des Comores', 'GDC', '科摩罗', '项目办公室', '+269 773 99 00', 'comoresol.procure@gmail.com', '科摩罗政府专门设立的项目小组：Projet Comorsol, 负责与Projet Comorsol项目所有的事务。\r\n当地市场的水电机构为Sonelec（国家电力公司）和Sonede（国家水开采和分配公司）。', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SGE', '多哥', 'AZON GUILLAUME', '0022822221355', '', '老客户');
INSERT INTO `crs_tabledata1530` VALUES ('493', '{9764FC0F-BA6D-4B2C-83F6-07AF59F9D0B6}', '66', 'INHE-0901', '2020-09-23 13:34:25', '0000-00-00 00:00:00', '2020-09-25 11:10:11', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092302/GCF', '', 'Protasis SA', '', '希腊', 'Sotiris Tsitsias', '+306973674811', 'stsitsias@protasis.net.gr', '此公司是一家电力系统工程和咨询公司，为希腊电力局HEDNO的AMR/MDM System提供维护服务，协助HEDNO进行样机测试等，故Protasis了解HEDNO如何操作。公司联系人Sotiris在兰吉尔工作15年、ABB工作10年，其对技术方面非常熟悉，且关于合作费用细节都需我司提供信息参考。此公司成立于2002年，公司人员少于20人，查询营业额为每年437万美元。Protasis SA与2011年与华立有合作，但之后华立脱离Protasis并在希腊设立办事处，华立自己主投并屡次中标。', '', 'Hellenic Electricity Distribution Network Operator SA', 'HEDNO', '希腊', '', '+30 21440 50205', 'infodeddie@deddie.gr', 'HEDNO为希腊电力局，HEDNO在PPC SA的分销部门分拆后于2012年成立，它是PPC SA（希腊国家能源集团）的100％子公司，但在组织和功能上均是独立的公司。HEDNO为749万希腊用户供电。HEDNO网络线路总长度为240,000公里，HEDNO雇用大约7,000名员工。HEDNO为上市公司，截止2019年12月31日，总资产为9.09417亿欧元，2019年营业额为1.62465亿欧元，全年税后总收入为1495.7万欧元。每年发2-3次电表招标，近两年招标电表为含通信模块的单三相智能电表，电表需连接到其电表系统ZFA-F，华立中标电表居多。', '', 'Hellenic Electricity Distribution Network Operator SA', 'HEDNO', '希腊', '', '+30 21440 50205', 'infodeddie@deddie.gr', 'HEDNO为希腊电力局，HEDNO在PPC SA的分销部门分拆后于2012年成立，它是PPC SA（希腊国家能源集团）的100％子公司，但在组织和功能上均是独立的公司。HEDNO为749万希腊用户供电。HEDNO网络线路总长度为240,000公里，HEDNO雇用大约7,000名员工。HEDNO为上市公司，截止2019年12月31日，总资产为9.09417亿欧元，2019年营业额为1.62465亿欧元，全年税后总收入为1495.7万欧元。每年发2-3次电表招标，近两年招标电表为含通信模块的单三相智能电表，电表需连接到其电表系统ZFA-F，华立中标电表居多。');
INSERT INTO `crs_tabledata1530` VALUES ('494', '{881CCA07-586B-4B59-ACFB-5926CDCE4038}', '75', 'INHE-0432', '2020-09-25 16:42:18', '0000-00-00 00:00:00', '2020-09-27 13:23:50', 'unchecked', 'n', 'n', '', '1', 'lxdj2020092501/SLC', '', 'LIBANGO HOLDINGS, INC.', 'LIBANGO', '利比里亚', 'Manuel Tati', '+244 923640833', 'mrmtati@gmail.com', '1. LIBANGO HOLDINGS, INC.为本地公司，公司CEO为Mr. Joseph Crayton\r\n2. 该公司是本地合资公司，其中AZA市场的Jose在LIBANGO控股\r\n3. 该公司的成立主要经营和当地电力公司LEC(Liberia Electricity Corporation)的生意\r\n4. 该公司CEO和电力公司二把手Thomas Zailee Gonkerwon关系不错，能多次安排一起去其见面\r\n5. 据悉该公司CEO和美国千禧年组织在当地的分支机构(MCA-L)的CEO是发小\r\n6. 该公司CEO和另一股东Alexander Kashif Garley在本地还有一个生产螺钉的工厂，且有计划在本地搭建一个钢铁厂', '', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', 'Monody Mansaray', '', 'momodumansaray2@gmail.com', '塞拉利昂国有配电及供电公司，此次项目招标为电表及相关配件的供货及安装EPC总包项目', '', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '塞拉利昂', 'Monody Mansaray', '', 'momodumansaray2@gmail.com', '塞拉利昂国有配电及供电公司，此次项目招标为电表及相关配件的供货及安装EPC总包项目						\r\n\r\r\n');
